CREATE OR REPLACE FUNCTION "app"."admin_inactive_ma_party_page"("p_entity_key" "text", "p_keyword" "text", "p_limit" integer, "p_offset" integer) RETURNS TABLE("entity_id" "uuid", "entity_name" "text", "category" "text", "detail" "text", "deleted_at" timestamp with time zone, "deactivated_by" "text", "deactivation_reason" "text", "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_keyword text := nullif(btrim(p_keyword), '');
  v_limit   integer := greatest(1, least(coalesce(p_limit, 20), 100));
  v_offset  integer := greatest(coalesce(p_offset, 0), 0);
begin
  if not app.is_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  if p_entity_key = 'ma_buyers' then
    return query
    select b.id,
           b.name,
           nullif(b.industries->>0, ''),
           b.contact_name,
           b.deleted_at,
           d.user_name,
           d.note,
           count(*) over()
      from public.ma_buyers b
      left join lateral (
        select c.user_name, c.note
          from public.entity_contributions c
         where c.entity_table = 'ma_buyers'
           and c.entity_id = b.id
           and c.action = 'deactivated'
         order by c.created_at desc, c.id desc
         limit 1
      ) d on true
     where b.deleted_at is not null
       and b.merged_into_id is null
       and (
         v_keyword is null
         or b.name ilike '%' || v_keyword || '%'
         or coalesce(b.contact_name, '') ilike '%' || v_keyword || '%'
       )
     order by b.deleted_at desc, b.name, b.id
     limit v_limit offset v_offset;
  elsif p_entity_key = 'ma_sellers' then
    return query
    select s.id,
           s.name,
           nullif(s.industries->>0, ''),
           s.contact_name,
           s.deleted_at,
           d.user_name,
           d.note,
           count(*) over()
      from public.ma_sellers s
      left join lateral (
        select c.user_name, c.note
          from public.entity_contributions c
         where c.entity_table = 'ma_sellers'
           and c.entity_id = s.id
           and c.action = 'deactivated'
         order by c.created_at desc, c.id desc
         limit 1
      ) d on true
     where s.deleted_at is not null
       and s.merged_into_id is null
       and (
         v_keyword is null
         or s.name ilike '%' || v_keyword || '%'
         or coalesce(s.contact_name, '') ilike '%' || v_keyword || '%'
       )
     order by s.deleted_at desc, s.name, s.id
     limit v_limit offset v_offset;
  else
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
end $$;


ALTER FUNCTION "app"."admin_inactive_ma_party_page"("p_entity_key" "text", "p_keyword" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "app"."admin_inactive_ma_party_page"("p_entity_key" "text", "p_keyword" "text", "p_limit" integer, "p_offset" integer) IS 'M&A BUYER·SELLER 비활성 행 조회 전용 DEFINER 헬퍼. can_read_ma_party()가 비활성 행을 최고관리자에게도 가리므로 이 한 곳에서만 우회하며, 내부에서 app.is_admin()을 다시 강제한다.';



CREATE OR REPLACE FUNCTION "app"."admin_restore_ma_party"("p_entity_key" "text", "p_id" "uuid", "p_reason" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_rows integer;
begin
  if not app.is_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if p_entity_key not in ('ma_buyers', 'ma_sellers') then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'reason_required' using errcode = '23514';
  end if;

  perform set_config(
    'app.contribution_ctx',
    jsonb_build_object(
      'action', 'reactivated',
      'source', 'manual',
      'note', btrim(p_reason)
    )::text,
    true
  );

  execute format(
    'update public.%I
        set deleted_at = null
      where id = $1 and deleted_at is not null and merged_into_id is null',
    p_entity_key
  ) using p_id;
  get diagnostics v_rows = row_count;

  return v_rows;
end $_$;


ALTER FUNCTION "app"."admin_restore_ma_party"("p_entity_key" "text", "p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."admin_restore_ma_party"("p_entity_key" "text", "p_id" "uuid", "p_reason" "text") IS 'M&A BUYER·SELLER 비활성 행 복구 전용 DEFINER 헬퍼. 자기 테이블의 deleted_at만 되돌리고 병합 원본은 건드리지 않는다.';



CREATE OR REPLACE FUNCTION "app"."after_kpi_actual_revision"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  perform app.refresh_kpi_result(new.assignment_id);
  return new;
end $$;


ALTER FUNCTION "app"."after_kpi_actual_revision"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."amount_text_bad"("p_text" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  select case
           when btrim(coalesce(p_text, '')) = '' then false
           else coalesce(
                  not (app.text_to_numeric(p_text) > '-Infinity'::numeric
                       and app.text_to_numeric(p_text) < 'Infinity'::numeric),
                  true)
         end;
$$;


ALTER FUNCTION "app"."amount_text_bad"("p_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."amount_text_bad"("p_text" "text") IS '적혀 있는데 수치로 읽을 수 없는 칸인가(빈 칸은 false, 오타·NaN·Infinity는 true).';



CREATE OR REPLACE FUNCTION "app"."apply_approval_budget_revision"("p_change_document_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_target        uuid;
  v_change_fields jsonb;
  v_change_values jsonb;
  v_target_fields jsonb;
  v_target_values jsonb;
  v_change_key    text;
  v_target_key    text;
  v_before        numeric;
  v_after         numeric;
  v_lost          text;
  v_applied       jsonb;
  v_seq           integer;
begin
  -- 멱등: 이 변경 문서는 한 번만 적용된다.
  if exists (
    select 1 from public.approval_budget_revisions
     where change_document_id = p_change_document_id
  ) then
    return;
  end if;

  select d.budget_document_id, v.fields, d.field_values
    into v_target, v_change_fields, v_change_values
    from public.approval_documents d
    join public.approval_form_versions v on v.id = d.form_version_id
   where d.id = p_change_document_id and d.deleted_at is null;

  if v_target is null then
    raise exception '예산 변경 품의에 대상 품의가 지정되어 있지 않습니다.' using errcode = '22023';
  end if;

  -- 지출 상신·배정 취소와 같은 잠금으로 줄 세우고, 잠근 뒤 멱등 확인을 다시 한다.
  perform app.lock_budget_source(v_target);
  if exists (
    select 1 from public.approval_budget_revisions
     where change_document_id = p_change_document_id
  ) then
    return;
  end if;

  select field_key into v_change_key from app.approval_budget_keys(v_change_fields);
  if v_change_key is null then
    raise exception '예산 변경 품의에 예산표가 없습니다.' using errcode = '22023';
  end if;

  select v.fields, d.field_values into v_target_fields, v_target_values
    from public.approval_documents d
    join public.approval_form_versions v on v.id = d.form_version_id
   where d.id = v_target and d.deleted_at is null
   for update of d;

  select field_key into v_target_key from app.approval_budget_keys(v_target_fields);
  if v_target_key is null then
    raise exception '대상 문서가 예산표를 가진 품의가 아닙니다.' using errcode = '22023';
  end if;

  -- **막는 것은 이것 하나다.** 이미 지출이 걸린 줄이 새 예산표에서 사라지면 그 지출이
  -- 가리킬 자리가 없어진다(금액을 줄이는 것은 막지 않는다 — 음수로 두고 결재자가 본다).
  select string_agg(u.line_id, ', ') into v_lost
    from app.approval_budget_usage(v_target) u
   where (u.spent <> 0 or u.pending <> 0)
     and not exists (
       select 1 from app.approval_budget_lines(v_change_fields, v_change_values) n
        where n.line_id = u.line_id
     );
  if v_lost is not null then
    raise exception '이미 지출이 걸린 예산 줄을 없앨 수 없습니다(줄 %). 금액만 고쳐 주세요.', v_lost
      using errcode = '23514';
  end if;

  select sum(amount) into v_before from app.approval_budget_lines(v_target_fields, v_target_values);
  select sum(amount) into v_after  from app.approval_budget_lines(v_change_fields, v_change_values);

  -- 열 key가 다른 양식으로 변경안을 올렸어도 금액이 대상 양식의 제자리에 앉는다.
  v_applied := app.approval_budget_remap(
    app.approval_budget_field(v_change_fields),
    app.approval_budget_field(v_target_fields),
    coalesce(v_change_values -> v_change_key, '{}'::jsonb)
  );

  -- 상신 검증이 양식끼리의 호환을 이미 보지만, 그것은 **양식**을 본 것이고 여기서 보는 것은
  -- **결과**다. 옮겨 적은 예산표가 대상 양식의 규칙(세 칸 모두 · 합계=공급가액+부가세)을
  -- 어기면 적용하지 않는다 — 반쯤 비어 버린 예산표를 승인 시점에 만들어 두면 그 품의는
  -- 이후 어느 화면에서도 다시 저장되지 않는다. 예산표 한 칸만 놓고 본다(대상 문서의 다른
  -- 칸이 옛 규칙으로 들어와 있어도 변경 적용을 인질로 잡지 않는다).
  perform app.assert_approval_amounts(
    jsonb_build_array(app.approval_budget_field(v_target_fields)),
    jsonb_build_object(v_target_key, v_applied)
  );

  update public.approval_documents
     set field_values = jsonb_set(
           coalesce(field_values, '{}'::jsonb),
           array[v_target_key],
           v_applied,
           true
         ),
         updated_at = now()
   where id = v_target;

  select coalesce(max(seq), 0) + 1 into v_seq
    from public.approval_budget_revisions where target_document_id = v_target;

  insert into public.approval_budget_revisions
    (target_document_id, change_document_id, seq,
     before_total, after_total, before_budget, applied_by)
  values (v_target, p_change_document_id, v_seq, v_before, v_after,
          v_target_values -> v_target_key, app.current_app_user_id())
  on conflict (change_document_id) do nothing;
end;
$$;


ALTER FUNCTION "app"."apply_approval_budget_revision"("p_change_document_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."apply_approval_budget_revision"("p_change_document_id" "uuid") IS '예산 변경 품의가 최종 승인될 때 대상 품의의 예산표를 갈아끼우고 이력을 남긴다. 열 구성이 다르면 역할끼리 옮겨 적고 그 결과를 대상 양식 규칙으로 다시 검증한다. 이미 적용된 변경 문서는 아무 일도 하지 않는다(재시도 안전). 잔액이 음수가 되는 변경도 막지 않는다.';



CREATE OR REPLACE FUNCTION "app"."approval_amount_keys"("p_field" "jsonb") RETURNS TABLE("gross_key" "text", "loose_gross_key" "text", "net_key" "text", "vat_key" "text", "kind_key" "text", "ref_key" "text")
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  c           jsonb;
  v_primary   text;
  v_first_money   text;
  v_first_numeric text;
  v_net       text;
  v_vat       text;
  v_gross     text;
  v_kind      text;
  v_ref       text;
  v_role      text;
begin
  if p_field is null or jsonb_typeof(p_field -> 'columns') <> 'array' then
    return;
  end if;

  for c in select * from jsonb_array_elements(p_field -> 'columns') loop
    if (c->>'type') = 'VAT_KIND' and v_kind is null then
      v_kind := c->>'key';
    end if;
    if (c->>'type') = 'BUDGET_REF' and v_ref is null then
      v_ref := c->>'key';
    end if;
    if (c->>'type') in ('MONEY', 'NUMBER') then
      if v_first_numeric is null then
        v_first_numeric := c->>'key';
      end if;
      if (c->>'type') = 'MONEY' and v_first_money is null then
        v_first_money := c->>'key';
      end if;
      if coalesce((c->>'primaryAmount')::boolean, false) then
        v_primary := c->>'key';
      end if;
      v_role := upper(btrim(coalesce(c->>'role', '')));
      if v_role = 'NET' and v_net is null then
        v_net := c->>'key';
      elsif v_role = 'VAT' and v_vat is null then
        v_vat := c->>'key';
      elsif v_role = 'GROSS' and v_gross is null then
        v_gross := c->>'key';
      end if;
    end if;
  end loop;

  gross_key       := coalesce(v_gross, v_primary, v_first_money);
  loose_gross_key := coalesce(v_gross, v_primary, v_first_numeric);
  net_key         := v_net;
  vat_key         := v_vat;
  kind_key        := v_kind;
  ref_key         := v_ref;
  return next;
end;
$$;


ALTER FUNCTION "app"."approval_amount_keys"("p_field" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."approval_amount_keys"("p_field" "jsonb") IS '표 한 벌의 금액 칸 위치(합계액·공급가액·부가세·과세 유형·예산 줄 참조). 프론트 fields.ts amountColumns와 같은 규칙이며, 역할 열이 없는 옛 양식에서는 합계액 키만 채워진다.';



CREATE OR REPLACE FUNCTION "app"."approval_budget_field"("p_fields" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  select f
    from app.approval_budget_keys(p_fields) k
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(p_fields) = 'array' then p_fields else '[]'::jsonb end
    ) f
   where f->>'key' = k.field_key
   limit 1;
$$;


ALTER FUNCTION "app"."approval_budget_field"("p_fields" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."approval_budget_field"("p_fields" "jsonb") IS '양식 스키마에서 예산표 필드 정의(열 목록 포함)를 통째로 꺼낸다. 예산표가 없으면 null.';



CREATE OR REPLACE FUNCTION "app"."approval_budget_item_amounts"("p_fields" "jsonb", "p_values" "jsonb") RETURNS TABLE("line_id" "text", "net" numeric, "vat" numeric, "gross" numeric, "vat_kind" "text", "split_required" boolean, "bad_amount" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  with fields_in as (
    select f.value as field, f.ord
      from jsonb_array_elements(
             case when jsonb_typeof(p_fields) = 'array' then p_fields else '[]'::jsonb end
           ) with ordinality as f(value, ord)
     where f.value->>'type' = 'BUDGET_TREE'
  ),
  keys as (
    select fi.field, k.gross_key, k.net_key, k.vat_key, k.kind_key
      from fields_in fi
      cross join lateral app.approval_amount_keys(fi.field) k
     where k.gross_key is not null
     order by fi.ord
     limit 1
  ),
  rows_in as (
    select row_number() over () as ord,
           e.value as row_json,
           k.gross_key, k.net_key, k.vat_key, k.kind_key
      from keys k,
           lateral jsonb_array_elements(
             case
               when jsonb_typeof(p_values -> (k.field->>'key') -> 'rows') = 'array'
                 then p_values -> (k.field->>'key') -> 'rows'
               else '[]'::jsonb
             end
           ) e
  ),
  depths as (
    select r.*, coalesce(app.text_to_numeric(r.row_json ->> 'depth'), 0)::int as depth
      from rows_in r
  ),
  leaves as (
    select d.*, lead(d.depth) over (order by d.ord) as next_depth
      from depths d
  )
  select l.row_json ->> 'id',
         case when l.net_key  is null then null
              else app.text_to_numeric(l.row_json -> 'values' ->> l.net_key) end,
         case when l.vat_key  is null then null
              else app.text_to_numeric(l.row_json -> 'values' ->> l.vat_key) end,
         app.text_to_numeric(l.row_json -> 'values' ->> l.gross_key),
         case when l.kind_key is null then null
              else nullif(btrim(coalesce(l.row_json -> 'values' ->> l.kind_key, '')), '') end,
         (l.net_key is not null or l.vat_key is not null or l.kind_key is not null),
         (app.amount_text_bad(l.row_json -> 'values' ->> l.gross_key)
          or (l.net_key is not null
              and app.amount_text_bad(l.row_json -> 'values' ->> l.net_key))
          or (l.vat_key is not null
              and app.amount_text_bad(l.row_json -> 'values' ->> l.vat_key)))
    from leaves l
   where (l.next_depth is null or l.next_depth <= l.depth)
     and coalesce(l.row_json ->> 'id', '') <> '';
$$;


ALTER FUNCTION "app"."approval_budget_item_amounts"("p_fields" "jsonb", "p_values" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."approval_budget_item_amounts"("p_fields" "jsonb", "p_values" "jsonb") IS '품의 예산표의 맨 아래 줄별 (줄 id, 공급가액, 부가세, 합계액, 과세 유형). 역할 열이 없는 옛 문서는 합계액만 채워지고 나머지는 null이다(추정하지 않는다).';



CREATE OR REPLACE FUNCTION "app"."approval_budget_keys"("p_fields" "jsonb") RETURNS TABLE("field_key" "text", "amount_key" "text")
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  f jsonb;
  c jsonb;
  v_primary text;
  v_first   text;
begin
  if p_fields is null or jsonb_typeof(p_fields) <> 'array' then
    return;
  end if;
  for f in select * from jsonb_array_elements(p_fields) loop
    if (f->>'type') <> 'BUDGET_TREE' or jsonb_typeof(f->'columns') <> 'array' then
      continue;
    end if;
    v_primary := null;
    v_first   := null;
    for c in select * from jsonb_array_elements(f->'columns') loop
      if (c->>'type') = 'MONEY' and v_first is null then
        v_first := c->>'key';
      end if;
      if coalesce((c->>'primaryAmount')::boolean, false) and (c->>'type') in ('MONEY', 'NUMBER') then
        v_primary := c->>'key';
      end if;
    end loop;
    field_key  := f->>'key';
    amount_key := coalesce(v_primary, v_first);
    if amount_key is not null then
      return next;
      -- 예산표는 양식당 하나다(프론트 validateSchema가 같은 규칙을 강제한다).
      return;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "app"."approval_budget_keys"("p_fields" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."approval_budget_keys"("p_fields" "jsonb") IS '양식 스키마에서 예산표 필드 key와 그 금액 열 key를 찾는다. 예산표가 없으면 0행이며, "이 양식이 품의서인가"를 이 함수가 답한다.';



CREATE OR REPLACE FUNCTION "app"."approval_budget_lines"("p_fields" "jsonb", "p_values" "jsonb") RETURNS TABLE("line_id" "text", "amount" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  select a.line_id, a.gross from app.approval_budget_item_amounts(p_fields, p_values) a;
$$;


ALTER FUNCTION "app"."approval_budget_lines"("p_fields" "jsonb", "p_values" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."approval_budget_lines"("p_fields" "jsonb", "p_values" "jsonb") IS '품의 예산표의 맨 아래 줄(줄 id, 합계액). 모든 차감·비교는 부가세 포함 합계액 기준이다. 세부 칸은 app.approval_budget_item_amounts가 갖는다.';



CREATE OR REPLACE FUNCTION "app"."approval_budget_remap"("p_from" "jsonb", "p_to" "jsonb", "p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_fg text; v_fn text; v_fv text; v_fk text;
  v_tg text; v_tn text; v_tv text; v_tk text;
  v_to_keys   text[];
  v_role_keys text[];
  v_rows   jsonb := '[]'::jsonb;
  v_row    jsonb;
  v_values jsonb;
  v_pair   text[];
  k        text;
begin
  -- 어느 한쪽이라도 열 구성을 모르면 손대지 않는다(옛 동작 그대로 베낀다).
  if p_value is null or jsonb_typeof(p_value -> 'rows') <> 'array'
     or jsonb_typeof(p_from -> 'columns') <> 'array'
     or jsonb_typeof(p_to -> 'columns') <> 'array' then
    return p_value;
  end if;

  select gross_key, net_key, vat_key, kind_key into v_fg, v_fn, v_fv, v_fk
    from app.approval_amount_keys(p_from);
  select gross_key, net_key, vat_key, kind_key into v_tg, v_tn, v_tv, v_tk
    from app.approval_amount_keys(p_to);

  select coalesce(array_agg(c->>'key'), '{}'::text[]) into v_to_keys
    from jsonb_array_elements(p_to -> 'columns') c;
  v_role_keys := array_remove(array[v_fg, v_fn, v_fv, v_fk], null);

  for v_row in select * from jsonb_array_elements(p_value -> 'rows') loop
    v_values := '{}'::jsonb;
    -- 역할 없는 칸(수량·단가·비고)은 key가 대상에도 있을 때만 따라간다.
    for k in select key from jsonb_each(coalesce(v_row -> 'values', '{}'::jsonb)) loop
      if k = any(v_to_keys) and not (k = any(v_role_keys)) then
        v_values := v_values || jsonb_build_object(k, v_row -> 'values' -> k);
      end if;
    end loop;
    foreach v_pair slice 1 in array array[
      array[v_fg, v_tg], array[v_fn, v_tn], array[v_fv, v_tv], array[v_fk, v_tk]
    ] loop
      if v_pair[1] is not null and v_pair[2] is not null
         and (v_row -> 'values') ? v_pair[1] then
        v_values := v_values || jsonb_build_object(v_pair[2], v_row -> 'values' -> v_pair[1]);
      end if;
    end loop;
    -- 줄 id·층·이름은 건드리지 않는다 — id가 바뀌면 나간 지출이 가리킬 자리가 사라진다.
    v_rows := v_rows || jsonb_build_array(v_row || jsonb_build_object('values', v_values));
  end loop;

  return p_value || jsonb_build_object('rows', v_rows);
end;
$$;


ALTER FUNCTION "app"."approval_budget_remap"("p_from" "jsonb", "p_to" "jsonb", "p_value" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."approval_budget_remap"("p_from" "jsonb", "p_to" "jsonb", "p_value" "jsonb") IS '예산표 값을 다른 양식의 열 key로 옮긴다(금액 역할끼리 맞추고, 대상에 없는 칸은 버린다). 화면 budgetRemap.ts와 같은 규칙이며 공급가액·부가세를 추정해 채우지 않는다.';



CREATE OR REPLACE FUNCTION "app"."approval_budget_usage"("p_document_id" "uuid") RETURNS TABLE("line_id" "text", "spent" numeric, "pending" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
  select u.line_id, u.spent, u.pending
    from app.approval_budget_usage_ex(p_document_id, null) u;
$$;


ALTER FUNCTION "app"."approval_budget_usage"("p_document_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."approval_budget_usage"("p_document_id" "uuid") IS '품의 한 건의 예산 줄별 사용액(승인 완료)과 예약액(결재 중). 저장하지 않고 매번 집계한다. public.approval_budget_status가 게이트를 지나 이 함수를 부른다.';



CREATE OR REPLACE FUNCTION "app"."approval_budget_usage_ex"("p_document_id" "uuid", "p_exclude_document_id" "uuid") RETURNS TABLE("line_id" "text", "spent" numeric, "pending" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
  select s.line_id,
         coalesce(sum(s.amount) filter (where d.status = 'APPROVED'), 0),
         coalesce(sum(s.amount) filter (
           where d.status in ('PENDING', 'IN_REVIEW', 'REVISION_REQUIRED')
         ), 0)
    from public.approval_documents d
    join public.approval_form_versions v on v.id = d.form_version_id
    cross join lateral app.approval_spend_lines(v.fields, d.field_values) s
   where d.budget_document_id = p_document_id
     and d.deleted_at is null
     and (p_exclude_document_id is null or d.id <> p_exclude_document_id)
     and coalesce(s.line_id, '') <> ''
   group by s.line_id;
$$;


ALTER FUNCTION "app"."approval_budget_usage_ex"("p_document_id" "uuid", "p_exclude_document_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."approval_budget_usage_ex"("p_document_id" "uuid", "p_exclude_document_id" "uuid") IS '품의 한 건의 예산 줄별 사용액·예약액. 두 번째 인자로 받은 문서는 집계에서 뺀다(상신하려는 문서가 자기 예약을 자기 잔액에서 두 번 빼지 않게 한다). 호출자 검증이 없으므로 authenticated에 열지 않는다.';



CREATE OR REPLACE FUNCTION "app"."approval_current_round"("target_document_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
  select coalesce(max(round), 1)
    from public.approval_lines
   where document_id = target_document_id;
$$;


ALTER FUNCTION "app"."approval_current_round"("target_document_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."approval_current_round"("target_document_id" "uuid") IS '문서의 현재 결재 회차(max(round), 결재선이 없으면 1). 모든 진행 판정의 기준.';



CREATE OR REPLACE FUNCTION "app"."approval_primary_amount"("p_fields" "jsonb", "p_values" "jsonb") RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  f jsonb;
  c jsonb;
  v numeric;
begin
  if p_fields is null or jsonb_typeof(p_fields) <> 'array' then
    return null;
  end if;
  for f in select * from jsonb_array_elements(p_fields) loop
    if (f->>'type') in ('MONEY', 'NUMBER')
       and coalesce((f->>'primaryAmount')::boolean, false) then
      return app.text_to_numeric(p_values ->> (f->>'key'));

    elsif (f->>'type') = 'BUDGET_TREE' then
      -- 예산표의 대표 금액은 맨 아래 줄들의 합이다. 대표 금액 표시가 붙은 열이 있을 때만
      -- 문서 금액이 된다 — 표시가 없으면 아래 TABLE 분기가 계속 자기 차례를 갖는다.
      if exists (
        select 1
          from jsonb_array_elements(coalesce(f->'columns', '[]'::jsonb)) col
         where coalesce((col.value->>'primaryAmount')::boolean, false)
      ) then
        select sum(l.amount) into v
          from app.approval_budget_lines(jsonb_build_array(f), p_values) l;
        return v;
      end if;

    elsif (f->>'type') = 'TABLE' and jsonb_typeof(f->'columns') = 'array' then
      for c in select * from jsonb_array_elements(f->'columns') loop
        if (c->>'type') in ('MONEY', 'NUMBER')
           and coalesce((c->>'primaryAmount')::boolean, false) then
          select sum(app.text_to_numeric(r.value->>(c->>'key'))) into v
            from jsonb_array_elements(coalesce(p_values->(f->>'key'), '[]'::jsonb)) r;
          return v;
        end if;
      end loop;
    end if;
  end loop;
  return null;
end;
$$;


ALTER FUNCTION "app"."approval_primary_amount"("p_fields" "jsonb", "p_values" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."approval_spend_item_amounts"("p_fields" "jsonb", "p_values" "jsonb") RETURNS TABLE("line_id" "text", "net" numeric, "vat" numeric, "gross" numeric, "vat_kind" "text", "split_required" boolean, "bad_amount" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  with fields_in as (
    select f.value as field, f.ord
      from jsonb_array_elements(
             case when jsonb_typeof(p_fields) = 'array' then p_fields else '[]'::jsonb end
           ) with ordinality as f(value, ord)
     where f.value->>'type' = 'TABLE'
  ),
  keys as (
    select fi.field, k.loose_gross_key as gross_key, k.net_key, k.vat_key, k.kind_key, k.ref_key
      from fields_in fi
      cross join lateral app.approval_amount_keys(fi.field) k
     where k.ref_key is not null
  )
  -- **예산 줄을 고르지 않은 행도 돌려준다**(line_id가 null). 여기서 버리면 금액만 적고
  -- 줄을 비운 행이 조용히 사라져, 어느 예산도 깎지 않은 채 결재가 흐른다. 버리는 자리는
  -- 집계(app.approval_spend_lines)이고 거절하는 자리는 검증이다.
  select nullif(btrim(coalesce(r.value ->> k.ref_key, '')), ''),
         case when k.net_key  is null then null
              else app.text_to_numeric(r.value ->> k.net_key) end,
         case when k.vat_key  is null then null
              else app.text_to_numeric(r.value ->> k.vat_key) end,
         case when k.gross_key is null then null
              else app.text_to_numeric(r.value ->> k.gross_key) end,
         case when k.kind_key is null then null
              else nullif(btrim(coalesce(r.value ->> k.kind_key, '')), '') end,
         (k.net_key is not null or k.vat_key is not null or k.kind_key is not null),
         ((k.gross_key is not null and app.amount_text_bad(r.value ->> k.gross_key))
          or (k.net_key is not null and app.amount_text_bad(r.value ->> k.net_key))
          or (k.vat_key is not null and app.amount_text_bad(r.value ->> k.vat_key)))
    from keys k,
         lateral jsonb_array_elements(
           case when jsonb_typeof(p_values -> (k.field->>'key')) = 'array'
                then p_values -> (k.field->>'key')
                else '[]'::jsonb
           end
         ) r;
$$;


ALTER FUNCTION "app"."approval_spend_item_amounts"("p_fields" "jsonb", "p_values" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."approval_spend_item_amounts"("p_fields" "jsonb", "p_values" "jsonb") IS '지출결의 문서의 항목별 (예산 줄 id, 공급가액, 부가세, 합계액, 과세 유형). 예산 줄 열을 가진 표를 모두 읽으며, 줄을 고르지 않은 행도 line_id=null로 돌려준다(검증이 거절한다).';



CREATE OR REPLACE FUNCTION "app"."approval_spend_lines"("p_fields" "jsonb", "p_values" "jsonb") RETURNS TABLE("line_id" "text", "amount" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  select a.line_id, a.gross
    from app.approval_spend_item_amounts(p_fields, p_values) a
   where a.line_id is not null;
$$;


ALTER FUNCTION "app"."approval_spend_lines"("p_fields" "jsonb", "p_values" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."approval_spend_lines"("p_fields" "jsonb", "p_values" "jsonb") IS '지출결의 문서에서 (예산 줄 id, 합계액) 목록. 부가세 포함 합계액 기준이며 세부 칸은 app.approval_spend_item_amounts가 갖는다.';



CREATE OR REPLACE FUNCTION "app"."approval_vat_rate"("p_kind" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case upper(btrim(coalesce(p_kind, '')))
    when 'TAXABLE'     then 0.1
    when 'EXEMPT'      then 0
    when 'ZERO_RATED'  then 0
    when 'NOT_TAXABLE' then 0
    else null
  end;
$$;


ALTER FUNCTION "app"."approval_vat_rate"("p_kind" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."approval_vat_rate"("p_kind" "text") IS '과세 유형의 세율. TAXABLE=0.1, EXEMPT·ZERO_RATED·NOT_TAXABLE=0, 그 밖(빈 값·모르는 값)은 null이다. null을 0이나 0.1로 되돌리지 않는 것이 "과세 유형을 추정하지 않는다"의 실체다.';



CREATE OR REPLACE FUNCTION "app"."assert_approval_amounts"("p_fields" "jsonb", "p_values" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  r      record;
  v_rate numeric;
begin
  for r in
    select false as is_spend, a.line_id, a.net, a.vat, a.gross, a.vat_kind,
           a.split_required, a.bad_amount
      from app.approval_budget_item_amounts(p_fields, p_values) a
    union all
    select true, b.line_id, b.net, b.vat, b.gross, b.vat_kind, b.split_required, b.bad_amount
      from app.approval_spend_item_amounts(p_fields, p_values) b
  loop
    -- 빈 행 판정보다 **먼저** 본다 — 오타는 모두 null로 읽혀 '안 쓴 행'으로 빠져나간다.
    if coalesce(r.bad_amount, false) then
      raise exception '금액을 숫자로 읽을 수 없습니다(항목 %). 숫자만 적어 주세요.', r.line_id
        using errcode = '23514';
    end if;

    -- 아무 숫자도 적히지 않은 행은 아직 쓰지 않은 행이다.
    if r.net is null and r.vat is null and r.gross is null then
      continue;
    end if;

    -- 금액이 적힌 지출 행은 반드시 예산 줄을 가리켜야 한다. 비워 두면 어느 예산도 깎지 않는다.
    if r.is_spend and r.line_id is null then
      raise exception '지출 항목에 예산 줄을 선택해 주세요.' using errcode = '23502';
    end if;

    -- 부가세 칸이 없는 옛 양식 — 합계액 하나만 있다. 유효 금액만 본다.
    if not r.split_required then
      if r.gross < 0 then
        raise exception '금액은 0원 이상이어야 합니다(항목 %).', r.line_id using errcode = '23514';
      end if;
      continue;
    end if;

    if r.net is null or r.vat is null or r.gross is null then
      raise exception '공급가액·부가세·합계액을 모두 입력해 주세요(항목 %).', r.line_id
        using errcode = '23514';
    end if;
    if r.net < 0 or r.vat < 0 or r.gross < 0 then
      raise exception '금액은 0원 이상이어야 합니다(항목 %).', r.line_id using errcode = '23514';
    end if;

    -- 과세 유형 칸이 없는 양식도 있으므로 **적혀 있을 때만** 본다. 적혀 있는데 모르는 값이면
    -- 그 칸이 뜻을 잃은 것이라 통과시키지 않는다(빈 값으로 되돌리지도 않는다).
    if r.vat_kind is not null then
      v_rate := app.approval_vat_rate(r.vat_kind);
      if v_rate is null then
        raise exception '항목의 과세 유형이 올바르지 않습니다(항목 %). 과세·면세·영세율·과세대상 아님 중 하나여야 합니다.',
          r.line_id using errcode = '23514';
      end if;
      -- 세율이 0인 유형에 세액이 붙어 있으면 둘 중 하나가 틀린 것이다. 어느 쪽인지 서버가
      -- 정할 수 없으므로 고르게 돌려보낸다.
      if v_rate = 0 and r.vat <> 0 then
        raise exception '부가세가 없는 과세 유형인데 세액이 적혀 있습니다(항목 %).', r.line_id
          using errcode = '23514';
      end if;
    end if;
    -- 증빙에 따른 세액 수정을 허용하므로 공급가액×세율을 강제하지 않는다. 다만 합계가
    -- 맞지 않으면 어느 숫자로 예산을 깎아야 하는지 알 수 없다.
    if r.gross <> r.net + r.vat then
      raise exception '합계액이 공급가액+부가세와 다릅니다(항목 %).', r.line_id
        using errcode = '23514';
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "app"."assert_approval_amounts"("p_fields" "jsonb", "p_values" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."assert_approval_amounts"("p_fields" "jsonb", "p_values" "jsonb") IS '문서의 예산·지출 항목 금액 정합성(숫자로 읽히는 값 · 예산 줄 참조 · 세 칸 모두 입력 · 0원 이상 · 과세 유형 유효 · 세율 0이면 세액 0 · 합계액=공급가액+부가세). 부가세 칸이 없는 옛 양식과 정말 빈 행만 통과한다.';



CREATE OR REPLACE FUNCTION "app"."assert_budget_spend_submittable"("p_document_id" "uuid", "p_form_id" "uuid", "p_form_version_id" "uuid", "p_field_values" "jsonb", "p_budget_document_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_source     uuid := p_budget_document_id;
  v_link       text;
  v_fields     jsonb;
  v_values     jsonb := coalesce(p_field_values, '{}'::jsonb);
  v_src_status public.approval_status;
  v_src_link   text;
  v_src_fields jsonb;
  v_src_values jsonb;
  r            record;
  v_t_net      text;
  v_t_vat      text;
  v_c_net      text;
  v_c_vat      text;
  v_budget     numeric;
  v_used       numeric;
  v_avail      numeric;
  v_links      integer;
begin
  select f.budget_link into v_link from public.approval_forms f where f.id = p_form_id;
  select v.fields into v_fields
    from public.approval_form_versions v where v.id = p_form_version_id;

  -- 양식 버전이 붙지 않은 문서(이관 복원본 등)는 검증할 표가 없다.
  if v_fields is null then
    return;
  end if;

  -- 금액 정합성은 근거 품의가 있든 없든 본다(품의서 자신의 예산표도 여기서 걸린다).
  perform app.assert_approval_amounts(v_fields, v_values);

  -- **예산을 배정하는 품의는 워크스페이스 한 곳에 걸린 뒤에만 상신된다.**
  -- 트리거(11)는 '둘 이상 걸지 못한다'까지만 말하고 0건은 막지 못한다 — 화면만 강제하면
  -- 직접 INSERT·UPDATE로 배정 없는 승인 품의가 서고, 그 예산은 어느 사업에도 잡히지 않은 채
  -- 지출만 받는다. 배정 품의의 정의는 (11)과 같다: 예산표 보유 + budget_link <> 'REVISE'.
  if coalesce(v_link, 'NONE') <> 'REVISE'
     and exists (select 1 from app.approval_budget_keys(v_fields)) then
    select count(*) into v_links
      from public.approval_program_links l
     where l.document_id = p_document_id
       and l.deleted_at is null;
    if v_links <> 1 then
      raise exception '예산을 배정하는 품의는 사업 워크스페이스 한 곳에 연결한 뒤 상신할 수 있습니다.'
        using errcode = '23502';
    end if;
  end if;

  if coalesce(v_link, 'NONE') = 'SPEND_REQUIRED' and v_source is null then
    raise exception '이 양식은 근거 품의가 필요합니다.' using errcode = '22023';
  end if;
  if v_source is null then
    return;
  end if;

  perform app.lock_budget_source(v_source);

  select d.status, coalesce(sf.budget_link, 'NONE'), v.fields, d.field_values
    into v_src_status, v_src_link, v_src_fields, v_src_values
    from public.approval_documents d
    join public.approval_form_versions v on v.id = d.form_version_id
    left join public.approval_forms sf on sf.id = d.form_id
   where d.id = v_source and d.deleted_at is null;

  if not found then
    raise exception '근거 품의를 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  -- 승인된 품의만 근거가 된다 — 흐르는 중인 예산은 결재 도중 바뀌어 차감의 근거가 흔들린다.
  if v_src_status <> 'APPROVED' then
    raise exception '근거 품의가 최종 승인되지 않았습니다.' using errcode = '42501';
  end if;
  -- 근거는 **원 배정 품의**다. 변경 품의도 예산표를 갖지만 그 금액은 원 품의에 이미
  -- 반영되어 있어, 다시 근거로 삼으면 같은 돈을 두 번 쓴다.
  if v_src_link = 'REVISE' then
    raise exception '예산 변경 품의는 근거 품의가 될 수 없습니다.' using errcode = '42501';
  end if;

  -- 예산 변경 품의(대상 품의를 가리키는 문서)는 잔액을 쓰는 것이 아니라 예산을 바꾸는 것이라
  -- 초과 검사를 받지 않는다. 무엇을 하는 문서인지는 양식의 budget_link가 답한다.
  if coalesce(v_link, 'NONE') = 'REVISE' then
    -- 다만 **표현할 수 없는 변경안은 막는다.** 대상이 공급가액·부가세 칸을 가진 양식인데
    -- 변경 양식에 그 칸이 없으면, 적용하는 순간 대상에 적힌 부가세가 조용히 지워진다.
    select k.net_key, k.vat_key into v_t_net, v_t_vat
      from app.approval_amount_keys(app.approval_budget_field(v_src_fields)) k;
    select k.net_key, k.vat_key into v_c_net, v_c_vat
      from app.approval_amount_keys(app.approval_budget_field(v_fields)) k;
    if (v_t_net is not null and v_c_net is null)
       or (v_t_vat is not null and v_c_vat is null) then
      raise exception
        '대상 품의는 공급가액·부가세 칸을 쓰는 양식입니다. 같은 칸을 가진 예산 변경 양식으로 작성해 주세요.'
        using errcode = '23514';
    end if;
    return;
  end if;

  for r in
    select s.line_id, sum(s.amount) as amount
      from app.approval_spend_lines(v_fields, v_values) s
     where coalesce(s.line_id, '') <> ''
     group by s.line_id
  loop
    select b.amount into v_budget
      from app.approval_budget_lines(v_src_fields, v_src_values) b
     where b.line_id = r.line_id;
    if not found then
      raise exception '근거 품의에 없는 예산 항목입니다(항목 %).', r.line_id using errcode = '23503';
    end if;

    select coalesce(u.spent, 0) + coalesce(u.pending, 0) into v_used
      from app.approval_budget_usage_ex(v_source, p_document_id) u
     where u.line_id = r.line_id;

    v_avail := coalesce(v_budget, 0) - coalesce(v_used, 0);
    if coalesce(r.amount, 0) > v_avail then
      raise exception
        '예산 항목의 사용 가능액을 초과합니다(항목 %, 사용 가능 %원, 신청 %원).',
        r.line_id,
        to_char(v_avail, 'FM999,999,999,999,990'),
        to_char(coalesce(r.amount, 0), 'FM999,999,999,999,990')
        using errcode = '23514';
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "app"."assert_budget_spend_submittable"("p_document_id" "uuid", "p_form_id" "uuid", "p_form_version_id" "uuid", "p_field_values" "jsonb", "p_budget_document_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."assert_budget_spend_submittable"("p_document_id" "uuid", "p_form_id" "uuid", "p_form_version_id" "uuid", "p_field_values" "jsonb", "p_budget_document_id" "uuid") IS '상신 직전 검증 — 금액 정합성, 배정 품의의 워크스페이스 연결 정확히 1건, 근거 품의 필수·승인 여부, 예산 항목 존재, 항목별 사용 가능액 초과. 값은 인자로 받는다(BEFORE 트리거가 기록 전 NEW를 검증한다). 근거 품의 단위 잠금으로 동시 상신·배정 취소를 줄 세우며, 최종 승인 단계에서는 다시 검사하지 않는다.';



CREATE OR REPLACE FUNCTION "app"."assert_no_active_budget_children"("p_document_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_count integer;
begin
  -- 지출 상신과 같은 잠금이다 — 다른 키로 잠그면 상신 중에 배정이 걷히는 창이 남는다.
  perform app.lock_budget_source(p_document_id);

  select count(*) into v_count
    from public.approval_documents d
    left join public.approval_forms f on f.id = d.form_id
   where d.budget_document_id = p_document_id
     and d.deleted_at is null
     and d.status in ('PENDING', 'IN_REVIEW', 'REVISION_REQUIRED', 'APPROVED')
     -- **끝난 예산 변경은 세지 않는다.** 이미 적용된 변경은 지금 예산표 안에 녹아 있는
     -- 이력이지 살아 있는 지출이 아니다. 세면 한 번이라도 예산을 고친 품의는 영원히
     -- 취소할 수 없게 된다. 아직 흐르는 변경 문서는 그대로 막는다.
     and not (
       coalesce(f.budget_link, 'NONE') = 'REVISE'
       and d.status = 'APPROVED'
     );

  if v_count > 0 then
    raise exception
      '이 품의를 근거로 하는 지출·변경 문서 %건이 남아 있어 승인을 취소할 수 없습니다. 먼저 그 문서들을 회수하거나 취소해 주세요.',
      v_count using errcode = '23504';
  end if;
end;
$$;


ALTER FUNCTION "app"."assert_no_active_budget_children"("p_document_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."assert_no_active_budget_children"("p_document_id" "uuid") IS '이 품의를 근거로 하는 살아 있는 지출/흐르는 변경 문서가 있으면 예외를 던진다. 이미 적용이 끝난 예산 변경 이력은 세지 않는다. 지출 상신과 같은 자문 잠금을 공유한다.';



CREATE OR REPLACE FUNCTION "app"."assert_program_exists"("p_entity_key" "text", "p_program_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_table text;
  v_found boolean;
begin
  v_table := case p_entity_key
    when 'program'    then 'programs'
    when 'ma_program' then 'ma_programs'
    when 'fund'       then 'funds'
  end;
  if v_table is null then
    return false;
  end if;
  -- 화이트리스트로 고른 이름만 들어가므로 동적 SQL 주입면이 없다.
  execute format('select exists (select 1 from public.%I where id = $1)', v_table)
    into v_found using p_program_id;
  return v_found;
end;
$_$;


ALTER FUNCTION "app"."assert_program_exists"("p_entity_key" "text", "p_program_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."assert_program_exists"("p_entity_key" "text", "p_program_id" "uuid") IS '다형 program_id가 entity_key가 지목한 사업 원장에 실재하는가. FK를 걸 수 없는 통합 원장의 참조 무결성 검사.';



CREATE OR REPLACE FUNCTION "app"."attachment_ref_sources"("p_target_type" "text", "p_target_id" "uuid" DEFAULT NULL::"uuid", "p_link_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("ref_type" "text", "ref_id" "uuid")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  -- M&A SELLER → 연결된 STARTUP 한 행.
  -- 조인이 곧 권한 판정이다 — 그 기업을 못 읽는 사람에게는 이 줄이 나오지 않는다.
  select 'startup'::text, s.id
    from public.startups s
   where p_target_type = 'ma_seller'
     and s.deleted_at is null
     and s.id = coalesce(
           -- 폼이 방금 고른 연결이 있으면 그것이 답이다(등록 화면에는 저장된 행이 없다).
           p_link_id,
           (select ms.startup_id
              from public.ma_sellers ms
             where ms.id = p_target_id
               and ms.deleted_at is null)
         );
$$;


ALTER FUNCTION "app"."attachment_ref_sources"("p_target_type" "text", "p_target_id" "uuid", "p_link_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."attachment_ref_sources"("p_target_type" "text", "p_target_id" "uuid", "p_link_id" "uuid") IS '이 대상이 자료를 함께 보는 다른 대상들(다형 키). 참조의 방향은 오직 이 함수의 분기가 정한다 — 첨부 행에 적지 않는 이유는 방향이 데이터가 되면 한 건씩 어긋날 수 있고 새 방향을 열 때 기존 행을 전부 고쳐야 하기 때문이다. p_link_id는 아직 저장되지 않은 연결(등록 화면)을 위한 후보이며, 후보의 열람 자격은 여전히 조인하는 원장의 RLS가 판정한다. INVOKER.';



CREATE OR REPLACE FUNCTION "app"."attendance_auto_status"("p_check_in" timestamp with time zone, "p_check_out" timestamp with time zone, "p_check_in_to" time without time zone, "p_work_min" integer) RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  select case
    when p_check_in is null then 'ABSENT'
    else case
      when ((p_check_in at time zone 'Asia/Seoul')::time > p_check_in_to)
       and (p_check_out is not null
            and p_check_out < p_check_in + make_interval(mins => p_work_min))
        then 'LATE_EARLY'
      when ((p_check_in at time zone 'Asia/Seoul')::time > p_check_in_to)
        then 'LATE'
      when (p_check_out is not null
            and p_check_out < p_check_in + make_interval(mins => p_work_min))
        then 'EARLY_LEAVE'
      else 'NORMAL'
    end
  end;
$$;


ALTER FUNCTION "app"."attendance_auto_status"("p_check_in" timestamp with time zone, "p_check_out" timestamp with time zone, "p_check_in_to" time without time zone, "p_work_min" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."audit_kpi_definition_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  insert into public.audit_logs
    (actor_user_id, action, changed_workspace, before_data, after_data, reason)
  values (
    app.current_app_user_id(), 'KPI_' || tg_op, 'management',
    case when tg_op = 'UPDATE' then to_jsonb(old) end,
    to_jsonb(new), tg_table_name
  );
  return new;
end $$;


ALTER FUNCTION "app"."audit_kpi_definition_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."audit_networks_merge"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  -- 인자를 주지 않은 옛 트리거 정의는 종전대로 동작한다(이 파일이 전부 다시 붙이지만,
  -- 다른 마이그레이션이 인자 없이 붙여 두었을 수 있다).
  v_ws text := coalesce(tg_argv[0], 'networks');
begin
  if tg_op = 'UPDATE'
     and new.merged_into_id is distinct from old.merged_into_id
     and new.merged_into_id is not null then
    insert into public.audit_logs (
      actor_user_id, action, changed_workspace, before_data, after_data, reason
    )
    values (
      app.current_app_user_id(),
      -- action은 원장이 아니라 **행위**를 부른다. 워크스페이스는 옆 칸이 답하므로
      -- 이름에 두 번 적지 않는다(종전 `NETWORKS_MERGE`는 그 둘을 붙여 놓은 값이었다).
      'ENTITY_MERGE',
      v_ws,
      jsonb_build_object('table', tg_table_name, 'id', new.id),
      jsonb_build_object('merged_into_id', new.merged_into_id),
      nullif(current_setting('app.audit_reason', true), '')
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app"."audit_networks_merge"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."audit_networks_merge"() IS '중복 병합(merged_into_id 설정)을 audit_logs에 적재한다. 워크스페이스는 트리거 인자(tg_argv[0])가 정한다 — 한 함수가 원장 넷에 붙으므로 함수 안에 박으면 그 값이 반드시 어느 원장에서 틀린다. 이미 쌓인 행은 고치지 않는다(감사 로그는 그때의 사실이다).';



CREATE OR REPLACE FUNCTION "app"."audit_permission_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  insert into public.audit_logs (
    actor_user_id, target_user_id, action, changed_workspace,
    before_permission, after_permission, reason, request_ip, user_agent
  )
  values (
    app.current_app_user_id(),
    new.user_id,
    'PERMISSION_CHANGE',
    new.workspace_key::text,
    case when tg_op = 'UPDATE' then old.permission_level::text else null end,
    new.permission_level::text,
    nullif(current_setting('app.audit_reason', true), ''),
    nullif(current_setting('app.request_ip', true), '')::inet,
    nullif(current_setting('app.user_agent', true), '')
  );
  return new;
end;
$$;


ALTER FUNCTION "app"."audit_permission_change"() OWNER TO "postgres";


