CREATE OR REPLACE FUNCTION "app"."cascade_program_children"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_key text := tg_argv[0];
begin
  -- 자식(assignees·내용물)은 program_modules FK의 on delete cascade가 이어서 지운다.
  delete from public.program_modules       where entity_key = v_key and program_id = old.id;
  delete from public.program_posts         where entity_key = v_key and program_id = old.id;
  delete from public.program_links         where entity_key = v_key and program_id = old.id;
  delete from public.program_participants  where entity_key = v_key and program_id = old.id;
  delete from public.program_overviews     where entity_key = v_key and program_id = old.id;
  delete from public.program_announcements where entity_key = v_key and program_id = old.id;
  delete from public.program_questions     where entity_key = v_key and program_id = old.id;
  delete from public.program_participant_entries
         where entity_key = v_key and program_id = old.id;
  return old;
end;
$$;


ALTER FUNCTION "app"."cascade_program_children"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."cascade_program_children"() IS '사업 물리 삭제 시 통합 원장의 소속 행을 함께 지운다. FK를 뗀 자리를 메우는 장치이며, 운영에서는 사업이 soft delete되므로 실제로는 시드 정리 경로에서만 탄다.';



CREATE OR REPLACE FUNCTION "app"."check_approval_budget_ref"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_ok boolean;
begin
  if NEW.budget_document_id is null then
    return NEW;
  end if;
  if TG_OP = 'UPDATE' and NEW.budget_document_id is not distinct from OLD.budget_document_id then
    return NEW;
  end if;

  select exists (
    select 1
      from public.approval_documents d
      join public.approval_form_versions v on v.id = d.form_version_id
      cross join lateral app.approval_budget_keys(v.fields) k
     where d.id = NEW.budget_document_id and d.deleted_at is null
  ) into v_ok;

  if not v_ok then
    raise exception '예산표를 가진 품의만 근거로 지정할 수 있습니다.' using errcode = '23514';
  end if;
  return NEW;
end;
$$;


ALTER FUNCTION "app"."check_approval_budget_ref"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."check_approval_program_link_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_status    public.approval_status;
  v_allocates boolean;
  v_other     integer;
begin
  -- 배정 품의의 정의: 예산표(BUDGET_TREE)를 가지고, 남의 예산을 고치는 변경 품의가 아닌 것.
  select d.status,
         exists (
           select 1
             from public.approval_form_versions v
             cross join lateral app.approval_budget_keys(v.fields) k
            where v.id = d.form_version_id
         )
         and coalesce(f.budget_link, 'NONE') <> 'REVISE'
    into v_status, v_allocates
    from public.approval_documents d
    left join public.approval_forms f on f.id = d.form_id
   where d.id = NEW.document_id;

  if not found then
    return NEW;
  end if;

  -- 최종 승인된 배정 품의의 배정은 걸지도, 옮기지도, 떼지도 못한다 — 그 워크스페이스의
  -- 예산 총액이 이 한 줄에 달려 있기 때문이다.
  -- INSERT 분기를 따로 두는 이유는 그 경우 OLD가 배정되지 않아 참조하는 순간 죽기 때문이다.
  if v_status = 'APPROVED' and coalesce(v_allocates, false) then
    if TG_OP = 'INSERT' then
      raise exception '최종 승인된 예산 배정 품의에는 워크스페이스 배정을 새로 걸 수 없습니다.'
        using errcode = '42501';
    elsif NEW.target_type is distinct from OLD.target_type
       or NEW.target_id   is distinct from OLD.target_id
       or NEW.deleted_at  is distinct from OLD.deleted_at
    then
      raise exception '최종 승인된 예산 배정 품의의 워크스페이스 배정은 바꿀 수 없습니다.'
        using errcode = '42501';
    end if;
  end if;

  if coalesce(v_allocates, false) and NEW.deleted_at is null then
    -- 조건부 유일성이라 부분 유니크 인덱스로 세울 수 없다('예산표를 가진 문서인가'는
    -- 이 표의 열이 아니다). 동시 삽입 둘이 서로를 못 보는 창을 자문 잠금으로 닫는다.
    perform pg_advisory_xact_lock(
      hashtextextended('approval_program_link:' || NEW.document_id::text, 0)
    );
    select count(*) into v_other
      from public.approval_program_links l
     where l.document_id = NEW.document_id
       and l.deleted_at is null
       and l.id <> NEW.id;
    if v_other > 0 then
      raise exception '예산을 배정하는 품의는 워크스페이스 한 곳에만 연결할 수 있습니다.'
        using errcode = '23505';
    end if;
  end if;

  return NEW;
end;
$$;


ALTER FUNCTION "app"."check_approval_program_link_rules"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."check_approval_program_link_rules"() IS '워크스페이스 배정 규칙 — 예산을 배정하는 품의(예산표 보유, budget_link<>REVISE)만 한 곳에 묶이고 승인 뒤 배정이 불변이다. 일반 결재와 예산 변경 품의는 여러 곳에 연결할 수 있다.';



CREATE OR REPLACE FUNCTION "app"."check_approval_submission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if NEW.status not in ('PENDING', 'IN_REVIEW') then
    return NEW;
  end if;
  -- 상신은 기안자 손에 있던 문서가 흐름에 들어서는 때뿐이다. 결재 진행과 승인 취소
  -- (APPROVED → 진행 중)는 상신이 아니므로 초과 검사를 걸지 않는다 — 걸면 예산이 줄어든
  -- 뒤에는 승인 취소가 영구히 막힌다.
  if TG_OP = 'UPDATE' and OLD.status not in ('DRAFT', 'REVISION_REQUIRED', 'REJECTED') then
    return NEW;
  end if;
  if NEW.deleted_at is not null then
    return NEW;
  end if;

  perform app.assert_budget_spend_submittable(
    NEW.id, NEW.form_id, NEW.form_version_id, NEW.field_values, NEW.budget_document_id
  );
  return NEW;
end;
$$;


ALTER FUNCTION "app"."check_approval_submission"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."check_approval_submission"() IS '기안 상태(DRAFT·REVISION_REQUIRED·REJECTED)나 신규 INSERT로 흐름에 들어설 때만 예산·금액 검증을 건다. 결재 진행과 승인 취소는 통과시킨다 — 초과는 상신에서만 막는다.';



CREATE OR REPLACE FUNCTION "app"."clear_dept_members_on_dept_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  update public.dept_members
     set deleted_at = now()
   where department_id = new.id
     and deleted_at is null;

  update public.users
     set department_id = null
   where department_id = new.id;

  return new;
end;
$$;


ALTER FUNCTION "app"."clear_dept_members_on_dept_delete"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."clear_dept_members_on_dept_delete"() IS '조직 soft delete 시 해당 조직의 인력 배치(dept_members)와 활성 버전 미러(users.department_id)를 함께 끊는다.';



CREATE OR REPLACE FUNCTION "app"."clone_approval_full_round"("p_document_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_round integer := app.approval_current_round(p_document_id);
  v_next  integer := v_round + 1;
begin
  insert into public.approval_lines
    (document_id, approver_id, step_order, kind, round, decision)
  select l.document_id, l.approver_id, l.step_order, l.kind, v_next,
         'PENDING'::public.approval_decision
    from public.approval_lines l
   where l.document_id = p_document_id
     and l.round = v_round
   order by l.kind, l.step_order, l.id;

  if not found then
    raise exception 'approval lines not found' using errcode = 'P0002';
  end if;

  return v_next;
end;
$$;


ALTER FUNCTION "app"."clone_approval_full_round"("p_document_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."clone_approval_full_round"("p_document_id" "uuid") IS '현재 회차 결재선 전체를 다음 회차 PENDING으로 복제한다(도장은 지우지 않고 회차로 쌓는다). 보완 복제(clone_approval_revision_round)와 달리 이미 처리된 자리까지 복제해 처음부터 다시 받는다. 호출자 검증은 하지 않으므로 검증을 마친 RPC만 부른다.';



CREATE OR REPLACE FUNCTION "app"."clone_approval_revision_round"("p_document_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_round integer := app.approval_current_round(p_document_id);
  v_next  integer := v_round + 1;
begin
  insert into public.approval_lines
    (document_id, approver_id, step_order, kind, round, decision)
  select l.document_id, l.approver_id, l.step_order, l.kind, v_next,
         'PENDING'::public.approval_decision
    from public.approval_lines l
   where l.document_id = p_document_id
     and l.round = v_round
     and l.decision in ('PENDING', 'REVISION_REQUESTED')
   order by l.kind, l.step_order, l.id;

  if not found then
    raise exception 'no approval lines remain after revision' using errcode = 'P0002';
  end if;

  return v_next;
end;
$$;


ALTER FUNCTION "app"."clone_approval_revision_round"("p_document_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."clone_approval_revision_round"("p_document_id" "uuid") IS '보완 재상신 시 보완 요청 자리와 미처리 자리만 다음 회차로 복제한다. 호출자 검증은 하지 않으므로 public/authenticated에 열지 않고 검증을 마친 resubmit RPC만 부른다.';



CREATE OR REPLACE FUNCTION "app"."clone_org_version_with_kpi"("p_src_version" "uuid", "p_label" "text", "p_from" "date", "p_to" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_new uuid;
  v_src_kpi uuid;
  v_new_kpi uuid;
begin
  if not (app.is_admin() or app.can_write_workspace('management')) then
    raise exception '조직 버전을 생성할 권한이 없습니다.' using errcode = '42501';
  end if;
  if btrim(coalesce(p_label, '')) = '' or p_from is null then
    raise exception '버전 이름과 시작일을 입력하세요.' using errcode = '22023';
  end if;
  if p_to is not null and p_to <= p_from then
    raise exception '종료일은 시작일보다 뒤여야 합니다.' using errcode = '22007';
  end if;

  insert into public.org_versions (label, effective_from, effective_to, status)
  values (btrim(p_label), p_from, p_to, 'DRAFT') returning id into v_new;

  insert into public.org_levels (name, sort_order, version_id, lineage_id)
  select l.name, l.sort_order, v_new, l.lineage_id
    from public.org_levels l
   where l.version_id = p_src_version and l.deleted_at is null;

  insert into public.departments
    (name, parent_id, level_id, sort_order, version_id, lineage_id, hr_hidden)
  select s.name, null, nl.id, s.sort_order, v_new, s.lineage_id, s.hr_hidden
    from public.departments s
    left join public.org_levels sl on sl.id = s.level_id
    left join public.org_levels nl
      on nl.version_id = v_new and nl.lineage_id = sl.lineage_id and nl.deleted_at is null
   where s.version_id = p_src_version and s.deleted_at is null;

  update public.departments c
     set parent_id = np.id
    from public.departments s_child
    join public.departments s_parent on s_parent.id = s_child.parent_id
    join public.departments np on np.version_id = v_new and np.lineage_id = s_parent.lineage_id
   where c.version_id = v_new and c.lineage_id = s_child.lineage_id
     and s_child.version_id = p_src_version;

  insert into public.dept_members
    (version_id, department_id, user_id, effective_from, effective_to)
  select v_new, np.id, latest.user_id, p_from, p_to
    from (
      select distinct on (m.user_id) m.user_id, m.department_id
        from public.dept_members m
       where m.version_id = p_src_version and m.deleted_at is null
       order by m.user_id, m.effective_from desc
    ) latest
    join public.departments sd on sd.id = latest.department_id
    join public.departments np on np.version_id = v_new and np.lineage_id = sd.lineage_id;

  select kv.id into v_src_kpi from public.kpi_versions kv
   where kv.org_version_id = p_src_version and kv.deleted_at is null limit 1;
  insert into public.kpi_versions (org_version_id, source_version_id, label, status)
  values (v_new, v_src_kpi, btrim(p_label) || ' KPI', 'DRAFT') returning id into v_new_kpi;

  if v_src_kpi is not null then
    insert into public.kpi_templates
      (kpi_version_id, source_template_id, source_blueprint_id, name, scope_type, role_hint)
    select v_new_kpi, t.id, t.source_blueprint_id, t.name, t.scope_type, t.role_hint
      from public.kpi_templates t
     where t.kpi_version_id = v_src_kpi and t.deleted_at is null;

    insert into public.kpi_template_items
      (template_id, source_item_id, section_label, metric_code, metric_name, description,
       criteria_text, unit, input_type, target_mode, rule_type, rule_params,
       default_target, max_score, evidence_required, sort_order)
    select nt.id, i.id, i.section_label, i.metric_code, i.metric_name, i.description,
           i.criteria_text, i.unit, i.input_type, i.target_mode, i.rule_type, i.rule_params,
           i.default_target, i.max_score, i.evidence_required, i.sort_order
      from public.kpi_template_items i
      join public.kpi_templates nt
        on nt.kpi_version_id = v_new_kpi and nt.source_template_id = i.template_id
     where i.deleted_at is null;

    insert into public.kpi_assignments
      (kpi_version_id, template_id, subject_type, department_id, user_id,
       assignment_kind, target_overrides)
    select v_new_kpi, nt.id, a.subject_type,
           case when a.subject_type = 'DEPARTMENT' then np.id end,
           case when a.subject_type = 'PERSON' then a.user_id end,
           a.assignment_kind, a.target_overrides
      from public.kpi_assignments a
      join public.kpi_templates nt
        on nt.kpi_version_id = v_new_kpi and nt.source_template_id = a.template_id
      left join public.departments sd on sd.id = a.department_id
      left join public.departments np
        on np.version_id = v_new and np.lineage_id = sd.lineage_id and np.deleted_at is null
     where a.kpi_version_id = v_src_kpi and a.deleted_at is null
       and (a.subject_type = 'PERSON' or np.id is not null);
  end if;
  return v_new;
end $$;


ALTER FUNCTION "app"."clone_org_version_with_kpi"("p_src_version" "uuid", "p_label" "text", "p_from" "date", "p_to" "date") OWNER TO "postgres";


