CREATE OR REPLACE FUNCTION "app"."custom_access_token_hook"("event" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  claims  jsonb := coalesce(event -> 'claims', '{}'::jsonb);
  u       record;
begin
  select id, user_type, session_version
    into u
    from public.users
   where auth_user_id = (event ->> 'user_id')::uuid
     and is_active and deleted_at is null;

  if u.id is not null then
    claims := jsonb_set(claims, '{app_user_id}',    to_jsonb(u.id));
    claims := jsonb_set(claims, '{app_role}',       to_jsonb(u.user_type::text));
    claims := jsonb_set(claims, '{session_version}',to_jsonb(u.session_version));
  end if;

  return jsonb_set(event, '{claims}', claims);
end;
$$;


ALTER FUNCTION "app"."custom_access_token_hook"("event" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."default_access_end"("p_program_id" "uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_row jsonb;
  v_end date;
begin
  v_row := app.program_row(p_program_id);
  -- 사업은 end_date, 조합은 term_end. 한 줄로 묻는 이유는 둘 다 "언제 끝나는가"의 답이고
  -- 원장마다 칸 이름만 다르기 때문이다.
  v_end := coalesce(nullif(v_row ->> 'end_date', ''), nullif(v_row ->> 'term_end', ''))::date;
  if v_end is null then
    return now() + interval '1 year';
  end if;
  return (v_end + interval '14 days')::timestamptz;
exception when others then
  return now() + interval '1 year';
end;
$$;


ALTER FUNCTION "app"."default_access_end"("p_program_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."default_access_end"("p_program_id" "uuid") IS '게스트 접근 종료 기본값(사업 종료일 또는 조합 존속기간 종료일 + 14일, 없으면 1년). 근거: 3_9_1 §8';



CREATE OR REPLACE FUNCTION "app"."enforce_module_template"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_ws  text := app.entity_key_workspace(new.entity_key);
  v_key text := new.module_type::text;
begin
  -- 카탈로그는 **생성 시점에만** 본다. 이미 배치된 인스턴스의 수정·운영은 건드리지 않는다.
  if tg_op = 'INSERT' and not app.module_template_available(v_key, v_ws) then
    raise exception '이 템플릿은 현재 워크스페이스에서 사용할 수 없습니다: %', v_key
      using errcode = '42501';
  end if;

  -- 성격은 **값이 바뀔 때** 본다. 템플릿 성격이 나중에 바뀌어 기존 행과 어긋나더라도 그 행의
  -- 기간·담당자를 고치는 것까지 막지는 않는다 — 어긋난 행의 노출은 판정 시점(게스트 목록·
  -- 링크 게이트)이 이미 닫으므로, 여기서 또 막으면 상한이 편집까지 가로막게 된다.
  if tg_op = 'INSERT' or old.visibility is distinct from new.visibility then
    if not (new.visibility::text = any (app.module_template_visibilities(v_key))) then
      raise exception '이 템플릿에서 고를 수 없는 공유 범위입니다: % (%)', v_key, new.visibility
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "app"."enforce_module_template"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."enforce_module_template"() IS '모듈 원장 쓰기에 템플릿 카탈로그·성격을 강제한다. 카탈로그는 생성 시점만, 공유 범위는 값이 바뀔 때만 본다.';



