    raise exception '사업을 찾을 수 없습니다(원장 %, id %).', new.entity_key, new.program_id
      using errcode = '23503';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app"."enforce_program_ref"() OWNER TO "postgres";


