CREATE OR REPLACE FUNCTION "app"."guard_department_membership_period"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v_org public.org_versions%rowtype;
begin
  select * into v_org from public.org_versions where id = new.version_id and deleted_at is null;
  if v_org.id is null then
    raise exception '조직 버전을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  if new.effective_from < v_org.effective_from
     or (v_org.effective_to is not null and new.effective_from >= v_org.effective_to)
     or (v_org.effective_to is not null and coalesce(new.effective_to, v_org.effective_to) > v_org.effective_to) then
    raise exception '인력 배치 기간은 조직 버전의 적용기간 안에 있어야 합니다.' using errcode = '23514';
  end if;
  return new;
end $$;


ALTER FUNCTION "app"."guard_department_membership_period"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."guard_guest_participant_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_user_type public.user_type;
begin
  if new.user_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.user_id is not distinct from old.user_id then
    return new;
  end if;
  -- SELECT RLS로 대상 사용자가 보이지 않는 경우를 "내부 사용자"로 오인해 통과시키면
  -- 숨은 M&A GUEST를 직접 INSERT/UPDATE로 배정할 수 있다. 먼저 보이는 사용자 행을
  -- 확정하고, 보이지 않는 대상은 거절한다. 내부 사용자는 그 다음에만 예외 통과한다.
  select u.user_type
    into v_user_type
    from public.users u
   where u.id = new.user_id
     and u.deleted_at is null;

  if not found then
    raise exception '배정할 사용자 계정을 확인할 권한이 없습니다.'
      using errcode = '42501', hint = 'guest_account_not_visible';
  end if;

  if not app.is_guest_user_type(v_user_type) then
    return new;
  end if;

  if not app.guest_account_visible_for_assignment(new.user_id, new.id) then
    raise exception '이 GUEST 계정을 명부에 배정할 권한이 없습니다.'
      using errcode = '42501', hint = 'guest_account_not_visible';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "app"."guard_guest_participant_assignment"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."guard_guest_participant_assignment"() IS '명부 줄에 GUEST 계정을 새로 배정할 때, 배정하는 사람이 그 계정을 이미 볼 수 있어야 한다. 대상 사용자 행 자체가 RLS로 보이지 않아도 거절하며, 현재 participant id를 판정에서 제외해 새 줄이 스스로를 근거로 보이게 만들 수 없다. 계정 없는 줄·보이는 내부 임직원·값 그대로의 갱신은 지나간다.';



CREATE OR REPLACE FUNCTION "app"."guard_kpi_definition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_version uuid;
  v_status text;
  v_scope text;
  v_template_version uuid;
  v_department_version uuid;
begin
  if tg_table_name = 'kpi_templates' then
    v_version := new.kpi_version_id;
  elsif tg_table_name = 'kpi_template_items' then
    select t.kpi_version_id into v_version from public.kpi_templates t where t.id = new.template_id;
  elsif tg_table_name = 'kpi_assignments' then
    v_version := new.kpi_version_id;
    select t.kpi_version_id, t.scope_type into v_template_version, v_scope
      from public.kpi_templates t where t.id = new.template_id and t.deleted_at is null;
    if v_template_version is distinct from v_version or v_scope is distinct from new.subject_type then
      raise exception 'KPI 템플릿과 할당 대상의 버전 또는 종류가 일치하지 않습니다.' using errcode = '23514';
    end if;
    if new.subject_type = 'DEPARTMENT' then
      select d.version_id into v_department_version
        from public.departments d where d.id = new.department_id and d.deleted_at is null;
      if v_department_version is distinct from (
        select kv.org_version_id from public.kpi_versions kv where kv.id = v_version
      ) then
        raise exception '선택한 조직 버전에 속한 부서만 KPI를 할당할 수 있습니다.' using errcode = '23514';
      end if;
    elsif not exists (
      select 1
        from public.dept_members dm
       where dm.version_id = (
               select kv.org_version_id from public.kpi_versions kv where kv.id = v_version
             )
         and dm.user_id = new.user_id
         and dm.deleted_at is null
    ) then
      raise exception '선택한 조직 버전에 배치된 임직원만 KPI를 할당할 수 있습니다.' using errcode = '23514';
    end if;
  end if;

  select kv.status into v_status from public.kpi_versions kv
   where kv.id = v_version and kv.deleted_at is null;
  if v_status = 'PUBLISHED' and tg_table_name = 'kpi_assignments'
     and tg_op = 'INSERT' and new.assignment_kind = 'PRIMARY' then
    return new;
  end if;
  if v_status is distinct from 'DRAFT' then
    raise exception '발행된 KPI 정의와 기존 할당은 수정할 수 없습니다.' using errcode = '55000';
  end if;
  return new;
end $$;


ALTER FUNCTION "app"."guard_kpi_definition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."guard_kpi_version_publish"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if old.status = 'DRAFT' and new.status = 'PUBLISHED'
     and coalesce(current_setting('app.kpi_publish_context', true), '') <> 'true' then
    raise exception '조직과 KPI 동시 발행 RPC를 사용하세요.' using errcode = '55000';
  end if;
  return new;
end $$;


