ALTER FUNCTION "app"."guest_account_has_any_participation"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."guest_account_has_other_participation"("p_user_id" "uuid", "p_excluded_participant_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
      from public.program_participants pp
     where pp.user_id = p_user_id
       and pp.id is distinct from p_excluded_participant_id
  );
$$;


ALTER FUNCTION "app"."guest_account_has_other_participation"("p_user_id" "uuid", "p_excluded_participant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."guest_account_has_other_participation"("p_user_id" "uuid", "p_excluded_participant_id" "uuid") IS '배정 중인 현재 명부 행을 빼고 GUEST 계정에 다른 참여가 있는지만 답한다. 숨은 참여도 세야 하므로 SECURITY DEFINER이며 행 내용은 반환하지 않는다.';



CREATE OR REPLACE FUNCTION "app"."guest_account_is_unlinked"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select not exists (
           select 1 from public.guest_identities gi where gi.user_id = p_user_id
         )
     and not exists (
           select 1
             from public.program_participants pp
            where pp.user_id = p_user_id and pp.entity_key = 'fund'
         );
$$;


ALTER FUNCTION "app"."guest_account_is_unlinked"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."guest_account_is_unlinked"("p_user_id" "uuid") IS 'GUEST 계정에 원장 인격과 FUND 참여가 모두 없는지만 답한다. PROJECT·M&A에 계정만 추가한 경우도 미연결 탭에 남는다. 숨은 연결도 세되 내용은 반환하지 않는 SECURITY DEFINER 판정이다.';



CREATE OR REPLACE FUNCTION "app"."guest_account_visible"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  select exists (
    select 1
      from public.users u
     where u.id = p_user_id
       and u.deleted_at is null
       and app.is_guest_user_type(u.user_type)
       and (
         app.is_admin()
         or exists (
           select 1
             from public.guest_identities gi
            where gi.user_id = u.id
              and case gi.master_table
                    when 'ma_sellers' then app.can_read_ma_party('ma_seller', gi.master_id)
                    when 'ma_buyers'  then app.can_read_ma_party('ma_buyer',  gi.master_id)
                    else true
                  end
         )
         or exists (
           select 1 from public.program_participants pp where pp.user_id = u.id
         )
         or (
           u.user_type = 'temporary_guest'
           and not app.guest_account_has_any_participation(u.id)
         )
       )
  );
$$;


ALTER FUNCTION "app"."guest_account_visible"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."guest_account_visible"("p_user_id" "uuid") IS '이 GUEST 계정이 호출자에게 보이는가(SECURITY INVOKER — 참여·인격의 가시성은 호출자 RLS가 답한다). M&A 인격은 정책과 함수 모두 딜 당사자 권한(app.can_read_ma_party)을 요구한다. 목록·명부 추가가 같은 판정을 쓴다.';



CREATE OR REPLACE FUNCTION "app"."guest_account_visible_for_assignment"("p_user_id" "uuid", "p_excluded_participant_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_user_type public.user_type;
begin
  select u.user_type
    into v_user_type
    from public.users u
   where u.id = p_user_id
     and u.deleted_at is null
     and app.is_guest_user_type(u.user_type);

  if not found then
    return false;
  end if;
  if app.is_admin() then
    return true;
  end if;
  if exists (
    select 1
      from public.guest_identities gi
     where gi.user_id = p_user_id
       and case gi.master_table
             when 'ma_sellers' then app.can_read_ma_party('ma_seller', gi.master_id)
             when 'ma_buyers'  then app.can_read_ma_party('ma_buyer',  gi.master_id)
             else true
           end
  ) then
    return true;
  end if;
  if exists (
    select 1
      from public.program_participants pp
     where pp.user_id = p_user_id
       and pp.id is distinct from p_excluded_participant_id
  ) then
    return true;
  end if;
  if v_user_type = 'temporary_guest'::public.user_type
     and not app.guest_account_has_other_participation(
       p_user_id, p_excluded_participant_id) then
    return true;
  end if;

  return false;
end;
$$;


ALTER FUNCTION "app"."guest_account_visible_for_assignment"("p_user_id" "uuid", "p_excluded_participant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."guest_account_visible_for_assignment"("p_user_id" "uuid", "p_excluded_participant_id" "uuid") IS '명부 배정 직전의 GUEST 계정 가시성. 현재 쓰기 대상 participant 행을 제외해 새 줄이 자신을 근거로 권한을 만들지 못하게 한다(SECURITY INVOKER).';



CREATE OR REPLACE FUNCTION "app"."guest_batch_error"("p_field" "text", "p_code" "text", "p_message" "text") RETURNS "jsonb"
