ALTER FUNCTION "app"."guest_has_password"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."guest_has_password"("p_user_id" "uuid") IS '게스트 계정에 비밀번호가 서 있는가. guest_credentials는 service_role만 닿는 표라 INVOKER 함수가 조인하면 42501로 죽는다 — 표를 여는 대신 파생 불리언만 꺼낸다. 근거: 3_9_1 §11.1';



CREATE OR REPLACE FUNCTION "app"."guest_module_ids"() RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
  select m.id
    from public.program_modules m
   where m.program_id in (select app.guest_program_ids())
     and m.visibility = 'GUEST_ONLY'
     and m.enabled
     and m.status <> 'CANCELLED'
     and app.module_template_allows_guest(m.module_type::text);
$$;


ALTER FUNCTION "app"."guest_module_ids"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."guest_module_ids"() IS '게스트에게 공개된 모듈(공유 범위 WORKS+GUEST + 켜짐 + 취소 아님 + 템플릿 상한 허용).
   게스트 메뉴 구성과 일정·슬롯·세션·글·링크·파일 노출의 단일 기준.';



CREATE OR REPLACE FUNCTION "app"."guest_open_module_ids"() RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
  select m.id
    from public.program_modules m
   where m.id in (select app.guest_module_ids())
     and m.status in ('OPEN', 'CLOSED');
$$;


ALTER FUNCTION "app"."guest_open_module_ids"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."guest_open_module_ids"() IS '게스트에게 내용까지 열린 모듈(공개 모듈 중 진행·완료).
   메뉴 줄·공지·일정은 guest_module_ids()가, 글·링크·파일·매칭·멘토링은 이 함수가 판정한다.';



CREATE OR REPLACE FUNCTION "app"."guest_program_ids"() RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
  with live as (
    select id, guest_access_ends_at from public.programs
      where deleted_at is null and status not in ('FINISHED', 'CANCELLED')
    union all
    select id, guest_access_ends_at from public.ma_programs
      where deleted_at is null and status not in ('FINISHED', 'SUSPENDED', 'CANCELLED')
    union all
    select id, guest_access_ends_at from public.funds
      where deleted_at is null and status <> 'CLOSED'
  )
  select p.program_id
    from public.program_participants p
    join live g on g.id = p.program_id
   where p.user_id = app.current_app_user_id()
     and p.login_status = 'ACTIVE'
     and p.program_id = app.guest_session_program_id()
     and (g.guest_access_ends_at is null or g.guest_access_ends_at > now());
$$;


ALTER FUNCTION "app"."guest_program_ids"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."guest_program_ids"() IS '게스트가 볼 수 있는 맥락 집합(로그인 개방 + 원장 생존 + 세션 고정 맥락 일치). M&A 중단·취소 딜은 제외한다.';



CREATE OR REPLACE FUNCTION "app"."guest_session_context_type"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'auth'
    AS $$
  select nullif(auth.jwt() ->> 'context_type', '');
$$;


ALTER FUNCTION "app"."guest_session_context_type"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."guest_session_context_type"() IS '게스트 세션에 고정된 맥락의 종류(program | ma_program | project_program, 장래 fund 등). 근거: 3_9_1 §7.1';



CREATE OR REPLACE FUNCTION "app"."guest_session_program_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'auth'
    AS $$
declare
  v_type  text := nullif(auth.jwt() ->> 'context_type', '');
  v_claim text;
begin
  if v_type is null then
    -- 구 토큰 폴백(배포 직후 8시간). 새 토큰은 반드시 context_type을 싣는다.
    v_claim := auth.jwt() ->> 'program_id';
  elsif v_type in ('program', 'ma_program', 'fund') then
    v_claim := auth.jwt() ->> 'context_id';
  else
    return null;
  end if;

  if v_claim is null or v_claim = '' then
    return null;
  end if;
  return v_claim::uuid;
exception when others then
  return null;
end;
$$;


ALTER FUNCTION "app"."guest_session_program_id"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."guest_session_program_id"() IS '게스트 세션에 고정된 사업. context_type이 사업 3종이면 context_id를, 클레임이 없는 구 토큰이면 program_id를 읽는다(배포 유예). 사업이 아닌 맥락이면 null이라 사업 조회가 전부 닫힌다.';



CREATE OR REPLACE FUNCTION "app"."has_contribution_trigger"("p_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  select exists (
    select 1
      from pg_trigger t
      join pg_class     c on c.oid = t.tgrelid
      join pg_namespace n on n.oid = c.relnamespace
      join pg_proc      p on p.oid = t.tgfoid
     where n.nspname = 'public'
       and c.relname = p_key
       and p.proname = 'log_entity_contribution'
       and not t.tgisinternal
  );
$$;


ALTER FUNCTION "app"."has_contribution_trigger"("p_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."has_contribution_trigger"("p_key" "text") IS '해당 원장에 변동 이력 기록 트리거가 붙어 있는가. RPC 허용 목록의 단일 원천 — 손으로 나열한 목록이 트리거 집합과 어긋나는 것을 구조적으로 막는다.';



CREATE OR REPLACE FUNCTION "app"."insert_entity_row"("p_table" "text", "p_values" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_cols text;
  v_id   uuid;
begin
  if not app.has_contribution_trigger(p_table) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  if p_values is null or jsonb_typeof(p_values) <> 'object' or p_values = '{}'::jsonb then
    raise exception 'empty_values' using errcode = '22023';
  end if;

  select string_agg(format('%I', k), ', ' order by k)
    into v_cols
    from jsonb_object_keys(p_values) as k;

  execute format(
    'insert into public.%I (%s) select %s from jsonb_populate_record(null::public.%I, $1) returning id',
    p_table, v_cols, v_cols, p_table
  ) using p_values into v_id;

  return v_id;
end $_$;


