end;
$$;


ALTER FUNCTION "app"."normalize_user_email"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."notify_approval"("p_document_id" "uuid", "p_recipients" "uuid"[], "p_type" "text", "p_actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_preview   text;
  v_actor_nm  text;
begin
  if p_recipients is null or array_length(p_recipients, 1) is null then
    return;
  end if;

  select left(coalesce(d.doc_no || ' · ', '') || d.title, 120)
    into v_preview
    from public.approval_documents d where d.id = p_document_id;

  select u.name into v_actor_nm from public.users u where u.id = p_actor;

  insert into public.notifications
    (recipient_id, actor_id, actor_name, type, target_type, target_id, ref_type, ref_id, body_preview)
  select distinct r, p_actor, v_actor_nm, p_type, 'approval', p_document_id,
         'approval_documents', p_document_id, v_preview
    from unnest(p_recipients) r
    join public.users u on u.id = r and u.deleted_at is null
   -- 자기 처리를 자기에게 알리지 않는다(반출 알림과 같은 규칙).
   where r is distinct from p_actor;
end;
$$;


ALTER FUNCTION "app"."notify_approval"("p_document_id" "uuid", "p_recipients" "uuid"[], "p_type" "text", "p_actor" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."notify_approval"("p_document_id" "uuid", "p_recipients" "uuid"[], "p_type" "text", "p_actor" "uuid") IS '결재 알림 팬아웃. 되돌림·재상신 RPC만 부르며 authenticated에는 열지 않는다(알림 원장의 INSERT 정책은 with check(false)라 DEFINER 경로만 쓴다).';



CREATE OR REPLACE FUNCTION "app"."prepare_kpi_actual_revision"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_item public.kpi_template_items%rowtype;
  v_assignment public.kpi_assignments%rowtype;
  v_status text;
  v_target numeric;
begin
  if not (app.is_admin() or app.can_write_workspace('management')) then
    raise exception 'KPI 실적을 입력할 권한이 없습니다.' using errcode = '42501';
  end if;
  select * into v_assignment from public.kpi_assignments
   where id = new.assignment_id and deleted_at is null;
  select * into v_item from public.kpi_template_items
   where id = new.template_item_id and deleted_at is null;
  if v_assignment.id is null or v_item.id is null or v_item.template_id <> v_assignment.template_id then
    raise exception '할당과 KPI 항목이 일치하지 않습니다.' using errcode = '23514';
  end if;
  select status into v_status from public.kpi_versions where id = v_assignment.kpi_version_id;
  if v_status is distinct from 'PUBLISHED' then
    raise exception '운영 중인 KPI에만 실적을 입력할 수 있습니다.' using errcode = '55000';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(new.assignment_id::text || ':' || new.template_item_id::text, 0));
  select coalesce(max(r.revision_no), 0) + 1 into new.revision_no
    from public.kpi_actual_revisions r
   where r.assignment_id = new.assignment_id and r.template_item_id = new.template_item_id;
  v_target := coalesce(nullif(v_assignment.target_overrides->>v_item.metric_code, '')::numeric, v_item.default_target);
  new.entered_by := app.current_app_user_id();
  new.computed_score := app.kpi_score(
    v_item.rule_type, v_item.rule_params, v_item.target_mode, v_target,
    new.actual_value, new.qualitative_value, new.actual_payload
  );
  return new;
end $$;


ALTER FUNCTION "app"."prepare_kpi_actual_revision"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."prevent_roster_removal_with_guest"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if old.deleted_at is null and new.deleted_at is not null and exists (
    select 1
      from public.program_participants p
     where p.entity_key = old.entity_key
       and p.program_id = old.program_id
       and p.master_table = old.master_table
       and p.master_id = old.master_id
  ) then
    raise exception 'GUEST 계정 연결이 남아 있어 참가 명단에서 뺄 수 없습니다. GUEST 설정에서 해당 연결을 먼저 제거하세요.'
      using errcode = '23503', hint = 'remove_guest_link_first';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app"."prevent_roster_removal_with_guest"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."program_row"("p_program_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_table text;
  v_row   jsonb;
begin
  v_table := case app.program_ws(p_program_id)
    when 'project' then 'programs'
    when 'mna'     then 'ma_programs'
    when 'fund'    then 'funds'
  end;
  if v_table is null then
    return null;
  end if;
  execute format('select to_jsonb(p) from public.%I p where p.id = $1', v_table)
    into v_row using p_program_id;
  return v_row;
end;
$_$;


ALTER FUNCTION "app"."program_row"("p_program_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."program_row"("p_program_id" "uuid") IS '사업 id → 그 사업이 실제로 있는 원장의 행 1건(jsonb). 세 원장의 컬럼명이 같아 호출부가 원장을 몰라도 된다.';



CREATE OR REPLACE FUNCTION "app"."program_ws"("p_program_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
  select case
    when p_program_id is null then null
    when exists (select 1 from public.programs    where id = p_program_id) then 'project'
    when exists (select 1 from public.ma_programs where id = p_program_id) then 'mna'
    when exists (select 1 from public.funds       where id = p_program_id) then 'fund'
  end;
$$;


ALTER FUNCTION "app"."program_ws"("p_program_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."program_ws"("p_program_id" "uuid") IS '이 id가 어느 원장의 것인가 — programs=project / ma_programs=mna / funds=fund. 게스트 계통(문·기간·개방)이 사업과 조합을 같은 경로로 다루므로 조합도 여기서 답한다.';



CREATE OR REPLACE FUNCTION "app"."prune_ma_program_party_links"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'app'
    AS $$
begin
  if new.category = 'SELL' then
    delete from public.ma_program_party_links
     where program_id = new.id and buyer_id is not null;
  elsif new.category = 'BUY' then
    delete from public.ma_program_party_links
     where program_id = new.id and seller_id is not null;
  elsif new.category is distinct from 'SELL_BUY' then
    delete from public.ma_program_party_links where program_id = new.id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app"."prune_ma_program_party_links"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."prune_module_assignees"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_key  text := tg_argv[0];
  v_pool text := tg_argv[1];
  v_still boolean;
begin
  -- 전량 교체 도중이었다면 커밋 시점엔 같은 사람이 다시 들어와 있다. 그때는 아무 일도
  -- 없었던 것이다 — 담당자 한 명의 기간 구간이 여러 줄일 수 있으므로 '한 줄이라도 남아
  -- 있는가'로 묻는다.
  execute format(
    'select exists (select 1 from public.%I where program_id = $1 and user_id = $2)', v_pool)
    into v_still using old.program_id, old.user_id;
  if v_still then return null; end if;

  delete from public.program_module_assignees a
   using public.program_modules m
   where a.program_module_id = m.id
     and m.entity_key = v_key
     and m.program_id = old.program_id
     and a.user_id = old.user_id;

  return null;
end;
$_$;


ALTER FUNCTION "app"."prune_module_assignees"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."prune_module_assignees"() IS '사업 담당자 풀에서 빠진 사람의 모듈 담당 배정을 거둔다. 지연 제약 트리거로만 호출되며(전량 교체 패턴 때문에 커밋 시점에 판정해야 한다), 커밋 시점에 풀에 남아 있으면 아무것도 하지 않는다.';



CREATE OR REPLACE FUNCTION "app"."publish_org_and_kpi_version"("p_org_version_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_org public.org_versions%rowtype;
  v_kpi public.kpi_versions%rowtype;
  v_missing_departments integer;
  v_missing_people integer;
  v_empty_templates integer;
  v_published_count integer;
begin
  if not (app.is_admin() or app.can_write_workspace('management')) then
    raise exception '조직과 KPI를 발행할 권한이 없습니다.' using errcode = '42501';
  end if;
  select * into v_org from public.org_versions
   where id = p_org_version_id and deleted_at is null for update;
  select * into v_kpi from public.kpi_versions
   where org_version_id = p_org_version_id and deleted_at is null for update;
  if v_org.id is null or v_kpi.id is null then
    raise exception '조직 또는 KPI 초안을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  if v_kpi.status <> 'DRAFT' then
    raise exception 'KPI 초안만 발행할 수 있습니다.' using errcode = '55000';
  end if;

  select count(*) into v_empty_templates
    from public.kpi_templates t
   where t.kpi_version_id = v_kpi.id and t.deleted_at is null
     and not exists (
       select 1 from public.kpi_template_items i
        where i.template_id = t.id and i.deleted_at is null
     );
  if v_empty_templates > 0 then
    raise exception '항목이 없는 KPI 템플릿이 %개 있습니다.', v_empty_templates using errcode = '23514';
  end if;

  if not exists (
    select 1 from public.kpi_templates t
     where t.kpi_version_id = v_kpi.id and t.scope_type = 'DEPARTMENT' and t.deleted_at is null
  ) or not exists (
    select 1 from public.kpi_templates t
     where t.kpi_version_id = v_kpi.id and t.scope_type = 'PERSON' and t.deleted_at is null
  ) then
    raise exception '부서용과 개인용 KPI 템플릿을 각각 하나 이상 만들어야 합니다.' using errcode = '23514';
  end if;

  select count(*) into v_missing_departments
    from public.departments d
   where d.version_id = p_org_version_id and d.deleted_at is null
     and exists (
       select 1 from public.dept_members dm
        where dm.version_id = p_org_version_id and dm.department_id = d.id and dm.deleted_at is null
     )
     and not exists (
       select 1 from public.kpi_assignments a
        where a.kpi_version_id = v_kpi.id and a.subject_type = 'DEPARTMENT'
          and a.department_id = d.id and a.assignment_kind = 'PRIMARY' and a.deleted_at is null
     );
  select count(*) into v_missing_people
    from (select distinct dm.user_id from public.dept_members dm
           where dm.version_id = p_org_version_id and dm.deleted_at is null) people
   where not exists (
     select 1 from public.kpi_assignments a
      where a.kpi_version_id = v_kpi.id and a.subject_type = 'PERSON'
        and a.user_id = people.user_id and a.assignment_kind = 'PRIMARY' and a.deleted_at is null
   );

  select count(*) into v_published_count from public.kpi_versions
   where status in ('PUBLISHED','CLOSED') and deleted_at is null;
  if v_org.status = 'PUBLISHED' and v_published_count > 0 then
    raise exception '이미 발행된 조직에는 새 조직개편을 통해서만 KPI를 교체할 수 있습니다.' using errcode = '55000';
  elsif v_org.status not in ('DRAFT','PUBLISHED') then
    raise exception '발행할 수 없는 조직 상태입니다.' using errcode = '55000';
  end if;

  perform set_config('app.kpi_publish_context', 'true', true);
  if v_org.status = 'DRAFT' then
    update public.org_versions
       set effective_to = v_org.effective_from
     where id = (
       select prior.id from public.org_versions prior
        where prior.status = 'PUBLISHED' and prior.deleted_at is null
          and prior.effective_from < v_org.effective_from
        order by prior.effective_from desc, prior.created_at desc limit 1
     );
    update public.org_versions set status = 'PUBLISHED' where id = v_org.id;
  end if;
  update public.kpi_versions
     set status = 'PUBLISHED', published_at = now(), published_by = app.current_app_user_id()
   where id = v_kpi.id;

  insert into public.audit_logs
    (actor_user_id, action, changed_workspace, after_data, reason)
  values (
    app.current_app_user_id(), 'KPI_VERSION_PUBLISH', 'management',
    jsonb_build_object(
      'org_version_id', v_org.id, 'kpi_version_id', v_kpi.id,
      'effective_from', v_org.effective_from,
      'missing_departments', v_missing_departments, 'missing_people', v_missing_people
    ),
    case when v_missing_departments + v_missing_people > 0
      then '조직·KPI 스냅샷 동시 발행(미할당 대상 후속 보완)'
      else '조직·KPI 스냅샷 동시 발행' end
  );
  return v_kpi.id;
end $$;


ALTER FUNCTION "app"."publish_org_and_kpi_version"("p_org_version_id" "uuid") OWNER TO "postgres";


