CREATE OR REPLACE FUNCTION "app"."refresh_kpi_result"("p_assignment_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_score numeric;
  v_completed integer;
  v_total integer;
  v_snapshot jsonb;
begin
  with items as (
    select i.* from public.kpi_assignments a
    join public.kpi_template_items i on i.template_id = a.template_id and i.deleted_at is null
    where a.id = p_assignment_id and a.deleted_at is null
  ), latest as (
    select distinct on (r.template_item_id)
           r.template_item_id, r.computed_score, r.actual_value, r.qualitative_value, r.entered_at
      from public.kpi_actual_revisions r
     where r.assignment_id = p_assignment_id
     order by r.template_item_id, r.revision_no desc
  )
  select coalesce(sum(l.computed_score), 0),
         count(l.template_item_id)::integer,
         count(i.id)::integer,
         coalesce(jsonb_agg(jsonb_build_object(
           'item_id', i.id, 'metric_code', i.metric_code, 'score', l.computed_score,
           'actual', l.actual_value, 'qualitative', l.qualitative_value, 'entered_at', l.entered_at
         ) order by i.sort_order), '[]'::jsonb)
    into v_score, v_completed, v_total, v_snapshot
    from items i left join latest l on l.template_item_id = i.id;

  insert into public.kpi_results
    (assignment_id, calculated_score, completed_items, total_items, calculation_snapshot, calculated_at)
  values
    (p_assignment_id, v_score, v_completed, v_total, v_snapshot, now())
  on conflict (assignment_id) do update set
    calculated_score = excluded.calculated_score,
    completed_items = excluded.completed_items,
    total_items = excluded.total_items,
    calculation_snapshot = excluded.calculation_snapshot,
    calculated_at = excluded.calculated_at,
    updated_at = now();
end $$;


ALTER FUNCTION "app"."refresh_kpi_result"("p_assignment_id" "uuid") OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."attendance_policies" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid",
    "check_in_from" time without time zone DEFAULT '07:00:00'::time without time zone NOT NULL,
    "check_in_to" time without time zone DEFAULT '09:00:00'::time without time zone NOT NULL,
    "work_minutes" integer DEFAULT 540 NOT NULL,
    "workdays" smallint[] DEFAULT '{1,2,3,4,5}'::smallint[] NOT NULL,
    "allow_external" boolean DEFAULT true NOT NULL,
    "effective_from" "date" DEFAULT CURRENT_DATE NOT NULL,
    "note" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "half_am_start" time without time zone DEFAULT '09:00:00'::time without time zone NOT NULL,
    "half_am_end" time without time zone DEFAULT '14:00:00'::time without time zone NOT NULL,
    "half_pm_start" time without time zone DEFAULT '14:00:00'::time without time zone NOT NULL,
    "half_pm_end" time without time zone DEFAULT '18:00:00'::time without time zone NOT NULL,
    "quarter_minutes" integer DEFAULT 120 NOT NULL,
    "ignore_schedule" boolean DEFAULT false NOT NULL,
    CONSTRAINT "attendance_policies_half_am_order" CHECK (("half_am_start" < "half_am_end")),
    CONSTRAINT "attendance_policies_half_pm_order" CHECK (("half_pm_start" < "half_pm_end")),
    CONSTRAINT "attendance_policies_quarter_minutes" CHECK ((("quarter_minutes" >= 30) AND ("quarter_minutes" <= 480))),
    CONSTRAINT "attendance_policies_time_order" CHECK (("check_in_from" < "check_in_to")),
    CONSTRAINT "attendance_policies_work_minutes" CHECK ((("work_minutes" >= 60) AND ("work_minutes" <= 1440))),
    CONSTRAINT "attendance_policies_workdays" CHECK (((("array_length"("workdays", 1) >= 1) AND ("array_length"("workdays", 1) <= 7)) AND ("workdays" <@ ARRAY[(0)::smallint, (1)::smallint, (2)::smallint, (3)::smallint, (4)::smallint, (5)::smallint, (6)::smallint])))
);


ALTER TABLE "public"."attendance_policies" OWNER TO "postgres";


COMMENT ON TABLE "public"."attendance_policies" IS '근무 기준(출근 가능 시간대·소정 근무시간·근무 요일). user_id가 null이면 전사 기본, 값이 있으면 임직원별 예외.';



COMMENT ON COLUMN "public"."attendance_policies"."half_am_start" IS '오전 반차 시작 시각(이 구간은 근무하지 않는다)';



COMMENT ON COLUMN "public"."attendance_policies"."half_am_end" IS '오전 반차 종료 시각 — 오전 반차를 쓴 날의 출근 기준선';



COMMENT ON COLUMN "public"."attendance_policies"."half_pm_start" IS '오후 반차 시작 시각 — 오후 반차를 쓴 날의 퇴근 기준선';



COMMENT ON COLUMN "public"."attendance_policies"."half_pm_end" IS '오후 반차 종료 시각(이 구간은 근무하지 않는다)';



COMMENT ON COLUMN "public"."attendance_policies"."quarter_minutes" IS '반반차 길이(분). 그날의 소정 근무시간에서 이만큼을 뺀다';



COMMENT ON COLUMN "public"."attendance_policies"."ignore_schedule" IS '근무 요건 무시 — 켜면 출퇴근을 자유롭게 찍고 지각·조기퇴근을 판정하지 않는다';



CREATE OR REPLACE FUNCTION "app"."resolve_attendance_policy"("p_user" "uuid", "p_date" "date") RETURNS "public"."attendance_policies"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
  select *
    from public.attendance_policies p
   where p.deleted_at is null
     and p.effective_from <= p_date
     and (p.user_id = p_user or p.user_id is null)
   order by (p.user_id is not null) desc,   -- 임직원 예외가 전사 기본을 이긴다
            p.effective_from desc
   limit 1;
$$;


