CREATE OR REPLACE FUNCTION "app"."stamp_validate_reservation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  r public.meeting_rooms%rowtype;
  slot_sec integer;
begin
  if NEW.created_by is null then
    NEW.created_by := app.current_app_user_id();
  end if;
  if NEW.created_by_name is null and NEW.created_by is not null then
    select u.name into NEW.created_by_name from public.users u where u.id = NEW.created_by;
  end if;

  select * into r from public.meeting_rooms
   where id = NEW.room_id and deleted_at is null;
  if not found then
    raise exception '존재하지 않는 회의실입니다.';
  end if;
  if not r.is_active then
    raise exception '비활성화된 회의실은 예약할 수 없습니다.';
  end if;

  -- 예약가능 요일(0=일..6=토)
  if not (extract(dow from NEW.reserved_date)::smallint = any (r.weekdays)) then
    raise exception '해당 요일은 예약할 수 없는 회의실입니다.';
  end if;

  -- 운영시간 범위 내
  if NEW.start_time < r.open_time or NEW.end_time > r.close_time then
    raise exception '운영시간(% ~ %)을 벗어난 예약입니다.', r.open_time, r.close_time;
  end if;

  -- 슬롯 정렬(오픈 시각 기준 slot_minutes 배수)
  slot_sec := r.slot_minutes * 60;
  if mod(extract(epoch from (NEW.start_time - r.open_time))::integer, slot_sec) <> 0
     or mod(extract(epoch from (NEW.end_time - r.open_time))::integer, slot_sec) <> 0 then
    raise exception '예약 시간은 % 분 단위여야 합니다.', r.slot_minutes;
  end if;

  return NEW;
end $$;


ALTER FUNCTION "app"."stamp_validate_reservation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."startup_pool_filtered"("p_keyword" "text" DEFAULT NULL::"text", "p_mine_user" "uuid" DEFAULT NULL::"uuid", "p_locations" "text"[] DEFAULT NULL::"text"[], "p_regions" "uuid"[] DEFAULT NULL::"uuid"[], "p_region_unset" boolean DEFAULT NULL::boolean, "p_industries" "text"[] DEFAULT NULL::"text"[], "p_stages" "text"[] DEFAULT NULL::"text"[], "p_stage_unset" boolean DEFAULT NULL::boolean, "p_categories" "text"[] DEFAULT NULL::"text"[], "p_category_unset" boolean DEFAULT NULL::boolean, "p_statuses" "text"[] DEFAULT NULL::"text"[], "p_age_min" integer DEFAULT NULL::integer, "p_age_max" integer DEFAULT NULL::integer, "p_search_email" boolean DEFAULT false, "p_search_phone" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "category" "text", "region_tag_id" "uuid", "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  select s.id,
         nullif(btrim(coalesce(s.management_status, '')), '') as category,
         lt.region_tag_id,
         s.updated_at
    from public.startups s
    -- 소재지는 태그명 문자열이지 FK가 아니다(20260715100100). 태그에 없는 값(옛 자유 입력)은
    -- 권역이 비어 미지정 칸에 선다 — 조용히 다른 칸에 섞이지 않는다.
    left join public.location_tags lt
           on lt.name = s.location and lt.deleted_at is null
   where s.deleted_at is null
     and s.merged_into_id is null
     -- 범위: '내 관리기업'. 전체 범위에서는 조건이 붙지 않는다.
     and (p_mine_user is null
          or s.created_by = p_mine_user
          or exists (select 1 from public.startup_managers sm
                      where sm.startup_id = s.id and sm.user_id = p_mine_user))
     -- 검색어: 기업명·대표자·사업자번호 + 담당자 이름. 이메일·연락처는 목록에서 공개된
     -- 경우에만 닿는다(가려진 값을 검색창이 되짚어 주지 않도록).
     and (p_keyword is null or btrim(p_keyword) = ''
          or s.name ilike '%' || btrim(p_keyword) || '%'
          or s.representative ilike '%' || btrim(p_keyword) || '%'
          or s.biz_reg_no ilike '%' || btrim(p_keyword) || '%'
          or (p_search_email and s.email ilike '%' || btrim(p_keyword) || '%')
          or (p_search_phone and s.phone ilike '%' || btrim(p_keyword) || '%')
          or exists (select 1
                       from public.startup_managers sm
                       join public.users u on u.id = sm.user_id
                      where sm.startup_id = s.id
                        and u.name ilike '%' || btrim(p_keyword) || '%'
                        and not app.is_guest_user_type(u.user_type)))
     and (p_locations is null or cardinality(p_locations) = 0
          or s.location = any(p_locations))
     -- 권역과 미지정은 한 축이다(OR). 배열만 주면 그 권역들, true만 주면 미지정만, 둘 다 주면 합집합.
     and (case
            when (p_regions is null or cardinality(p_regions) = 0)
                 and p_region_unset is null then true
            when (p_regions is null or cardinality(p_regions) = 0)
              then (p_region_unset and lt.region_tag_id is null)
                   or (not p_region_unset and lt.region_tag_id is not null)
            else lt.region_tag_id = any(p_regions)
                 or (coalesce(p_region_unset, false) and lt.region_tag_id is null)
          end)
     and (p_industries is null or cardinality(p_industries) = 0
          or s.industries ?| p_industries)
     -- 투자단계는 카드에서 필터 바로 돌아갔지만 미지정 축은 서버에 남긴다 — 인자를 지우면
     -- 되살릴 때 다시 함수를 드롭해야 하고, 주지 않으면 조건이 붙지 않아 비용도 없다.
     and (case
            when (p_stages is null or cardinality(p_stages) = 0)
                 and p_stage_unset is null then true
            when (p_stages is null or cardinality(p_stages) = 0)
              then (p_stage_unset and nullif(btrim(coalesce(s.stage, '')), '') is null)
                   or (not p_stage_unset and nullif(btrim(coalesce(s.stage, '')), '') is not null)
            else s.stage = any(p_stages)
                 or (coalesce(p_stage_unset, false)
                     and nullif(btrim(coalesce(s.stage, '')), '') is null)
          end)
     -- 구분도 권역과 같은 규약(배열 OR 미지정). 빈 문자열은 미지정으로 본다.
     and (case
            when (p_categories is null or cardinality(p_categories) = 0)
                 and p_category_unset is null then true
            when (p_categories is null or cardinality(p_categories) = 0)
              then (p_category_unset
                    and nullif(btrim(coalesce(s.management_status, '')), '') is null)
                   or (not p_category_unset
                       and nullif(btrim(coalesce(s.management_status, '')), '') is not null)
            else s.management_status = any(p_categories)
                 or (coalesce(p_category_unset, false)
                     and nullif(btrim(coalesce(s.management_status, '')), '') is null)
          end)
     and (p_statuses is null or cardinality(p_statuses) = 0
          or s.pool_status = any(p_statuses))
     -- 업력(년차) 범위 → 설립일 경계. 최소 N년차 = N년 전 또는 그 이전 설립,
     -- 최대 N년차 = (N+1)년 전보다 나중 설립(만 나이 N년 초과분 제외).
     and (p_age_min is null
          or s.founded_on <= (current_date - make_interval(years => p_age_min)))
     and (p_age_max is null
          or s.founded_on > (current_date - make_interval(years => p_age_max + 1)))
$$;


ALTER FUNCTION "app"."startup_pool_filtered"("p_keyword" "text", "p_mine_user" "uuid", "p_locations" "text"[], "p_regions" "uuid"[], "p_region_unset" boolean, "p_industries" "text"[], "p_stages" "text"[], "p_stage_unset" boolean, "p_categories" "text"[], "p_category_unset" boolean, "p_statuses" "text"[], "p_age_min" integer, "p_age_max" integer, "p_search_email" boolean, "p_search_phone" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "app"."startup_pool_filtered"("p_keyword" "text", "p_mine_user" "uuid", "p_locations" "text"[], "p_regions" "uuid"[], "p_region_unset" boolean, "p_industries" "text"[], "p_stages" "text"[], "p_stage_unset" boolean, "p_categories" "text"[], "p_category_unset" boolean, "p_statuses" "text"[], "p_age_min" integer, "p_age_max" integer, "p_search_email" boolean, "p_search_phone" boolean) IS 'STARTUP 기업 목록의 필터 판정 한 벌. 목록(startup_pool_entities)과 요약 집계(startup_facet_counts)가 나란히 부른다 — 조건이 한 곳에 있어야 표와 카드가 어긋나지 않는다. 권역은 location_tags를 이름으로 이어 얻고, 권역·구분·투자단계는 각자 미지정 축과 OR로 묶인다. SECURITY INVOKER — startups의 RLS를 그대로 따른다.';



CREATE OR REPLACE FUNCTION "app"."startups_identity_gate"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_norm     text;
  v_hit      uuid;
  v_hit_name text;
  v_hit_biz  text;
  v_live     boolean;
  v_changed  boolean;
begin
  v_norm := app.format_biz_reg_no(new.biz_reg_no);
  if v_norm is not null
     and (tg_op = 'INSERT' or v_norm is distinct from app.format_biz_reg_no(old.biz_reg_no)) then
    if not app.is_valid_biz_reg_no(v_norm) then
      raise exception '사업자등록번호 형식이 맞지 않습니다: %', new.biz_reg_no
        using errcode = '22023', hint = 'biz_reg_no_invalid';
    end if;
  end if;
  new.biz_reg_no := v_norm;

  v_live := new.deleted_at is null and new.merged_into_id is null;
  v_changed := tg_op = 'INSERT'
    or new.name  is distinct from old.name
    or new.email is distinct from old.email
    or new.phone is distinct from old.phone
    or new.biz_reg_no is distinct from old.biz_reg_no
    or (old.deleted_at is not null and new.deleted_at is null)
    or (old.merged_into_id is not null and new.merged_into_id is null);

  -- 번호 없이 들어오는 행이 번호를 가진 기존 기업과 이름·연락처가 같으면, 그 기업은 이미
  -- 원장에 있다. 번호가 같은 경우는 유일 인덱스(uq_startups_biz_reg_no_live)가 막는다.
  if v_live and v_changed and new.biz_reg_no is null then
    v_hit := app.find_startup_identity(null, new.name, new.email, new.phone, new.id, true, true);
    if v_hit is not null then
      select s.name, s.biz_reg_no into v_hit_name, v_hit_biz from public.startups s where s.id = v_hit;
      raise exception '이미 등록된 기업입니다 — %(사업자등록번호 %). 새로 만들지 말고 그 행을 고치세요.',
        v_hit_name, v_hit_biz
        using errcode = '23505', hint = 'startup_identity_duplicate:' || v_hit;
    end if;
  end if;

  -- 보육·투자로 올라가는 순간에만 번호를 요구한다.
  if new.management_status in ('incubated', 'invested')
     and new.biz_reg_no is null
     and (tg_op = 'INSERT' or new.management_status is distinct from old.management_status) then
    raise exception '보육·투자 기업은 사업자등록번호가 있어야 합니다. 번호를 먼저 채우세요.'
      using errcode = '23514', hint = 'biz_reg_no_required';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "app"."startups_identity_gate"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."startups_identity_gate"() IS 'startups BEFORE INSERT/UPDATE — 사업자등록번호를 XXX-XX-XXXXX로 정규화하고 값이 바뀔 때 체크섬을 본다. 번호 없는 행이 번호 있는 기존 기업과 이름·연락처가 같으면 거절(23505, hint startup_identity_duplicate:<id>). 보육·투자 전환 시 번호 필수(23514, hint biz_reg_no_required).';



CREATE OR REPLACE FUNCTION "app"."startups_lifecycle_gate"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if new.management_status is distinct from 'invested' then
    new.pool_status := null;
  end if;
  if new.management_status is distinct from 'other' then
    new.management_status_etc := null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app"."startups_lifecycle_gate"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."sync_capital_call_payment_state"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_prev_paid_at timestamptz;
begin
  -- 일부납입은 차수 롤업 전용 값이라 LP 행에는 두지 않는다.
  if new.status = 'PARTIALLY_PAID' then
    new.status := 'SCHEDULED';
  end if;

  -- OLD는 UPDATE에서만 존재한다(INSERT에서 참조하면 미할당 에러).
  if tg_op = 'UPDATE' then
    v_prev_paid_at := old.paid_at;
  end if;

  new.is_paid := (new.status = 'PAID');
  new.amount  := case when new.is_paid then new.requested_amount else 0 end;
  -- 최초 납입일은 보존한다 — 상태를 다시 저장해도 납입일이 오늘로 밀리지 않는다.
  new.paid_at := case when new.is_paid then coalesce(v_prev_paid_at, now()) else null end;
  return new;
end $$;


ALTER FUNCTION "app"."sync_capital_call_payment_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."sync_capital_call_rollups"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  call_ids uuid[] := array[]::uuid[];
  lp_ids   uuid[] := array[]::uuid[];
  fund_ids uuid[] := array[]::uuid[];
  c uuid;
  l uuid;
  f uuid;
  v_total    integer;
  v_paid     integer;
  v_overdue  integer;
  v_notified integer;
begin
  -- 영향받은 차수·LP·펀드 키를 OLD/NEW 양쪽에서 수집(키 변경·삭제까지 커버).
  if tg_op in ('INSERT','UPDATE') then
    call_ids := call_ids || new.capital_call_id;
    if new.lp_id is not null then lp_ids := lp_ids || new.lp_id; end if;
    if new.fund_id is not null then fund_ids := fund_ids || new.fund_id; end if;
  end if;
  if tg_op in ('UPDATE','DELETE') then
    call_ids := call_ids || old.capital_call_id;
    if old.lp_id is not null then lp_ids := lp_ids || old.lp_id; end if;
    if old.fund_id is not null then fund_ids := fund_ids || old.fund_id; end if;
  end if;

  -- 차수 총 요청액 = 그 차수 요청액의 합(파생).
  -- 차수 상태 = LP 행 상태의 분포에서 롤업: 전원 납입=PAID, 일부 납입=PARTIALLY_PAID,
  --             아무도 안 냈으면 연체 > 통지 > 예정 순으로 가장 앞선 신호를 올린다.
  foreach c in array call_ids loop
    select count(*),
           count(*) filter (where p.status = 'PAID'),
           count(*) filter (where p.status = 'OVERDUE'),
           count(*) filter (where p.status = 'NOTIFIED')
      into v_total, v_paid, v_overdue, v_notified
      from public.capital_call_payments p
     where p.capital_call_id = c;

    update public.capital_calls cc
       set amount = coalesce((
             select sum(p.requested_amount) from public.capital_call_payments p
              where p.capital_call_id = c), 0),
           status = (case
                       when v_total = 0     then 'SCHEDULED'
                       when v_paid = v_total then 'PAID'
                       when v_paid > 0      then 'PARTIALLY_PAID'
                       when v_overdue > 0   then 'OVERDUE'
                       when v_notified > 0  then 'NOTIFIED'
                       else 'SCHEDULED'
                     end)::public.capital_call_status
     where cc.id = c;
  end loop;

  -- LP 실 납입액 = 그 LP의 납입완료 실 납입액 합(파생).
  foreach l in array lp_ids loop
    update public.fund_lps fl
       set paid_amount = coalesce((
             select sum(p.amount) from public.capital_call_payments p
              where p.lp_id = l and p.is_paid), 0)
     where fl.id = l;
  end loop;

  -- 펀드 실출자금액 = 그 펀드 납입완료 실 납입액 합(파생).
  foreach f in array fund_ids loop
    update public.funds fu
       set paid_in_amount = coalesce((
             select sum(p.amount) from public.capital_call_payments p
              where p.fund_id = f and p.is_paid), 0)
     where fu.id = f;
  end loop;

  return null;
end;
$$;


ALTER FUNCTION "app"."sync_capital_call_rollups"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."sync_fund_drawn_amount"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  recompute_fund uuid;
begin
  -- 신규/변경 대상 펀드 재계산
  if tg_op in ('INSERT', 'UPDATE') then
    update public.funds f
       set drawn_amount = coalesce((
             select sum(i.amount)
               from public.investments i
              where i.fund_id = new.fund_id
                and i.deleted_at is null), 0)
     where f.id = new.fund_id;
  end if;

  -- 삭제 또는 소속 펀드 변경 시 이전 펀드도 재계산
  if tg_op = 'DELETE' then
    recompute_fund := old.fund_id;
  elsif tg_op = 'UPDATE' and new.fund_id is distinct from old.fund_id then
    recompute_fund := old.fund_id;
  end if;

  if recompute_fund is not null then
    update public.funds f
       set drawn_amount = coalesce((
             select sum(i.amount)
               from public.investments i
              where i.fund_id = recompute_fund
                and i.deleted_at is null), 0)
     where f.id = recompute_fund;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "app"."sync_fund_drawn_amount"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."sync_fund_lp_ownership"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_fund  uuid;
  v_total numeric;
begin
  -- 자기 UPDATE가 이 트리거를 다시 부르는 것을 막는다(UPDATE OF 절이 1차 방어, 이건 2차).
  if pg_trigger_depth() > 1 then
    return null;
  end if;

  -- OLD/NEW는 각각 DELETE/INSERT에서만 없다 — tg_op로 갈라 잡는다.
  if tg_op = 'DELETE' then
    v_fund := old.fund_id;
  else
    v_fund := new.fund_id;
  end if;
  if v_fund is null then
    return null;
  end if;

  -- 약정총액 = 그 펀드 활성 LP 약정액의 합. 비활성 LP는 분모에서 빠진다.
  select coalesce(sum(commitment_amount), 0) into v_total
    from public.fund_lps
   where fund_id = v_fund and deleted_at is null;

  update public.fund_lps fl
     set ownership_pct = case
                           when fl.deleted_at is not null then null
                           when v_total > 0 then round(fl.commitment_amount / v_total * 100, 2)
                           else null
                         end
   where fl.fund_id = v_fund
     and fl.ownership_pct is distinct from (case
                           when fl.deleted_at is not null then null
                           when v_total > 0 then round(fl.commitment_amount / v_total * 100, 2)
                           else null
                         end);

  return null;
end $$;


ALTER FUNCTION "app"."sync_fund_lp_ownership"() OWNER TO "postgres";


