CREATE OR REPLACE FUNCTION "app"."text_to_numeric"("p_text" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
begin
  return nullif(regexp_replace(coalesce(p_text, ''), '[,[:space:]]', '', 'g'), '')::numeric;
exception when others then
  return null;
end;
$$;


ALTER FUNCTION "app"."text_to_numeric"("p_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."text_to_numeric"("p_text" "text") IS '사람이 적은 수치 문자열을 numeric으로. 쉼표·공백을 걷어내고 읽을 수 없으면 null을 돌려준다 (프론트 numeric.ts의 toNumber와 같은 규칙).';



CREATE OR REPLACE FUNCTION "app"."touch_ma_seller_quick_review"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  -- 퀵 리뷰가 바뀌지 않은 저장(연락처·희망사항 수정)은 작성 사실을 건드리지 않는다.
  if tg_op = 'UPDATE' and new.quick_review is not distinct from old.quick_review then
    return new;
  end if;

  if new.quick_review is null then
    -- 지우면 작성 사실도 없다. 남겨 두면 없는 문서의 작성일이 카드에 선다.
    new.quick_review_written_at := null;
    new.quick_review_written_by := null;
  else
    new.quick_review_written_at := now();
    -- 행위자를 모르는 경로(service_role)에서는 비워 둔다 — 지어내지 않는다.
    new.quick_review_written_by := app.current_app_user_id();
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app"."touch_ma_seller_quick_review"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."touch_ma_seller_quick_review"() IS 'ma_sellers.quick_review가 실제로 바뀐 저장에만 작성일·작성자를 새로 적는다. 다른 칸만 고친 저장은 지나가고, 퀵 리뷰를 지우면 작성 사실도 함께 비운다.';



CREATE OR REPLACE FUNCTION "app"."track_affiliation_history"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_ctx      jsonb := coalesce(nullif(current_setting('app.contribution_ctx', true), '')::jsonb, '{}'::jsonb);
  -- 3축의 '내용 비교'용 정규화 스냅샷(공백 트림·빈값 제거). 표시는 원값을 쓰되 비교만 정규화한다.
  v_old3     jsonb := jsonb_strip_nulls(jsonb_build_object(
                        'affiliation', nullif(btrim(coalesce(OLD.affiliation, '')), ''),
                        'department',  nullif(btrim(coalesce(OLD.profile->>'department', '')), ''),
                        'position',    nullif(btrim(coalesce(OLD.profile->>'position', '')), '')));
  v_new3     jsonb := jsonb_strip_nulls(jsonb_build_object(
                        'affiliation', nullif(btrim(coalesce(NEW.affiliation, '')), ''),
                        'department',  nullif(btrim(coalesce(NEW.profile->>'department', '')), ''),
                        'position',    nullif(btrim(coalesce(NEW.profile->>'position', '')), '')));
  v_old_hist jsonb := coalesce(OLD.profile->'affiliation_history', '[]'::jsonb);
  v_new_hist jsonb := coalesce(NEW.profile->'affiliation_history', '[]'::jsonb);
  v_hist     jsonb;
  -- 행위자명 스냅샷(현재 세션 사용자 본인). 표시 전용 — 이후 개명은 소급하지 않는다.
  v_actor    text;
begin
  -- 이력 배열의 소유자는 트리거다. 정상 저장은 기존 배열을 그대로(또는 병합 흡수로 더 길게)
  -- 실어 오지만, profile을 통째로 새로 만들어 배열을 떨군 저장은 OLD보다 짧다 — 그때 OLD를 복원한다.
  if jsonb_array_length(v_new_hist) >= jsonb_array_length(v_old_hist) then
    v_hist := v_new_hist;
  else
    v_hist := v_old_hist;
  end if;

  -- 3축이 실제로 바뀌었고 직전 값이 비어있지 않으면, 직전 조합을 이력으로 덧붙인다(append-only).
  if v_old3 <> '{}'::jsonb and v_old3 is distinct from v_new3 then
    -- 본인 이름만 조회하므로 users_select(본인/내부 조회 허용)를 그대로 통과한다.
    select u.name into v_actor from public.users u where u.id = app.current_app_user_id();
    v_hist := v_hist || jsonb_build_object(
      'affiliation', OLD.affiliation,
      'department',  OLD.profile->>'department',
      'position',    OLD.profile->>'position',
      'by',          v_actor,
      'source',      coalesce(v_ctx->>'source', 'manual'),
      'note',        v_ctx->>'note',
      'at',          now()
    );
  end if;

  -- 빈 이력이면 키를 만들지 않는다(profile 오염 방지).
  if v_hist <> '[]'::jsonb then
    NEW.profile := jsonb_set(coalesce(NEW.profile, '{}'::jsonb), '{affiliation_history}', v_hist, true);
  end if;

  return NEW;
end $$;


ALTER FUNCTION "app"."track_affiliation_history"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."track_affiliation_history"() IS '소속 이력 트리거(BEFORE UPDATE). 소속·부서·직책이 바뀌면 직전 조합을 profile.affiliation_history에 보존하며, 그 항목에 갱신한 사람(by, 표시용 이름 스냅샷)을 함께 남긴다. 배열의 소유자로서 클라이언트의 profile 통째 교체로 이력이 유실되는 것도 막는다.';



CREATE OR REPLACE FUNCTION "app"."track_network_contact_history"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_history jsonb;
begin
  if new.email is not distinct from old.email and new.phone is not distinct from old.phone then
    return new;
  end if;
  if nullif(btrim(coalesce(old.email, '')), '') is null
     and app.norm_phone(old.phone) is null then
    return new;
  end if;

  v_history := coalesce(new.profile -> 'contact_history', '[]'::jsonb);
  new.profile := jsonb_set(
    coalesce(new.profile, '{}'::jsonb),
    '{contact_history}',
    v_history || jsonb_build_array(jsonb_build_object(
      'email', old.email,
      'phone', old.phone,
      'changed_at', clock_timestamp(),
      'changed_by', app.current_app_user_id()
    )),
    true
  );
  return new;
end;
$$;


ALTER FUNCTION "app"."track_network_contact_history"() OWNER TO "postgres";


COMMENT ON FUNCTION "app"."track_network_contact_history"() IS 'NETWORKS 이메일·전화 변경 전 값을 profile.contact_history에 보존한다. 현재 연락처는 유일키가 아니다.';



CREATE OR REPLACE FUNCTION "app"."validate_guest_participant_roster"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  -- 인격 없는 임시 게스트는 가리킬 원장이 없으므로 기존 GUEST 연결 자체를 정본으로 둔다.
  if new.master_table is null or new.master_id is null then
    return new;
  end if;

  -- 참가 줄의 계정은 반드시 바로 그 원장 인격에 연결된 계정이어야 한다. 이메일로 찾은 다른
  -- users 행을 잘못 끼워 넣어도 화면에서는 이름이 비슷해 보여 발견하기 어렵기 때문에 FK에
  -- 준하는 이 검사를 다형 매핑 트리거가 맡는다.
  if new.user_id is not null and not exists (
    select 1
      from public.guest_identities gi
     where gi.user_id = new.user_id
       and gi.master_table = new.master_table
       and gi.master_id = new.master_id
  ) then
    raise exception '선택한 계정은 이 참가자의 자격에 연결된 계정이 아닙니다.'
      using errcode = '23503', hint = 'participant_user_identity_mismatch';
  end if;

  if new.entity_key in ('program', 'ma_program') then
    if not exists (
      select 1
        from public.program_participant_entries e
       where e.entity_key = new.entity_key
         and e.program_id = new.program_id
         and e.master_table = new.master_table
         and e.master_id = new.master_id
         and e.deleted_at is null
    ) then
      raise exception '실제 참가 명단에 없는 대상에게 GUEST 계정을 연결할 수 없습니다. 참가 명단에 먼저 추가하세요.'
        using errcode = '23503', hint = 'guest_requires_roster_entry';
    end if;
  elsif new.entity_key = 'fund' then
    if new.master_table <> 'startups' or not exists (
      select 1
        from public.investments i
       where i.fund_id = new.program_id
         and i.startup_id = new.master_id
         and i.deleted_at is null
    ) then
      raise exception '포트폴리오에 없는 기업에게 조합 GUEST 계정을 연결할 수 없습니다.'
        using errcode = '23503', hint = 'guest_requires_portfolio_entry';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "app"."validate_guest_participant_roster"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."validate_ma_party_viewers"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_bad uuid;
begin
  select coalesce(array_agg(x order by x), '{}'::uuid[])
    into new.viewer_ids
    from (
      select distinct id as x
        from unnest(coalesce(new.viewer_ids, '{}'::uuid[])) id
       where id is not null
         and id is distinct from new.created_by
    ) normalized;

  select ids.id
    into v_bad
    from unnest(new.viewer_ids) ids(id)
    left join public.users u
      on u.id = ids.id
     and u.deleted_at is null
     and u.is_active
     and not app.is_guest_user_type(u.user_type)
   where u.id is null
      or (
        u.user_type::text <> 'super_admin'
        and not exists (
          select 1
            from public.workspace_permissions wp
           where wp.user_id = u.id
             and wp.workspace_key::text = 'mna'
             and wp.permission_level in ('read', 'write')
             and (wp.expires_at is null or wp.expires_at > now())
        )
      )
   limit 1;

  if v_bad is not null then
    raise exception 'M&A 열람 권한이 없는 사용자는 열람자로 지정할 수 없습니다: %', v_bad
      using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app"."validate_ma_party_viewers"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."validate_ma_program_party_link_access"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if new.buyer_id is not null
     and not app.can_read_ma_party('ma_buyer', new.buyer_id) then
    raise exception '열람할 수 없는 M&A BUYER 게시글은 프로젝트에 연결할 수 없습니다.'
      using errcode = '42501';
  end if;
  if new.seller_id is not null
     and not app.can_read_ma_party('ma_seller', new.seller_id) then
    raise exception '열람할 수 없는 M&A SELLER 게시글은 프로젝트에 연결할 수 없습니다.'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app"."validate_ma_program_party_link_access"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."ws_module_row"("p_entity_key" "text", "p_module_id" "uuid") RETURNS TABLE("program_id" "uuid", "module_type" "text", "enabled" boolean, "status" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  select m.program_id, m.module_type::text, m.enabled, m.status::text
    from public.program_modules m
   where m.id = p_module_id
     and m.entity_key = p_entity_key;
$$;


ALTER FUNCTION "app"."ws_module_row"("p_entity_key" "text", "p_module_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."ws_module_row"("p_entity_key" "text", "p_module_id" "uuid") IS '다형 키로 모듈 1행을 읽는 단일 창구. SECURITY INVOKER이므로 호출자의 모듈 RLS가 그대로 적용된다.';



CREATE OR REPLACE FUNCTION "app"."ws_module_tables"("p_entity_key" "text") RETURNS TABLE("module_table" "text", "managers_table" "text", "timeline_table" "text")
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  select t.c2, t.c3, t.c4
    from (values
      ('program',    'program_modules', 'program_managers',    'program_timeline_items'),
      ('ma_program', 'program_modules', 'ma_program_managers', 'ma_program_timeline_items')
    ) as t(c1, c2, c3, c4)
   where t.c1 = p_entity_key;
$$;


ALTER FUNCTION "app"."ws_module_tables"("p_entity_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."ws_module_tables"("p_entity_key" "text") IS '다형 키 → 모듈·담당자·타임라인 원장 이름. 모듈 원장은 2026-09-03 통합되어 세 키 모두 program_modules를 가리킨다.';



CREATE OR REPLACE FUNCTION "public"."add_program_guest_accounts"("p_entity_key" "text", "p_program_id" "uuid", "p_user_ids" "uuid"[]) RETURNS TABLE("user_id" "uuid", "status" "text", "reason" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid  uuid := app.current_app_user_id();
  v_ws   text;
  v_id   uuid;
  v_seen uuid[] := '{}'::uuid[];
begin
  if v_uid is null or app.is_guest() then
    raise exception '내부 사용자만 게스트 명부를 고칠 수 있습니다.' using errcode = '42501';
  end if;
  if p_entity_key is null or p_entity_key not in ('program', 'ma_program', 'fund') then
    raise exception '알 수 없는 사업 원장입니다: %', p_entity_key using errcode = '22023';
  end if;

  -- **담당자 판정이 실재 확인보다 먼저다.** 순서를 뒤집으면 "없는 사업"과 "볼 수 없는
  -- 사업"이 다른 오류로 갈려, id를 넣어 보는 것만으로 M&A 딜의 실재를 알 수 있다.
  if p_program_id is null or not app.is_program_manager(p_program_id) then
    raise exception '담당자(PM·MEMBER·운용역)만 게스트 명부에 계정을 담을 수 있습니다.'
      using errcode = '42501';
  end if;

  -- 원장 키와 실제 id의 짝. 트리거(app.enforce_program_ref)도 같은 사실을 막지만,
  -- 여기서 먼저 답해야 담당자인 사업의 id에 남의 원장 키를 붙이는 요청이 명확히 걸린다.
  v_ws := app.program_ws(p_program_id);
  if v_ws is null or v_ws is distinct from app.entity_key_workspace(p_entity_key) then
    raise exception '사업 원장과 대상이 짝이 맞지 않습니다.' using errcode = '22023';
  end if;

  if p_user_ids is null or array_length(p_user_ids, 1) is null then
    return;
  end if;
  if array_length(p_user_ids, 1) > 200 then
    raise exception '한 번에 담을 수 있는 계정은 최대 200건입니다.' using errcode = '22023';
  end if;

  -- **맥락 하나에 잠금 하나**를 루프 밖에서 미리 잡는다. 원장 연결이 없는 줄은 유일
  -- 인덱스(uq_program_participants_master)가 덮지 않으므로 — 부분 인덱스의 조건이
  -- master_id is not null이다 — 확인과 삽입을 한 잠금 안에 둔다. 계정마다 잠그면
  -- [A,B]와 [B,A] 두 요청이 서로의 잠금을 기다려 교착한다. 잠금이 하나뿐이면 그 교착이
  -- 성립할 수 없고, 결과 순서는 입력 순서 그대로 유지된다(정렬은 잠금에도 응답에도
  -- 들어가지 않는다). 잠금은 트랜잭션이 끝날 때 함께 풀린다.
  perform pg_advisory_xact_lock(
    hashtextextended(p_entity_key || ':' || p_program_id::text, 0));

  foreach v_id in array p_user_ids loop
    continue when v_id is null;

    user_id := v_id;
    status  := null;
    reason  := null;

    if v_id = any (v_seen) then
      status := 'ALREADY_PRESENT';
      reason := 'DUPLICATE_IN_REQUEST';
      return next;
      continue;
    end if;
    v_seen := v_seen || v_id;

    -- 살아 있는 GUEST 계정이면서 호출자에게 보이는가. 둘을 한 사유로 묶어 답한다.
    if not exists (
      select 1
        from public.users u
       where u.id = v_id
         and u.deleted_at is null
         and u.is_active
         and app.is_guest_user_type(u.user_type)
    ) or not app.guest_account_visible(v_id) then
      status := 'FAILED';
      reason := 'ACCOUNT_NOT_AVAILABLE';
      return next;
      continue;
    end if;

    -- 이미 이 사업에 있는 계정은 **손대지 않는다.** 원장 연결이 있는 줄이든 없는 줄이든
    -- 마찬가지다 — 담기를 다시 눌렀다는 이유로 기존 줄의 인격·문 상태를 지울 수 없다.
    if exists (
      select 1
        from public.program_participants pp
       where pp.entity_key = p_entity_key
         and pp.program_id = p_program_id
         and pp.user_id    = v_id
    ) then
      status := 'ALREADY_PRESENT';
      return next;
      continue;
    end if;

    -- 쓰는 것은 이 한 줄뿐이다. 원장 참조는 null이고(연결은 선택이다) 문은 닫힌 채로
    -- 시작한다 — 명부에 담기와 로그인 열기는 다른 축이고, 여는 것은 담당자의 별도
    -- 행위다(open_program_guest_access). created_by는 트리거가 찍는다.
    insert into public.program_participants
      (entity_key, program_id, user_id, master_table, master_id, login_status)
    values
      (p_entity_key, p_program_id, v_id, null, null, 'NOT_ALLOWED');

    perform app.log_guest_access(
      v_id,
      'GUEST_ROSTER_ADD',
      'guest:roster',
      jsonb_build_object(
        'entity_key', p_entity_key,
        'program_id', p_program_id,
        'workspace',  v_ws,
        'source',     'workspace_guest_menu'
      ),
      null
    );

    status := 'ADDED';
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "public"."add_program_guest_accounts"("p_entity_key" "text", "p_program_id" "uuid", "p_user_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_program_guest_accounts"("p_entity_key" "text", "p_program_id" "uuid", "p_user_ids" "uuid"[]) IS '이미 있는 GUEST 계정을 그 사업·조합 명부에 담는다(담당자 전용, SECURITY INVOKER). 계정·인격·참가 원장을 만들지 않고 program_participants 한 줄만 쓰며 원장 참조는 null, 문은 NOT_ALLOWED로 닫힌 채다. 계정당 ADDED/ALREADY_PRESENT/FAILED 한 줄을 입력 순서대로 돌려주고, 보이지 않는 계정은 존재를 답하지 않는다.';



CREATE OR REPLACE FUNCTION "public"."admin_entities_delete_blockers"("p_entity_key" "text", "p_ids" "uuid"[]) RETURNS TABLE("blocker_key" "text", "blocker_label" "text", "row_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if not app.is_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if p_entity_key not in (
    'startups', 'networks', 'programs', 'ma_programs', 'ma_buyers', 'ma_sellers', 'funds'
  ) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  if coalesce(array_length(p_ids, 1), 0) = 0 or cardinality(p_ids) > 100 then
    raise exception 'invalid_selection' using errcode = '22023';
  end if;

  return query
  select b.blocker_key, b.blocker_label, sum(b.row_count)::bigint
    from (select distinct x as id from unnest(p_ids) as x) selected
    cross join lateral public.admin_entity_delete_blockers(p_entity_key, selected.id) b
   group by b.blocker_key, b.blocker_label
   order by b.blocker_label;
end $$;


ALTER FUNCTION "public"."admin_entities_delete_blockers"("p_entity_key" "text", "p_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_entities_delete_blockers"("p_entity_key" "text", "p_ids" "uuid"[]) IS 'ADMIN 다중 영구 삭제 확인용 연결 데이터 합계(7종, 최대 100건). 삭제 RPC는 각 행의 단건 blocker를 다시 판정한다.';



CREATE OR REPLACE FUNCTION "public"."admin_entity_delete_blockers"("p_entity_key" "text", "p_id" "uuid") RETURNS TABLE("blocker_key" "text", "blocker_label" "text", "row_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if not app.is_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  if p_entity_key = 'startups' then
    return query
    select b.blocker_key, b.blocker_label, b.row_count
      from (values
        ('applications'::text, '지원서'::text,
          (select count(*) from public.application_submissions where startup_id = p_id)),
        ('guest_accounts'::text, '게스트 초대·계정'::text,
          (select count(*) from public.guest_invitations
            where company_id = p_id or (target_type = 'startup' and target_id = p_id))),
        ('investments'::text, '투자 이력'::text,
          (select count(*) from public.investments where startup_id = p_id)),
        ('ma_links'::text, 'M&A 연결'::text,
          ((select count(*) from public.ma_buyers where startup_id = p_id)
           + (select count(*) from public.ma_sellers where startup_id = p_id)
           + (select count(*) from public.ma_deals where target_company_id = p_id)
           + (select count(*) from public.ma_match_candidates
               where buyer_company_id = p_id or seller_company_id = p_id))),
        ('guest_users'::text, '연결 계정'::text,
          (select count(*) from public.users where company_id = p_id)),
        ('merged_rows'::text, '병합 원본'::text,
          (select count(*) from public.startups where merged_into_id = p_id)),
        ('attachments'::text, '첨부 자료'::text,
          (select count(*) from public.attachments where target_type = 'startup' and target_id = p_id)),
        ('feedback'::text, '피드백'::text,
          (select count(*) from public.entity_feedback where target_type = 'startup' and target_id = p_id)),
        ('minutes'::text, '회의록 연결'::text,
          (select count(*) from public.meeting_minute_links where target_type = 'startup' and target_id = p_id)),
        ('approvals'::text, '전자결재 연결'::text,
          (select count(*) from public.approval_program_links where target_type = 'startup' and target_id = p_id))
      ) as b(blocker_key, blocker_label, row_count)
     where b.row_count > 0;

  elsif p_entity_key = 'networks' then
    return query
    select b.blocker_key, b.blocker_label, b.row_count
      from (values
        ('merged_rows'::text, '병합 원본'::text,
          (select count(*) from public.networks where merged_into_id = p_id)),
        ('attachments'::text, '첨부 자료'::text,
          (select count(*) from public.attachments where target_type = 'network' and target_id = p_id)),
        ('feedback'::text, '피드백'::text,
          (select count(*) from public.entity_feedback where target_type = 'network' and target_id = p_id)),
        ('minutes'::text, '회의록 연결'::text,
          (select count(*) from public.meeting_minute_links where target_type = 'network' and target_id = p_id)),
        ('approvals'::text, '전자결재 연결'::text,
          (select count(*) from public.approval_program_links where target_type = 'network' and target_id = p_id))
      ) as b(blocker_key, blocker_label, row_count)
     where b.row_count > 0;

  elsif p_entity_key = 'programs' then
    return query
    select b.blocker_key, b.blocker_label, b.row_count
      from (values
        ('applications'::text, '지원양식·지원서'::text,
          ((select count(*) from public.application_forms where program_id = p_id)
           + (select count(*) from public.application_submissions where program_id = p_id))),
        ('staffing'::text, '담당자·부서 배치'::text,
          ((select count(*) from public.program_departments where program_id = p_id)
           + (select count(*) from public.program_managers where program_id = p_id))),
        ('timeline'::text, '일정·일정 충돌'::text,
          ((select count(*) from public.program_timeline_items where program_id = p_id)
           + (select count(*) from public.timeline_conflicts where program_id = p_id))),
        ('modules'::text, '모듈·본문'::text,
          ((select count(*) from public.program_modules
             where program_id = p_id and entity_key = 'program')
           + (select count(*) from public.program_posts
               where program_id = p_id and entity_key = 'program')
           + (select count(*) from public.program_links
               where program_id = p_id and entity_key = 'program')
           + (select count(*) from public.program_overviews
               where program_id = p_id and entity_key = 'program')
           + (select count(*) from public.program_announcements
               where program_id = p_id and entity_key = 'program')
           + (select count(*) from public.program_questions
               where program_id = p_id and entity_key = 'program')
           + (select count(*) from public.program_notices n
               where n.program_id = p_id
                 and exists (select 1 from public.program_modules m
                              where m.id = n.program_module_id and m.entity_key = 'program')))),
        ('participants'::text, '참가자 명부'::text,
          ((select count(*) from public.program_participants
             where program_id = p_id and entity_key = 'program')
           + (select count(*) from public.program_participant_entries
               where program_id = p_id and entity_key = 'program'))),
        ('guest_accounts'::text, '게스트 초대·계정'::text,
          (select count(*) from public.guest_invitations
            where target_type = 'program' and target_id = p_id)),
        ('exports'::text, '내보내기 작업'::text,
          (select count(*) from public.export_jobs where program_id = p_id)),
        ('kpi_snapshots'::text, 'KPI 스냅샷'::text,
          (select count(*) from public.module_kpi_snapshots where program_id = p_id)),
        ('attachments'::text, '첨부 자료'::text,
          (select count(*) from public.attachments where target_type = 'program' and target_id = p_id)),
        ('feedback'::text, '피드백'::text,
          (select count(*) from public.entity_feedback where target_type = 'program' and target_id = p_id)),
        ('minutes'::text, '회의록 연결'::text,
          (select count(*) from public.meeting_minute_links where target_type = 'program' and target_id = p_id)),
        ('approvals'::text, '전자결재 연결'::text,
          (select count(*) from public.approval_program_links where target_type = 'program' and target_id = p_id))
      ) as b(blocker_key, blocker_label, row_count)
     where b.row_count > 0;

  elsif p_entity_key = 'ma_programs' then
    return query
    select b.blocker_key, b.blocker_label, b.row_count
      from (values
        ('staffing'::text, '담당자·부서 배치'::text,
          ((select count(*) from public.ma_program_departments where program_id = p_id)
           + (select count(*) from public.ma_program_managers where program_id = p_id))),
        ('timeline'::text, '일정'::text,
          (select count(*) from public.ma_program_timeline_items where program_id = p_id)),
        ('party_links'::text, '거래상대 연결'::text,
          (select count(*) from public.ma_program_party_links where program_id = p_id)),
        ('modules'::text, '모듈·본문'::text,
          ((select count(*) from public.program_modules
             where program_id = p_id and entity_key = 'ma_program')
           + (select count(*) from public.program_posts
               where program_id = p_id and entity_key = 'ma_program')
           + (select count(*) from public.program_links
               where program_id = p_id and entity_key = 'ma_program')
           + (select count(*) from public.program_overviews
               where program_id = p_id and entity_key = 'ma_program')
           + (select count(*) from public.program_announcements
               where program_id = p_id and entity_key = 'ma_program')
           + (select count(*) from public.program_questions
               where program_id = p_id and entity_key = 'ma_program')
           + (select count(*) from public.program_notices n
               where n.program_id = p_id
                 and exists (select 1 from public.program_modules m
                              where m.id = n.program_module_id and m.entity_key = 'ma_program')))),
        ('participants'::text, '참가자 명부'::text,
          ((select count(*) from public.program_participants
             where program_id = p_id and entity_key = 'ma_program')
           + (select count(*) from public.program_participant_entries
               where program_id = p_id and entity_key = 'ma_program'))),
        ('retired_modules'::text, '퇴역 모듈 원장'::text,
          ((select count(*) from public._retired_ma_program_links where program_id = p_id)
           + (select count(*) from public._retired_ma_program_modules where program_id = p_id)
           + (select count(*) from public._retired_ma_program_participants where program_id = p_id)
           + (select count(*) from public._retired_ma_program_posts where program_id = p_id))),
        ('guest_accounts'::text, '게스트 초대·계정'::text,
          (select count(*) from public.guest_invitations
            where target_type = 'ma_program' and target_id = p_id)),
        ('attachments'::text, '첨부 자료'::text,
          (select count(*) from public.attachments where target_type = 'ma_program' and target_id = p_id)),
        ('feedback'::text, '피드백'::text,
          (select count(*) from public.entity_feedback where target_type = 'ma_program' and target_id = p_id)),
        ('minutes'::text, '회의록 연결'::text,
          (select count(*) from public.meeting_minute_links where target_type = 'ma_program' and target_id = p_id)),
        ('approvals'::text, '전자결재 연결'::text,
          (select count(*) from public.approval_program_links where target_type = 'ma_program' and target_id = p_id))
      ) as b(blocker_key, blocker_label, row_count)
     where b.row_count > 0;

  elsif p_entity_key = 'funds' then
    -- approval_program_links는 CHECK가 program·ma_program만 받으므로 조합에는 오지 않는다.
    return query
    select b.blocker_key, b.blocker_label, b.row_count
      from (values
        ('fund_lps'::text, '조합원(LP)'::text,
          (select count(*) from public.fund_lps where fund_id = p_id)),
        ('capital_calls'::text, '캐피탈콜·납입'::text,
          ((select count(*) from public.capital_calls where fund_id = p_id)
           + (select count(*) from public.capital_call_payments where fund_id = p_id))),
        ('investments'::text, '투자 이력·투자목적'::text,
          ((select count(*) from public.investments where fund_id = p_id)
           + (select count(*) from public.investment_purposes where fund_id = p_id))),
        ('fund_purposes'::text, '결성목적'::text,
          (select count(*) from public.fund_purposes where fund_id = p_id)),
        ('managers'::text, '담당자'::text,
          (select count(*) from public.fund_managers where fund_id = p_id)),
        ('content'::text, '사업개요·공지·Q&A'::text,
          ((select count(*) from public.program_overviews
             where program_id = p_id and entity_key = 'fund')
           + (select count(*) from public.program_announcements
               where program_id = p_id and entity_key = 'fund')
           + (select count(*) from public.program_questions
               where program_id = p_id and entity_key = 'fund'))),
        ('participants'::text, '참가자 명부'::text,
          (select count(*) from public.program_participants
            where program_id = p_id and entity_key = 'fund')),
        ('guest_accounts'::text, '게스트 초대·계정'::text,
          (select count(*) from public.guest_invitations
            where target_type = 'fund' and target_id = p_id)),
        ('attachments'::text, '첨부 자료'::text,
          (select count(*) from public.attachments where target_type = 'fund' and target_id = p_id)),
        ('feedback'::text, '피드백'::text,
          (select count(*) from public.entity_feedback where target_type = 'fund' and target_id = p_id)),
        ('minutes'::text, '회의록 연결'::text,
          (select count(*) from public.meeting_minute_links where target_type = 'fund' and target_id = p_id))
      ) as b(blocker_key, blocker_label, row_count)
     where b.row_count > 0;

  elsif p_entity_key = 'ma_buyers' then
    return query
    select b.blocker_key, b.blocker_label, b.row_count
      from (values
        ('program_links'::text, 'M&A 사업 연결'::text,
          (select count(*) from public.ma_program_party_links where buyer_id = p_id)),
        ('merged_rows'::text, '병합 원본'::text,
          (select count(*) from public.ma_buyers where merged_into_id = p_id)),
        ('participants'::text, '참가자 명부'::text,
          ((select count(*) from public.program_participants
             where master_table = 'ma_buyers' and master_id = p_id)
           + (select count(*) from public.program_participant_entries
               where master_table = 'ma_buyers' and master_id = p_id))),
        ('guest_accounts'::text, '게스트 초대·계정'::text,
          ((select count(*) from public.guest_identities
             where master_table = 'ma_buyers' and master_id = p_id)
           + (select count(*) from public.guest_invitations
               where target_type = 'ma_buyer' and target_id = p_id))),
        ('attachments'::text, '첨부 자료'::text,
          (select count(*) from public.attachments where target_type = 'ma_buyer' and target_id = p_id)),
        ('feedback'::text, '피드백'::text,
          (select count(*) from public.entity_feedback where target_type = 'ma_buyer' and target_id = p_id)),
        ('minutes'::text, '회의록 연결'::text,
          (select count(*) from public.meeting_minute_links where target_type = 'ma_buyer' and target_id = p_id))
      ) as b(blocker_key, blocker_label, row_count)
     where b.row_count > 0;

  elsif p_entity_key = 'ma_sellers' then
    return query
    select b.blocker_key, b.blocker_label, b.row_count
      from (values
        ('program_links'::text, 'M&A 사업 연결'::text,
          (select count(*) from public.ma_program_party_links where seller_id = p_id)),
        ('merged_rows'::text, '병합 원본'::text,
          (select count(*) from public.ma_sellers where merged_into_id = p_id)),
        ('participants'::text, '참가자 명부'::text,
          ((select count(*) from public.program_participants
             where master_table = 'ma_sellers' and master_id = p_id)
           + (select count(*) from public.program_participant_entries
               where master_table = 'ma_sellers' and master_id = p_id))),
        ('guest_accounts'::text, '게스트 초대·계정'::text,
          ((select count(*) from public.guest_identities
             where master_table = 'ma_sellers' and master_id = p_id)
           + (select count(*) from public.guest_invitations
               where target_type = 'ma_seller' and target_id = p_id))),
        ('attachments'::text, '첨부 자료'::text,
          (select count(*) from public.attachments where target_type = 'ma_seller' and target_id = p_id)),
        ('feedback'::text, '피드백'::text,
          (select count(*) from public.entity_feedback where target_type = 'ma_seller' and target_id = p_id)),
        ('minutes'::text, '회의록 연결'::text,
          (select count(*) from public.meeting_minute_links where target_type = 'ma_seller' and target_id = p_id))
      ) as b(blocker_key, blocker_label, row_count)
     where b.row_count > 0;

  else
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
end $$;


ALTER FUNCTION "public"."admin_entity_delete_blockers"("p_entity_key" "text", "p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_entity_delete_blockers"("p_entity_key" "text", "p_id" "uuid") IS 'ADMIN 비활성 원장 영구 삭제를 막는 업무 연결과 자료 건수(7종). FK가 on delete cascade여도 업무·공용 기록이면 전부 막는다 — 거절 대신 조용한 cascade가 가장 나쁜 실패다. program_id를 쓰는 다형 표는 entity_key를 함께 걸어 워크스페이스가 섞이지 않게 하고, 모듈 하위 표는 부모 program_modules 행이 대신 막는다. 삭제 RPC가 같은 함수를 다시 판정한다.';



CREATE OR REPLACE FUNCTION "public"."admin_hard_delete_entities"("p_entity_key" "text", "p_ids" "uuid"[], "p_reason" "text", "p_confirm_text" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_id    uuid;
  v_count integer := 0;
begin
  if not app.is_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if p_entity_key not in (
    'startups', 'networks', 'programs', 'ma_programs', 'ma_buyers', 'ma_sellers', 'funds'
  ) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  if coalesce(array_length(p_ids, 1), 0) = 0 then
    raise exception 'empty_selection' using errcode = '22023';
  end if;
  if cardinality(p_ids) > 100 then
    raise exception 'too_many_entities' using errcode = '22023';
  end if;

  for v_id in select distinct x from unnest(p_ids) as x
  loop
    perform public.admin_hard_delete_entity(
      p_entity_key,
      v_id,
      btrim(p_reason),
      p_confirm_text
    );
    v_count := v_count + 1;
  end loop;

  return v_count;
end $$;


ALTER FUNCTION "public"."admin_hard_delete_entities"("p_entity_key" "text", "p_ids" "uuid"[], "p_reason" "text", "p_confirm_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_hard_delete_entities"("p_entity_key" "text", "p_ids" "uuid"[], "p_reason" "text", "p_confirm_text" "text") IS 'ADMIN 비활성 원장 선택 행 물리 삭제(7종, 최대 100건). 단건 확인 문구·사유·blocker·감사 로그 규칙을 그대로 재사용하며 한 행이라도 실패하면 전체 롤백.';



CREATE OR REPLACE FUNCTION "public"."admin_hard_delete_entity"("p_entity_key" "text", "p_id" "uuid", "p_reason" "text", "p_confirm_text" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_name       text;
  v_deleted_at timestamptz;
  v_blockers   text;
  v_target     text;  -- attachments·notifications 등 다형 target_type
  v_contrib    text;  -- entity_contributions.entity_table (표 이름과 다르다)
  v_workspace  text;  -- audit_logs.changed_workspace
  v_rows       integer;
begin
  if not app.is_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if p_entity_key not in (
    'startups', 'networks', 'programs', 'ma_programs', 'ma_buyers', 'ma_sellers', 'funds'
  ) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'reason_required' using errcode = '23514';
  end if;
  if btrim(coalesce(p_confirm_text, ''), E' .\t\r\n') <> '삭제합니다' then
    raise exception 'confirm_text_mismatch' using errcode = '22023';
  end if;

  -- 비활성 행만 온다. 병합 칸이 있는 넷은 병합 원본도 함께 거른다.
  if p_entity_key = 'startups' then
    select s.name, s.deleted_at into v_name, v_deleted_at
      from public.startups s
     where s.id = p_id and s.deleted_at is not null and s.merged_into_id is null;
    v_target := 'startup'; v_contrib := 'startups'; v_workspace := 'startup';

  elsif p_entity_key = 'networks' then
    select n.name, n.deleted_at into v_name, v_deleted_at
      from public.networks n
     where n.id = p_id and n.deleted_at is not null and n.merged_into_id is null;
    v_target := 'network'; v_contrib := 'networks'; v_workspace := 'networks';

  elsif p_entity_key = 'programs' then
    select p.title, p.deleted_at into v_name, v_deleted_at
      from public.programs p
     where p.id = p_id and p.deleted_at is not null;
    v_target := 'program'; v_contrib := 'program'; v_workspace := 'project';

  elsif p_entity_key = 'ma_programs' then
    select m.title, m.deleted_at into v_name, v_deleted_at
      from public.ma_programs m
     where m.id = p_id and m.deleted_at is not null;
    v_target := 'ma_program'; v_contrib := 'ma_program'; v_workspace := 'mna';

  elsif p_entity_key = 'ma_buyers' then
    select b.name, b.deleted_at into v_name, v_deleted_at
      from public.ma_buyers b
     where b.id = p_id and b.deleted_at is not null and b.merged_into_id is null;
    v_target := 'ma_buyer'; v_contrib := 'ma_buyers'; v_workspace := 'mna';

  elsif p_entity_key = 'ma_sellers' then
    select s.name, s.deleted_at into v_name, v_deleted_at
      from public.ma_sellers s
     where s.id = p_id and s.deleted_at is not null and s.merged_into_id is null;
    v_target := 'ma_seller'; v_contrib := 'ma_sellers'; v_workspace := 'mna';

  elsif p_entity_key = 'funds' then
    select f.name, f.deleted_at into v_name, v_deleted_at
      from public.funds f
     where f.id = p_id and f.deleted_at is not null;
    v_target := 'fund'; v_contrib := 'fund'; v_workspace := 'fund';

  else
    -- 위 허용 목록과 이 분기 둘 다 통과해야 한다. 한쪽만 열려도 삭제는 일어나지 않는다.
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;

  -- 일곱 원장 모두 이름 칸이 NOT NULL이므로 null은 "그런 비활성 행이 없다"는 뜻이다.
  if v_name is null then
    raise exception 'inactive_entity_not_found' using errcode = '02000';
  end if;

  select string_agg(b.blocker_label || ' ' || b.row_count || '건', ', ')
    into v_blockers
    from public.admin_entity_delete_blockers(p_entity_key, p_id) b;
  if v_blockers is not null then
    raise exception 'dependent_records_exist: %', v_blockers using errcode = '23001';
  end if;

  -- 되돌릴 수 없는 작업이라 지우기 전에 남긴다.
  insert into public.audit_logs (
    actor_user_id, action, changed_workspace, before_data, reason
  ) values (
    app.current_app_user_id(),
    'LEDGER_HARD_DELETE',
    v_workspace,
    jsonb_build_object(
      'entity_key', p_entity_key,
      'entity_id', p_id,
      'entity_name', v_name,
      'deleted_at', v_deleted_at
    ),
    btrim(p_reason)
  );

  -- 파생·내부 기록만 본체와 함께 제거한다.
  -- entity_codes는 발급 트리거가 붙은 셋(programs·ma_programs·funds)에만 행이 있고
  -- 레지스트리 키가 표 이름이다. 나머지 넷에서는 0건이라 조건만 두고 지나간다.
  if p_entity_key = 'startups' then
    delete from public.startup_managers where startup_id = p_id;
  end if;

  delete from public.notifications where target_type = v_target and target_id = p_id;
  delete from public.entity_codes where entity_table = p_entity_key and entity_id = p_id;
  delete from public.entity_contributions where entity_table = v_contrib and entity_id = p_id;

  if p_entity_key = 'startups' then
    delete from public.startups
     where id = p_id and deleted_at is not null and merged_into_id is null;
  elsif p_entity_key = 'networks' then
    delete from public.networks
     where id = p_id and deleted_at is not null and merged_into_id is null;
  elsif p_entity_key = 'programs' then
    delete from public.programs where id = p_id and deleted_at is not null;
  elsif p_entity_key = 'ma_programs' then
    delete from public.ma_programs where id = p_id and deleted_at is not null;
  elsif p_entity_key = 'ma_buyers' then
    delete from public.ma_buyers
     where id = p_id and deleted_at is not null and merged_into_id is null;
  elsif p_entity_key = 'ma_sellers' then
    delete from public.ma_sellers
     where id = p_id and deleted_at is not null and merged_into_id is null;
  elsif p_entity_key = 'funds' then
    delete from public.funds where id = p_id and deleted_at is not null;
  else
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    raise exception 'inactive_entity_not_found' using errcode = '02000';
  end if;
end $$;


ALTER FUNCTION "public"."admin_hard_delete_entity"("p_entity_key" "text", "p_id" "uuid", "p_reason" "text", "p_confirm_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_hard_delete_entity"("p_entity_key" "text", "p_id" "uuid", "p_reason" "text", "p_confirm_text" "text") IS 'ADMIN 전용 7종 원장 비활성 행 물리 삭제. 확인 문구 "삭제합니다"·사유·blocker 0건을 강제하고 지우기 전에 audit_logs(LEDGER_HARD_DELETE)를 원장의 워크스페이스로 남긴다. 지우는 것은 파생·내부 기록(notifications·entity_codes·entity_contributions, STARTUP은 startup_managers까지)과 본체뿐이며 업무 자료는 blocker가 대신 막는다. 표 이름·이름 칸·병합 조건·다형 어휘는 7종 분기에서만 정해지고 동적 식별자를 만들지 않는다.';



CREATE OR REPLACE FUNCTION "public"."admin_inactive_ledger_entities"("p_entity_key" "text", "p_keyword" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("entity_id" "uuid", "entity_name" "text", "category" "text", "detail" "text", "deleted_at" timestamp with time zone, "deactivated_by" "text", "deactivation_reason" "text", "total_count" bigint)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_keyword text := nullif(btrim(p_keyword), '');
  v_limit   integer := greatest(1, least(coalesce(p_limit, 20), 100));
  v_offset  integer := greatest(coalesce(p_offset, 0), 0);
begin
  if not app.is_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  if p_entity_key = 'startups' then
    return query
    select s.id,
           s.name,
           s.management_status,
           s.representative,
           s.deleted_at,
           d.user_name,
           d.note,
           count(*) over()
      from public.startups s
      left join lateral (
        select c.user_name, c.note
          from public.entity_contributions c
         where c.entity_table = 'startups'
           and c.entity_id = s.id
           and c.action = 'deactivated'
         order by c.created_at desc, c.id desc
         limit 1
      ) d on true
     where s.deleted_at is not null
       and s.merged_into_id is null
       and (
         v_keyword is null
         or s.name ilike '%' || v_keyword || '%'
         or coalesce(s.representative, '') ilike '%' || v_keyword || '%'
       )
     order by s.deleted_at desc, s.name, s.id
     limit v_limit offset v_offset;

  elsif p_entity_key = 'networks' then
    return query
    select n.id,
           n.name,
           n.category,
           n.affiliation,
           n.deleted_at,
           d.user_name,
           d.note,
           count(*) over()
      from public.networks n
      left join lateral (
        select c.user_name, c.note
          from public.entity_contributions c
         where c.entity_table = 'networks'
           and c.entity_id = n.id
           and c.action = 'deactivated'
         order by c.created_at desc, c.id desc
         limit 1
      ) d on true
     where n.deleted_at is not null
       and n.merged_into_id is null
       and (
         v_keyword is null
         or n.name ilike '%' || v_keyword || '%'
         or coalesce(n.affiliation, '') ilike '%' || v_keyword || '%'
       )
     order by n.deleted_at desc, n.name, n.id
     limit v_limit offset v_offset;

  elsif p_entity_key = 'programs' then
    -- programs에는 merged_into_id가 없다. 병합 조건을 넣지 않는다.
    return query
    select p.id,
           p.title,
           p.category,
           p.host_organization,
           p.deleted_at,
           d.user_name,
           d.note,
           count(*) over()
      from public.programs p
      left join lateral (
        select c.user_name, c.note
          from public.entity_contributions c
         where c.entity_table = 'program'
           and c.entity_id = p.id
           and c.action = 'deactivated'
         order by c.created_at desc, c.id desc
         limit 1
      ) d on true
     where p.deleted_at is not null
       and (
         v_keyword is null
         or p.title ilike '%' || v_keyword || '%'
         or coalesce(p.code, '') ilike '%' || v_keyword || '%'
         or coalesce(p.host_organization, '') ilike '%' || v_keyword || '%'
       )
     order by p.deleted_at desc, p.title, p.id
     limit v_limit offset v_offset;

  elsif p_entity_key = 'ma_programs' then
    return query
    select m.id,
           m.title,
           m.category,
           m.host_organization,
           m.deleted_at,
           d.user_name,
           d.note,
           count(*) over()
      from public.ma_programs m
      left join lateral (
        select c.user_name, c.note
          from public.entity_contributions c
         where c.entity_table = 'ma_program'
           and c.entity_id = m.id
           and c.action = 'deactivated'
         order by c.created_at desc, c.id desc
         limit 1
      ) d on true
     where m.deleted_at is not null
       and (
         v_keyword is null
         or m.title ilike '%' || v_keyword || '%'
         or coalesce(m.code, '') ilike '%' || v_keyword || '%'
         or coalesce(m.host_organization, '') ilike '%' || v_keyword || '%'
       )
     order by m.deleted_at desc, m.title, m.id
     limit v_limit offset v_offset;

  elsif p_entity_key in ('ma_buyers', 'ma_sellers') then
    return query
    select h.entity_id,
           h.entity_name,
           h.category,
           h.detail,
           h.deleted_at,
           h.deactivated_by,
           h.deactivation_reason,
           h.total_count
      from app.admin_inactive_ma_party_page(p_entity_key, v_keyword, v_limit, v_offset) h;

  elsif p_entity_key = 'funds' then
    return query
    select f.id,
           f.name,
           f.status::text,
           f.code,
           f.deleted_at,
           d.user_name,
           d.note,
           count(*) over()
      from public.funds f
      left join lateral (
        select c.user_name, c.note
          from public.entity_contributions c
         where c.entity_table = 'fund'
           and c.entity_id = f.id
           and c.action = 'deactivated'
         order by c.created_at desc, c.id desc
         limit 1
      ) d on true
     where f.deleted_at is not null
       and (
         v_keyword is null
         or f.name ilike '%' || v_keyword || '%'
         or coalesce(f.code, '') ilike '%' || v_keyword || '%'
       )
     order by f.deleted_at desc, f.name, f.id
     limit v_limit offset v_offset;

  else
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
end $$;


ALTER FUNCTION "public"."admin_inactive_ledger_entities"("p_entity_key" "text", "p_keyword" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_inactive_ledger_entities"("p_entity_key" "text", "p_keyword" "text", "p_limit" integer, "p_offset" integer) IS 'ADMIN 전용 비활성 원장 목록. 7종(startups·networks·programs·ma_programs·ma_buyers·ma_sellers·funds)을 같은 표시 계약으로 페이지 조회한다. 기여 이력 키는 각 원장의 현재 트리거 인자를 따른다.';



CREATE OR REPLACE FUNCTION "public"."admin_ledger_console_capabilities"("p_entity_key" "text" DEFAULT NULL::"text") RETURNS TABLE("entity_key" "text", "can_list" boolean, "can_restore" boolean, "can_hard_delete" boolean, "unsupported_note" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_key text := nullif(btrim(p_entity_key), '');
begin
  if not app.is_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if v_key is not null and v_key not in (
    'startups', 'networks', 'programs', 'ma_programs', 'ma_buyers', 'ma_sellers', 'funds'
  ) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;

  return query
  select c.entity_key, c.can_list, c.can_restore, c.can_hard_delete, c.unsupported_note
    from (values
      ('startups'::text,    true, true, true, null::text),
      ('networks'::text,    true, true, true, null::text),
      ('programs'::text,    true, true, true, null::text),
      ('ma_programs'::text, true, true, true, null::text),
      ('ma_buyers'::text,   true, true, true, null::text),
      ('ma_sellers'::text,  true, true, true, null::text),
      ('funds'::text,       true, true, true, null::text)
    ) as c(entity_key, can_list, can_restore, can_hard_delete, unsupported_note)
   where v_key is null or c.entity_key = v_key
   order by c.entity_key;
end $$;


ALTER FUNCTION "public"."admin_ledger_console_capabilities"("p_entity_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_ledger_console_capabilities"("p_entity_key" "text") IS 'ADMIN 비활성 원장 콘솔이 원장별로 무엇을 할 수 있는지 답하는 표. 조회·복구·영구 삭제 모두 7종 원장에서 참이며 미지원 사유는 없다.';



CREATE OR REPLACE FUNCTION "public"."admin_reset_guest_password"("p_user_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_account      public.users%rowtype;
  v_reason       text := nullif(btrim(coalesce(p_reason, '')), '');
  v_had_password boolean;
  v_version      integer;
begin
  if not app.is_admin() then
    raise exception 'GUEST 비밀번호는 시스템 관리자만 초기화할 수 있습니다.' using errcode = '42501';
  end if;
  if v_reason is null then
    raise exception '초기화 사유를 입력해야 합니다.' using errcode = '22023';
  end if;

  select u.* into v_account
    from public.users u
   where u.id = p_user_id and u.deleted_at is null
   for update;
  if not found then
    raise exception '대상 계정을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  if not app.is_guest_user_type(v_account.user_type) then
    raise exception 'GUEST 계정이 아닙니다.' using errcode = '22023';
  end if;

  -- 연락처가 없거나 너무 짧으면 초기화가 **로그인할 수 없는 계정**을 만든다. 먼저
  -- 연락처를 고치라고 답하는 편이 정직하다(admin_update_guest_contact와 같은 기준).
  if v_account.phone is null
     or app.norm_phone(v_account.phone) is null
     or length(app.norm_phone(v_account.phone)) < 9 then
    raise exception '연락처가 없어 초기화할 수 없습니다. 먼저 연락처를 수정하십시오.'
      using errcode = '22023';
  end if;

  v_had_password := app.guest_has_password(p_user_id);

  -- 해시·설정시각·재설정 토큰·잠금을 한 번에 비운다. 살아 있던 재설정 링크도 여기서
  -- 죽는다 — 초기화 뒤에 옛 링크가 통하면 그 링크가 계정을 다시 가져간다.
  insert into public.guest_credentials (
    user_id, password_hash, password_set_at,
    login_attempts, locked_until, reset_token_hash, reset_expires_at,
    reset_session_version
  ) values (p_user_id, null, null, 0, null, null, null, null)
  on conflict (user_id) do update
    set password_hash    = null,
        password_set_at  = null,
        login_attempts   = 0,
        locked_until     = null,
        reset_token_hash = null,
        reset_expires_at = null,
        reset_session_version = null;

  -- 발급된 세션과 단명 티켓(설정·선택)을 죽인다. is_active는 유지한다 — 초기화는
  -- 정지도 해제도 아니다.
  update public.users
     set session_version = session_version + 1,
         updated_at = now()
   where id = p_user_id
  returning session_version into v_version;

  perform app.log_guest_change(
    p_user_id,
    'GUEST_PASSWORD_RESET',
    'guest:credentials',
    jsonb_build_object('has_password', v_had_password),
    jsonb_build_object('has_password', false, 'initial_password', 'users.phone'),
    v_reason
  );

  return jsonb_build_object(
    'user_id', p_user_id,
    'had_password', v_had_password,
    'session_version', v_version,
    'sessions_invalidated', true
  );
end;
$$;


ALTER FUNCTION "public"."admin_reset_guest_password"("p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_reset_guest_password"("p_user_id" "uuid", "p_reason" "text") IS 'ADMIN 전용 GUEST 비밀번호 초기화. 해시·설정시각·재설정 토큰·잠금을 비워 계정을 개시 상태로 되돌리고 session_version을 올린다(is_active 유지). 그 뒤의 로그인은 현재 연락처로 들어와 개인 비밀번호를 정한 뒤에만 세션을 받는다. 값은 한 칸도 호출자에게 돌려주지 않는다. 근거: 3_9_1 §6.2';



CREATE OR REPLACE FUNCTION "public"."admin_set_permission_template"("p_user_type" "text", "p_workspace_key" "text", "p_level" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_actor      uuid := app.current_app_user_id();
  v_before     text;
  v_scope      public.scope_type;
begin
  -- 권한: ADMIN 쓰기 보유자(사실상 최고 관리자)만 조작 가능
  if not app.can_write_workspace('admin') then
    raise exception '권한이 없습니다.' using errcode = '42501';
  end if;

  if p_level not in ('none','read','write') then
    raise exception '허용되지 않은 권한 단계입니다: %', p_level using errcode = '22023';
  end if;

  -- 재귀 잠금 방지: 최고 관리자의 ADMIN 쓰기 권한은 해제할 수 없다
  if p_user_type = 'super_admin' and p_workspace_key = 'admin' and p_level <> 'write' then
    raise exception '시스템 관리자 권한은 해제할 수 없습니다.' using errcode = 'P0001';
  end if;

  -- 변경 전 값/범위 조회(없으면 기본값)
  select permission_level::text, scope_type
    into v_before, v_scope
    from public.permission_templates
   where user_type = p_user_type::public.user_type
     and workspace_key = p_workspace_key::public.workspace_key;

  v_before := coalesce(v_before, 'none');
  v_scope  := coalesce(v_scope, 'global');

  -- 1) 템플릿 갱신(멱등 upsert)
  insert into public.permission_templates (user_type, workspace_key, permission_level, scope_type)
  values (p_user_type::public.user_type, p_workspace_key::public.workspace_key,
          p_level::public.permission_level, v_scope)
  on conflict (user_type, workspace_key)
    do update set permission_level = excluded.permission_level;

  -- 2) 해당 역할 사용자들의 실 권한에 전파(세션 즉시 반영)
  insert into public.workspace_permissions (user_id, workspace_key, permission_level, scope_type)
  select u.id, p_workspace_key::public.workspace_key, p_level::public.permission_level, v_scope
    from public.users u
   where u.user_type = p_user_type::public.user_type
     and u.deleted_at is null
  on conflict (user_id, workspace_key)
    do update set permission_level = excluded.permission_level;

  -- 3) 감사 로그 기록
  insert into public.audit_logs
    (actor_user_id, action, changed_workspace, before_permission, after_permission,
     before_data, after_data)
  values
    (v_actor, 'PERMISSION_CHANGE', p_workspace_key, v_before, p_level,
     jsonb_build_object('user_type', p_user_type, 'level', v_before),
     jsonb_build_object('user_type', p_user_type, 'level', p_level));
end;
$$;


ALTER FUNCTION "public"."admin_set_permission_template"("p_user_type" "text", "p_workspace_key" "text", "p_level" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_guest_contact"("p_user_id" "uuid", "p_email" "text", "p_phone" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_account    public.users%rowtype;
  v_email      text := nullif(btrim(coalesce(p_email, '')), '');
  v_phone      text := nullif(btrim(coalesce(p_phone, '')), '');
  v_reason     text := nullif(btrim(coalesce(p_reason, '')), '');
  v_norm_email text;
  v_norm_phone text;
  v_holder     text;
  v_email_changed boolean;
  v_phone_changed boolean;
  v_reset_cleared boolean := false;
  v_version    integer;
begin
  if not app.is_admin() then
    raise exception 'GUEST 연락처는 시스템 관리자만 수정할 수 있습니다.' using errcode = '42501';
  end if;
  if v_reason is null then
    raise exception '수정 사유를 입력해야 합니다.' using errcode = '22023';
  end if;
  if v_email is null or v_phone is null then
    raise exception '이메일과 연락처를 모두 입력해야 합니다(바꾸지 않는 칸도 현재 값을 보냅니다).'
      using errcode = '22023';
  end if;

  v_norm_email := app.norm_email(v_email);
  v_norm_phone := app.norm_phone(v_phone);

  -- 형식 검사. 이메일은 로그인 아이디라 공백·다중 @를 허용하지 않고, 전화는 숫자만 남겨
  -- 9~15자리를 요구한다(02-123-4567 = 9자리, 국가번호 포함 최대 15자리 — E.164).
  if length(v_email) > 254 or v_norm_email !~ '^[^@[:space:]]+@[^@[:space:].]+(\.[^@[:space:].]+)+$' then
    raise exception '이메일 형식이 올바르지 않습니다: %', v_email using errcode = '22023';
  end if;
  if v_norm_phone is null or length(v_norm_phone) < 9 or length(v_norm_phone) > 15 then
    raise exception '연락처는 숫자 9~15자리여야 합니다.' using errcode = '22023';
  end if;

  select u.* into v_account
    from public.users u
   where u.id = p_user_id and u.deleted_at is null
   for update;
  if not found then
    raise exception '대상 계정을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  if not app.is_guest_user_type(v_account.user_type) then
    raise exception 'GUEST 계정이 아닙니다. 임직원 연락처는 인사 원장이 소유합니다.'
      using errcode = '22023';
  end if;

  -- 중복은 **정지된 계정까지** 본다. 정지는 되돌릴 수 있으므로, 정지 계정의 아이디를
  -- 다른 계정에 붙이면 해제하는 순간 살아 있는 계정 둘이 같은 아이디를 갖는다.
  -- 이메일은 내부 임직원까지 포함한 전체 활성 users에서 하나다(uq_users_email_live와 같은 범위).
  -- 조건을 인덱스 식(lower(btrim(email)))과 같은 모양으로 적는다. app.norm_email과 값은
  -- 같지만, 같은 식으로 물어야 부분 유일 인덱스를 타고 판정이 인덱스와 어긋나지 않는다.
  select u.name into v_holder
    from public.users u
   where u.id <> p_user_id
     and u.deleted_at is null
     and lower(btrim(u.email)) = v_norm_email
   limit 1;
  if v_holder is not null then
    raise exception '이 이메일은 이미 다른 계정(%)이 쓰고 있습니다.', v_holder
      using errcode = '23505';
  end if;

  -- 전화는 개시 상태의 초기 비밀번호이므로 GUEST 계정 사이에서 하나다
  -- (uq_users_guest_phone과 같은 범위 — 임직원 전화는 자격증명이 아니라 여기서 보지 않는다).
  select u.name into v_holder
    from public.users u
   where u.id <> p_user_id
     and u.deleted_at is null
     and app.is_guest_user_type(u.user_type)
     and app.norm_phone(u.phone) = v_norm_phone
   limit 1;
  if v_holder is not null then
    raise exception '이 연락처는 이미 다른 GUEST 계정(%)이 쓰고 있습니다.', v_holder
      using errcode = '23505';
  end if;

  v_email_changed := app.norm_email(v_account.email) is distinct from v_norm_email;
  v_phone_changed := app.norm_phone(v_account.phone) is distinct from v_norm_phone;

  -- 표기만 다른 재전송(대소문자·하이픈)은 값이 같으므로 아무 일도 하지 않는다.
  -- 세션을 죽이지도, 감사 로그에 빈 줄을 남기지도 않는다.
  if not v_email_changed and not v_phone_changed then
    return jsonb_build_object(
      'user_id', p_user_id,
      'changed', false,
      'email_changed', false,
      'phone_changed', false,
      'session_version', v_account.session_version
    );
  end if;

  update public.users
     set email = v_email,
         phone = v_phone,
         -- 아이디·초기 비밀번호가 바뀌면 옛 세션과 단명 티켓(설정·선택)은 그 자리에서 죽는다.
         -- is_active는 이 창구의 사실이 아니므로 그대로 둔다.
         session_version = session_version + 1,
         updated_at = now()
   where id = p_user_id
  returning session_version into v_version;

  -- 살아 있는 재설정 링크도 함께 죽인다. 링크는 **옛 연락처로 나간 열쇠**이므로, 주소나
  -- 번호가 바뀐 뒤에도 그것이 통하면 방금 끊어 낸 옛 수신처가 계정을 다시 가져간다.
  -- **비밀번호 해시는 건드리지 않는다** — 연락처 수정은 초기화가 아니다(초기화는 별개
  -- 창구이며 사유를 따로 받는다). 잠금 카운터도 그대로 둔다: 그것은 시도 이력의 사실이다.
  update public.guest_credentials
     set reset_token_hash = null,
         reset_expires_at = null,
         reset_session_version = null
   where user_id = p_user_id
     and (reset_token_hash is not null
          or reset_expires_at is not null
          or reset_session_version is not null);
  v_reset_cleared := found;

  perform app.log_guest_change(
    p_user_id,
    'GUEST_CONTACT_UPDATE',
    'guest:contact',
    jsonb_build_object('email', v_account.email, 'phone', v_account.phone),
    jsonb_build_object(
      'email', v_email,
      'phone', v_phone,
      'reset_link_cleared', v_reset_cleared
    ),
    v_reason
  );

  return jsonb_build_object(
    'user_id', p_user_id,
    'changed', true,
    'email_changed', v_email_changed,
    'phone_changed', v_phone_changed,
    'reset_link_cleared', v_reset_cleared,
    'session_version', v_version
  );
end;
$_$;


ALTER FUNCTION "public"."admin_update_guest_contact"("p_user_id" "uuid", "p_email" "text", "p_phone" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_update_guest_contact"("p_user_id" "uuid", "p_email" "text", "p_phone" "text", "p_reason" "text") IS 'ADMIN 전용 GUEST 로그인 아이디(이메일)·연락처 수정. users만 고치고 원장은 건드리지 않는다. 중복은 정지 계정까지 보며, 값이 바뀌면 session_version을 올려 세션과 단명 티켓을 무효화하고 살아 있는 재설정 링크를 비운다(비밀번호 해시·잠금과 is_active는 유지). 변경 전/후를 audit_logs에 남긴다. 근거: 3_9_1 §6.2';



CREATE OR REPLACE FUNCTION "public"."all_network_entities"("p_keyword" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 30, "p_offset" integer DEFAULT 0, "p_categories" "text"[] DEFAULT NULL::"text"[], "p_uncategorized" boolean DEFAULT NULL::boolean, "p_region_scope" "text"[] DEFAULT NULL::"text"[], "p_regions" "uuid"[] DEFAULT NULL::"uuid"[], "p_countries" "uuid"[] DEFAULT NULL::"uuid"[], "p_country_unset" boolean DEFAULT NULL::boolean, "p_search_email" boolean DEFAULT false, "p_search_phone" boolean DEFAULT false, "p_expertise" "text"[] DEFAULT NULL::"text"[], "p_match" "text" DEFAULT NULL::"text", "p_activity_min" integer DEFAULT NULL::integer, "p_activity_max" integer DEFAULT NULL::integer, "p_satisfaction_min" numeric DEFAULT NULL::numeric, "p_satisfaction_max" numeric DEFAULT NULL::numeric) RETURNS TABLE("id" "uuid", "name" "text", "affiliation" "text", "email" "text", "phone" "text", "linkedin_url" "text", "category" "text", "region_scope" "text", "region_tag_id" "uuid", "country_tag_id" "uuid", "region_name" "text", "country_name" "text", "profile" "jsonb", "expertise" "jsonb", "is_provisional" boolean, "created_by" "uuid", "creator_name" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "last_action" "text", "last_contributed_at" timestamp with time zone, "activity_count" bigint, "satisfaction_avg" numeric, "total_count" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  with m as (
    select * from public.network_entity_metrics()
  ),
  filtered as (
    select d.*,
           ct.region_tag_id as ct_region_tag_id,
           ct.name          as ct_country_name,
           coalesce(mm.activity_count, 0)::bigint as act,
           mm.satisfaction_avg as sat
      from public.networks d
      left join public.country_tags ct on ct.id = d.country_tag_id
      left join m mm on mm.entity_id = d.id
     where d.deleted_at is null
       and d.merged_into_id is null
       -- 구분과 미지정은 한 축이다(OR). 목록 필터에서 '미지정'이 구분 선택지 옆에 서므로
       -- '투자사 또는 미지정'이 표현돼야 한다 — 종전처럼 두 조건을 AND로 묶으면 그 조합은
       -- 늘 0건이 되고, 결과가 빈 이유가 화면 어디에도 보이지 않는다.
       and (case
              when (p_categories is null or cardinality(p_categories) = 0)
                   and p_uncategorized is null then true
              when (p_categories is null or cardinality(p_categories) = 0)
                then (p_uncategorized and d.category is null)
                     or (not p_uncategorized and d.category is not null)
              else d.category = any(p_categories)
                   or (coalesce(p_uncategorized, false) and d.category is null)
            end)
       and (p_region_scope is null or cardinality(p_region_scope) = 0
            or d.region_scope = any(p_region_scope))
       and (p_regions is null or cardinality(p_regions) = 0 or ct.region_tag_id = any(p_regions))
       and (p_countries is null or cardinality(p_countries) = 0 or d.country_tag_id = any(p_countries))
       and (p_country_unset is null
            or (p_country_unset and d.country_tag_id is null)
            or (not p_country_unset and d.country_tag_id is not null))
       -- 검색 범위: 이름·소속은 항상, 이메일·연락처는 목록에서 공개된 경우에만 닿는다.
       and (p_keyword is null or btrim(p_keyword) = ''
            or d.name ilike '%' || btrim(p_keyword) || '%'
            or d.affiliation ilike '%' || btrim(p_keyword) || '%'
            or (p_search_email and d.email ilike '%' || btrim(p_keyword) || '%')
            or (p_search_phone and d.phone ilike '%' || btrim(p_keyword) || '%'))
       and (p_expertise is null or cardinality(p_expertise) = 0 or d.expertise ?| p_expertise)
       -- 매칭 배지와 같은 규칙: 값이 비어 있으면 '가능'이 기본이다.
       and (p_match is null
            or (p_match = 'possible'
                and coalesce(nullif(d.profile ->> 'match_available', ''), 'true') in ('true', 'available'))
            or (p_match = 'impossible'
                and coalesce(nullif(d.profile ->> 'match_available', ''), 'true') not in ('true', 'available')))
       and (p_activity_min is null or coalesce(mm.activity_count, 0) >= p_activity_min)
       and (p_activity_max is null or coalesce(mm.activity_count, 0) <= p_activity_max)
       and (p_satisfaction_min is null or mm.satisfaction_avg >= p_satisfaction_min)
       and (p_satisfaction_max is null or mm.satisfaction_avg <= p_satisfaction_max)
  )
  select
    f.id, f.name, f.affiliation, f.email, f.phone, f.linkedin_url,
    f.category, f.region_scope,
    f.ct_region_tag_id as region_tag_id,
    f.country_tag_id,
    r.name as region_name,
    f.ct_country_name as country_name,
    f.profile, f.expertise, f.is_provisional,
    f.created_by, u.name as creator_name, f.created_at, f.updated_at,
    -- 기여 이력은 '내 것' 목록의 축이다. 전체 목록에서는 남의 레코드에 내 기여 시각이 없어
    -- 뜻이 서지 않으므로 비운다(반환 열은 두 범위가 같은 규약을 쓰도록 유지한다).
    null::text        as last_action,
    null::timestamptz as last_contributed_at,
    f.act, f.sat,
    count(*) over () as total_count
  from filtered f
  left join public.users u       on u.id = f.created_by
  left join public.region_tags r on r.id = f.ct_region_tag_id
  order by f.name asc
  limit greatest(p_limit, 0)
  offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."all_network_entities"("p_keyword" "text", "p_limit" integer, "p_offset" integer, "p_categories" "text"[], "p_uncategorized" boolean, "p_region_scope" "text"[], "p_regions" "uuid"[], "p_countries" "uuid"[], "p_country_unset" boolean, "p_search_email" boolean, "p_search_phone" boolean, "p_expertise" "text"[], "p_match" "text", "p_activity_min" integer, "p_activity_max" integer, "p_satisfaction_min" numeric, "p_satisfaction_max" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."all_network_entities"("p_keyword" "text", "p_limit" integer, "p_offset" integer, "p_categories" "text"[], "p_uncategorized" boolean, "p_region_scope" "text"[], "p_regions" "uuid"[], "p_countries" "uuid"[], "p_country_unset" boolean, "p_search_email" boolean, "p_search_phone" boolean, "p_expertise" "text"[], "p_match" "text", "p_activity_min" integer, "p_activity_max" integer, "p_satisfaction_min" numeric, "p_satisfaction_max" numeric) IS 'NETWORKS 통합 목록(볼 수 있는 전부). 구분·국가·권역·지역·영역·매칭·활동 축을 서버에서 건다. 구분과 미지정(p_uncategorized)은 한 축이라 OR로 합쳐 판정한다. 권역은 국가를 조인해 판정한다(행에 저장하지 않는다). SECURITY INVOKER — public.networks의 RLS를 그대로 따른다.';



CREATE OR REPLACE FUNCTION "public"."approval_budget_spend_items"("p_document_id" "uuid") RETURNS TABLE("line_id" "text", "document_id" "uuid", "doc_no" "text", "title" "text", "status" "text", "amount" numeric, "created_at" timestamp with time zone, "readable" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if app.current_app_user_id() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;
  -- 게이트는 **근거 품의 한 건**이다. 그 품의를 읽을 수 있으면 그 예산이 어디로 나갔는지
  -- 볼 수 있어야 한다(합계를 이미 볼 수 있는 사람과 같은 집합).
  if not app.can_read_approval(p_document_id) then
    raise exception 'not allowed to read this document' using errcode = '42501';
  end if;

  return query
    select s.line_id,
           d.id,
           case when app.can_read_approval(d.id) then d.doc_no end,
           case when app.can_read_approval(d.id) then d.title end,
           d.status::text,
           -- 한 문서가 같은 예산 줄에 두 항목을 올릴 수 있다. 그대로 두면 목록에 같은
           -- (문서, 줄)이 두 번 서고 합계(approval_budget_status)와도 어긋난다.
           sum(s.amount),
           d.created_at,
           app.can_read_approval(d.id)
      from public.approval_documents d
      join public.approval_form_versions v on v.id = d.form_version_id
      cross join lateral app.approval_spend_lines(v.fields, d.field_values) s
     where d.budget_document_id = p_document_id
       and d.deleted_at is null
       and d.status in ('PENDING', 'IN_REVIEW', 'REVISION_REQUIRED', 'APPROVED')
       and coalesce(s.line_id, '') <> ''
     group by s.line_id, d.id
     order by d.created_at desc;
end;
$$;


ALTER FUNCTION "public"."approval_budget_spend_items"("p_document_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approval_budget_spend_items"("p_document_id" "uuid") IS '근거 품의 한 건의 예산 줄별 지출 내역(줄 id, 문서별 금액 합, 상태, 일자). 그 품의를 열람할 수 있는 사람만 통과하며, 개별 지출 문서의 제목·번호는 그 문서를 열람할 수 있을 때에만 채운다 (아니면 readable=false). 본문·기안자·결재선은 돌려주지 않는다.';



CREATE OR REPLACE FUNCTION "public"."approval_budget_status"("p_document_id" "uuid") RETURNS TABLE("line_id" "text", "spent" numeric, "pending" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if app.current_app_user_id() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;
  if not app.can_read_approval(p_document_id) then
    raise exception 'not allowed to read this document' using errcode = '42501';
  end if;
  return query select * from app.approval_budget_usage(p_document_id);
end;
$$;


ALTER FUNCTION "public"."approval_budget_status"("p_document_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approval_budget_status"("p_document_id" "uuid") IS '품의 상세·지출결의 기안 화면이 읽는 예산 줄별 사용 현황. 그 품의를 열람할 수 있는 사람만 통과한다(app.can_read_approval).';



CREATE OR REPLACE FUNCTION "public"."assign_entity_code"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  new.code := public.claim_entity_code(TG_TABLE_NAME, new.id, new.code);
  return new;
end;
$$;


ALTER FUNCTION "public"."assign_entity_code"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assign_entity_code"() IS '원장 BEFORE INSERT 공용 트리거: 전역 레지스트리에서 유니크 코드를 받아 code에 채운다. 원장이 늘어도 이 함수 하나를 붙이면 된다.';



CREATE OR REPLACE FUNCTION "public"."attach_meeting_recording"("p_recording_id" "uuid", "p_minute_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if not app.can_write_recording(p_recording_id) or not app.is_minute_author(p_minute_id) then
    raise exception '녹음을 회의록에 연결할 권한이 없습니다.' using errcode = '42501';
  end if;
  update public.meeting_recordings
     set minute_id = p_minute_id, updated_at = now(), last_activity_at = now()
   where id = p_recording_id and (minute_id is null or minute_id = p_minute_id);
  if not found then
    raise exception '이미 다른 회의록에 연결된 녹음입니다.' using errcode = '23514';
  end if;
end;
$$;


ALTER FUNCTION "public"."attach_meeting_recording"("p_recording_id" "uuid", "p_minute_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."attachments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "target_type" "text" NOT NULL,
    "target_id" "uuid" NOT NULL,
    "file_name" "text" NOT NULL,
    "storage_path" "text",
    "content_type" "text",
    "byte_size" bigint,
    "uploaded_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "program_module_id" "uuid",
    "label" "text",
    "description" "text",
    "kind" "text" DEFAULT 'FILE'::"text" NOT NULL,
    "url" "text",
    CONSTRAINT "attachments_kind_shape" CHECK (((("kind" = 'FILE'::"text") AND ("storage_path" IS NOT NULL) AND ("url" IS NULL)) OR (("kind" = 'LINK'::"text") AND ("storage_path" IS NULL) AND ("url" IS NOT NULL) AND ("url" ~* '^https?://'::"text"))))
);


ALTER TABLE "public"."attachments" OWNER TO "postgres";


COMMENT ON COLUMN "public"."attachments"."program_module_id" IS '파일첨부 모듈이 올린 파일의 귀속 모듈 인스턴스. 값이 있어도 target_type/target_id는
   사업(program)이므로 사업 상세의 자료 관리 패널에 같은 행이 그대로 보인다.
   부모 원장이 워크스페이스별로 나뉘어 있어 FK는 걸지 않는다';



COMMENT ON COLUMN "public"."attachments"."label" IS '파일의 표시명. 비어 있으면 화면은 file_name을 대신 쓴다(파일명은 올린 사람의 사정을 달고 온다)';



COMMENT ON COLUMN "public"."attachments"."description" IS '파일 설명(한 줄). 파일첨부 모듈·자료 관리 목록에서 표시명 아래에 노출한다';



COMMENT ON COLUMN "public"."attachments"."kind" IS '자료 종류: FILE(스토리지 실물) | LINK(바깥 주소). 둘을 가르는 유일한 칸이며 CHECK가 모양을 강제한다.';



COMMENT ON COLUMN "public"."attachments"."url" IS 'LINK 행의 전체 주소(http/https). FILE 행에서는 항상 null이다. 호스트는 file_name이 따로 갖는다(목록·검색용).';



COMMENT ON CONSTRAINT "attachments_kind_shape" ON "public"."attachments" IS 'FILE은 스토리지 경로만, LINK는 주소만 갖는다. 둘 다 갖거나 둘 다 없는 행을 막는다 — 그런 행은 목록에는 뜨는데 열 수 없는 자료가 된다.';



CREATE OR REPLACE FUNCTION "public"."attachment_refs"("p_target_type" "text", "p_target_id" "uuid" DEFAULT NULL::"uuid", "p_link_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."attachments"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  select a.*
    from app.attachment_ref_sources(p_target_type, p_target_id, p_link_id) r
    join public.attachments a
      on a.target_type = r.ref_type
     and a.target_id = r.ref_id
   where a.deleted_at is null
   order by a.created_at desc;
$$;


ALTER FUNCTION "public"."attachment_refs"("p_target_type" "text", "p_target_id" "uuid", "p_link_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."attachment_refs"("p_target_type" "text", "p_target_id" "uuid", "p_link_id" "uuid") IS '이 대상이 함께 보는 다른 대상의 자료(읽기 전용). 방향은 app.attachment_ref_sources()가, 열람 자격은 그 함수가 조인하는 각 원장의 RLS와 attachments의 SELECT 정책이 판정한다. p_link_id는 아직 저장되지 않은 연결(등록 화면)의 후보다. 파일을 복제하지 않으므로 원본이 바뀌면 여기도 그날로 함께 바뀐다.';



CREATE OR REPLACE FUNCTION "public"."attendance_board"("p_date" "date") RETURNS TABLE("user_id" "uuid", "user_name" "text", "department_id" "uuid", "is_workday" boolean, "day_id" "uuid", "work_place" "public"."attendance_place", "check_in_at" timestamp with time zone, "check_out_at" timestamp with time zone, "status_code" "text", "auto_status_code" "text", "note" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  select u.id, u.name, u.department_id,
         coalesce(extract(dow from p_date)::smallint = any (p.workdays), false),
         d.id, d.work_place, d.check_in_at, d.check_out_at,
         d.status_code, d.auto_status_code, d.note
    from public.users u
    left join lateral app.resolve_attendance_policy(u.id, p_date) p on true
    left join public.attendance_days d
           on d.user_id = u.id and d.work_date = p_date and d.deleted_at is null
   where app.can_read_workspace('management')
     and u.deleted_at is null
     and u.user_type not in ('external_startup', 'external_expert', 'temporary_guest')
   order by u.name;
$$;


ALTER FUNCTION "public"."attendance_board"("p_date" "date") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."attendance_days" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "work_date" "date" NOT NULL,
    "work_place" "public"."attendance_place" DEFAULT 'INTERNAL'::"public"."attendance_place" NOT NULL,
    "check_in_at" timestamp with time zone,
    "check_out_at" timestamp with time zone,
    "status_code" "text" NOT NULL,
    "auto_status_code" "text",
    "policy_check_in_to" time without time zone NOT NULL,
    "policy_work_minutes" integer NOT NULL,
    "note" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "attendance_days_time_order" CHECK ((("check_out_at" IS NULL) OR (("check_in_at" IS NOT NULL) AND ("check_out_at" >= "check_in_at"))))
);


ALTER TABLE "public"."attendance_days" OWNER TO "postgres";


COMMENT ON COLUMN "public"."attendance_days"."auto_status_code" IS '규칙이 매긴 원본 상태. status_code와 다르면 관리자가 정정한 행이다.';



COMMENT ON COLUMN "public"."attendance_days"."policy_check_in_to" IS '판정에 쓴 출근 마감(스냅샷). 정책을 바꿔도 과거 판정이 흔들리지 않게 행에 복사해 둔다.';



CREATE OR REPLACE FUNCTION "public"."attendance_check_in"("p_place" "public"."attendance_place" DEFAULT 'INTERNAL'::"public"."attendance_place") RETURNS "public"."attendance_days"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_user   uuid := app.current_app_user_id();
  v_policy public.attendance_policies%rowtype;
  v_date   date := app.kst_today();
  v_now    timestamptz := now();
  v_row    public.attendance_days%rowtype;
  v_out    timestamptz;
  v_auto   text;
begin
  if v_user is null or not app.is_internal_user() then
    raise exception '근태를 기록할 수 있는 계정이 아닙니다.';
  end if;

  v_policy := app.resolve_attendance_policy(v_user, v_date);
  if v_policy.id is null then
    raise exception '적용할 근무 기준이 없습니다. 근태 설정을 확인하세요.';
  end if;

  if not (extract(dow from v_date)::smallint = any (v_policy.workdays)) then
    raise exception '오늘은 근무일이 아닙니다.';
  end if;

  if app.kst_now()::time < v_policy.check_in_from then
    raise exception '출근은 % 이후부터 기록할 수 있습니다.', v_policy.check_in_from;
  end if;

  if p_place = 'EXTERNAL' and not v_policy.allow_external then
    raise exception '외부근무가 허용되지 않은 근무 기준입니다.';
  end if;

  select * into v_row from public.attendance_days
   where user_id = v_user and work_date = v_date and deleted_at is null;

  if found then
    -- 다시 근무를 시작하는 것이므로 앞선 퇴근은 그날의 끝이 아니게 된다.
    v_out := case when v_row.check_out_at is not null and v_row.check_out_at < v_now
                  then null else v_row.check_out_at end;
    v_auto := app.attendance_auto_status(
                v_now, v_out, v_policy.check_in_to, v_policy.work_minutes);

    update public.attendance_days
       set check_in_at      = v_now,
           check_out_at     = v_out,
           work_place       = p_place,
           auto_status_code = v_auto,
           -- 관리자가 이미 고친 행은 확정 상태를 유지한다.
           status_code      = case
                                when v_row.auto_status_code is distinct from v_row.status_code
                                  then v_row.status_code
                                else v_auto
                              end
     where id = v_row.id
     returning * into v_row;
  else
    v_auto := app.attendance_auto_status(v_now, null, v_policy.check_in_to, v_policy.work_minutes);
    insert into public.attendance_days (
      user_id, work_date, work_place, check_in_at,
      status_code, auto_status_code, policy_check_in_to, policy_work_minutes
    )
    values (
      v_user, v_date, p_place, v_now,
      v_auto, v_auto, v_policy.check_in_to, v_policy.work_minutes
    )
    returning * into v_row;
  end if;

  return v_row;
end $$;


ALTER FUNCTION "public"."attendance_check_in"("p_place" "public"."attendance_place") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."attendance_check_in"("p_place" "public"."attendance_place") IS '본인 오늘 출근 스탬프. 다시 찍으면 마지막 시각이 그날의 출근이 되고, 그보다 이른 퇴근 기록은 비워진다.';



CREATE OR REPLACE FUNCTION "public"."attendance_check_out"() RETURNS "public"."attendance_days"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_user uuid := app.current_app_user_id();
  v_date date := app.kst_today();
  v_now  timestamptz := now();
  v_row  public.attendance_days%rowtype;
  v_auto text;
begin
  if v_user is null or not app.is_internal_user() then
    raise exception '근태를 기록할 수 있는 계정이 아닙니다.';
  end if;

  select * into v_row from public.attendance_days
   where user_id = v_user and work_date = v_date and deleted_at is null;

  if not found or v_row.check_in_at is null then
    raise exception '출근 기록이 없어 퇴근을 기록할 수 없습니다.';
  end if;

  v_auto := app.attendance_auto_status(
    v_row.check_in_at, v_now, v_row.policy_check_in_to, v_row.policy_work_minutes);

  update public.attendance_days
     set check_out_at     = v_now,
         auto_status_code = v_auto,
         status_code      = case
                              when v_row.auto_status_code is distinct from v_row.status_code
                                then v_row.status_code
                              else v_auto
                            end
   where id = v_row.id
   returning * into v_row;

  return v_row;
end $$;


ALTER FUNCTION "public"."attendance_check_out"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."attendance_check_out"() IS '본인 오늘 퇴근 스탬프. 다시 찍으면 마지막 시각이 그날의 퇴근이 된다.';



CREATE OR REPLACE FUNCTION "public"."attendance_month"("p_user_id" "uuid", "p_from" "date", "p_to" "date") RETURNS TABLE("work_date" "date", "is_workday" boolean, "day_id" "uuid", "work_place" "public"."attendance_place", "check_in_at" timestamp with time zone, "check_out_at" timestamp with time zone, "status_code" "text", "auto_status_code" "text", "note" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  select g.d::date,
         coalesce(extract(dow from g.d)::smallint = any (p.workdays), false),
         a.id, a.work_place, a.check_in_at, a.check_out_at,
         a.status_code, a.auto_status_code, a.note
    from generate_series(p_from, p_to, interval '1 day') g(d)
    left join lateral app.resolve_attendance_policy(p_user_id, g.d::date) p on true
    left join public.attendance_days a
           on a.user_id = p_user_id and a.work_date = g.d::date and a.deleted_at is null
   where p_to >= p_from
     and p_to - p_from <= 366   -- 한 번에 훑는 범위를 1년으로 묶는다(대량 Export 경로 차단)
   order by g.d;
$$;


ALTER FUNCTION "public"."attendance_month"("p_user_id" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."authorize_guest_password_reset"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_uid uuid := app.current_app_user_id();
  v_ok  boolean;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.' using errcode = '42501';
  end if;
  if app.is_guest() then
    raise exception '내부 사용자만 재설정 안내를 보낼 수 있습니다.' using errcode = '42501';
  end if;

  select app.is_guest_user_type(u.user_type) and u.deleted_at is null and u.is_active
    into v_ok
    from public.users u
   where u.id = p_user_id;

  if v_ok is not true then
    raise exception '재설정 대상이 아닙니다(게스트가 아니거나 정지된 계정).' using errcode = '22023';
  end if;

  perform app.log_guest_access(
    p_user_id,
    'GUEST_PASSWORD_RESET_SEND',
    'guest:account',
    jsonb_build_object('requested_by', v_uid),
    null
  );
end;
$$;


ALTER FUNCTION "public"."authorize_guest_password_reset"("p_user_id" "uuid") OWNER TO "postgres";


