CREATE OR REPLACE FUNCTION "public"."claim_entity_code"("p_table" "text", "p_id" "uuid", "p_code" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  candidate text;
  tries     int := 0;
begin
  loop
    tries := tries + 1;
    -- 명시 코드는 첫 시도에서만 존중한다(충돌하면 그 코드는 못 쓴다 — 조용히 바꾸지 않는다).
    candidate := case when tries = 1 and p_code is not null and btrim(p_code) <> ''
                      then upper(btrim(p_code))
                      else public.gen_entity_code() end;

    begin
      insert into public.entity_codes (code, entity_table, entity_id)
      values (candidate, p_table, p_id);
      return candidate;
    exception when unique_violation then
      if tries = 1 and p_code is not null and btrim(p_code) <> '' then
        raise exception '이미 사용 중인 코드입니다: %', candidate using errcode = '23505';
      end if;
      -- 난수 충돌: 다시 뽑는다. 32^6(약 10.7억) 공간이라 실질적으로 1~2회면 끝난다.
      if tries > 50 then
        raise exception 'code_space_exhausted' using errcode = '54000';
      end if;
    end;
  end loop;
end;
$$;


ALTER FUNCTION "public"."claim_entity_code"("p_table" "text", "p_id" "uuid", "p_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_entity_code"("p_table" "text", "p_id" "uuid", "p_code" "text") IS '전역 레지스트리에서 레코드 코드를 예약해 반환한다. 다른 워크스페이스의 코드까지 봐야 중복을 판정할 수 있어 SECURITY DEFINER다. 호출 권한은 revoke로 잠겨 있어 원장 트리거만 경유한다.';



