CREATE OR REPLACE FUNCTION "public"."close_program_guest_access"("p_participant_ids" "uuid"[], "p_reason" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid   uuid := app.current_app_user_id();
  r       record;
  v_count integer := 0;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.' using errcode = '42501';
  end if;
  if p_participant_ids is null or array_length(p_participant_ids, 1) is null then
    return 0;
  end if;

  for r in
    select pp.id, pp.program_id, pp.user_id
      from public.program_participants pp
     where pp.id = any (p_participant_ids)
  loop
    if not app.is_program_manager(r.program_id) then
      raise exception '사업 담당자(PM·MEMBER)만 게스트 로그인을 닫을 수 있습니다.' using errcode = '42501';
    end if;

    update public.program_participants
       set login_status = 'BLOCKED',
           updated_at   = now()
     where id = r.id;

    -- 발급된 토큰 무효화. 대상은 이 명부 행에 연결된 외부 게스트 계정으로 한정한다.
    if r.user_id is not null then
      update public.users
         set session_version = session_version + 1
       where id = r.user_id
         and user_type in ('external_startup', 'external_expert', 'temporary_guest');
    end if;

    perform app.log_guest_access(
      r.user_id,
      'GUEST_ACCESS_CLOSE',
      'guest:blocked',
      jsonb_build_object('participant_id', r.id, 'program_id', r.program_id),
      p_reason
    );

    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."close_program_guest_access"("p_participant_ids" "uuid"[], "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."close_program_guest_access"("p_participant_ids" "uuid"[], "p_reason" "text") IS '연동 DB 명부 행의 게스트 로그인을 닫고 접속 중인 세션까지 무효화한다(담당자 전용).';



CREATE OR REPLACE FUNCTION "public"."complete_meeting_recording"("p_recording_id" "uuid", "p_transcript" "text", "p_ai_draft" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if not app.can_write_recording(p_recording_id) then
    raise exception '녹음 처리를 완료할 권한이 없습니다.' using errcode = '42501';
  end if;
  if length(coalesce(p_transcript, '')) > 240000 then
    raise exception '전사 내용이 너무 깁니다.' using errcode = '22023';
  end if;
  if p_ai_draft is null or jsonb_typeof(p_ai_draft) <> 'object' then
    raise exception 'AI 초안 형식이 올바르지 않습니다.' using errcode = '22023';
  end if;
  update public.meeting_recordings
     set transcript = nullif(trim(p_transcript), ''), ai_draft = p_ai_draft,
         status = 'READY', error_code = null, last_activity_at = now(), updated_at = now()
   where id = p_recording_id;
end;
$$;


ALTER FUNCTION "public"."complete_meeting_recording"("p_recording_id" "uuid", "p_transcript" "text", "p_ai_draft" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_meeting_recording_segment"("p_segment_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'storage'
    AS $$
declare
  v_segment public.meeting_recording_segments%rowtype;
begin
  select * into v_segment from public.meeting_recording_segments where id = p_segment_id;
  if v_segment.id is null or not app.can_write_recording(v_segment.recording_id) then
    raise exception '녹음 구간을 완료할 권한이 없습니다.' using errcode = '42501';
  end if;
  if not exists (
    select 1 from storage.objects o
     where o.bucket_id = 'meeting-recordings' and o.name = v_segment.storage_path
  ) then
    raise exception '업로드된 녹음 파일을 찾을 수 없습니다.' using errcode = '22023';
  end if;
  update public.meeting_recording_segments
     set status = case when status = 'PENDING' then 'UPLOADED' else status end,
         uploaded_at = coalesce(uploaded_at, now()), updated_at = now()
   where id = p_segment_id;
end;
$$;


ALTER FUNCTION "public"."complete_meeting_recording_segment"("p_segment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_guest_account"("p_name" "text", "p_email" "text", "p_phone" "text", "p_master_table" "text" DEFAULT NULL::"text", "p_master_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor         uuid := app.current_app_user_id();
  v_name          text := nullif(btrim(p_name), '');
  v_email         text := nullif(btrim(p_email), '');
  v_phone         text := nullif(btrim(p_phone), '');
  v_existing      uuid;
  v_existing_name text;
  v_new           uuid;
begin
  if v_actor is null or app.is_guest() then
    raise exception '내부 사용자만 GUEST 계정을 생성할 수 있습니다.' using errcode = '42501';
  end if;

  if (p_master_table is null) <> (p_master_id is null) then
    raise exception '원장을 연결하려면 원장 종류와 대상을 함께 지정해야 합니다.' using errcode = '22023';
  end if;

  if p_master_table is not null then
    return public.issue_guest_account(
      p_master_table,
      p_master_id,
      v_name,
      v_email,
      v_phone
    );
  end if;

  if v_name is null or v_email is null or v_phone is null then
    raise exception '이름, 이메일, 연락처를 모두 입력해야 합니다.' using errcode = '22023';
  end if;

  if exists (
    select 1 from public.users u
     where u.deleted_at is null
       and lower(u.email) = lower(v_email)
       and not app.is_guest_user_type(u.user_type)
  ) then
    raise exception '이 이메일은 내부 임직원 계정입니다. GUEST 계정은 다른 주소로 생성하십시오.'
      using errcode = '22023';
  end if;

  select u.id, u.name
    into v_existing, v_existing_name
    from public.users u
   where u.deleted_at is null
     and app.is_guest_user_type(u.user_type)
     and lower(u.email) = lower(v_email);

  if v_existing is not null then
    if app.norm_entity_name(v_existing_name) is distinct from app.norm_entity_name(v_name) then
      raise exception '이 이메일(%)은 다른 사람(%)의 GUEST 계정에 쓰이고 있습니다.',
        v_email, v_existing_name
        using errcode = '23505', hint = 'guest_email_name_mismatch:' || v_existing;
    end if;
    return v_existing;
  end if;

  insert into public.users (user_type, name, email, phone)
  values ('temporary_guest', v_name, v_email, v_phone)
  returning id into v_new;

  insert into public.workspace_permissions
    (user_id, workspace_key, permission_level, scope_type, scope_id)
  values (v_new, 'guest', 'write', 'self', null)
  on conflict (user_id, workspace_key) do nothing;

  insert into public.guest_credentials (user_id)
  values (v_new)
  on conflict (user_id) do nothing;

  perform app.log_guest_access(
    v_new,
    'GUEST_ACCOUNT_ISSUE',
    'guest:account',
    jsonb_build_object('person_source', 'manual', 'master_table', null, 'master_id', null),
    null
  );

  return v_new;
end;
$$;


ALTER FUNCTION "public"."create_guest_account"("p_name" "text", "p_email" "text", "p_phone" "text", "p_master_table" "text", "p_master_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_guest_account"("p_name" "text", "p_email" "text", "p_phone" "text", "p_master_table" "text", "p_master_id" "uuid") IS '모든 내부 화면이 공유하는 GUEST 계정 생성 경로. 원장은 선택이며, 없으면 temporary_guest를 만들고 있으면 issue_guest_account로 인격을 연결한다.';



CREATE OR REPLACE FUNCTION "public"."create_guest_accounts"("p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_max        constant integer := 200;
  v_actor      uuid    := app.current_app_user_id();
  v_parsed     jsonb;
  v_results    jsonb   := '[]'::jsonb;
  v_created    integer := 0;
  v_failed     integer := 0;
  v_iter       record;
  v_row        jsonb;
  v_errors     jsonb;
  v_idx        integer;
  v_key        text;
  v_name       text;
  v_email      text;
  v_email_key  text;
  v_phone      text;
  v_phone_key  text;
  v_master_tbl text;
  v_master_txt text;
  v_master_id  uuid;
  v_user_type  text;
  v_company    uuid;
  v_new        uuid;
  v_state      text;
  v_msg        text;
  v_constraint text;
begin
  -- 호출 자체의 인가. 화면에서 감추는 것은 인가가 아니므로 여기서 막는다.
  if v_actor is null or app.is_guest() then
    raise exception '내부 사용자만 GUEST 계정을 생성할 수 있습니다.' using errcode = '42501';
  end if;

  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception '입력은 행 배열(jsonb array)이어야 합니다.' using errcode = '22023';
  end if;
  if jsonb_array_length(p_rows) = 0 then
    raise exception '생성할 행을 하나 이상 넣어야 합니다.' using errcode = '22023';
  end if;
  if jsonb_array_length(p_rows) > v_max then
    raise exception '한 번에 처리할 수 있는 행은 최대 %건입니다.', v_max using errcode = '22023';
  end if;

  -- ① 입력을 한 번만 훑어 정규화하고, 배치 안 중복을 행마다 표시한다.
  --    중복 표시는 창(window)으로 센다 — 같은 키를 가진 행 전부에 같은 답이 붙어야 하며
  --    어느 하나를 승자로 고르지 않는다.
  with raw as (
    select (t.ord - 1)::integer as idx,
           case when jsonb_typeof(t.elem) = 'object' then t.elem else null end as obj
      from jsonb_array_elements(p_rows) with ordinality as t(elem, ord)
  ),
  norm as (
    select r.idx,
           r.obj is not null                                          as is_object,
           nullif(btrim(coalesce(r.obj ->> 'key', '')), '')            as key,
           nullif(btrim(coalesce(r.obj ->> 'name', '')), '')           as name,
           nullif(btrim(coalesce(r.obj ->> 'email', '')), '')          as email,
           nullif(btrim(coalesce(r.obj ->> 'phone', '')), '')          as phone,
           nullif(btrim(coalesce(r.obj ->> 'master_table', '')), '')   as master_table,
           nullif(btrim(coalesce(r.obj ->> 'master_id', '')), '')      as master_id
      from raw r
  ),
  keyed as (
    select n.*,
           app.norm_email(n.email) as email_key,
           app.norm_phone(n.phone) as phone_key
      from norm n
  ),
  flagged as (
    select k.*,
           (k.email_key is not null and count(*) over (partition by k.email_key) > 1) as dup_email,
           (k.phone_key is not null and count(*) over (partition by k.phone_key) > 1) as dup_phone,
           (k.key       is not null and count(*) over (partition by k.key)       > 1) as dup_key
      from keyed k
  )
  select coalesce(
           jsonb_agg(
             jsonb_build_object(
               'idx',          f.idx,
               'is_object',    f.is_object,
               'key',          f.key,
               'name',         f.name,
               'email',        f.email,
               'email_key',    f.email_key,
               'phone',        f.phone,
               'phone_key',    f.phone_key,
               'master_table', f.master_table,
               'master_id',    f.master_id,
               'dup_email',    f.dup_email,
               'dup_phone',    f.dup_phone,
               'dup_key',      f.dup_key
             ) order by f.idx
           ),
           '[]'::jsonb
         )
    into v_parsed
    from flagged f;

  -- ② 행마다 독립적으로 판정하고 만든다.
  for v_iter in
    select e.elem from jsonb_array_elements(v_parsed) as e(elem)
     order by (e.elem ->> 'idx')::integer
  loop
    v_row        := v_iter.elem;
    v_errors     := '[]'::jsonb;
    v_new        := null;
    v_user_type  := null;
    v_company    := null;
    v_master_id  := null;
    v_idx        := (v_row ->> 'idx')::integer;
    v_key        := v_row ->> 'key';
    v_name       := v_row ->> 'name';
    v_email      := v_row ->> 'email';
    v_email_key  := v_row ->> 'email_key';
    v_phone      := v_row ->> 'phone';
    v_phone_key  := v_row ->> 'phone_key';
    v_master_tbl := v_row ->> 'master_table';
    v_master_txt := v_row ->> 'master_id';

    -- ②-1 입력 자체의 문제. 칸마다 모아서 한 번에 돌려준다(한 칸 고치고 다시 올리는
    --      왕복을 만들지 않는다).
    if not coalesce((v_row ->> 'is_object')::boolean, false) then
      v_errors := v_errors || app.guest_batch_error(
        'row', 'ROW_NOT_OBJECT', '행은 name·email·phone을 가진 객체여야 합니다.');
    else
      if v_name is null then
        v_errors := v_errors || app.guest_batch_error(
          'name', 'NAME_REQUIRED', '이름을 입력해야 합니다.');
      elsif length(v_name) > 100 then
        v_errors := v_errors || app.guest_batch_error(
          'name', 'NAME_TOO_LONG', '이름은 100자를 넘을 수 없습니다.');
      end if;

      if v_email is null then
        v_errors := v_errors || app.guest_batch_error(
          'email', 'EMAIL_REQUIRED', '이메일을 입력해야 합니다(이메일이 로그인 ID입니다).');
      -- 형식 검사는 admin_update_guest_contact(20260913130000)와 같은 식을 쓴다 —
      -- 같은 계정 원장의 같은 칸이므로 창구마다 다른 기준을 두지 않는다.
      elsif length(v_email) > 254
         or v_email_key !~ '^[^@[:space:]]+@[^@[:space:].]+(\.[^@[:space:].]+)+$' then
        v_errors := v_errors || app.guest_batch_error(
          'email', 'EMAIL_INVALID', '이메일 형식이 올바르지 않습니다.');
      elsif coalesce((v_row ->> 'dup_email')::boolean, false) then
        v_errors := v_errors || app.guest_batch_error(
          'email', 'EMAIL_DUPLICATE_IN_BATCH',
          '같은 이메일이 입력 안에 두 번 이상 있습니다. 해당 행 전부를 만들지 않습니다.');
      end if;

      if v_phone is null then
        v_errors := v_errors || app.guest_batch_error(
          'phone', 'PHONE_REQUIRED', '연락처를 입력해야 합니다(연락처가 초기 비밀번호입니다).');
      elsif v_phone_key is null or length(v_phone_key) < 9 or length(v_phone_key) > 15 then
        v_errors := v_errors || app.guest_batch_error(
          'phone', 'PHONE_INVALID', '연락처는 숫자 9~15자리여야 합니다.');
      elsif coalesce((v_row ->> 'dup_phone')::boolean, false) then
        v_errors := v_errors || app.guest_batch_error(
          'phone', 'PHONE_DUPLICATE_IN_BATCH',
          '같은 연락처가 입력 안에 두 번 이상 있습니다. 해당 행 전부를 만들지 않습니다.');
      end if;

      -- 호출자 식별자가 겹치면 결과를 입력 행에 되짚을 수 없다. index는 항상 고유하므로
      -- 결과 자체는 쓸 수 있지만, key로 짝을 맞추는 화면이 잘못 붙이는 것을 막는다.
      if coalesce((v_row ->> 'dup_key')::boolean, false) then
        v_errors := v_errors || app.guest_batch_error(
          'key', 'KEY_DUPLICATE_IN_BATCH', '같은 key가 입력 안에 두 번 이상 있습니다.');
      end if;

      if (v_master_tbl is null) <> (v_master_txt is null) then
        v_errors := v_errors || app.guest_batch_error(
          'master_table', 'MASTER_PAIR_REQUIRED',
          '원장을 연결하려면 master_table과 master_id를 함께 지정해야 합니다.');
      elsif v_master_tbl is not null then
        if v_master_tbl not in ('startups', 'networks', 'ma_sellers', 'ma_buyers') then
          v_errors := v_errors || app.guest_batch_error(
            'master_table', 'MASTER_TABLE_UNKNOWN', '지원하지 않는 원장입니다.');
        elsif v_master_txt !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
          v_errors := v_errors || app.guest_batch_error(
            'master_id', 'MASTER_ID_INVALID', 'master_id가 uuid 형식이 아닙니다.');
        end if;
      end if;
    end if;

    -- ②-2 DB가 답해야 하는 문제 + 삽입. 한 행의 실패가 다른 행을 되돌리지 않도록
    --      행마다 예외 블록(=savepoint)을 둔다.
    if v_errors = '[]'::jsonb then
      begin
        if v_master_tbl is not null then
          v_master_id := v_master_txt::uuid;

          -- 원장 연결은 **그 원장 행을 읽을 수 있는 사람만** 한다. M&A는 존재 자체가
          -- 기밀이라 '없음'과 '권한 없음'을 갈라 답하지 않는다(can_read_ma_party가 둘을
          -- 같은 false로 돌려준다 — 여기서 되살리면 이메일만으로 매각 검토를 알 수 있다).
          if not app.can_read_master_table(v_master_tbl)
             or (v_master_tbl = 'ma_sellers' and not app.can_read_ma_party('ma_seller', v_master_id))
             or (v_master_tbl = 'ma_buyers'  and not app.can_read_ma_party('ma_buyer',  v_master_id)) then
            v_errors := v_errors || app.guest_batch_error(
              'master_table', 'MASTER_FORBIDDEN', '이 원장 대상에 계정을 연결할 권한이 없습니다.');

          -- 흡수된 행(merged_into_id)은 고를 수 없다 — 화면의 원장 선택창과 같은 기준이며,
          -- 인격을 비켜 간 행에 붙이면 그 계정이 어느 정본에 속하는지 답할 수 없다.
          -- can_read_ma_party는 살아 있는지만 보고 병합은 보지 않으므로 M&A도 여기서
          -- 따로 확인한다. **권한 판정 뒤에 오는 순서**라 못 읽는 사람에게는 여전히
          -- FORBIDDEN 하나만 가고 병합 여부도 새지 않는다.
          elsif v_master_tbl = 'startups' and not exists (
            select 1 from public.startups s
             where s.id = v_master_id and s.deleted_at is null and s.merged_into_id is null
          ) then
            v_errors := v_errors || app.guest_batch_error(
              'master_id', 'MASTER_NOT_FOUND', '원장에서 살아 있는 정본 대상을 찾을 수 없습니다.');
          elsif v_master_tbl = 'networks' and not exists (
            select 1 from public.networks n
             where n.id = v_master_id and n.deleted_at is null and n.merged_into_id is null
          ) then
            v_errors := v_errors || app.guest_batch_error(
              'master_id', 'MASTER_NOT_FOUND', '원장에서 살아 있는 정본 대상을 찾을 수 없습니다.');
          elsif v_master_tbl = 'ma_sellers' and not exists (
            select 1 from public.ma_sellers x
             where x.id = v_master_id and x.deleted_at is null and x.merged_into_id is null
          ) then
            v_errors := v_errors || app.guest_batch_error(
              'master_id', 'MASTER_NOT_FOUND', '원장에서 살아 있는 정본 대상을 찾을 수 없습니다.');
          elsif v_master_tbl = 'ma_buyers' and not exists (
            select 1 from public.ma_buyers x
             where x.id = v_master_id and x.deleted_at is null and x.merged_into_id is null
          ) then
            v_errors := v_errors || app.guest_batch_error(
              'master_id', 'MASTER_NOT_FOUND', '원장에서 살아 있는 정본 대상을 찾을 수 없습니다.');
          end if;

          -- 유형을 늘리지 않는다 — 무엇인지는 guest_identities.master_table이 답한다
          -- (2026-09-08 확정). company_id는 startups(id) FK라 그 인격만 채운다.
          if v_master_tbl = 'networks' then
            v_user_type := 'external_expert';
          else
            v_user_type := 'external_startup';
          end if;
          if v_master_tbl = 'startups' then
            v_company := v_master_id;
          end if;
        else
          v_user_type := 'temporary_guest';
        end if;

        -- 이메일은 활성 계정 전체에서 하나다. **정지 계정도 자리를 지킨다**(is_active를
        -- 보지 않는다) — 정지는 잠시 막은 상태이고 계정은 살아 있다. 재운 계정(deleted_at)
        -- 만 자리를 비켜 주며, 이 기준이 uq_users_email_live와 같다. 식도 같은 모양으로
        -- 적어 그 인덱스를 탄다.
        if v_errors = '[]'::jsonb then
          if exists (
            select 1 from public.users u
             where u.deleted_at is null
               and lower(btrim(u.email)) = v_email_key
               and not app.is_guest_user_type(u.user_type)
          ) then
            v_errors := v_errors || app.guest_batch_error(
              'email', 'EMAIL_TAKEN_INTERNAL',
              '이 이메일은 내부 임직원 계정입니다. GUEST 계정은 다른 주소로 만드십시오.');
          elsif exists (
            select 1 from public.users u
             where u.deleted_at is null
               and lower(btrim(u.email)) = v_email_key
               and app.is_guest_user_type(u.user_type)
          ) then
            v_errors := v_errors || app.guest_batch_error(
              'email', 'EMAIL_TAKEN_GUEST',
              '이 이메일을 쓰는 GUEST 계정이 이미 있습니다(정지된 계정도 포함). 기존 계정을 이 경로로 재사용하지 않습니다.');
          end if;

          if exists (
            select 1 from public.users u
             where u.deleted_at is null
               and app.is_guest_user_type(u.user_type)
               and app.norm_phone(u.phone) = v_phone_key
          ) then
            v_errors := v_errors || app.guest_batch_error(
              'phone', 'PHONE_TAKEN_GUEST',
              '이 연락처를 쓰는 GUEST 계정이 이미 있습니다(정지된 계정도 포함). 연락처가 초기 비밀번호이므로 나눠 쓸 수 없습니다.');
          end if;
        end if;

        if v_errors = '[]'::jsonb then
          insert into public.users (user_type, name, email, phone, company_id)
          values (v_user_type::public.user_type, v_name, v_email, v_phone, v_company)
          returning id into v_new;

          insert into public.workspace_permissions
            (user_id, workspace_key, permission_level, scope_type, scope_id)
          values (v_new, 'guest', 'write', 'self', null);

          -- 자격증명 자리를 비워 둔 채 함께 만든다. 행이 없으면 로그인 경로가
          -- "초기 상태"와 "계정 없음"을 구분하지 못한다.
          insert into public.guest_credentials (user_id) values (v_new);

          if v_master_tbl is not null then
            insert into public.guest_identities (master_table, master_id, user_id, created_by)
            values (v_master_tbl, v_master_id, v_new, v_actor);
          end if;

          perform app.log_guest_access(
            v_new,
            'GUEST_ACCOUNT_ISSUE',
            'guest:account',
            jsonb_build_object(
              'person_source', 'manual',
              'source',        'batch',
              'batch_index',   v_idx,
              'batch_key',     v_key,
              'master_table',  v_master_tbl,
              'master_id',     v_master_id
            ),
            null
          );
        end if;
      exception
        -- 인가 실패는 행 사유로 접지 않는다 — 전체 호출이 멈춰야 하는 사실이다.
        when insufficient_privilege then
          raise;
        when unique_violation then
          get stacked diagnostics
            v_constraint = constraint_name,
            v_msg        = message_text;
          v_new := null;
          -- 사전 검사를 통과한 뒤에도 인덱스가 막았다면 같은 키를 다른 요청이 방금 만든
          -- 것이다(검사와 삽입 사이의 틈). 어느 인덱스가 막았는지는 constraint_name이
          -- 답하고, 그 값이 비는 드문 경우에는 메시지 문구로 되짚는다.
          if coalesce(v_constraint, '') = 'uq_users_email_live'
             or position('uq_users_email_live' in coalesce(v_msg, '')) > 0 then
            v_errors := v_errors || app.guest_batch_error(
              'email', 'EMAIL_TAKEN_GUEST', '방금 다른 요청이 이 이메일로 계정을 만들었습니다.');
          elsif coalesce(v_constraint, '') = 'uq_users_guest_phone'
             or position('uq_users_guest_phone' in coalesce(v_msg, '')) > 0 then
            v_errors := v_errors || app.guest_batch_error(
              'phone', 'PHONE_TAKEN_GUEST', '방금 다른 요청이 이 연락처로 계정을 만들었습니다.');
          else
            -- 어느 값이 부딪혔는지 모르는 중복은 **문구를 그대로 돌려주지 않는다.**
            -- 원본 메시지에는 인덱스·컬럼 이름과 호출자가 볼 수 없는 계정의 값이
            -- 그대로 담긴다(숨은 계정의 존재를 되짚는 통로가 된다). 진단은 서버
            -- 로그로만 남기고 화면에는 담당자가 할 수 있는 일만 말한다.
            raise log 'create_guest_accounts 중복 거부: index=% constraint=% message=%',
              v_idx, v_constraint, v_msg;
            v_errors := v_errors || app.guest_batch_error(
              'row', 'DB_CONFLICT',
              '이미 있는 값과 부딪혀 만들지 못했습니다. 입력을 확인한 뒤 다시 시도하십시오.');
          end if;
        when others then
          get stacked diagnostics
            v_state = returned_sqlstate,
            v_msg   = message_text;
          v_new := null;
          -- 같은 이유로 원본 메시지·SQLSTATE를 밖으로 내보내지 않는다.
          raise log 'create_guest_accounts 행 실패: index=% sqlstate=% message=%',
            v_idx, v_state, v_msg;
          v_errors := v_errors || app.guest_batch_error(
            'row', 'DB_ERROR', '이 행을 만들지 못했습니다. 담당자에게 문의하십시오.');
      end;
    end if;

    v_results := v_results || jsonb_build_array(
      jsonb_build_object(
        'index',        v_idx,
        'key',          v_key,
        'status',       (case when v_new is not null then 'CREATED' else 'FAILED' end)::text,
        'user_id',      v_new,
        'user_type',    case when v_new is not null then v_user_type end,
        'master_table', v_master_tbl,
        'master_id',    v_master_txt,
        'errors',       v_errors
      )
    );

    if v_new is not null then
      v_created := v_created + 1;
    else
      v_failed := v_failed + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'total',   jsonb_array_length(p_rows),
    'created', v_created,
    'failed',  v_failed,
    'rows',    v_results
  );
end;
$_$;


ALTER FUNCTION "public"."create_guest_accounts"("p_rows" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_guest_accounts"("p_rows" "jsonb") IS 'GUEST 계정 엄격 일괄 생성. 내부 사용자만 호출하며, 행마다 독립적으로 만들고 이미 쓰이는 이메일·연락처(정지 계정 포함)는 기존 계정을 재사용하지 않고 그 행만 실패시킨다. 배치 안 중복은 관련 행 전부를 실패시킨다. 원장 연결은 그 원장을 읽을 수 있는 사람만 할 수 있고 M&A는 존재를 답하지 않는다. 결과는 입력 index/key·status·user_id·칸별 사유를 담은 jsonb.';



CREATE OR REPLACE FUNCTION "public"."current_org_version_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'app'
    AS $$
  with pub as (
    select id, effective_from, effective_to, created_at
      from public.org_versions
     where status = 'PUBLISHED' and deleted_at is null
  ),
  containing as (
    select id from pub
     where effective_from <= current_date
       and (effective_to is null or current_date < effective_to)
     order by effective_from desc, created_at desc
     limit 1
  ),
  ended as (
    select id from pub
     where effective_to is not null and effective_to <= current_date
     order by effective_to desc, created_at desc
     limit 1
  )
  select coalesce((select id from containing), (select id from ended));
$$;


ALTER FUNCTION "public"."current_org_version_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deactivate_entities"("p_entity_key" "text", "p_ids" "uuid"[], "p_reason" "text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_id    uuid;
  v_count integer := 0;
begin
  if p_entity_key not in (
    'startups',
    'networks',
    'programs',
    'ma_programs',
    'ma_buyers',
    'ma_sellers',
    'funds'
  ) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  if coalesce(array_length(p_ids, 1), 0) = 0 then
    raise exception 'empty_selection' using errcode = '22023';
  end if;
  if cardinality(p_ids) > 100 then
    raise exception 'too_many_entities' using errcode = '22023';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'reason_required' using errcode = '23514';
  end if;

  -- 원장별 예외를 두지 않는다. 사유가 남지 않는 경로가 하나라도 있으면 비활성 목록의
  -- '누가·왜' 칸이 그 원장에서만 비어 버린다.
  for v_id in select distinct x from unnest(p_ids) as x
  loop
    perform public.deactivate_entity(p_entity_key, v_id, btrim(p_reason));
    v_count := v_count + 1;
  end loop;

  return v_count;
end $$;


ALTER FUNCTION "public"."deactivate_entities"("p_entity_key" "text", "p_ids" "uuid"[], "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."deactivate_entities"("p_entity_key" "text", "p_ids" "uuid"[], "p_reason" "text") IS '데이터 센터와 업무 워크스페이스 목록의 선택 행을 한 트랜잭션에서 비활성화한다(7종). 전부 deactivate_entity를 거쳐 원장별 RLS·생성자 트리거·기여 이력 사유를 그대로 통과한다.';



CREATE OR REPLACE FUNCTION "public"."deactivate_entity"("p_entity_key" "text", "p_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_rows integer;
begin
  if not app.has_contribution_trigger(p_entity_key) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'reason_required' using errcode = '23514';
  end if;

  perform set_config('app.contribution_ctx',
                     jsonb_build_object('note', btrim(p_reason))::text,
                     true);

  execute format(
    'update public.%I set deleted_at = now() where id = $1 and deleted_at is null',
    p_entity_key
  ) using p_id;
  get diagnostics v_rows = row_count;

  -- 0행이면 대상이 없거나 RLS가 막은 것이다. 둘을 구분해 알려주지 않는다.
  if v_rows = 0 then
    raise exception 'not_found_or_forbidden' using errcode = '42501';
  end if;
end $_$;


ALTER FUNCTION "public"."deactivate_entity"("p_entity_key" "text", "p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."deactivate_entity"("p_entity_key" "text", "p_id" "uuid", "p_reason" "text") IS '사유를 남기는 소프트 삭제. 사유를 트랜잭션 컨텍스트에 실어 기록 트리거가 note로 남기게 한다. SECURITY INVOKER — 원장 쓰기 권한은 각 원장의 RLS가 그대로 판정한다.';



CREATE OR REPLACE FUNCTION "public"."decide_approval_document"("p_line_id" "uuid", "p_decision" "public"."approval_decision", "p_comment" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid       uuid := app.current_app_user_id();
  v_doc       uuid;
  v_kind      public.approval_line_kind;
  v_step      integer;
  v_round     integer;
  v_line_rnd  integer;
  v_approver  uuid;
  v_current   public.approval_decision;
  v_status    public.approval_status;
  v_remaining integer;
  v_notify    uuid[];
  v_budget    text;
begin
  if v_uid is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;
  if p_decision not in ('APPROVED', 'REJECTED', 'REVISION_REQUESTED') then
    raise exception 'unsupported approval decision' using errcode = '22023';
  end if;
  if p_decision <> 'APPROVED' and nullif(btrim(p_comment), '') is null then
    raise exception 'a reason is required for rejection or revision' using errcode = '22023';
  end if;

  select l.document_id, l.kind, l.step_order, l.round, l.approver_id, l.decision, d.status
    into v_doc, v_kind, v_step, v_line_rnd, v_approver, v_current, v_status
    from public.approval_lines l
    join public.approval_documents d on d.id = l.document_id
   where l.id = p_line_id and d.deleted_at is null;

  if not found then
    raise exception 'approval line not found' using errcode = 'P0002';
  end if;
  if v_approver is distinct from v_uid then
    raise exception 'only the assigned approver may decide' using errcode = '42501';
  end if;
  if v_current <> 'PENDING' then
    raise exception 'this line is already decided' using errcode = '42501';
  end if;
  if v_status not in ('PENDING', 'IN_REVIEW') then
    raise exception 'document is not in progress' using errcode = '42501';
  end if;

  v_round := app.approval_current_round(v_doc);
  if v_line_rnd <> v_round then
    raise exception 'this line belongs to an earlier round' using errcode = '42501';
  end if;
  if exists (
    select 1 from public.approval_lines
     where document_id = v_doc and round = v_round
       and decision in ('REJECTED', 'REVISION_REQUESTED')
  ) then
    raise exception 'document has already stopped' using errcode = '42501';
  end if;
  if exists (
    select 1 from public.approval_lines
     where document_id = v_doc and round = v_round and kind = v_kind
       and step_order < v_step and decision = 'PENDING'
  ) then
    raise exception 'it is not your turn yet' using errcode = '42501';
  end if;

  if p_decision = 'APPROVED' then
    update public.approval_lines
       set decision = 'APPROVED', decided_at = now(), comment = nullif(btrim(p_comment), '')
     where id = p_line_id;

    select count(*) into v_remaining
      from public.approval_lines
     where document_id = v_doc and round = v_round and decision = 'PENDING';

    update public.approval_documents
       set status = case when v_remaining = 0 then 'APPROVED'::public.approval_status
                         else 'IN_REVIEW'::public.approval_status end,
           updated_at = now()
     where id = v_doc;

    -- 예산 변경 품의는 **최종 승인 순간에** 대상 품의의 예산표를 갈아끼운다.
    -- 여기서 예외가 나면 트랜잭션이 통째로 되돌아가 이 승인도 성립하지 않는다 — 그것이 맞다.
    -- 적용할 수 없는 변경을 승인만 해 두면 "문서는 승인인데 예산은 그대로"인 상태가 남고,
    -- 그 어긋남은 나중에 아무도 발견하지 못한다.
    if v_remaining = 0 then
      select f.budget_link into v_budget
        from public.approval_documents d
        join public.approval_forms f on f.id = d.form_id
       where d.id = v_doc;
      if v_budget = 'REVISE' then
        perform app.apply_approval_budget_revision(v_doc);
      end if;
    end if;
    return;
  end if;

  update public.approval_lines
     set decision = p_decision,
         decided_at = now(),
         comment = nullif(btrim(p_comment), ''),
         return_to_step = null,
         return_via_drafter = null,
         return_reset_agreement = null
   where id = p_line_id;

  update public.approval_documents
     set status = case
                    when p_decision = 'REJECTED'
                      then 'REJECTED'::public.approval_status
                    else 'REVISION_REQUIRED'::public.approval_status
                  end,
         completed_at = case when p_decision = 'REJECTED' then coalesce(completed_at, now())
                             else null end,
         updated_at = now()
   where id = v_doc;

  select array_agg(drafter_id) into v_notify
    from public.approval_documents where id = v_doc and drafter_id is not null;
  perform app.notify_approval(
    v_doc,
    v_notify,
    case when p_decision = 'REJECTED' then 'approval_rejected'
         else 'approval_revision_requested' end,
    v_uid
  );
end;
$$;


ALTER FUNCTION "public"."decide_approval_document"("p_line_id" "uuid", "p_decision" "public"."approval_decision", "p_comment" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."decide_approval_document"("p_line_id" "uuid", "p_decision" "public"."approval_decision", "p_comment" "text") IS '현재 회차의 자기 차례에서 승인·반려·보완 요청을 처리한다. 반려는 종결하고 보완 요청은 문서를 REVISION_REQUIRED로 멈춘다. 예산 변경 품의는 최종 승인 시 대상 품의의 예산표를 갈아끼운다(app.apply_approval_budget_revision).';



CREATE OR REPLACE FUNCTION "public"."delete_approval_document"("p_document_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid     uuid := app.current_app_user_id();
  v_drafter uuid;
  v_status  public.approval_status;
  v_title   text;
  v_doc_no  text;
  v_round   integer;
begin
  if v_uid is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  select drafter_id, status, title, doc_no
    into v_drafter, v_status, v_title, v_doc_no
    from public.approval_documents
   where id = p_document_id and deleted_at is null
   for update;

  if not found then
    raise exception 'document not found' using errcode = 'P0002';
  end if;
  if v_drafter is distinct from v_uid then
    raise exception 'only the drafter may delete this document' using errcode = '42501';
  end if;
  -- 기안 단계만. 흐르는 중인 문서를 지우려면 먼저 기안 취소로 되가져와야 하고, 그 취소
  -- 사실은 결재선에 선 사람들에게 알림으로 간다 — 지우는 일이 알림을 건너뛰지 못한다.
  if v_status <> 'DRAFT' then
    raise exception 'only a draft may be deleted' using errcode = '42501';
  end if;
  -- 이관 문서는 그때의 기록이라 지우지 않는다(하이웍스 복원본).
  if exists (
    select 1 from public.approval_legacy_documents where document_id = p_document_id
  ) then
    raise exception 'an imported document may not be deleted' using errcode = '42501';
  end if;
  -- 이 문서를 근거 품의로 가리키는 지출·변경 문서가 있으면 지울 수 없다(FK도 막지만,
  -- 오류 문구로 이유를 말하기 위해 먼저 본다).
  if exists (
    select 1 from public.approval_documents
     where budget_document_id = p_document_id and deleted_at is null
  ) then
    raise exception 'another document refers to this one as its budget source'
      using errcode = '23503';
  end if;
  if exists (
    select 1 from public.approval_legacy_document_links
     where resolved_document_id = p_document_id
  ) then
    raise exception 'a legacy link resolves to this document' using errcode = '23503';
  end if;

  v_round := app.approval_current_round(p_document_id);

  -- 되돌릴 수 없으므로 지우기 전에 스냅샷을 남긴다. 도장 이력을 통째로 담는 이유는
  -- 취소된 문서에는 결재자의 판단이 실려 있었고, 지우고 나면 그것을 되짚을 곳이
  -- 이 한 줄뿐이기 때문이다.
  insert into public.audit_logs (actor_user_id, action, changed_workspace, before_data, reason)
  values (
    v_uid, 'APPROVAL_DRAFT_DELETE', 'management',
    jsonb_build_object(
      'document_id', p_document_id,
      'title', v_title,
      'doc_no', v_doc_no,
      'rounds', v_round,
      'lines', (
        select jsonb_agg(
                 jsonb_build_object(
                   'approver_id', l.approver_id, 'kind', l.kind, 'step_order', l.step_order,
                   'round', l.round, 'decision', l.decision, 'decided_at', l.decided_at,
                   'comment', l.comment
                 ) order by l.round, l.kind, l.step_order
               )
          from public.approval_lines l where l.document_id = p_document_id
      ),
      'event_count', (
        select count(*) from public.approval_document_events where document_id = p_document_id
      )
    ),
    '기안 삭제(기안자)'
  );

  -- 첨부·의견은 소프트 삭제로 남긴다 — 스토리지 실물을 SQL에서 지울 수 없어 행만 지우면
  -- 아무도 찾을 수 없는 파일이 남는다. 문서가 사라지면 이 행을 세우는 화면도 없다.
  update public.attachments
     set deleted_at = now()
   where target_type = 'approval'
     and target_id = p_document_id
     and deleted_at is null;
  update public.entity_feedback
     set deleted_at = now()
   where target_type = 'approval'
     and target_id = p_document_id
     and deleted_at is null;

  -- 이벤트는 FK가 cascade가 아니라 삭제를 막는다. 문서가 없으면 가리킬 대상도 없다.
  delete from public.approval_document_events where document_id = p_document_id;
  -- 열 수 없는 알림을 받은함에 남기지 않는다(결재 알림과 의견 멘션 알림 둘 다).
  delete from public.notifications
   where target_type = 'approval' and target_id = p_document_id;

  -- 결재선·참조자·확인·상호참조·사업연동·예산변경은 FK cascade가 함께 거둔다.
  delete from public.approval_documents where id = p_document_id;
end;
$$;


ALTER FUNCTION "public"."delete_approval_document"("p_document_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_approval_document"("p_document_id" "uuid") IS '기안 삭제 — 기안 단계(DRAFT) 문서를 기안자가 물리 삭제한다. 첨부·의견은 소프트 삭제로 남기고(스토리지 실물을 SQL에서 지울 수 없다) 이벤트·알림은 함께 지운다. 되돌릴 수 없어 audit_logs에 도장 이력 스냅샷을 적재한다.';



CREATE OR REPLACE FUNCTION "public"."delete_program_module"("p_entity_key" "text", "p_module_id" "uuid", "p_confirm_text" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_module   text;
  v_managers text;
  v_timeline text;
  v_ws       text := app.entity_key_workspace(p_entity_key);
  v_program  uuid;
  v_title    text;
  v_type     text;
  v_uid      uuid := app.current_app_user_id();
  v_is_pm    boolean;
  v_block    text;
  r          record;
  r2         record;
begin
  select t.module_table, t.managers_table, t.timeline_table
    into v_module, v_managers, v_timeline
    from app.ws_module_tables(p_entity_key) t;
  if v_module is null then
    raise exception '알 수 없는 사업 원장입니다.' using errcode = '22023';
  end if;

  -- entity_key를 함께 건다(위 blockers와 같은 이유). 이 조건이 워크스페이스 경계다.
  execute format('select program_id, title, module_type::text from public.%I
                    where id = $1 and entity_key = $2', v_module)
    into v_program, v_title, v_type using p_module_id, p_entity_key;
  if v_program is null then
    raise exception '삭제할 모듈을 찾을 수 없습니다.' using errcode = '02000';
  end if;

  -- (1) 인가. 워크스페이스 쓰기 + 사업 접근을 먼저 보고, 그 위에 PM을 얹는다.
  if not (app.can_write_workspace(v_ws) and app.can_access_ws_program(v_ws, v_program)) then
    raise exception '이 사업의 모듈을 변경할 권한이 없습니다.' using errcode = '42501';
  end if;

  -- PM 요구에는 관리자 우회가 없다. 우회를 두면 'PM만 지운다'가 PM을 비워 두는 것으로
  -- 뒤집히기 때문이다 — PM이 없는 사업에서는 아무도 지울 수 없고, 먼저 PM을 지정해야 하며,
  -- 그 지정 자체가 누가 책임지고 지웠는지를 남긴다.
  execute format(
    'select exists (select 1 from public.%I m
       where m.program_id = $1 and m.user_id = $2 and m.role = ''PM'')', v_managers)
    into v_is_pm using v_program, v_uid;
  if not coalesce(v_is_pm, false) then
    raise exception '모듈 삭제는 이 사업의 PM만 할 수 있습니다.' using errcode = '42501';
  end if;

  -- (2) 따라쓰기. 모듈 종류·이름과 무관하게 언제나 '삭제합니다'다.
  --     앞뒤 공백과 마침표만 눈감아 준다.
  if btrim(coalesce(p_confirm_text, ''), E' .\t\r\n') <> '삭제합니다' then
    raise exception '확인 문구가 일치하지 않습니다.' using errcode = '22023';
  end if;

  -- (3) 밖에서 들어온 기록만 막는다. 내부에서 잡아 둔 배치는 함께 사라지며,
  --     무엇이 사라지는지는 삭제창이 이미 건수로 알렸다.
  select string_agg(b.rel_name || ' ' || b.row_count || '건', ', ')
    into v_block
    from public.program_module_delete_blockers(p_entity_key, p_module_id) b
   where b.blocking;
  if v_block is not null then
    raise exception '남아 있는 데이터가 있어 삭제할 수 없습니다: %', v_block
      using errcode = '23001';
  end if;

  -- (4) 감사 로그. 되돌릴 수 없는 작업이라 지우기 전에 남긴다.
  insert into public.audit_logs (actor_user_id, action, changed_workspace, before_data, reason)
  values (
    v_uid, 'MODULE_DELETE', v_ws,
    jsonb_build_object('entity_key', p_entity_key, 'module_id', p_module_id,
                       'program_id', v_program, 'title', v_title, 'module_type', v_type),
    '운영 모듈 하드 삭제(PM)'
  );

  -- (5) 첨부는 지우지 않고 귀속만 푼다 — 파일은 사업 자료로 돌아간다.
  --     행을 지우면 스토리지 실물이 남아 아무도 못 찾는 파일이 된다.
  update public.attachments
     set program_module_id = null
   where program_module_id = p_module_id;

  -- (6) 세간 정리 후 본체 삭제.
  --     타임라인은 cascade가 걸려 있지 않고(FK RESTRICT), 링크는 다형이라 FK 자체가 없다.
  execute format('delete from public.%I where program_module_id = $1', v_timeline)
    using p_module_id;

  delete from public.program_module_public_links
   where entity_key = p_entity_key and program_module_id = p_module_id;

  -- 자식 먼저, 부모 나중이다. 자식의 FK가 모두 cascade는 아니기 때문이다 —
  -- application_submissions는 form_id로 폼에 매달려 있고 그 FK에 on delete가 없어서,
  -- 이미 지운 지원서 한 건(deleted_at)만 남아 있어도 폼 삭제가 FK 오류로 끝난다.
  for r in select * from app.module_content_tables(v_module) loop
    for r2 in select * from app.module_cascade_children(r.rel_name) loop
      execute format(
        'delete from public.%I ch using public.%I pt
          where ch.%I = pt.%I and pt.%I = $1',
        r2.rel_name, r.rel_name, r2.fk_col, r2.parent_col, r.fk_col)
        using p_module_id;
    end loop;
    execute format('delete from public.%I where %I = $1', r.rel_name, r.fk_col)
      using p_module_id;
  end loop;

  -- 담당자 배정은 cascade라 본체 삭제가 함께 지운다.
  execute format('delete from public.%I where id = $1', v_module)
    using p_module_id;
end;
$_$;


ALTER FUNCTION "public"."delete_program_module"("p_entity_key" "text", "p_module_id" "uuid", "p_confirm_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_program_module"("p_entity_key" "text", "p_module_id" "uuid", "p_confirm_text" "text") IS '운영 모듈 인스턴스 물리 삭제. PM 전용 · 확인 문구(''삭제합니다'') · 밖에서 들어온 기록 0건의 세 관문을 통과해야 실행된다. 내부 배치는 함께 삭제되고 첨부는 귀속만 풀린다. audit_logs 적재.';



CREATE OR REPLACE FUNCTION "public"."enforce_ma_module_assignee_in_pool"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_program_id uuid;
begin
  select program_id into v_program_id
  from public.ma_program_modules where id = new.program_module_id;

  if v_program_id is null then
    raise exception '모듈 인스턴스를 찾을 수 없습니다.' using errcode = '23503';
  end if;

  if not exists (
    select 1 from public.ma_program_managers pm
    where pm.program_id = v_program_id and pm.user_id = new.user_id
  ) then
    raise exception '담당자는 사업 담당자 풀에 있는 사용자만 지정할 수 있습니다.' using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_ma_module_assignee_in_pool"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_module_assignee_in_pool"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_key     text;
  v_program uuid;
  v_table   text;
  v_ok      boolean;
begin
  select entity_key, program_id into v_key, v_program
    from public.program_modules where id = new.program_module_id;
  if v_program is null then
    raise exception '모듈 인스턴스를 찾을 수 없습니다.';
  end if;

  v_table := case v_key
    when 'program'    then 'program_managers'
    when 'ma_program' then 'ma_program_managers'
  end;
  -- 알 수 없는 원장 키는 여기서 사유와 함께 멈춘다. 두지 않으면 format('%I', null)이
  -- 담당자에게 아무것도 말해 주지 않는 오류로 떨어진다.
  if v_table is null then
    raise exception '알 수 없는 사업 원장입니다: %', v_key using errcode = '22023';
  end if;

  execute format(
    'select exists (select 1 from public.%I where program_id = $1 and user_id = $2)', v_table)
    into v_ok using v_program, new.user_id;

  if not v_ok then
    raise exception '담당자는 사업 담당자 풀에 있는 사용자만 지정할 수 있습니다.' using errcode = '23514';
  end if;
  return new;
end;
$_$;


ALTER FUNCTION "public"."enforce_module_assignee_in_pool"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_meeting_recording"("p_recording_id" "uuid", "p_duration_ms" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if not app.can_write_recording(p_recording_id) then
    raise exception '녹음을 종료할 권한이 없습니다.' using errcode = '42501';
  end if;
  if p_duration_ms < 0 then
    raise exception '녹음 시간이 올바르지 않습니다.' using errcode = '22023';
  end if;
  update public.meeting_recordings
     set status = 'PROCESSING', stopped_at = coalesce(stopped_at, now()),
         duration_ms = p_duration_ms, last_activity_at = now(), updated_at = now()
   where id = p_recording_id and status in ('RECORDING', 'FAILED');
end;
$$;


ALTER FUNCTION "public"."finish_meeting_recording"("p_recording_id" "uuid", "p_duration_ms" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fund_list_totals"("p_keyword" "text" DEFAULT NULL::"text", "p_statuses" "text"[] DEFAULT NULL::"text"[], "p_sources" "text"[] DEFAULT NULL::"text"[], "p_characters" "text"[] DEFAULT NULL::"text"[], "p_strategies" "text"[] DEFAULT NULL::"text"[], "p_fund_types" "text"[] DEFAULT NULL::"text"[], "p_term_from" "date" DEFAULT NULL::"date", "p_term_to" "date" DEFAULT NULL::"date", "p_balance_min" numeric DEFAULT NULL::numeric, "p_balance_max" numeric DEFAULT NULL::numeric, "p_strategy" "text" DEFAULT NULL::"text", "p_mine_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("fund_count" bigint, "total_commitment" numeric, "paid_in_amount" numeric, "drawn_amount" numeric, "balance" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'app'
    AS $$
  with scoped as (
    select f.total_commitment, f.paid_in_amount, f.drawn_amount, f.balance
      from public.funds f
     -- 목록과 같은 부분 인덱스 조건(20260731220000의 규약). 빼면 순차 스캔으로 되돌아간다.
     where f.deleted_at is null
       -- 스코프 — 구분 프리필터(AC/VC/PE 탭)와 '내 펀드'.
       -- '내 펀드'의 담당 축은 대표펀드매니저와 운용·관리 인력 둘이라 양쪽을 본다.
       -- 생성자는 권한 축이 아니지만 '내가 만든 것'을 찾는 자리라 함께 건다(화면과 동일).
       and (p_strategy is null or f.strategy_type::text = p_strategy)
       and (
         p_mine_user_id is null
         or f.created_by = p_mine_user_id
         or f.manager_id = p_mine_user_id
         or exists (
              select 1 from public.fund_managers m
               where m.fund_id = f.id and m.user_id = p_mine_user_id)
       )
       -- 좁힘 — 검색어와 필터. 빈 배열은 '미적용'으로 되돌린다.
       -- 빈 배열을 그대로 = any()에 넣으면 아무 행도 만족하지 않아 카드가 통째로 0이 된다.
       and (
         p_keyword is null
         or f.name ilike '%' || p_keyword || '%'
         or f.code ilike '%' || p_keyword || '%'
         or exists (
              select 1 from public.users u
               where u.id = f.manager_id and u.name ilike '%' || p_keyword || '%')
       )
       and (coalesce(cardinality(p_statuses), 0) = 0
            or f.status::text = any (p_statuses))
       and (coalesce(cardinality(p_sources), 0) = 0
            or f.source_type::text = any (p_sources))
       and (coalesce(cardinality(p_characters), 0) = 0
            or f.character_type::text = any (p_characters))
       -- 구분 필터의 '미지정'(__none__)은 실제 코드가 아니라 is null 표식이다(화면과 같은 규약).
       and (coalesce(cardinality(p_strategies), 0) = 0
            or f.strategy_type::text = any (p_strategies)
            or ('__none__' = any (p_strategies) and f.strategy_type is null))
       and (coalesce(cardinality(p_fund_types), 0) = 0
            or f.fund_type::text = any (p_fund_types))
       -- 존속기간은 "이 구간에 존속 중" — 지정 구간과 펀드 기간이 겹치면 걸린다.
       -- 기간이 비어 있는 펀드는 겹친다고 단정할 근거가 없어 이 필터를 걸면 빠진다(비교가 null).
       and (p_term_to is null or f.term_start <= p_term_to)
       and (p_term_from is null or f.term_end >= p_term_from)
       and (p_balance_min is null or f.balance >= p_balance_min)
       and (p_balance_max is null or f.balance <= p_balance_max)
  )
  select
    count(*),
    coalesce(sum(s.total_commitment), 0),
    -- 실출자금액만 nullable이라 여기서만 coalesce를 걷는다. 값을 적은 펀드가 하나도 없으면
    -- 합계가 null로 온다 — '0원이 들어왔다'와 '아직 아무도 안 적었다'는 다른 말이고,
    -- 0으로 뭉개면 화면이 출자율 0%를 사실인 양 그린다.
    sum(s.paid_in_amount),
    coalesce(sum(s.drawn_amount), 0),
    coalesce(sum(s.balance), 0)
    from scoped s;
$$;


ALTER FUNCTION "public"."fund_list_totals"("p_keyword" "text", "p_statuses" "text"[], "p_sources" "text"[], "p_characters" "text"[], "p_strategies" "text"[], "p_fund_types" "text"[], "p_term_from" "date", "p_term_to" "date", "p_balance_min" numeric, "p_balance_max" numeric, "p_strategy" "text", "p_mine_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fund_list_totals"("p_keyword" "text", "p_statuses" "text"[], "p_sources" "text"[], "p_characters" "text"[], "p_strategies" "text"[], "p_fund_types" "text"[], "p_term_from" "date", "p_term_to" "date", "p_balance_min" numeric, "p_balance_max" numeric, "p_strategy" "text", "p_mine_user_id" "uuid") IS 'FUND 목록 요약 카드의 금액 합계 4종. 인자는 목록 필터와 1:1이며 반환의 fund_count는 목록 건수와 대조해 조건 드리프트를 잡는 용도다.';



CREATE OR REPLACE FUNCTION "public"."gen_entity_code"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  alphabet constant text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
  candidate text := '';
  i int;
begin
  for i in 1..6 loop
    candidate := candidate || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
  end loop;
  return candidate;
end;
$$;


ALTER FUNCTION "public"."gen_entity_code"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."gen_entity_code"() IS '레코드 코드 후보(6자리 영숫자) 1건 생성. 유니크 보장은 entity_codes PK가 진다.';



CREATE OR REPLACE FUNCTION "public"."guest_accounts_list"("p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_entity_key" "text" DEFAULT NULL::"text", "p_master_tables" "text"[] DEFAULT NULL::"text"[], "p_only_orphans" boolean DEFAULT false, "p_facet" "text" DEFAULT NULL::"text") RETURNS TABLE("user_id" "uuid", "name" "text", "email" "text", "phone" "text", "user_type" "text", "is_active" boolean, "company_name" "text", "identities" "jsonb", "has_password" boolean, "created_at" timestamp with time zone, "last_login_at" timestamp with time zone, "program_count" integer, "open_count" integer, "programs" "jsonb", "total_count" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
#variable_conflict use_column
declare
  v_raw   boolean := app.is_admin();
  v_term  text    := nullif(btrim(coalesce(p_search, '')), '');
  v_digit text    := app.norm_phone(p_search);
begin
  if app.current_app_user_id() is null or app.is_guest() then
    raise exception '내부 사용자만 게스트 계정 목록을 볼 수 있습니다.' using errcode = '42501';
  end if;
  if p_entity_key is not null and p_entity_key not in ('program', 'ma_program', 'fund') then
    raise exception '알 수 없는 사업 원장입니다: %', p_entity_key using errcode = '22023';
  end if;
  if p_master_tables is not null and exists (
    select 1 from unnest(p_master_tables) t
     where t not in ('startups', 'networks', 'ma_sellers', 'ma_buyers')
  ) then
    raise exception '알 수 없는 인격 원장이 섞여 있습니다.' using errcode = '22023';
  end if;
  if p_facet is not null
     and p_facet not in ('startups', 'networks', 'ma_sellers', 'ma_buyers', 'fund', 'unlinked') then
    raise exception '알 수 없는 GUEST 계정 탭입니다: %', p_facet using errcode = '22023';
  end if;

  return query
  with ledger as (
    select 'program'::text as entity_key, id, code, title, status::text as status,
           guest_access_ends_at
      from public.programs where deleted_at is null
    union all
    select 'ma_program', id, code, title, status::text, guest_access_ends_at
      from public.ma_programs where deleted_at is null
    union all
    select 'fund', id, code, name, status::text, guest_access_ends_at
      from public.funds where deleted_at is null
  ),
  accounts as (
    select u.id, u.name, u.email, u.phone, u.user_type::text as user_type, u.is_active,
           u.created_at, u.company_id
      from public.users u
     where app.is_guest_user_type(u.user_type)
       and u.deleted_at is null
       and (
         v_term is null
         or u.name  ilike '%' || v_term || '%'
         or u.email ilike '%' || v_term || '%'
         or (v_digit is not null and app.norm_phone(u.phone) like '%' || v_digit || '%')
       )
       and app.guest_account_visible(u.id)
       and (
         p_master_tables is null
         or exists (
           select 1 from public.guest_identities gi
            where gi.user_id = u.id and gi.master_table = any (p_master_tables)
         )
       )
       and (
         p_facet is null
         or (
           p_facet in ('startups', 'networks', 'ma_sellers', 'ma_buyers')
           and exists (
             select 1 from public.guest_identities gi
              where gi.user_id = u.id and gi.master_table = p_facet
           )
         )
         or (
           p_facet = 'fund'
           and exists (
             select 1
               from public.program_participants pp
               join public.funds f on f.id = pp.program_id and f.deleted_at is null
              where pp.user_id = u.id and pp.entity_key = 'fund'
           )
         )
         or (p_facet = 'unlinked' and app.guest_account_is_unlinked(u.id))
       )
  ),
  participations as (
    select distinct on (p.user_id, p.entity_key, p.program_id)
           p.user_id, p.entity_key, p.program_id, p.master_table, p.login_status
      from public.program_participants p
     where p.user_id is not null
       and (p_entity_key is null or p.entity_key = p_entity_key)
     order by p.user_id, p.entity_key, p.program_id,
              case p.login_status
                when 'ACTIVE'      then 1
                when 'INVITED'     then 2
                when 'BLOCKED'     then 3
                when 'NOT_ALLOWED' then 4
                else 5
              end,
              p.master_table nulls last,
              p.id
  ),
  links as (
    select t.user_id,
           count(*) filter (where l.id is not null)::int as program_count,
           count(*) filter (
             where l.id is not null and t.login_status in ('INVITED', 'ACTIVE')
           )::int as open_count,
           coalesce(
             jsonb_agg(
               jsonb_build_object(
                 'program_id', t.program_id,
                 'entity_key', t.entity_key,
                 'workspace', app.entity_key_workspace(t.entity_key),
                 'code', l.code,
                 'title', l.title,
                 'master_table', t.master_table,
                 'login_status', t.login_status,
                 'program_status', l.status,
                 'access_ends_at', l.guest_access_ends_at
               ) order by l.title
             ) filter (where l.id is not null),
             '[]'::jsonb
           ) as programs
      from participations t
      left join ledger l on l.id = t.program_id and l.entity_key = t.entity_key
     group by t.user_id
  ),
  logins as (
    select gi.app_user_id as user_id, max(gi.used_at) as last_login_at
      from public.guest_invitations gi
     where gi.app_user_id is not null
     group by gi.app_user_id
  ),
  personas as (
    select gi.user_id,
           jsonb_agg(
             jsonb_build_object(
               'master_table', gi.master_table,
               'master_id', gi.master_id,
               'name', coalesce(s.name, n.name, ms.name, mb.name)
             ) order by gi.master_table
           ) as identities
      from public.guest_identities gi
      left join public.startups s
        on gi.master_table = 'startups' and s.id = gi.master_id
      left join public.networks n
        on gi.master_table = 'networks' and n.id = gi.master_id
      left join public.ma_sellers ms
        on gi.master_table = 'ma_sellers' and ms.id = gi.master_id
      left join public.ma_buyers mb
        on gi.master_table = 'ma_buyers' and mb.id = gi.master_id
     where case gi.master_table
             when 'ma_sellers' then app.can_read_ma_party('ma_seller', gi.master_id)
             when 'ma_buyers'  then app.can_read_ma_party('ma_buyer',  gi.master_id)
             else true
           end
     group by gi.user_id
  )
  select a.id,
         a.name,
         case when v_raw then a.email else app.mask_email(a.email) end,
         case when v_raw then a.phone else app.mask_phone(a.phone) end,
         a.user_type,
         a.is_active,
         s.name,
         coalesce(p.identities, '[]'::jsonb),
         app.guest_has_password(a.id),
         a.created_at,
         g.last_login_at,
         coalesce(k.program_count, 0),
         coalesce(k.open_count, 0),
         coalesce(k.programs, '[]'::jsonb),
         count(*) over ()
    from accounts a
    left join links k on k.user_id = a.id
    left join logins g on g.user_id = a.id
    left join personas p on p.user_id = a.id
    left join public.startups s on s.id = a.company_id
   where not coalesce(p_only_orphans, false) or coalesce(k.program_count, 0) = 0
   order by a.is_active desc, a.name
   limit least(greatest(coalesce(p_limit, 50), 1), 100)
  offset greatest(coalesce(p_offset, 0), 0);
end;
$$;


ALTER FUNCTION "public"."guest_accounts_list"("p_search" "text", "p_limit" integer, "p_offset" integer, "p_entity_key" "text", "p_master_tables" "text"[], "p_only_orphans" boolean, "p_facet" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guest_accounts_list"("p_search" "text", "p_limit" integer, "p_offset" integer, "p_entity_key" "text", "p_master_tables" "text"[], "p_only_orphans" boolean, "p_facet" "text") IS '전사 GUEST 계정 목록. p_facet은 스타트업·전문가·BUYER·SELLER 인격, FUND 참여, 분류 미연결을 서버 페이징 전에 분류한다. 한 계정의 복수 인격은 각 탭에 각각 나타나며, 원장 인격 없이 PROJECT·M&A에 계정만 추가한 경우는 미연결에 남는다. 참여 사업과 M&A 인격은 호출자가 읽을 수 있는 범위만 반환한다.';



CREATE OR REPLACE FUNCTION "public"."guest_my_participations"() RETURNS TABLE("participant_id" "uuid", "program_id" "uuid", "entity_key" "text", "workspace" "text", "code" "text", "title" "text", "persona" "text", "access_ends_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
  with live as (
    select 'program'::text as entity_key, id, code, title, guest_access_ends_at
      from public.programs    where deleted_at is null and status not in ('FINISHED', 'CANCELLED')
    union all
    select 'ma_program', id, code, title, guest_access_ends_at
      from public.ma_programs where deleted_at is null and status not in ('FINISHED', 'SUSPENDED', 'CANCELLED')
    union all
    select 'fund', id, code, name, guest_access_ends_at
      from public.funds       where deleted_at is null and status <> 'CLOSED'
  )
  select p.id,
         p.program_id,
         p.entity_key,
         app.entity_key_workspace(p.entity_key),
         g.code,
         g.title,
         p.master_table,
         g.guest_access_ends_at
    from public.program_participants p
    join live g
      on g.id = p.program_id
     and g.entity_key = p.entity_key
   where p.user_id = app.current_app_user_id()
     and p.login_status in ('INVITED', 'ACTIVE')
     and (g.guest_access_ends_at is null or g.guest_access_ends_at > now())
   order by g.title;
$$;


ALTER FUNCTION "public"."guest_my_participations"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guest_my_participations"() IS '호출자 본인의 열린 참여 목록. 세션 고정 맥락을 보지 않는다 — 맥락을 고르기 전에 부르는 목록이기 때문이다. 접근 기간은 사업 원장이 답한다. 근거: 3_9_1 §7~§8';



CREATE OR REPLACE FUNCTION "public"."guest_password_commit"("p_user_id" "uuid", "p_expected_session_version" integer, "p_expected_password_hash" "text", "p_new_password_hash" "text", "p_consume_ticket" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_account public.users%rowtype;
  v_hash    text;
  v_exists  boolean;
  v_version integer;
begin
  if p_user_id is null
     or p_expected_session_version is null
     or nullif(btrim(coalesce(p_new_password_hash, '')), '') is null then
    raise exception '필수 인자가 비어 있습니다.' using errcode = '22023';
  end if;

  select u.* into v_account
    from public.users u
   where u.id = p_user_id
   for update;
  if not found
     or v_account.deleted_at is not null
     or not v_account.is_active
     or v_account.user_type not in ('external_startup', 'external_expert', 'temporary_guest')
  then
    return jsonb_build_object('committed', false, 'reason', 'account_unavailable');
  end if;

  if v_account.session_version is distinct from p_expected_session_version then
    return jsonb_build_object('committed', false, 'reason', 'version_mismatch');
  end if;

  select c.password_hash into v_hash
    from public.guest_credentials c
   where c.user_id = p_user_id
   for update;
  v_exists := found;

  -- 행이 없는 것과 해시가 null인 것은 같은 사실이다(개시 상태).
  if v_hash is distinct from nullif(btrim(coalesce(p_expected_password_hash, '')), '') then
    return jsonb_build_object('committed', false, 'reason', 'password_changed');
  end if;

  if v_exists then
    update public.guest_credentials
       set password_hash    = p_new_password_hash,
           password_set_at  = now(),
           login_attempts   = 0,
           locked_until     = null,
           reset_token_hash = null,
           reset_expires_at = null
     where user_id = p_user_id;
  else
    insert into public.guest_credentials
      (user_id, password_hash, password_set_at, login_attempts, locked_until,
       reset_token_hash, reset_expires_at)
    values (p_user_id, p_new_password_hash, now(), 0, null, null, null);
  end if;

  v_version := v_account.session_version;
  if coalesce(p_consume_ticket, false) then
    update public.users
       set session_version = session_version + 1,
           updated_at = now()
     where id = p_user_id
    returning session_version into v_version;
  end if;

  return jsonb_build_object('committed', true, 'session_version', v_version);
end;
$$;


ALTER FUNCTION "public"."guest_password_commit"("p_user_id" "uuid", "p_expected_session_version" integer, "p_expected_password_hash" "text", "p_new_password_hash" "text", "p_consume_ticket" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guest_password_commit"("p_user_id" "uuid", "p_expected_session_version" integer, "p_expected_password_hash" "text", "p_new_password_hash" "text", "p_consume_ticket" boolean) IS '게스트 비밀번호의 유일한 쓰기 경로(비교 후 교체). 계정 생존·활성·GUEST 여부, 기대 session_version, 기대 password_hash가 모두 맞을 때만 저장하고 어긋나면 사유만 돌려준다. 티켓 경로는 성공 시 판을 올려 티켓을 소진하고 오른 판을 돌려준다. INVOKER이며 실행권한은 service_role 전용이다. 근거: 3_9_1 §6.2.1';



CREATE OR REPLACE FUNCTION "public"."guest_reset_token_consume"("p_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_hash    text := nullif(btrim(coalesce(p_token_hash, '')), '');
  v_user_id uuid;
  v_account public.users%rowtype;
  v_cred    public.guest_credentials%rowtype;
  v_rows    integer;
begin
  if v_hash is null then
    raise exception '필수 인자가 비어 있습니다.' using errcode = '22023';
  end if;

  -- 주인을 먼저 찾되 여기서는 잠그지 않는다. 잠금 순서를 users → guest_credentials로
  -- 고정해야 ADMIN 창구·비밀번호 커밋과 교착하지 않으며, 잠근 뒤에 해시를 다시 본다.
  select c.user_id into v_user_id
    from public.guest_credentials c
   where c.reset_token_hash = v_hash;
  if not found then
    return jsonb_build_object('consumed', false, 'reason', 'not_found');
  end if;

  select u.* into v_account
    from public.users u
   where u.id = v_user_id
   for update;
  if not found
     or v_account.deleted_at is not null
     or not v_account.is_active
     or v_account.user_type not in ('external_startup', 'external_expert', 'temporary_guest')
  then
    return jsonb_build_object('consumed', false, 'reason', 'account_unavailable');
  end if;

  select c.* into v_cred
    from public.guest_credentials c
   where c.user_id = v_user_id
   for update;
  -- 잠금을 얻기까지 사이에 다른 요청이 먼저 소진했거나 ADMIN이 비웠을 수 있다.
  if not found or v_cred.reset_token_hash is distinct from v_hash then
    return jsonb_build_object('consumed', false, 'reason', 'not_found');
  end if;
  if v_cred.reset_expires_at is null or v_cred.reset_expires_at <= now() then
    return jsonb_build_object('consumed', false, 'reason', 'expired');
  end if;
  -- 발급 때 적어 둔 판과 다르면 그 링크는 옛 계정 상태의 것이다(연락처 수정·초기화·차단).
  -- 이 마이그레이션 이전에 발급된 링크는 칸이 비어 있어 같은 자리에서 죽는다.
  if v_cred.reset_session_version is distinct from v_account.session_version then
    return jsonb_build_object('consumed', false, 'reason', 'version_mismatch');
  end if;

  -- 해시를 조건에 넣어 비운다. 같은 링크로 두 요청이 들어오면 하나만 1행을 고친다.
  -- **비밀번호 해시는 비우지 않는다** — 비우면 계정이 개시 상태로 돌아가 계정 생성 때
  -- 확정한 전화번호가 다시 통하고, 사용자가 링크만 열고 그만두면 그 상태로 남는다.
  -- 덮어쓸 권한은 티켓의 rst 표시가 준다(3_9_1 §6.2.1).
  update public.guest_credentials
     set reset_token_hash      = null,
         reset_expires_at      = null,
         reset_session_version = null,
         login_attempts        = 0,
         locked_until          = null
   where user_id = v_user_id
     and reset_token_hash = v_hash;
  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    return jsonb_build_object('consumed', false, 'reason', 'not_found');
  end if;

  -- 이름까지 함께 돌려주는 이유: 호출자가 계정을 다시 읽지 않아야 한다. 그 재조회가
  -- 새 경합 창이고, 거기서 읽은 판으로 티켓을 서명하면 옛 링크가 새 자격으로 승격된다.
  return jsonb_build_object(
    'consumed', true,
    'user_id', v_user_id,
    'session_version', v_account.session_version,
    'name', v_account.name
  );
end;
$$;


ALTER FUNCTION "public"."guest_reset_token_consume"("p_token_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guest_reset_token_consume"("p_token_hash" "text") IS '재설정 링크 소진(원자적). users → guest_credentials 순서로 잠그고 해시·만료·계정 상태·발급 시점 판을 확인한 뒤 해시를 조건에 넣은 UPDATE로 정확히 한 번 비운다. 검증한 판과 이름을 돌려주므로 호출자는 계정을 다시 읽지 않는다. INVOKER이며 실행권한은 service_role 전용이다. 근거: 3_9_1 §6.2.3';



CREATE OR REPLACE FUNCTION "public"."guest_reset_token_issue"("p_user_id" "uuid", "p_expected_session_version" integer, "p_token_hash" "text", "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_account public.users%rowtype;
begin
  if p_user_id is null
     or p_expected_session_version is null
     or nullif(btrim(coalesce(p_token_hash, '')), '') is null
     or p_expires_at is null then
    raise exception '필수 인자가 비어 있습니다.' using errcode = '22023';
  end if;
  if p_expires_at <= now() then
    raise exception '만료 시각이 이미 지났습니다.' using errcode = '22023';
  end if;

  select u.* into v_account
    from public.users u
   where u.id = p_user_id
   for update;
  if not found
     or v_account.deleted_at is not null
     or not v_account.is_active
     or v_account.user_type not in ('external_startup', 'external_expert', 'temporary_guest')
  then
    return jsonb_build_object('issued', false, 'reason', 'account_unavailable');
  end if;

  -- 호출자가 수신처를 읽은 그 시점의 계정이어야 한다. 판이 올랐다면 그 사이에 주소나
  -- 번호가 바뀐 것이므로, 저장을 거절해 **옛 주소로 링크가 나가는 길**을 닫는다.
  if v_account.session_version is distinct from p_expected_session_version then
    return jsonb_build_object('issued', false, 'reason', 'version_mismatch');
  end if;

  insert into public.guest_credentials
    (user_id, reset_token_hash, reset_expires_at, reset_session_version,
     login_attempts, locked_until)
  values (p_user_id, p_token_hash, p_expires_at, v_account.session_version, 0, null)
  on conflict (user_id) do update
    set reset_token_hash      = p_token_hash,
        reset_expires_at      = p_expires_at,
        reset_session_version = v_account.session_version,
        login_attempts        = 0,
        locked_until          = null;

  return jsonb_build_object('issued', true, 'session_version', v_account.session_version);
end;
$$;


ALTER FUNCTION "public"."guest_reset_token_issue"("p_user_id" "uuid", "p_expected_session_version" integer, "p_token_hash" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guest_reset_token_issue"("p_user_id" "uuid", "p_expected_session_version" integer, "p_token_hash" "text", "p_expires_at" timestamp with time zone) IS '재설정 링크 토큰 저장(조건부). users를 먼저 잠그고 생존·활성·GUEST와 기대 session_version이 맞을 때만 해시를 적으며 그 판을 reset_session_version에 함께 남긴다. 원문 토큰은 받지 않는다. INVOKER이며 실행권한은 service_role 전용이다. 근거: 3_9_1 §6.2.3';



CREATE OR REPLACE FUNCTION "public"."hard_delete_guest_account"("p_user_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_account          public.users%rowtype;
  v_ref              record;
  v_count            bigint;
  v_blockers         text[] := array[]::text[];
  v_identity_count   integer := 0;
  v_participant_count integer := 0;
  v_invitation_count integer := 0;
  v_notification_count integer := 0;
  v_memo_count       integer := 0;
  v_anonymized_count integer := 0;
begin
  if not app.is_admin() then
    raise exception 'GUEST 계정은 시스템 관리자만 영구 삭제할 수 있습니다.' using errcode = '42501';
  end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception '삭제 사유를 입력해야 합니다.' using errcode = '22023';
  end if;

  select u.* into v_account
    from public.users u
   where u.id = p_user_id and u.deleted_at is null
   for update;
  if not found then
    raise exception '대상 계정을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  if not app.is_guest_user_type(v_account.user_type) then
    raise exception 'GUEST 계정이 아닙니다.' using errcode = '22023';
  end if;

  select count(*)::integer into v_identity_count
    from public.guest_identities where user_id = p_user_id;
  select count(*)::integer into v_participant_count
    from public.program_participants where user_id = p_user_id;
  select count(*)::integer into v_invitation_count
    from public.guest_invitations where app_user_id = p_user_id;
  select count(*)::integer into v_notification_count
    from public.notifications where recipient_id = p_user_id;
  select count(*)::integer into v_memo_count
    from public.quick_memos where user_id = p_user_id;

  -- 개인에게만 속하는 전달·인증 자료는 업무 기록이 아니므로 계정과 함께 제거한다.
  delete from public.guest_invitations where app_user_id = p_user_id;
  delete from public.notifications where recipient_id = p_user_id;
  delete from public.quick_memos where user_id = p_user_id;

  -- 필수 참조는 임의로 지울 수도, null로 만들 수도 없다. 무엇이 막는지 모두 모아 한 번에 답한다.
  for v_ref in
    select ns.nspname as schema_name, cls.relname as table_name, att.attname as column_name
      from pg_catalog.pg_constraint con
      join pg_catalog.pg_class cls on cls.oid = con.conrelid
      join pg_catalog.pg_namespace ns on ns.oid = cls.relnamespace
      join pg_catalog.pg_attribute att
        on att.attrelid = con.conrelid and att.attnum = con.conkey[1]
     where con.contype = 'f'
       and con.confrelid = 'public.users'::regclass
       and pg_catalog.array_length(con.conkey, 1) = 1
       and att.attnotnull
       and con.confdeltype in ('a', 'r')
       and ns.nspname = 'public'
  loop
    execute pg_catalog.format(
      'select count(*) from %I.%I where %I = $1',
      v_ref.schema_name, v_ref.table_name, v_ref.column_name
    ) into v_count using p_user_id;
    if v_count > 0 then
      v_blockers := pg_catalog.array_append(
        v_blockers,
        pg_catalog.format('%I.%I(%s건)', v_ref.table_name, v_ref.column_name, v_count)
      );
    end if;
  end loop;

  if pg_catalog.array_length(v_blockers, 1) is not null then
    raise exception '필수 업무 참조가 남아 있어 삭제할 수 없습니다: %',
      pg_catalog.array_to_string(v_blockers, ', ')
      using errcode = '23503';
  end if;

  -- 업무 행은 보존한다. 사용자 FK가 nullable인 모든 곳에서 대상 계정 참조만 익명화한다.
  for v_ref in
    select ns.nspname as schema_name, cls.relname as table_name, att.attname as column_name
      from pg_catalog.pg_constraint con
      join pg_catalog.pg_class cls on cls.oid = con.conrelid
      join pg_catalog.pg_namespace ns on ns.oid = cls.relnamespace
      join pg_catalog.pg_attribute att
        on att.attrelid = con.conrelid and att.attnum = con.conkey[1]
     where con.contype = 'f'
       and con.confrelid = 'public.users'::regclass
       and pg_catalog.array_length(con.conkey, 1) = 1
       and not att.attnotnull
       and con.confdeltype in ('a', 'r')
       and ns.nspname = 'public'
  loop
    execute pg_catalog.format(
      'update %I.%I set %I = null where %I = $1',
      v_ref.schema_name, v_ref.table_name, v_ref.column_name, v_ref.column_name
    ) using p_user_id;
    get diagnostics v_count = row_count;
    v_anonymized_count := v_anonymized_count + v_count::integer;
  end loop;

  perform app.log_guest_access(
    p_user_id,
    'GUEST_ACCOUNT_HARD_DELETE',
    'guest:deleted',
    jsonb_build_object(
      'user_id', p_user_id,
      'name', v_account.name,
      'email', v_account.email,
      'user_type', v_account.user_type,
      'identity_count', v_identity_count,
      'participant_unlinked_count', v_participant_count,
      'invitation_count', v_invitation_count,
      'notification_count', v_notification_count,
      'memo_count', v_memo_count,
      'anonymized_reference_count', v_anonymized_count
    ),
    btrim(p_reason)
  );

  -- credentials·identities·workspace_permissions 등 계정 종속 행은 FK CASCADE로 함께 사라진다.
  delete from public.users where id = p_user_id;

  return jsonb_build_object(
    'identities', v_identity_count,
    'participants_unlinked', v_participant_count,
    'invitations_deleted', v_invitation_count,
    'notifications_deleted', v_notification_count,
    'memos_deleted', v_memo_count,
    'references_anonymized', v_anonymized_count
  );
end;
$_$;


ALTER FUNCTION "public"."hard_delete_guest_account"("p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."hard_delete_guest_account"("p_user_id" "uuid", "p_reason" "text") IS 'ADMIN 전용 GUEST 계정 물리 삭제. 인증·개인 자료를 제거하고 업무 기록의 nullable 사용자 참조는 익명화한다. 필수 참조가 남으면 전부 롤백한다.';



CREATE OR REPLACE FUNCTION "public"."hard_delete_guest_accounts"("p_user_ids" "uuid"[], "p_reason" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid;
  v_count   integer := 0;
begin
  if not app.is_admin() then
    raise exception 'GUEST 계정은 시스템 관리자만 영구 삭제할 수 있습니다.' using errcode = '42501';
  end if;
  if coalesce(pg_catalog.array_length(p_user_ids, 1), 0) = 0 then
    raise exception '삭제할 계정을 하나 이상 선택해야 합니다.' using errcode = '22023';
  end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception '삭제 사유를 입력해야 합니다.' using errcode = '22023';
  end if;

  for v_user_id in
    select distinct picked.id from pg_catalog.unnest(p_user_ids) as picked(id)
     where picked.id is not null
     order by picked.id
  loop
    perform public.hard_delete_guest_account(v_user_id, p_reason);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."hard_delete_guest_accounts"("p_user_ids" "uuid"[], "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."hard_delete_guest_accounts"("p_user_ids" "uuid"[], "p_reason" "text") IS 'ADMIN 전용 GUEST 계정 일괄 물리 삭제. 선택 전체를 한 트랜잭션에서 처리해 부분 삭제를 남기지 않는다.';



CREATE OR REPLACE FUNCTION "public"."increment_board_post_view"("p_post_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_count integer;
begin
  if not app.can_read_board_post(p_post_id) then
    return null;
  end if;
  update public.board_posts
     set view_count = view_count + 1
   where id = p_post_id
     and deleted_at is null
  returning view_count into v_count;
  return v_count;
end $$;


ALTER FUNCTION "public"."increment_board_post_view"("p_post_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."increment_board_post_view"("p_post_id" "uuid") IS '게시글 조회수 +1. 열람 권한자(app.can_read_board_post)만 반영하며 view_count 외 컬럼·updated_at을 바꾸지 않는다.';



CREATE OR REPLACE FUNCTION "public"."increment_minute_view"("p_minute_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_count integer;
begin
  if not app.can_read_minute(p_minute_id) then
    return null;
  end if;
  update public.meeting_minutes
     set view_count = view_count + 1
   where id = p_minute_id
     and deleted_at is null
  returning view_count into v_count;
  return v_count;
end $$;


ALTER FUNCTION "public"."increment_minute_view"("p_minute_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."increment_minute_view"("p_minute_id" "uuid") IS '회의록 조회수 +1. 열람 권한자(app.can_read_minute)만 반영하며 view_count 외 컬럼·updated_at을 바꾸지 않는다.';



CREATE OR REPLACE FUNCTION "public"."issue_guest_account"("p_master_table" "text", "p_master_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_email" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid       uuid := app.current_app_user_id();
  v_existing  uuid;
  v_name      text;
  v_email     text;
  v_phone     text;
  v_user_type text;
  v_company   uuid;
  v_new       uuid;
  v_email_key text;
  -- 원장에서 꺼냈는가, 담당자가 지정했는가. 감사 로그가 이 사실을 남긴다.
  v_source    text;
  -- 같은 이메일을 쥔 기존 계정의 이름(②-1 대조용).
  v_other_name text;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.' using errcode = '42501';
  end if;
  -- 게스트가 게스트를 만들 수 있으면 계정 원장이 밖에서 자란다.
  if app.is_guest() then
    raise exception '내부 사용자만 게스트 계정을 발급할 수 있습니다.' using errcode = '42501';
  end if;
  if p_master_table is null or p_master_id is null then
    raise exception '원장과 대상을 지정해야 합니다.' using errcode = '22023';
  end if;
  -- 허용 목록. 여기 없는 원장은 계정을 세울 수 없다 — 그리고 그 강제는 이 함수만이
  -- 아니라 guest_identities·program_participants의 CHECK가 함께 진다(한 곳만 열면
  -- 다른 곳에서 막혀, 발급은 되는데 명부에 담기지 않는 계정이 생긴다).
  if p_master_table not in ('startups', 'networks', 'ma_sellers', 'ma_buyers') then
    raise exception '지원하지 않는 원장입니다: %', p_master_table using errcode = '22023';
  end if;

  -- ⓪ 사람 확정. 원장 값은 **기본값**이지 정답이 아니다 — 담당자가 넘긴 값이 이긴다.
  --   셋 중 하나만 넘어와도 나머지는 원장에서 채운다(발급 폼이 이름만 고치는 경우).
  --
  --   `else`를 쓰지 않고 원장마다 `when`을 적는다 — 원장이 둘일 때는 else가 곧 나머지
  --   하나였지만 넷이 된 지금은 모르는 값이 조용히 마지막 가지로 흘러든다. 어느 가지도
  --   타지 않으면 v_name이 비고 아래 'not found'가 사유와 함께 멈춘다.
  if p_master_table = 'startups' then
    -- top-level 칸을 먼저 본다. contact jsonb는 20260710140000 이후 아무도 쓰지 않는
    -- 옛 칸이라, 그것만 보면 화면에 이메일이 보이는 기업이 여기서는 '없음'이 된다.
    select s.representative,
           coalesce(nullif(s.email, ''), nullif(s.contact ->> 'email', '')),
           coalesce(nullif(s.phone, ''), nullif(s.contact ->> 'phone', ''))
      into v_name, v_email, v_phone
      from public.startups s
     where s.id = p_master_id and s.deleted_at is null;
    v_user_type := 'external_startup';
    -- company_id는 startups(id) FK다. 스타트업 인격만 그 칸을 채울 수 있고, 나머지
    -- 원장은 비워 둔다 — 소속은 guest_identities가 답한다(3_9_2 §5).
    v_company   := p_master_id;
  elsif p_master_table = 'networks' then
    select n.name, nullif(n.email, ''), nullif(n.phone, '')
      into v_name, v_email, v_phone
      from public.networks n
     where n.id = p_master_id and n.deleted_at is null and n.merged_into_id is null;
    v_user_type := 'external_expert';
  elsif p_master_table = 'ma_sellers' then
    select nullif(x.contact_name, ''), nullif(x.contact_email, ''), nullif(x.phone, '')
      into v_name, v_email, v_phone
      from public.ma_sellers x
     where x.id = p_master_id and x.deleted_at is null;
    -- user_type을 늘리지 않는다(2026-09-08 확정). 3종이 서로 갈라 판정하는 자리가 없고
    -- 30여 곳에서 한 묶음으로만 쓰인다 — 무엇인지는 master_table이 답한다. 매각 기업·
    -- 인수 후보사는 둘 다 기업이므로 external_startup을 그대로 쓴다.
    v_user_type := 'external_startup';
  elsif p_master_table = 'ma_buyers' then
    select nullif(x.contact_name, ''), nullif(x.contact_email, ''), nullif(x.phone, '')
      into v_name, v_email, v_phone
      from public.ma_buyers x
     where x.id = p_master_id and x.deleted_at is null;
    v_user_type := 'external_startup';
  end if;

  -- 원장 행 자체가 없으면 여기서 멈춘다(인자를 다 넘겨도 마찬가지다 —
  -- 없는 대상에 인격을 붙이면 그 계정이 무엇에 속하는지 답할 수 없다).
  if not found then
    raise exception '원장에서 대상을 찾을 수 없습니다.' using errcode = '22023';
  end if;

  v_source := case
    when coalesce(nullif(btrim(p_email), ''), nullif(btrim(p_name), ''), nullif(btrim(p_phone), '')) is null
      then 'ledger' else 'specified'
  end;

  v_name  := coalesce(nullif(btrim(p_name),  ''), v_name);
  v_email := coalesce(nullif(btrim(p_email), ''), v_email);
  v_phone := coalesce(nullif(btrim(p_phone), ''), v_phone);

  -- 비교는 소문자로 하고 **저장은 적힌 그대로** 한다. 유일 인덱스가 lower(email)이라
  -- 판정은 어차피 대소문자를 가리지 않으며, 여기서 낮춰 저장하면 담당자가 적은 표기가
  -- 화면·메일 안내에서 조용히 바뀐다(우리가 고칠 값이 아니다).
  v_email_key := lower(v_email);

  if v_name is null then
    raise exception '이름이 없어 계정을 세울 수 없습니다. 담당자 이름을 지정하거나 원장에서 보완하십시오.'
      using errcode = '22023';
  end if;
  if v_email is null then
    raise exception '이메일이 없어 계정을 세울 수 없습니다(이메일이 로그인 ID입니다). 담당자 이메일을 지정하거나 원장에서 보완하십시오.'
      using errcode = '22023';
  end if;

  -- 내부 임직원의 주소로 게스트 계정을 세우지 않는다.
  --
  -- 종전에는 이 길이 사실상 닫혀 있었다 — 이메일이 원장에서만 왔기 때문이다. 담당자가
  -- 직접 적게 되면서 오타 한 번으로 자기 회사 주소가 들어올 수 있게 됐다. 유일 인덱스
  -- (uq_users_guest_email)는 **게스트끼리만** 막으므로 이 조합은 조용히 저장된다.
  --
  -- 그러면 한 이메일에 users 행이 둘이 되고, 임직원 목록을 묻는 조회는 유형으로
  -- 거르므로(lib/userTypes) 겉으로는 멀쩡하지만 사람을 이메일로 찾는 자리마다 답이
  -- 둘이 된다. 게스트 로그인 경로도 그 사람을 영영 받지 않는다(유형이 다르다).
  -- 즉 만들어 봐야 쓰이지 않는 행이므로, 만들지 않고 사유를 말한다.
  if exists (
    select 1 from public.users u
     where u.deleted_at is null
       and lower(u.email) = v_email_key
       and not app.is_guest_user_type(u.user_type)
  ) then
    raise exception '이 이메일은 내부 임직원 계정입니다. 게스트 계정은 다른 주소로 세우십시오.'
      using errcode = '22023';
  end if;

  -- ① 이 원장 행 × 이 사람에게 이미 계정이 있는가.
  --    재운 계정(deleted_at)은 세지 않는다 — 병합으로 흡수된 계정이 새 발급을
  --    영원히 막으면 안 된다(그 매핑은 병합이 이미 옮겼다).
  select gi.user_id into v_existing
    from public.guest_identities gi
    join public.users u on u.id = gi.user_id and u.deleted_at is null
   where gi.master_table = p_master_table
     and gi.master_id    = p_master_id
     and lower(u.email)  = v_email_key;
  if v_existing is not null then
    return v_existing;
  end if;

  -- ② 같은 이메일의 게스트 계정이 이미 있는가 — 같은 사람이 다른 자격으로 들어와 있는 경우다.
  --    이때는 계정을 만들지 않고 **인격만 하나 더 붙인다.**
  select u.id into v_existing
    from public.users u
   where u.user_type in ('external_startup', 'external_expert', 'temporary_guest')
     and u.deleted_at is null
     and lower(u.email) = v_email_key;

  -- ②-1 같은 이메일인데 **이름이 다르면** 다른 사람이다 (2026-09-11, 3_3_8 §6).
  --     종전에는 이름을 보지 않고 인격만 붙여, 실수로 같은 이메일이 들어간 두 사람(A기업
  --     홍길동 / B기업 임꺽정)이 한 계정이 되었다 — 먼저 들어온 쪽이 두 기업의 자료를 다
  --     본다. 이메일은 한 사람이 하나씩 쓰는 값이라 "같은 이메일 + 다른 이름"은 오입력
  --     말고는 생기지 않는다. 대조는 공백·법인 표기를 걷은 뒤 한다(홍 길동 / 홍길동).
  if v_existing is not null then
    select u.name into v_other_name from public.users u where u.id = v_existing;
    if app.norm_entity_name(v_other_name) is distinct from app.norm_entity_name(v_name) then
      raise exception '이 이메일(%)은 다른 사람(%)의 게스트 계정에 쓰이고 있습니다. 원장의 이메일을 확인하십시오.',
        v_email, v_other_name
        using errcode = '23505', hint = 'guest_email_name_mismatch:' || v_existing;
    end if;
  end if;

  if v_existing is null then
    -- ③ 새 계정. 여기서만 연락처가 필요하다 — 초기 비밀번호이기 때문이며, 이미 계정이
    --    있는 사람은 자기 비밀번호로 들어오므로 위 두 갈래에서는 묻지 않는다.
    if v_phone is null then
      raise exception '연락처가 없어 계정을 세울 수 없습니다(연락처가 초기 비밀번호입니다). 담당자 연락처를 지정하거나 원장에서 보완하십시오.'
        using errcode = '22023';
    end if;

    insert into public.users (user_type, name, email, phone, company_id)
    values (v_user_type::public.user_type, v_name, v_email, v_phone, v_company)
    returning id into v_new;

    -- 게스트 워크스페이스 권한 한 벌. **범위(scope)는 화면을 가르지 않는다** — 게스트가
    -- 보는 것은 전적으로 app.guest_program_ids()/guest_module_ids()가 판정하며, 자격은
    -- 세션에 고정된 참여 줄이 답한다. 여기 값은 권한 템플릿과의 형식만 맞춘다.
    insert into public.workspace_permissions (user_id, workspace_key, permission_level, scope_type, scope_id)
    values (v_new, 'guest', 'write', 'self'::public.scope_type, null)
    on conflict (user_id, workspace_key) do nothing;

    -- 자격증명 자리를 비워 둔 채로 함께 만든다. 행이 없으면 로그인 경로가 "초기 상태"와
    -- "계정 없음"을 구분하지 못한다.
    insert into public.guest_credentials (user_id) values (v_new)
    on conflict (user_id) do nothing;
  else
    v_new := v_existing;
  end if;

  -- 인격을 붙인다. 한 계정이 여러 인격을 갖는 것도(참가기업 + 참가전문가),
  -- 한 원장 행이 여러 계정을 갖는 것도(회사 담당자 여럿) 정상이다.
  insert into public.guest_identities (master_table, master_id, user_id, created_by)
  values (p_master_table, p_master_id, v_new, v_uid)
  on conflict (master_table, master_id, user_id) do nothing;

  perform app.log_guest_access(
    v_new,
    case when v_existing is null then 'GUEST_ACCOUNT_ISSUE' else 'GUEST_IDENTITY_ADD' end,
    'guest:account',
    jsonb_build_object(
      'master_table',  p_master_table,
      'master_id',     p_master_id,
      -- 이 계정의 이메일을 누가 정했는가. 원장 연락처를 그대로 쓴 것과 담당자가
      -- 지정한 것은 나중에 갈라 물어야 하는 사실이다.
      'person_source', v_source
    ),
    null
  );

  return v_new;
end;
$$;


ALTER FUNCTION "public"."issue_guest_account"("p_master_table" "text", "p_master_id" "uuid", "p_name" "text", "p_email" "text", "p_phone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."issue_guest_account"("p_master_table" "text", "p_master_id" "uuid", "p_name" "text", "p_email" "text", "p_phone" "text") IS '원장 행 × 사람에게 게스트 계정을 세우고 인격을 붙인다(멱등: 같은 이메일·같은 이름이면 그 계정을 그대로 돌려준다). 같은 이메일인데 이름이 다르면 거절한다(2026-09-11 — 두 사람이 한 계정이 되어 남의 기업 자료를 보는 사고를 막는다, 3_3_8 §6). 원장 값은 기본값이고 담당자가 넘긴 값이 이긴다. 근거: 3_9_1 §4, 3_9_2 §5';



CREATE OR REPLACE FUNCTION "public"."log_sensitive_access"("p_resource_type" "text", "p_resource_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_user uuid := app.current_app_user_id();
begin
  -- 1) 호출자 인증(활성 앱 사용자) 확인
  if v_user is null then
    raise exception '인증이 필요합니다.' using errcode = '42501';
  end if;

  -- 2) 열람 사유 필수(공백만 입력 시 거부)
  if p_reason is null or length(trim(p_reason)) < 2 then
    raise exception '열람 사유를 입력해야 합니다.' using errcode = '22023';
  end if;

  if p_resource_type is null or length(trim(p_resource_type)) = 0 then
    raise exception '대상 리소스 유형이 필요합니다.' using errcode = '22023';
  end if;

  -- 3) 접근 로그 적재(실패 시 예외 전파 → 클라이언트는 원본을 열람하지 못한다)
  insert into public.access_logs (user_id, resource_type, resource_id, reason)
  values (v_user, trim(p_resource_type), p_resource_id, trim(p_reason));
end;
$$;


ALTER FUNCTION "public"."log_sensitive_access"("p_resource_type" "text", "p_resource_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ma_party_ledger_counts"("p_table" "text") RETURNS TABLE("mine" bigint, "total" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
begin
  if app.current_app_user_id() is null
     or app.is_guest()
     or not app.can_read_workspace('mna') then
    raise exception 'M&A 원장 건수 조회 권한이 없습니다.' using errcode = '42501';
  end if;
  if p_table not in ('ma_sellers', 'ma_buyers') then
    raise exception '지원하지 않는 M&A 원장입니다.' using errcode = '22023';
  end if;

  return query execute format(
    $sql$
      select
        count(*) filter (
          where p.created_by = app.current_app_user_id()
             or exists (
               select 1
                 from public.entity_contributions c
                where c.entity_table = %L
                  and c.entity_id = p.id
                  and c.user_id = app.current_app_user_id()
             )
        )::bigint as mine,
        count(*)::bigint as total
      from public.%I p
      where p.deleted_at is null
        and p.merged_into_id is null
    $sql$,
    p_table,
    p_table
  );
end;
$_$;


ALTER FUNCTION "public"."ma_party_ledger_counts"("p_table" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ma_party_ledger_counts"("p_table" "text") IS 'M&A SELLER·BUYER 활성 원장의 내 누적(생성자 또는 기여자)과 전사 누적을 함께 센다. 허용 원장은 두 표로 고정하며 SECURITY INVOKER로 기존 RLS를 따른다.';



CREATE OR REPLACE FUNCTION "public"."ma_party_posts_list"("p_target_type" "text", "p_keyword" "text" DEFAULT NULL::"text", "p_decisions" "text"[] DEFAULT NULL::"text"[], "p_limit" integer DEFAULT 30, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_result jsonb;
begin
  if app.current_app_user_id() is null
     or app.is_guest()
     or not app.can_read_workspace('mna') then
    raise exception 'M&A 목록 열람 권한이 없습니다.' using errcode = '42501';
  end if;
  if p_target_type not in ('ma_buyer', 'ma_seller') then
    raise exception '지원하지 않는 M&A 게시글 종류입니다: %', p_target_type
      using errcode = '22023';
  end if;

  with source as (
    select 'ma_buyer'::text as target_type,
           x.id, x.name, x.industries, x.wish, x.available_funds,
           null::text as decision, x.contact_name, x.contact_email, x.phone,
           x.startup_id, x.created_at, x.updated_at, x.created_by, x.viewer_ids,
           u.name as creator_name,
           app.can_read_ma_party('ma_buyer', x.id) as can_read
      from public.ma_buyers x
      left join public.users u on u.id = x.created_by
     where p_target_type = 'ma_buyer'
       and x.deleted_at is null
    union all
    select 'ma_seller'::text,
           x.id, x.name, x.industries, x.wish, x.available_funds,
           x.decision::text, x.contact_name, x.contact_email, x.phone,
           x.startup_id, x.created_at, x.updated_at, x.created_by, x.viewer_ids,
           u.name,
           app.can_read_ma_party('ma_seller', x.id)
      from public.ma_sellers x
      left join public.users u on u.id = x.created_by
     where p_target_type = 'ma_seller'
       and x.deleted_at is null
  ), filtered as (
    select *
      from source s
     where (
       s.can_read
       and (
         nullif(btrim(coalesce(p_keyword, '')), '') is null
         or s.name ilike '%' || btrim(p_keyword) || '%'
         or coalesce(s.wish, '') ilike '%' || btrim(p_keyword) || '%'
       )
       and (
         coalesce(cardinality(p_decisions), 0) = 0
         or (s.decision is null and '__unset__' = any (p_decisions))
         or s.decision = any (p_decisions)
       )
     )
     or (
       not s.can_read
       and nullif(btrim(coalesce(p_keyword, '')), '') is null
       and coalesce(cardinality(p_decisions), 0) = 0
     )
  ), page as (
    select *
      from filtered
     order by updated_at desc
    limit least(greatest(coalesce(p_limit, 30), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', id,
          'name', case when can_read then name else '열람 권한이 없는 게시글' end,
          'industries', case when can_read then industries else '[]'::jsonb end,
          'wish', case when can_read then wish end,
          'available_funds', case when can_read then available_funds end,
          'decision', case when can_read then decision end,
          'contact_name', case when can_read then contact_name end,
          'contact_email', case when can_read then contact_email end,
          'phone', case when can_read then phone end,
          'startup_id', case when can_read then startup_id end,
          'created_at', created_at,
          'updated_at', updated_at,
          'created_by', case when can_read then created_by end,
          'viewer_ids', case when can_read then to_jsonb(viewer_ids) else '[]'::jsonb end,
          'creator_name', case when can_read then creator_name end,
          'can_read', can_read
        ) order by updated_at desc
      ) from page
    ), '[]'::jsonb),
    'total', (select count(*) from filtered),
    'totalAll', (select count(*) from source)
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."ma_party_posts_list"("p_target_type" "text", "p_keyword" "text", "p_decisions" "text"[], "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ma_party_posts_list"("p_target_type" "text", "p_keyword" "text", "p_decisions" "text"[], "p_limit" integer, "p_offset" integer) IS 'M&A BUYER·SELLER 목록의 안전 투영. 작성자·열람자·최고관리자는 내용 요약을, 그 밖의 M&A 열람자는 존재와 시각만 본다.';



CREATE OR REPLACE FUNCTION "public"."ma_party_viewer_candidates"() RETURNS TABLE("id" "uuid", "name" "text", "email" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if app.is_guest() or not app.can_write_workspace('mna') then
    raise exception 'M&A 열람자를 지정할 권한이 없습니다.' using errcode = '42501';
  end if;

  return query
  select u.id, u.name, u.email
    from public.users u
   where u.deleted_at is null
     and u.is_active
     and not app.is_guest_user_type(u.user_type)
     and (
       u.user_type::text = 'super_admin'
       or exists (
         select 1
           from public.workspace_permissions wp
          where wp.user_id = u.id
            and wp.workspace_key::text = 'mna'
            and wp.permission_level in ('read', 'write')
            and (wp.expires_at is null or wp.expires_at > now())
       )
     )
   order by u.name, u.id;
end;
$$;


ALTER FUNCTION "public"."ma_party_viewer_candidates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_entity"("p_table" "text", "p_primary_id" "uuid", "p_duplicate_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_rows integer;
  r      record;
  v_hit  integer;
begin
  if not app.has_contribution_trigger(p_table) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  if p_primary_id = p_duplicate_id then
    raise exception 'same_record' using errcode = '22023';
  end if;

  -- ── (a) 옮길 수 없는 겹침을 **먼저** 본다 ─────────────────────────
  -- 절반만 옮긴 뒤 거절하면 그 트랜잭션은 되돌아가지만, 순서를 뒤로 두면 실패할 때마다
  -- 무거운 UPDATE를 헛돌린다. 그리고 거절 사유가 무엇인지 말하려면 옮기기 전에 알아야 한다.
  for r in select * from app.merge_ref_tables(p_table) where on_conflict = 'block' loop
    execute format(
      'select count(*)::int from public.%I d
        where d.%I = $1 and d.%I = $2
          and exists (select 1 from public.%I p
                       where p.%I = $1 and p.%I = $3 and %s)',
      r.rel_name, r.type_col, r.id_col, r.rel_name, r.type_col, r.id_col,
      app.merge_conflict_join(r.conflict_cols)
    ) into v_hit using r.type_value, p_duplicate_id, p_primary_id;
    if v_hit > 0 then
      -- 사유에 표 이름을 담는다 — "병합할 수 없습니다" 한 줄이면 무엇을 먼저 정리해야
      -- 하는지 담당자가 알 수 없다.
      raise exception 'merge_conflict:%', r.rel_name using errcode = '23505';
    end if;
  end loop;

  -- ── (b) 중복 행: 어디로 흡수됐는지(트리거가 'merged'로 기록) ──────
  perform set_config('app.contribution_ctx',
                     jsonb_build_object('note', '정본으로 병합됨')::text,
                     true);
  execute format(
    'update public.%I set merged_into_id = $1 where id = $2 and merged_into_id is null',
    p_table
  ) using p_primary_id, p_duplicate_id;
  get diagnostics v_rows = row_count;

  if v_rows = 0 then
    raise exception 'not_found_or_forbidden' using errcode = '42501';
  end if;

  -- ── (c) 정본 행: 무엇을 흡수했는지 ────────────────────────────────
  -- 정본은 값이 바뀌지 않으므로 트리거가 볼 것이 없다 — 원장 변경이 아니라 순수 기록이라
  -- 여기서 직접 남긴다(행위자는 스탬프 트리거가 채운다).
  insert into public.entity_contributions (entity_table, entity_id, action, source, note)
  values (p_table, p_primary_id, 'merged', 'manual', coalesce(nullif(btrim(p_note), ''), '중복 병합'));

  -- ── (d) 다형 참조를 정본으로 옮긴다 ───────────────────────────────
  perform set_config('app.contribution_ctx',
                     jsonb_build_object('source', 'manual', 'note', '중복 병합으로 이관')::text,
                     true);
  for r in select * from app.merge_ref_tables(p_table) where on_conflict <> 'block' loop
    -- 겹치는 줄만 먼저 치운다. **겹침이 성립하는 표에만** 이 단계가 있다 — 유일 제약이 없는
    -- 표(자료·코멘트)에서 대상 키만으로 겹침을 판정하면, 정본에 자료가 하나라도 있을 때
    -- 중복 쪽 자료가 전부 접힌다.
    if r.on_conflict = 'soft' then
      execute format(
        'update public.%I d set deleted_at = now()
          where d.%I = $1 and d.%I = $2 and d.deleted_at is null
            and exists (select 1 from public.%I p
                         where p.%I = $1 and p.%I = $3 and p.deleted_at is null and %s)',
        r.rel_name, r.type_col, r.id_col, r.rel_name, r.type_col, r.id_col,
        app.merge_conflict_join(r.conflict_cols)
      ) using r.type_value, p_duplicate_id, p_primary_id;
    elsif r.on_conflict = 'delete' then
      execute format(
        'delete from public.%I d
          where d.%I = $1 and d.%I = $2
            and exists (select 1 from public.%I p
                         where p.%I = $1 and p.%I = $3 and %s)',
        r.rel_name, r.type_col, r.id_col, r.rel_name, r.type_col, r.id_col,
        app.merge_conflict_join(r.conflict_cols)
      ) using r.type_value, p_duplicate_id, p_primary_id;
    end if;

    -- 남은 줄을 정본으로 옮긴다.
    execute format(
      'update public.%I set %I = $3 where %I = $1 and %I = $2',
      r.rel_name, r.id_col, r.type_col, r.id_col
    ) using r.type_value, p_duplicate_id, p_primary_id;
  end loop;

  -- ── (e) 하드 FK를 정본으로 옮긴다 ─────────────────────────────────
  -- 유일 제약에 걸리면 그대로 터뜨린다. 여기서 한쪽을 지우는 판단을 하지 않는 이유는
  -- (a)와 같다 — 무엇을 지울지는 그 표의 일이고, 병합이 대신 정하면 그 표의 규칙이 무너진다.
  -- 거절은 트랜잭션 전체를 되돌리므로 절반만 옮겨진 상태가 남지 않는다.
  for r in select * from app.merge_fk_columns(p_table) loop
    execute format('update public.%I set %I = $2 where %I = $1', r.rel_name, r.fk_col, r.fk_col)
      using p_duplicate_id, p_primary_id;
  end loop;

  -- ── (f) 소속 3축 흡수(소속 컬럼을 가진 원장만 — 현재 NETWORKS) ────
  if app.entity_has_affiliation(p_table) then
    perform set_config('app.contribution_ctx',
                       jsonb_build_object('source', 'manual', 'note', '병합 이력 흡수')::text,
                       true);
    execute format($m$
      update public.%1$I p
         set profile = jsonb_set(
               coalesce(p.profile, '{}'::jsonb),
               '{affiliation_history}',
               coalesce(p.profile->'affiliation_history', '[]'::jsonb)
                 || coalesce(d.profile->'affiliation_history', '[]'::jsonb)
                 || case
                      when (coalesce(btrim(d.affiliation), '') is distinct from coalesce(btrim(p.affiliation), '')
                            or coalesce(btrim(d.profile->>'department'), '') is distinct from coalesce(btrim(p.profile->>'department'), '')
                            or coalesce(btrim(d.profile->>'position'), '') is distinct from coalesce(btrim(p.profile->>'position'), ''))
                       and coalesce(btrim(d.affiliation), '') || coalesce(btrim(d.profile->>'department'), '') || coalesce(btrim(d.profile->>'position'), '') <> ''
                      then jsonb_build_array(jsonb_build_object(
                             'affiliation', d.affiliation,
                             'department',  d.profile->>'department',
                             'position',    d.profile->>'position',
                             'source', 'merge', 'note', '중복 병합 흡수', 'at', now()))
                      else '[]'::jsonb
                    end,
               true)
        from public.%1$I d
       where p.id = $1 and d.id = $2
         and (
           coalesce(d.profile->'affiliation_history', '[]'::jsonb) <> '[]'::jsonb
           or (
             (coalesce(btrim(d.affiliation), '') is distinct from coalesce(btrim(p.affiliation), '')
              or coalesce(btrim(d.profile->>'department'), '') is distinct from coalesce(btrim(p.profile->>'department'), '')
              or coalesce(btrim(d.profile->>'position'), '') is distinct from coalesce(btrim(p.profile->>'position'), ''))
             and coalesce(btrim(d.affiliation), '') || coalesce(btrim(d.profile->>'department'), '') || coalesce(btrim(d.profile->>'position'), '') <> ''
           )
         )
    $m$, p_table) using p_primary_id, p_duplicate_id;
  end if;
end $_$;


ALTER FUNCTION "public"."merge_entity"("p_table" "text", "p_primary_id" "uuid", "p_duplicate_id" "uuid", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_entity"("p_table" "text", "p_primary_id" "uuid", "p_duplicate_id" "uuid", "p_note" "text") IS '중복 병합: 중복 행에 merged_into_id 지정 + 양쪽에 기여 기록 + **참조를 정본으로 이관**(자료·코멘트·회의록 링크·참가자 명단·하드 FK 전부) + 소속 3축 흡수. 기여·감사·접근 로그와 부여 코드는 옮기지 않는다(그 행에 일어난 일이라 주인을 바꾸면 거짓 기록이 된다). GUEST 명부·게스트 계정 매핑이 겹치면 옮기지 않고 merge_conflict로 거절한다 — 지우는 일에는 저마다 제 경로가 있다.';



CREATE OR REPLACE FUNCTION "public"."my_attendance_policy"("p_date" "date" DEFAULT NULL::"date") RETURNS "public"."attendance_policies"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
  select app.resolve_attendance_policy(
           app.current_app_user_id(),
           coalesce(p_date, app.kst_today())
         )
   where app.current_app_user_id() is not null
     and app.is_internal_user();
$$;


ALTER FUNCTION "public"."my_attendance_policy"("p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_kpi_dashboard"("p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("scope_type" "text", "assignment_id" "uuid", "template_name" "text", "subject_name" "text", "item_id" "uuid", "metric_code" "text", "metric_name" "text", "description" "text", "criteria_text" "text", "unit" "text", "target_mode" "text", "rule_type" "text", "rule_params" "jsonb", "target_value" numeric, "actual_value" numeric, "qualitative_value" "text", "actual_payload" "jsonb", "computed_score" numeric, "evidence_ref" "text", "max_score" numeric, "total_score" numeric, "completed_items" integer, "total_items" integer, "rank" integer, "grade" "text", "payout_rate" numeric, "kpi_version_label" "text", "org_version_label" "text", "effective_from" "date", "effective_to" "date", "membership_from" "date")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with selected_org as (
    select ov.*
      from public.org_versions ov
     where ov.status = 'PUBLISHED'
       and ov.deleted_at is null
       and ov.effective_from <= p_as_of
     order by
       (ov.effective_to is null or p_as_of < ov.effective_to) desc,
       case when ov.effective_to is null or p_as_of < ov.effective_to
         then ov.effective_from end desc,
       case when ov.effective_to is not null and ov.effective_to <= p_as_of
         then ov.effective_to end desc,
       ov.created_at desc
     limit 1
  ), selected_version as (
    select kv.*, ov.label as org_label, ov.effective_from as org_from, ov.effective_to as org_to
      from public.kpi_versions kv
      join selected_org ov on ov.id = kv.org_version_id
     where kv.status in ('PUBLISHED','CLOSED') and kv.deleted_at is null
  ), membership as (
    select dm.department_id, dm.effective_from
      from public.dept_members dm
      join selected_version sv on sv.org_version_id = dm.version_id
     where dm.user_id = app.current_app_user_id()
       and dm.deleted_at is null
       and dm.effective_from <= p_as_of
       and (dm.effective_to is null or p_as_of < dm.effective_to)
     order by dm.effective_from desc
     limit 1
  )
  select a.subject_type, a.id, t.name,
         case when a.subject_type = 'PERSON' then u.name else d.name end,
         i.id, i.metric_code, i.metric_name, i.description, i.criteria_text, i.unit,
         i.target_mode, i.rule_type, i.rule_params,
         coalesce(nullif(a.target_overrides->>i.metric_code, '')::numeric, i.default_target),
         latest.actual_value, latest.qualitative_value, latest.actual_payload,
         latest.computed_score, latest.evidence_ref, i.max_score,
         r.calculated_score, r.completed_items, r.total_items, r.rank, r.grade, r.payout_rate,
         sv.label, sv.org_label, sv.org_from, sv.org_to, m.effective_from
    from selected_version sv
    left join membership m on true
    join public.kpi_assignments a
      on a.kpi_version_id = sv.id and a.deleted_at is null
     and (
       (a.subject_type = 'PERSON' and a.user_id = app.current_app_user_id())
       or (a.subject_type = 'DEPARTMENT' and a.department_id = m.department_id)
     )
    join public.kpi_templates t on t.id = a.template_id and t.deleted_at is null
    join public.kpi_template_items i on i.template_id = t.id and i.deleted_at is null
    left join public.users u on u.id = a.user_id
    left join public.departments d on d.id = a.department_id
    left join lateral (
      select ar.* from public.kpi_actual_revisions ar
       where ar.assignment_id = a.id and ar.template_item_id = i.id
       order by ar.revision_no desc limit 1
    ) latest on true
    left join public.kpi_results r on r.assignment_id = a.id and r.deleted_at is null
   order by case when a.subject_type = 'PERSON' then 0 else 1 end, t.name, i.sort_order
$$;


ALTER FUNCTION "public"."my_kpi_dashboard"("p_as_of" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_network_entities"("p_keyword" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 30, "p_offset" integer DEFAULT 0, "p_categories" "text"[] DEFAULT NULL::"text"[], "p_uncategorized" boolean DEFAULT NULL::boolean, "p_region_scope" "text"[] DEFAULT NULL::"text"[], "p_regions" "uuid"[] DEFAULT NULL::"uuid"[], "p_countries" "uuid"[] DEFAULT NULL::"uuid"[], "p_country_unset" boolean DEFAULT NULL::boolean, "p_search_email" boolean DEFAULT false, "p_search_phone" boolean DEFAULT false, "p_expertise" "text"[] DEFAULT NULL::"text"[], "p_match" "text" DEFAULT NULL::"text", "p_activity_min" integer DEFAULT NULL::integer, "p_activity_max" integer DEFAULT NULL::integer, "p_satisfaction_min" numeric DEFAULT NULL::numeric, "p_satisfaction_max" numeric DEFAULT NULL::numeric) RETURNS TABLE("id" "uuid", "name" "text", "affiliation" "text", "email" "text", "phone" "text", "linkedin_url" "text", "category" "text", "region_scope" "text", "region_tag_id" "uuid", "country_tag_id" "uuid", "region_name" "text", "country_name" "text", "profile" "jsonb", "expertise" "jsonb", "is_provisional" boolean, "created_by" "uuid", "creator_name" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "last_action" "text", "last_contributed_at" timestamp with time zone, "activity_count" bigint, "satisfaction_avg" numeric, "total_count" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  with mine as (
    select
      c.entity_id,
      max(c.created_at) as last_at,
      (array_agg(c.action order by c.created_at desc))[1] as last_action
    from public.entity_contributions c
    where c.user_id = app.current_app_user_id()
      and c.entity_table = 'networks'
    group by c.entity_id
  ),
  m as (
    select * from public.network_entity_metrics()
  ),
  filtered as (
    select d.*,
           ct.region_tag_id as ct_region_tag_id,
           ct.name          as ct_country_name,
           coalesce(mc.last_action, 'created') as l_action,
           coalesce(mc.last_at, d.created_at)  as l_at,
           coalesce(mm.activity_count, 0)::bigint as act,
           mm.satisfaction_avg as sat
      from public.networks d
      left join public.country_tags ct on ct.id = d.country_tag_id
      left join mine mc on mc.entity_id = d.id
      left join m mm on mm.entity_id = d.id
     where d.deleted_at is null
       and d.merged_into_id is null
       -- 생성자이거나 기여자면 내 것으로 본다.
       and (d.created_by = app.current_app_user_id() or mc.entity_id is not null)
       -- 구분과 미지정은 한 축이다(OR). 목록 필터에서 '미지정'이 구분 선택지 옆에 서므로
       -- '투자사 또는 미지정'이 표현돼야 한다 — 종전처럼 두 조건을 AND로 묶으면 그 조합은
       -- 늘 0건이 되고, 결과가 빈 이유가 화면 어디에도 보이지 않는다.
       and (case
              when (p_categories is null or cardinality(p_categories) = 0)
                   and p_uncategorized is null then true
              when (p_categories is null or cardinality(p_categories) = 0)
                then (p_uncategorized and d.category is null)
                     or (not p_uncategorized and d.category is not null)
              else d.category = any(p_categories)
                   or (coalesce(p_uncategorized, false) and d.category is null)
            end)
       and (p_region_scope is null or cardinality(p_region_scope) = 0
            or d.region_scope = any(p_region_scope))
       and (p_regions is null or cardinality(p_regions) = 0 or ct.region_tag_id = any(p_regions))
       and (p_countries is null or cardinality(p_countries) = 0 or d.country_tag_id = any(p_countries))
       and (p_country_unset is null
            or (p_country_unset and d.country_tag_id is null)
            or (not p_country_unset and d.country_tag_id is not null))
       and (p_keyword is null or btrim(p_keyword) = ''
            or d.name ilike '%' || btrim(p_keyword) || '%'
            or d.affiliation ilike '%' || btrim(p_keyword) || '%'
            or (p_search_email and d.email ilike '%' || btrim(p_keyword) || '%')
            or (p_search_phone and d.phone ilike '%' || btrim(p_keyword) || '%'))
       and (p_expertise is null or cardinality(p_expertise) = 0 or d.expertise ?| p_expertise)
       and (p_match is null
            or (p_match = 'possible'
                and coalesce(nullif(d.profile ->> 'match_available', ''), 'true') in ('true', 'available'))
            or (p_match = 'impossible'
                and coalesce(nullif(d.profile ->> 'match_available', ''), 'true') not in ('true', 'available')))
       and (p_activity_min is null or coalesce(mm.activity_count, 0) >= p_activity_min)
       and (p_activity_max is null or coalesce(mm.activity_count, 0) <= p_activity_max)
       and (p_satisfaction_min is null or mm.satisfaction_avg >= p_satisfaction_min)
       and (p_satisfaction_max is null or mm.satisfaction_avg <= p_satisfaction_max)
  )
  select
    f.id, f.name, f.affiliation, f.email, f.phone, f.linkedin_url,
    f.category, f.region_scope,
    f.ct_region_tag_id as region_tag_id,
    f.country_tag_id,
    r.name as region_name,
    f.ct_country_name as country_name,
    f.profile, f.expertise, f.is_provisional,
    f.created_by, u.name as creator_name, f.created_at, f.updated_at,
    f.l_action as last_action,
    f.l_at     as last_contributed_at,
    f.act, f.sat,
    count(*) over () as total_count
  from filtered f
  left join public.users u       on u.id = f.created_by
  left join public.region_tags r on r.id = f.ct_region_tag_id
  order by f.l_at desc, f.name asc
  limit greatest(p_limit, 0)
  offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."my_network_entities"("p_keyword" "text", "p_limit" integer, "p_offset" integer, "p_categories" "text"[], "p_uncategorized" boolean, "p_region_scope" "text"[], "p_regions" "uuid"[], "p_countries" "uuid"[], "p_country_unset" boolean, "p_search_email" boolean, "p_search_phone" boolean, "p_expertise" "text"[], "p_match" "text", "p_activity_min" integer, "p_activity_max" integer, "p_satisfaction_min" numeric, "p_satisfaction_max" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."my_network_entities"("p_keyword" "text", "p_limit" integer, "p_offset" integer, "p_categories" "text"[], "p_uncategorized" boolean, "p_region_scope" "text"[], "p_regions" "uuid"[], "p_countries" "uuid"[], "p_country_unset" boolean, "p_search_email" boolean, "p_search_phone" boolean, "p_expertise" "text"[], "p_match" "text", "p_activity_min" integer, "p_activity_max" integer, "p_satisfaction_min" numeric, "p_satisfaction_max" numeric) IS '호출자가 생성자이거나 기여자인 NETWORKS 통합 목록. all_network_entities와 인자·반환 열 규약이 같고 범위와 정렬(최근 기여순)만 다르다.';



CREATE OR REPLACE FUNCTION "public"."network_entity_metrics"() RETURNS TABLE("entity_id" "uuid", "activity_count" bigint, "satisfaction_avg" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
  select pp.master_id as entity_id,
         count(distinct pp.program_id) as activity_count,
         -- 만족도의 근거 원장(mentor_satisfaction_records)은 20260903150000에서 걷혔다.
         -- 멘토링을 다시 설계할 때 이 자리를 다시 채운다. 그때까지 목록은 '-'로 표기한다.
         null::numeric as satisfaction_avg
    from public.program_participants pp
   where pp.master_id is not null
     -- 권한 게이트: NETWORKS 열람 권한이 없으면 0행(집계값이 목록으로 새어 나가지 않는다).
     and app.can_read_workspace('networks')
   group by pp.master_id;
$$;


ALTER FUNCTION "public"."network_entity_metrics"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."network_entity_metrics"() IS 'NETWORKS 인물의 활동(참여 사업 수) 집계. 만족도는 근거 원장이 걷혀(20260903150000) null이며 멘토링 재설계 때 되살린다. AC 원장을 우회 집계하므로 SECURITY DEFINER이며 함수 내부에서 networks 읽기 권한을 검사한다.';



CREATE OR REPLACE FUNCTION "public"."network_facet_counts"("p_scope" "text", "p_keyword" "text" DEFAULT NULL::"text", "p_categories" "text"[] DEFAULT NULL::"text"[], "p_uncategorized" boolean DEFAULT NULL::boolean, "p_regions" "uuid"[] DEFAULT NULL::"uuid"[], "p_countries" "uuid"[] DEFAULT NULL::"uuid"[], "p_search_email" boolean DEFAULT false, "p_search_phone" boolean DEFAULT false, "p_expertise" "text"[] DEFAULT NULL::"text"[], "p_match" "text" DEFAULT NULL::"text", "p_activity_min" integer DEFAULT NULL::integer, "p_activity_max" integer DEFAULT NULL::integer, "p_country_unset" boolean DEFAULT NULL::boolean) RETURNS TABLE("axis" "text", "key" "text", "cnt" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  -- 호출자가 준 문자열로 함수 이름을 만들지 않는다 — 두 값 중 하나로 고정한다.
  target text := case p_scope when 'mine' then 'my_network_entities' else 'all_network_entities' end;
  -- 목록 RPC는 페이지 함수라 limit이 필수다. 집계에서는 자르지 않는다.
  no_limit constant integer := 2147483647;
begin
  -- 구분 축 — 구분 조건(p_categories·p_uncategorized)을 빼고 센다.
  -- 국가 조건은 둘 다 남긴다(p_countries·p_country_unset).
  -- 구분이 비어 있는 행은 목록 필터와 같은 키('UNSET')로 모은다.
  return query execute format($q$
    select 'category'::text,
           coalesce(e.category, 'UNSET')::text,
           count(*)::bigint
      from public.%I($1, $2, 0,
                     null::text[], null::boolean, null::text[],
                     $3, $4, $5,
                     $6, $7, $8, $9, $10, $11) e
     group by 2
  $q$, target)
  using p_keyword, no_limit, p_regions, p_countries, p_country_unset,
        p_search_email, p_search_phone, p_expertise, p_match,
        p_activity_min, p_activity_max;

  -- 권역 축 — 이 축 자신의 조건을 빼고 센다: 권역 목록(p_regions)과 '미지정'(p_country_unset).
  -- 국가 목록은 남긴다: 국가는 권역의 아래 단이라, 국가를 골라 둔 채 권역 칸을 보면 그
  -- 국가가 속한 권역만 서는 것이 사실이다.
  -- 권역이 비어 있는 행(국가를 아직 모르는 행)은 'UNSET'으로 모은다.
  return query execute format($q$
    select 'region'::text,
           coalesce(e.region_tag_id::text, 'UNSET'),
           count(*)::bigint
      from public.%I($1, $2, 0,
                     $3, $4, null::text[],
                     null::uuid[], $5, null::boolean,
                     $6, $7, $8, $9, $10, $11) e
     group by 2
  $q$, target)
  using p_keyword, no_limit, p_categories, p_uncategorized, p_countries,
        p_search_email, p_search_phone, p_expertise, p_match,
        p_activity_min, p_activity_max;
end;
$_$;


ALTER FUNCTION "public"."network_facet_counts"("p_scope" "text", "p_keyword" "text", "p_categories" "text"[], "p_uncategorized" boolean, "p_regions" "uuid"[], "p_countries" "uuid"[], "p_search_email" boolean, "p_search_phone" boolean, "p_expertise" "text"[], "p_match" "text", "p_activity_min" integer, "p_activity_max" integer, "p_country_unset" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."network_facet_counts"("p_scope" "text", "p_keyword" "text", "p_categories" "text"[], "p_uncategorized" boolean, "p_regions" "uuid"[], "p_countries" "uuid"[], "p_search_email" boolean, "p_search_phone" boolean, "p_expertise" "text"[], "p_match" "text", "p_activity_min" integer, "p_activity_max" integer, "p_country_unset" boolean) IS 'NETWORKS 목록 요약 카드(구분·권역) 집계. 목록 RPC(my_/all_network_entities)를 그대로 호출해 묶으므로 필터 판정이 목록과 어긋나지 않는다. 각 축은 자기 조건을 빼고 세어 타일이 필터로 동작한다 — 권역 축은 자기 조건에 p_regions와 p_country_unset(미지정 칸)이 함께 든다. 구분·권역이 비어 있는 행의 키는 ''UNSET''. SECURITY INVOKER — public.networks의 RLS를 그대로 따른다.';



CREATE OR REPLACE FUNCTION "public"."open_program_guest_access"("p_participant_ids" "uuid"[]) RETURNS TABLE("participant_id" "uuid", "program_code" "text", "target_name" "text", "email" "text", "phone" "text", "account_is_new" boolean)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_uid       uuid := app.current_app_user_id();
  r           record;
  v_prog      jsonb;
  v_ws        text;
  v_code      text;
  v_status    text;
  v_name      text;
  v_email     text;
  v_phone     text;
  v_company   uuid;
  v_account   uuid;
  v_table     text;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.' using errcode = '42501';
  end if;
  if p_participant_ids is null or array_length(p_participant_ids, 1) is null then
    return;
  end if;

  for r in
    select pp.id, pp.program_id, pp.master_table, pp.master_id, pp.login_status, pp.user_id
      from public.program_participants pp
     where pp.id = any (p_participant_ids)
  loop
    v_prog   := app.program_row(r.program_id);
    v_ws     := app.program_ws(r.program_id);
    v_code   := v_prog ->> 'code';
    v_status := v_prog ->> 'status';

    if not app.is_program_manager(r.program_id) then
      raise exception '담당자(PM·MEMBER·운용역)만 게스트 로그인을 열 수 있습니다.' using errcode = '42501';
    end if;
    -- 죽은 상태의 값은 원장마다 다르다(사업 = 종료·취소, 조합 = 해산). 한 목록으로 뭉치면
    -- 청산 중(LIQUIDATING) 조합의 문이 열리지 않거나 반대로 멀쩡한 사업이 막힌다.
    if (v_ws = 'fund' and v_status = 'CLOSED')
       or (v_ws is distinct from 'fund' and v_status in ('FINISHED', 'CANCELLED')) then
      raise exception '종료된 사업·해산된 조합은 로그인을 열 수 없습니다.' using errcode = '22023';
    end if;

    -- 원장 참조는 더 이상 요구하지 않는다(연결은 선택이다). 요구하는 것은 계정이다.
    if r.user_id is null then
      raise exception '계정이 연결되지 않은 참가자입니다. 통합 GUEST 메뉴에서 계정을 만든 뒤 명부에 담으십시오.'
        using errcode = '22023';
    end if;

    v_account := r.user_id;

    select u.name, u.email, u.phone, u.company_id
      into v_name, v_email, v_phone, v_company
      from public.users u
     where u.id = v_account
       and u.deleted_at is null
       and u.is_active
       and app.is_guest_user_type(u.user_type);

    if not found then
      raise exception '살아 있는 GUEST 계정이 아닙니다. 계정 상태를 먼저 확인하십시오.'
        using errcode = '22023';
    end if;

    -- 초대 레코드는 명부 행당 1건. 사업코드는 로그인 요소가 아니라 안내·식별용으로 남는다.
    update public.guest_invitations
       set business_code     = v_code,
           name              = v_name,
           email             = v_email,
           phone             = v_phone,
           company_id        = v_company,
           app_user_id       = v_account,
           target_type       = 'PROGRAM',
           target_id         = r.program_id,
           invite_expires_at = now() + interval '1 year',
           otp_hash          = null,
           otp_expires_at    = null,
           otp_attempts      = 0
     where guest_invitations.participant_id = r.id;

    if not found then
      insert into public.guest_invitations
        (business_code, name, email, phone, invited_user_type, company_id,
         app_user_id, target_type, target_id, participant_id, created_by, invite_expires_at)
      select v_code, v_name, v_email, v_phone, u.user_type, v_company,
             v_account, 'PROGRAM', r.program_id, r.id, v_uid, now() + interval '1 year'
        from public.users u where u.id = v_account;
    end if;

    -- 이 맥락에 아직 기간이 없으면 기본값을 채운다. 원장이 셋이라 표 이름을 판정해 동적으로
    -- 쓴다. INVOKER라 여기서도 원장의 RLS가 걸리며, 바로 위에서 담당자임을 확인했으므로 통과한다.
    v_table := case v_ws
                 when 'project' then 'programs'
                 when 'mna'     then 'ma_programs'
                 when 'fund'    then 'funds'
               end;
    if v_table is not null and (v_prog ->> 'guest_access_ends_at') is null then
      execute format(
        'update public.%I set guest_access_ends_at = $2, updated_at = now()'
        || ' where id = $1 and guest_access_ends_at is null', v_table)
        using r.program_id, app.default_access_end(r.program_id);
    end if;

    -- user_id는 값이 그대로다(위에서 not null을 확인했다) — 배정 가드는 지나간다.
    update public.program_participants pp
       set user_id         = coalesce(pp.user_id, v_account),
           login_status    = case when pp.login_status = 'ACTIVE' then 'ACTIVE'::public.participant_login_status
                                  else 'INVITED'::public.participant_login_status end,
           invited_at      = coalesce(pp.invited_at, now()),
           login_opened_by = v_uid,
           login_opened_at = now(),
           updated_at      = now()
     where pp.id = r.id;

    perform app.log_guest_access(
      v_account,
      'GUEST_ACCESS_OPEN',
      'guest:login',
      jsonb_build_object('participant_id', r.id, 'program_id', r.program_id,
                         'workspace', v_ws,
                         'master_table', r.master_table, 'master_id', r.master_id,
                         'account_is_new', false),
      null
    );

    participant_id := r.id;
    program_code   := v_code;
    target_name    := v_name;
    email          := v_email;
    phone          := v_phone;
    account_is_new := false;
    return next;
  end loop;
end;
$_$;


ALTER FUNCTION "public"."open_program_guest_access"("p_participant_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."open_program_guest_access"("p_participant_ids" "uuid"[]) IS '명부 행의 게스트 로그인을 연다(그 사업·조합 담당자 전용, SECURITY INVOKER). PROJECT·M&A·FUND 담당자가 각자의 워크스페이스 권한만으로 끝까지 연다. 원장 연결이 없는 줄도 열 수 있으나 **계정을 만들지는 않는다** — 계정이 없는 줄은 거절하며 발급은 통합 GUEST 메뉴가 맡는다(2026-09-13). account_is_new는 항상 false다.';



CREATE OR REPLACE FUNCTION "public"."prepare_meeting_recording_segment"("p_segment_id" "uuid", "p_recording_id" "uuid", "p_segment_no" integer, "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_duration_ms" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if not app.can_write_recording(p_recording_id) then
    raise exception '녹음 구간을 저장할 권한이 없습니다.' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.meeting_recordings
     where id = p_recording_id and status = 'RECORDING' and deleted_at is null
  ) then
    raise exception '녹음 중인 세션이 아닙니다.' using errcode = '22023';
  end if;
  -- CASE는 괄호로 감싼다. plpgsql은 IF 조건을 첫 THEN에서 끊으므로 괄호가 없으면 42601이다.
  if p_storage_path <> p_recording_id::text || '/' || p_segment_id::text ||
      (case p_mime_type
        when 'audio/webm' then '.webm'
        when 'audio/mp4' then '.m4a'
        when 'audio/ogg' then '.ogg'
        when 'audio/wav' then '.wav'
        when 'audio/mpeg' then '.mp3'
        when 'audio/mp3' then '.mp3'
        when 'audio/x-m4a' then '.m4a'
        when 'audio/aac' then '.aac'
      end) then
    raise exception '스토리지 경로가 올바르지 않습니다.' using errcode = '22023';
  end if;

  insert into public.meeting_recording_segments (
    id, recording_id, segment_no, storage_path, file_name, mime_type, byte_size, duration_ms
  ) values (
    p_segment_id, p_recording_id, p_segment_no, p_storage_path,
    left(trim(p_file_name), 180), p_mime_type, p_byte_size, p_duration_ms
  )
  on conflict (id) do nothing;

  update public.meeting_recordings
     set last_activity_at = now(), updated_at = now()
   where id = p_recording_id;
end;
$$;


ALTER FUNCTION "public"."prepare_meeting_recording_segment"("p_segment_id" "uuid", "p_recording_id" "uuid", "p_segment_no" integer, "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_duration_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."program_module_delete_blockers"("p_entity_key" "text", "p_module_id" "uuid") RETURNS TABLE("rel_name" "text", "row_count" bigint, "blocking" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_module   text;
  v_managers text;
  v_timeline text;
  v_ws       text := app.entity_key_workspace(p_entity_key);
  v_program  uuid;
  r          record;
  r2         record;
  c          bigint;
begin
  select t.module_table, t.managers_table, t.timeline_table
    into v_module, v_managers, v_timeline
    from app.ws_module_tables(p_entity_key) t;
  if v_module is null then
    raise exception '알 수 없는 사업 원장입니다.' using errcode = '22023';
  end if;

  -- entity_key를 함께 건다. id로만 찾으면 다른 워크스페이스의 모듈이 자기 키로 걸린다.
  execute format('select program_id from public.%I where id = $1 and entity_key = $2', v_module)
    into v_program using p_module_id, p_entity_key;
  if v_program is null then
    return; -- 이미 없는 모듈. 막을 것도 알릴 것도 없다.
  end if;

  -- 인가: 이 사업을 볼 수 있는 사람만 잔존 건수를 볼 수 있다(건수도 업무 정보다).
  if not (app.can_read_workspace(v_ws) and app.can_access_ws_program(v_ws, v_program)) then
    raise exception '이 사업의 모듈을 조회할 권한이 없습니다.' using errcode = '42501';
  end if;

  for r in select * from app.module_content_tables(v_module) loop
    execute format('select count(*) from public.%I where %I = $1%s',
                   r.rel_name, r.fk_col,
                   case when r.soft_delete then ' and deleted_at is null' else '' end)
      into c using p_module_id;

    if c > 0 then
      rel_name := r.rel_name;
      row_count := c;
      blocking := app.module_external_record(r.rel_name);
      return next;

      -- 부모에 행이 있을 때만 자식을 센다. 부모가 비면 자식도 비기 때문이다(FK).
      for r2 in select * from app.module_cascade_children(r.rel_name) loop
        execute format(
          'select count(*) from public.%I ch join public.%I pt on ch.%I = pt.%I where pt.%I = $1%s',
          r2.rel_name, r.rel_name, r2.fk_col, r2.parent_col, r.fk_col,
          case when r2.soft_delete then ' and ch.deleted_at is null' else '' end)
          into c using p_module_id;
        if c > 0 then
          rel_name := r2.rel_name;
          row_count := c;
          blocking := app.module_external_record(r2.rel_name);
          return next;
        end if;
      end loop;
    end if;
  end loop;

  -- 첨부는 FK 없이 program_module_id 한 컬럼으로만 귀속된다(20260803230100). 지우지 않고
  -- 귀속만 푸는 대상이라 차단하지 않는다 — 화면이 '사업 자료로 옮겨집니다'로 안내한다.
  select count(*) into c
    from public.attachments
   where program_module_id = p_module_id and deleted_at is null;
  if c > 0 then
    rel_name := 'attachments'; row_count := c; blocking := false; return next;
  end if;
end;
$_$;


ALTER FUNCTION "public"."program_module_delete_blockers"("p_entity_key" "text", "p_module_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."program_module_delete_blockers"("p_entity_key" "text", "p_module_id" "uuid") IS '모듈 삭제 시 남아 있는 데이터(원장명·건수·차단 여부). blocking=true는 밖에서 들어온 기록이라 삭제를 막고, false는 모듈과 함께 사라지므로 삭제창이 고지한다.';



CREATE OR REPLACE FUNCTION "public"."program_participant_removal_preview"("p_participant_ids" "uuid"[]) RETURNS TABLE("kind" "text", "label" "text", "n" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  r record;
begin
  if app.current_app_user_id() is null then
    raise exception '로그인이 필요합니다.' using errcode = '42501';
  end if;
  if p_participant_ids is null or array_length(p_participant_ids, 1) is null then
    return;
  end if;

  -- 미리보기도 담당자만 본다 — 건수 자체가 그 사업의 사실이다.
  for r in
    select distinct pp.program_id
      from public.program_participants pp
     where pp.id = any (p_participant_ids)
  loop
    if not app.is_program_manager(r.program_id) then
      raise exception '사업 담당자(PM·MEMBER)만 명부를 볼 수 있습니다.' using errcode = '42501';
    end if;
  end loop;

  return query
  with target as (
    select pp.user_id, pp.program_id, pp.entity_key
      from public.program_participants pp
     where pp.id = any (p_participant_ids)
       and pp.user_id is not null
  ),
  counted as (
    select '지원서'::text as label,
           count(*)::bigint as n,
           'application'::text as kind
      from public.application_submissions s
      join target t on t.user_id = s.applicant_user_id and t.program_id = s.program_id
     where s.deleted_at is null
    union all
    select 'Q&A 질문', count(*)::bigint, 'question'
      from public.program_questions q
      join target t on t.user_id = q.created_by
                   and t.program_id = q.program_id
                   and t.entity_key = q.entity_key
     where q.deleted_at is null
    union all
    select '올린 자료', count(*)::bigint, 'attachment'
      from public.attachments a
      join public.program_modules m on m.id = a.program_module_id
      join target t on t.user_id = a.uploaded_by
                   and t.program_id = m.program_id
                   and t.entity_key = m.entity_key
     where a.deleted_at is null
  )
  select c.kind, c.label, c.n from counted c where c.n > 0;
end;
$$;


ALTER FUNCTION "public"."program_participant_removal_preview"("p_participant_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."program_participant_removal_preview"("p_participant_ids" "uuid"[]) IS '명부 행을 뺐을 때 남는 기록의 건수(지원서·질문·자료). 삭제창이 미리 밝히는 용도이며 담당자 전용.';



CREATE OR REPLACE FUNCTION "public"."promote_to_invested"("p_startup_id" "uuid", "p_lead_user_id" "uuid", "p_support_user_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_pool_status" "text" DEFAULT NULL::"text", "p_stage" "text" DEFAULT NULL::"text", "p_closed_on" "date" DEFAULT NULL::"date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid         uuid := app.current_app_user_id();
  v_is_invested boolean;
  v_support     uuid;
  v_support_ids uuid[];
begin
  if v_uid is null then
    raise exception 'unauthorized' using errcode = '42501';
  end if;
  if p_lead_user_id is null then
    raise exception 'lead_required' using errcode = '23514';
  end if;
  select coalesce(array_agg(distinct u.support_id), '{}'::uuid[])
    into v_support_ids
    from unnest(coalesce(p_support_user_ids, '{}'::uuid[])) as u(support_id)
   where u.support_id is not null
     and u.support_id <> p_lead_user_id;

  select (management_status = 'invested')
    into v_is_invested
    from public.startups
   where id = p_startup_id and deleted_at is null;
  if not found then
    raise exception 'startup_not_found' using errcode = 'P0002';
  end if;

  if v_is_invested then
    -- 이미 투자기업이면 관리 주체(딜메이커 또는 자사 투자 펀드의 관리인력)만 담당·현황을 고친다.
    if not (app.is_admin() or app.can_manage_invested_startup(p_startup_id, v_uid)) then
      raise exception 'forbidden' using errcode = '42501';
    end if;
  else
    if not (
      app.is_admin()
      or exists (
        select 1
          from public.investments i
         where i.startup_id = p_startup_id
           and i.is_own_investment
           and i.deleted_at is null
           and app.can_access_fund(i.fund_id)
      )
    ) then
      raise exception 'investment_required' using errcode = '42501';
    end if;
  end if;

  update public.startup_managers set is_lead = false where startup_id = p_startup_id;

  insert into public.startup_managers (startup_id, user_id, is_lead, assigned_by)
    values (p_startup_id, p_lead_user_id, true, v_uid)
  on conflict (startup_id, user_id)
    do update set is_lead = true, assigned_by = v_uid;

  foreach v_support in array v_support_ids
  loop
    insert into public.startup_managers (startup_id, user_id, is_lead, assigned_by)
      values (p_startup_id, v_support, false, v_uid)
    on conflict (startup_id, user_id)
      do update set is_lead = false, assigned_by = v_uid;
  end loop;

  delete from public.startup_managers m
   where m.startup_id = p_startup_id
     and not m.is_lead
     and m.user_id <> all (v_support_ids);

  update public.startups
     set management_status = 'invested',
         pool_status = coalesce(p_pool_status, pool_status),
         stage       = coalesce(p_stage, stage),
         closed_on   = case
                         when coalesce(p_pool_status, pool_status) = '폐업' then p_closed_on
                         else null
                       end
   where id = p_startup_id;
end;
$$;


ALTER FUNCTION "public"."promote_to_invested"("p_startup_id" "uuid", "p_lead_user_id" "uuid", "p_support_user_ids" "uuid"[], "p_pool_status" "text", "p_stage" "text", "p_closed_on" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."promote_to_invested"("p_startup_id" "uuid", "p_lead_user_id" "uuid", "p_support_user_ids" "uuid"[], "p_pool_status" "text", "p_stage" "text", "p_closed_on" "date") IS '스타트업을 투자기업으로 승격하고 딜메이커(정 1 + 부 N)·관리현황·단계를 동기화한다. 신규 승격은 자사 투자 집행이 근거이고, 이미 투자기업인 행은 관리 주체(app.can_manage_invested_startup)만 고친다.';



