CREATE OR REPLACE FUNCTION "public"."reassign_entity"("p_from" "text", "p_to" "text", "p_id" "uuid", "p_values" "jsonb", "p_source" "text" DEFAULT 'manual'::"text", "p_batch_id" "uuid" DEFAULT NULL::"uuid", "p_target_action" "text" DEFAULT NULL::"text", "p_note_target" "text" DEFAULT NULL::"text", "p_note_source" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_new_id uuid;
  v_rows   integer;
begin
  if not app.has_contribution_trigger(p_from) or not app.has_contribution_trigger(p_to) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  if p_from = p_to then
    raise exception 'same_entity' using errcode = '22023';
  end if;
  if p_source not in ('manual', 'upload') then
    raise exception 'invalid_source' using errcode = '22023';
  end if;

  -- 대상 등록. 컨텍스트는 문장 단위로 갈아 끼운다(AFTER 트리거는 각 문장 끝에 돈다).
  perform set_config('app.contribution_ctx',
                     jsonb_build_object(
                       'source', p_source,
                       'batch_id', p_batch_id,
                       'action', p_target_action,
                       'note', p_note_target
                     )::text,
                     true);
  v_new_id := app.insert_entity_row(p_to, p_values);

  -- 원본 비활성화. 이관은 '옮긴 것'이므로 사유를 남겨 단순 폐기와 구분한다.
  perform set_config('app.contribution_ctx',
                     jsonb_build_object(
                       'source', p_source,
                       'batch_id', p_batch_id,
                       'note', coalesce(p_note_source, '구분 변경 이관')
                     )::text,
                     true);
  execute format(
    'update public.%I set deleted_at = now() where id = $1 and deleted_at is null',
    p_from
  ) using p_id;
  get diagnostics v_rows = row_count;

  if v_rows = 0 then
    raise exception 'not_found_or_forbidden' using errcode = '42501';
  end if;

  return v_new_id;
end $_$;


ALTER FUNCTION "public"."reassign_entity"("p_from" "text", "p_to" "text", "p_id" "uuid", "p_values" "jsonb", "p_source" "text", "p_batch_id" "uuid", "p_target_action" "text", "p_note_target" "text", "p_note_source" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reassign_entity"("p_from" "text", "p_to" "text", "p_id" "uuid", "p_values" "jsonb", "p_source" "text", "p_batch_id" "uuid", "p_target_action" "text", "p_note_target" "text", "p_note_source" "text") IS '구분 이관: 대상 원장 등록 + 원본 비활성화를 한 트랜잭션으로. 수동 이관과 업로드 재분류 공용. SECURITY INVOKER — 쓰기 권한은 각 원장 RLS가 판정한다.';



CREATE OR REPLACE FUNCTION "public"."recall_approval_decision"("p_line_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid          uuid := app.current_app_user_id();
  v_doc          uuid;
  v_line_round   integer;
  v_round        integer;
  v_approver     uuid;
  v_decision     public.approval_decision;
  v_status       public.approval_status;
  v_latest_line  uuid;
  v_next_round   integer;
  v_has_approved boolean;
  v_notify       uuid[];
  v_allocates    boolean;
begin
  if v_uid is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  select l.document_id, l.round, l.approver_id, l.decision, d.status
    into v_doc, v_line_round, v_approver, v_decision, v_status
    from public.approval_lines l
    join public.approval_documents d on d.id = l.document_id
   where l.id = p_line_id
     and d.deleted_at is null
   for update of l, d;

  if not found then
    raise exception 'approval line not found' using errcode = 'P0002';
  end if;
  if v_approver is distinct from v_uid then
    raise exception 'only the assigned approver may recall a decision' using errcode = '42501';
  end if;
  if v_decision <> 'APPROVED' then
    raise exception 'only an approved decision may be recalled' using errcode = '42501';
  end if;

  v_round := app.approval_current_round(v_doc);
  if v_line_round <> v_round then
    raise exception 'this line belongs to an earlier round' using errcode = '42501';
  end if;

  if v_status in ('PENDING', 'IN_REVIEW') then
    if not exists (
      select 1 from public.approval_lines
       where document_id = v_doc and round = v_round and decision = 'PENDING'
    ) then
      raise exception 'no later decision remains' using errcode = '42501';
    end if;

    update public.approval_lines
       set decision = 'PENDING',
           decided_at = null,
           comment = null
     where id = p_line_id;

    select exists (
      select 1 from public.approval_lines
       where document_id = v_doc and round = v_round and decision = 'APPROVED'
    ) into v_has_approved;

    update public.approval_documents
       set status = case when v_has_approved
                           then 'IN_REVIEW'::public.approval_status
                         else 'PENDING'::public.approval_status
                    end,
           completed_at = null,
           updated_at = now()
     where id = v_doc;

    insert into public.approval_document_events (
      document_id, source_system, event_type, actor_user_id,
      comment_snapshot, occurred_at, source_payload
    ) values (
      v_doc, 'NATIVE', 'APPROVAL_WITHDRAWN', v_uid,
      nullif(btrim(p_reason), ''), now(), jsonb_build_object('line_id', p_line_id, 'round', v_round)
    );

    select array_agg(drafter_id) into v_notify
      from public.approval_documents where id = v_doc and drafter_id is not null;
    perform app.notify_approval(v_doc, v_notify, 'approval_withdrawn', v_uid);
    return 'WITHDRAWN';
  end if;

  if v_status <> 'APPROVED' then
    raise exception 'document is not recallable' using errcode = '42501';
  end if;

  select l.id into v_latest_line
    from public.approval_lines l
   where l.document_id = v_doc
     and l.round = v_round
     and l.decision = 'APPROVED'
   order by l.decided_at desc nulls last, l.id desc
   limit 1;
  if v_latest_line is distinct from p_line_id then
    raise exception 'only the final approver may reset the document' using errcode = '42501';
  end if;

  if nullif(btrim(p_reason), '') is null then
    raise exception 'a reason is required for final approval reset' using errcode = '22023';
  end if;

  -- 최종 승인을 되돌리는 것은 배정을 걷는 일이다. 이 품의를 근거로 하는 지출이 살아 있으면
  -- 먼저 그쪽을 정리해야 한다 — 순서를 뒤집으면 지출이 가리킬 배정이 사라진 채 남는다.
  perform app.assert_no_active_budget_children(v_doc);

  -- 최종 승인 취소는 완료 회차를 고쳐 쓰지 않는다. 결재선 전체를 새 회차로 복제해
  -- 과거 도장과 시각은 그대로 남기고 다음 재상신이 처음 사람부터 시작되게 한다.
  v_next_round := app.clone_approval_full_round(v_doc);

  update public.approval_documents
     set status = 'REJECTED'::public.approval_status,
         completed_at = now(),
         updated_at = now()
   where id = v_doc;

  insert into public.approval_document_events (
    document_id, source_system, event_type, actor_user_id,
    comment_snapshot, occurred_at, source_payload
  ) values (
    v_doc, 'NATIVE', 'FINAL_APPROVAL_RESET', v_uid,
    nullif(btrim(p_reason), ''), now(),
    jsonb_build_object('line_id', p_line_id, 'previous_round', v_round, 'next_round', v_next_round)
  );

  -- 배정 품의의 승인 취소는 되돌리기 어려운 금전 사실(배정 회수)이라 감사 원장에 남긴다.
  -- 되돌아온 금액은 최초 금액이 아니라 **그 순간 유효했던 예산표의 합계**다.
  select exists (
    select 1
      from public.approval_form_versions v
      cross join lateral app.approval_budget_keys(v.fields) k
     where v.id = (select form_version_id from public.approval_documents where id = v_doc)
  ) into v_allocates;

  if coalesce(v_allocates, false) then
    insert into public.audit_logs (actor_user_id, action, changed_workspace, before_data, reason)
    select v_uid, 'APPROVAL_BUDGET_ALLOCATION_RESET', 'management',
           jsonb_build_object(
             'document_id', v_doc,
             'doc_no', d.doc_no,
             'budget_total', (
               select sum(b.amount)
                 from app.approval_budget_lines(v.fields, d.field_values) b
             ),
             'workspace_links', (
               select jsonb_agg(jsonb_build_object('target_type', l.target_type,
                                                   'target_id', l.target_id))
                 from public.approval_program_links l
                where l.document_id = v_doc and l.deleted_at is null
             )
           ),
           nullif(btrim(p_reason), '')
      from public.approval_documents d
      join public.approval_form_versions v on v.id = d.form_version_id
     where d.id = v_doc;
  end if;

  select array_agg(drafter_id) into v_notify
    from public.approval_documents where id = v_doc and drafter_id is not null;
  perform app.notify_approval(v_doc, v_notify, 'approval_final_reset', v_uid);
  return 'RESET';
end;
$$;


ALTER FUNCTION "public"."recall_approval_decision"("p_line_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recall_approval_decision"("p_line_id" "uuid", "p_reason" "text") IS '미결 결재가 남은 진행 중 문서에서 본인 승인을 취소한다. 완료 문서는 실제 마지막 승인자가 전체 결재선을 초기화해 기안자에게 반려하며, 배정 품의라면 살아 있는 지출이 없어야 하고 회수 사실을 audit_logs에 남긴다.';



CREATE OR REPLACE FUNCTION "public"."register_trade_partner_quick"("p_name" "text", "p_partner_type" "text", "p_registration_no" "text", "p_bank_code" "text", "p_account_no" "text", "p_account_holder" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid uuid := app.current_app_user_id();
  v_id  uuid;
begin
  if v_uid is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;
  -- 내부 임직원만. 게스트는 결재를 쓰지 않으므로 여기에 닿을 이유가 없다.
  if not app.is_internal_user() then
    raise exception 'internal users only' using errcode = '42501';
  end if;
  if nullif(btrim(coalesce(p_name, '')), '') is null then
    raise exception '거래처명을 입력하세요.' using errcode = '22023';
  end if;

  insert into public.trade_partners
    (code_prefix, code_seq, name, partner_type, registration_no,
     bank_code, account_no, account_holder, is_active)
  values ('YN', 1, btrim(p_name), coalesce(nullif(btrim(p_partner_type), ''), 'CORPORATE'),
          nullif(btrim(coalesce(p_registration_no, '')), ''),
          nullif(btrim(coalesce(p_bank_code, '')), ''),
          nullif(btrim(coalesce(p_account_no, '')), ''),
          nullif(btrim(coalesce(p_account_holder, '')), ''),
          true)
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."register_trade_partner_quick"("p_name" "text", "p_partner_type" "text", "p_registration_no" "text", "p_bank_code" "text", "p_account_no" "text", "p_account_holder" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."register_trade_partner_quick"("p_name" "text", "p_partner_type" "text", "p_registration_no" "text", "p_bank_code" "text", "p_account_no" "text", "p_account_holder" "text") IS '송금 요청 화면에서 없는 거래처를 그 자리에서 원장에 넣는다. 만들어지는 행은 언제나 "확인 전"(verified_at is null)이며 경영지원이 증빙을 보고 확인해야 딱지가 떨어진다. code_seq는 인자로 받은 값이 아니라 원장 트리거가 잠금 아래에서 다시 매긴다.';



CREATE OR REPLACE FUNCTION "public"."remove_program_participants"("p_participant_ids" "uuid"[], "p_reason" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid   uuid := app.current_app_user_id();
  r       record;
  v_count integer := 0;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.' using errcode = '42501';
  end if;
  if p_participant_ids is null or array_length(p_participant_ids, 1) is null then
    return 0;
  end if;

  for r in
    select pp.id, pp.program_id, pp.user_id, pp.master_table, pp.master_id, pp.login_status
      from public.program_participants pp
     where pp.id = any (p_participant_ids)
  loop
    -- 닫기와 같은 게이트다. 담은 사람이 거둘 수 있어야 하므로 더 좁히지 않는다.
    if not app.is_program_manager(r.program_id) then
      raise exception '사업 담당자(PM·MEMBER)만 명부에서 뺄 수 있습니다.' using errcode = '42501';
    end if;

    -- 문이 사라졌는데 발급된 토큰이 살아 있으면 그 사업이 계속 열려 있다.
    -- 토큰은 계정 단위라 이 사람의 다른 사업 세션도 함께 끊긴다 — 잘게 자를 수 없다.
    if r.user_id is not null then
      update public.users
         set session_version = session_version + 1
       where id = r.user_id
         and app.is_guest_user_type(user_type);
    end if;

    -- 행이 사라지므로 감사 로그가 유일한 흔적이다. 지우기 전에 남긴다.
    perform app.log_guest_access(
      r.user_id,
      'GUEST_ACCESS_REMOVE',
      'guest:removed',
      jsonb_build_object(
        'participant_id', r.id,
        'program_id',     r.program_id,
        'master_table',   r.master_table,
        'master_id',      r.master_id,
        'login_status',   r.login_status
      ),
      p_reason
    );

    delete from public.program_participants where id = r.id;
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."remove_program_participants"("p_participant_ids" "uuid"[], "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_program_participants"("p_participant_ids" "uuid"[], "p_reason" "text") IS '게스트 명부 행을 그 사업에서 물리적으로 뺀다(담당자 전용). 계정·비밀번호·다른 사업의 줄은 그대로이며, 지원서·질문·자료 등 밖에서 들어온 기록도 지우지 않는다.';



CREATE OR REPLACE FUNCTION "public"."reopen_program_guest_access"("p_participant_ids" "uuid"[], "p_reason" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid    uuid := app.current_app_user_id();
  r        record;
  v_next   public.participant_login_status;
  v_count  integer := 0;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.' using errcode = '42501';
  end if;
  if p_participant_ids is null or array_length(p_participant_ids, 1) is null then
    return 0;
  end if;

  for r in
    select pp.id, pp.program_id, pp.user_id, pp.joined_at, pp.login_status
      from public.program_participants pp
     where pp.id = any (p_participant_ids)
  loop
    if not app.is_program_manager(r.program_id) then
      raise exception '사업 담당자(PM·MEMBER)만 차단을 해제할 수 있습니다.' using errcode = '42501';
    end if;

    -- 차단된 행만 되돌린다. 아직 열지 않은 행(NOT_ALLOWED)까지 집으면 이 함수가
    -- 안내 없이 문을 여는 경로가 된다 — 문을 여는 일은 open_program_guest_access의 몫이다.
    if r.login_status <> 'BLOCKED' then
      continue;
    end if;

    -- 되돌릴 곳은 저장돼 있지 않고 원장이 답한다: 들어와 본 적이 있으면 이용 중, 없으면 초대.
    v_next := case
                when r.joined_at is not null then 'ACTIVE'::public.participant_login_status
                else 'INVITED'::public.participant_login_status
              end;

    update public.program_participants
       set login_status = v_next,
           updated_at   = now()
     where id = r.id;

    perform app.log_guest_access(
      r.user_id,
      'GUEST_ACCESS_REOPEN',
      'guest:login',
      jsonb_build_object('participant_id', r.id, 'program_id', r.program_id,
                         'restored_to', v_next),
      p_reason
    );

    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."reopen_program_guest_access"("p_participant_ids" "uuid"[], "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reopen_program_guest_access"("p_participant_ids" "uuid"[], "p_reason" "text") IS '차단된 명부 행의 게스트 로그인을 다시 연다(그 사업 담당자 전용). 되돌릴 상태는 저장하지 않고 원장에 되묻는다 — joined_at이 있으면 ACTIVE, 없으면 INVITED. 안내를 다시 보내지 않고(그건 open_program_guest_access의 일), 세션 판도 올리지 않는다(차단 때 이미 죽였고, 올리면 그 계정의 다른 사업 세션까지 끊긴다). 접근 기간에는 손대지 않는다 — 기간은 차단과 직교한 축이다. 근거: 3_9_1 §11.3';



CREATE OR REPLACE FUNCTION "public"."reset_program_guest_password"("p_participant_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
declare
  v_uid   uuid := app.current_app_user_id();
  r       record;
  v_count integer := 0;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.' using errcode = '42501';
  end if;
  if p_participant_ids is null or array_length(p_participant_ids, 1) is null then
    return 0;
  end if;

  for r in
    select pp.id, pp.program_id
      from public.program_participants pp
     where pp.id = any (p_participant_ids)
  loop
    if not app.is_program_manager(r.program_id) then
      raise exception '사업 담당자(PM·MEMBER)만 비밀번호를 초기화할 수 있습니다.' using errcode = '42501';
    end if;

    update public.guest_invitations
       set password_hash   = null,
           password_set_at = null,
           login_attempts  = 0,
           locked_until    = null
     where guest_invitations.participant_id = r.id;

    if found then
      v_count := v_count + 1;
      perform app.log_guest_access(
        null,
        'GUEST_PASSWORD_RESET',
        'guest:password-reset',
        jsonb_build_object('participant_id', r.id, 'program_id', r.program_id),
        null
      );
    end if;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."reset_program_guest_password"("p_participant_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reset_program_guest_password"("p_participant_ids" "uuid"[]) IS '게스트 비밀번호를 초기 상태(원장 전화번호)로 되돌린다(담당자 전용, SECURITY INVOKER).';



CREATE OR REPLACE FUNCTION "public"."restore_entities"("p_entity_key" "text", "p_ids" "uuid"[], "p_reason" "text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_id    uuid;
  v_count integer := 0;
begin
  if not app.is_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if p_entity_key not in (
    'startups', 'networks', 'programs', 'ma_programs', 'ma_buyers', 'ma_sellers', 'funds'
  ) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  if coalesce(array_length(p_ids, 1), 0) = 0 then
    raise exception 'empty_selection' using errcode = '22023';
  end if;
  if cardinality(p_ids) > 100 then
    raise exception 'too_many_entities' using errcode = '22023';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'reason_required' using errcode = '23514';
  end if;

  for v_id in select distinct x from unnest(p_ids) as x
  loop
    perform public.restore_entity(p_entity_key, v_id, btrim(p_reason));
    v_count := v_count + 1;
  end loop;

  return v_count;
end $$;


ALTER FUNCTION "public"."restore_entities"("p_entity_key" "text", "p_ids" "uuid"[], "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."restore_entities"("p_entity_key" "text", "p_ids" "uuid"[], "p_reason" "text") IS 'ADMIN 비활성 원장 선택 행을 한 트랜잭션에서 복구한다(7종). 한 행이라도 단건 복구 검증에 실패하면 전체 롤백.';



CREATE OR REPLACE FUNCTION "public"."restore_entity"("p_entity_key" "text", "p_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_rows   integer;
  v_row    record;
  v_match  boolean;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if not app.is_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if p_entity_key not in (
    'startups', 'networks', 'programs', 'ma_programs', 'ma_buyers', 'ma_sellers', 'funds'
  ) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  if v_reason = '' then
    raise exception 'reason_required' using errcode = '23514';
  end if;

  -- M&A 당사자는 SELECT 정책이 비활성 행을 가리므로 좁은 DEFINER 헬퍼 한 곳으로만 간다.
  if p_entity_key in ('ma_buyers', 'ma_sellers') then
    if app.admin_restore_ma_party(p_entity_key, p_id, v_reason) = 0 then
      raise exception 'not_found_or_forbidden' using errcode = '42501';
    end if;
    return;
  end if;

  if p_entity_key in ('startups', 'networks') then
    -- 복구 직전에 활성 중복을 다시 본다. 이름·이메일·전화 중 빈 값이 아닌 두 칸 이상이
    -- 일치하면 담당자의 병합 판단 없이 같은 대상을 둘로 되살리지 않는다.
    if p_entity_key = 'startups' then
      select s.id, s.name, s.email, s.phone, null::uuid as country_tag_id
        into v_row
        from public.startups s
       where s.id = p_id
         and s.deleted_at is not null
         and s.merged_into_id is null;
    else
      select n.id, n.name, n.email, n.phone, n.country_tag_id
        into v_row
        from public.networks n
       where n.id = p_id
         and n.deleted_at is not null
         and n.merged_into_id is null;
    end if;

    if v_row.id is null then
      raise exception 'not_found_or_forbidden' using errcode = '42501';
    end if;
    if p_entity_key = 'networks' and v_row.country_tag_id is null then
      raise exception 'restore_required_fields_missing' using errcode = '23514';
    end if;

    execute format(
      'select exists (
         select 1
           from public.%I x
          where x.id <> $1
            and x.deleted_at is null
            and x.merged_into_id is null
            and (
              case when nullif(lower(btrim($2)), '''') is not null
                         and lower(btrim(x.name)) = lower(btrim($2)) then 1 else 0 end
              + case when nullif(lower(btrim($3)), '''') is not null
                         and lower(btrim(coalesce(x.email, ''''))) = lower(btrim($3)) then 1 else 0 end
              + case when nullif(regexp_replace($4, ''\D'', '''', ''g''), '''') is not null
                         and regexp_replace(coalesce(x.phone, ''''), ''\D'', '''', ''g'')
                             = regexp_replace($4, ''\D'', '''', ''g'') then 1 else 0 end
            ) >= 2
       )',
      p_entity_key
    ) into v_match using p_id, v_row.name, v_row.email, v_row.phone;

    if v_match then
      raise exception 'active_duplicate_exists' using errcode = '23505';
    end if;
  end if;

  perform set_config(
    'app.contribution_ctx',
    jsonb_build_object(
      'action', 'reactivated',
      'source', 'manual',
      'note', v_reason
    )::text,
    true
  );

  if p_entity_key in ('startups', 'networks') then
    execute format(
      'update public.%I
          set deleted_at = null
        where id = $1 and deleted_at is not null and merged_into_id is null',
      p_entity_key
    ) using p_id;
  else
    -- programs·ma_programs·funds에는 merged_into_id 칸이 없다.
    execute format(
      'update public.%I
          set deleted_at = null
        where id = $1 and deleted_at is not null',
      p_entity_key
    ) using p_id;
  end if;
  get diagnostics v_rows = row_count;

  -- 조회와 UPDATE 사이에 다른 관리자가 먼저 복구한 경우도 성공으로 가장하지 않는다.
  if v_rows = 0 then
    raise exception 'not_found_or_forbidden' using errcode = '42501';
  end if;
end $_$;


ALTER FUNCTION "public"."restore_entity"("p_entity_key" "text", "p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."restore_entity"("p_entity_key" "text", "p_id" "uuid", "p_reason" "text") IS 'ADMIN 전용 7종 원장 soft-delete 복구. STARTUP·NETWORKS는 활성 중복·병합 행·필수값 누락을 그대로 차단하고, 나머지는 자기 테이블의 deleted_at만 되돌린다. reactivated 기여 이력을 같은 트랜잭션에 남긴다.';



CREATE OR REPLACE FUNCTION "public"."resubmit_approval_document"("p_document_id" "uuid", "p_title" "text", "p_field_values" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid         uuid := app.current_app_user_id();
  v_drafter     uuid;
  v_status      public.approval_status;
  v_round       integer;
  v_next        integer;
  v_carried     boolean := false;
  v_final_reset boolean := false;
  v_notify      uuid[];
begin
  if v_uid is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  select drafter_id, status into v_drafter, v_status
    from public.approval_documents
   where id = p_document_id and deleted_at is null
   for update;

  if not found then
    raise exception 'document not found' using errcode = 'P0002';
  end if;
  if v_drafter is distinct from v_uid then
    raise exception 'only the drafter may resubmit this document' using errcode = '42501';
  end if;

  v_round := app.approval_current_round(p_document_id);
  if v_status = 'REJECTED' then
    select exists (
      select 1
        from public.approval_document_events e
       where e.document_id = p_document_id
         and e.event_type = 'FINAL_APPROVAL_RESET'
         and (e.source_payload ->> 'next_round')::integer = v_round
    ) and exists (
      select 1 from public.approval_lines
       where document_id = p_document_id and round = v_round
    ) and not exists (
      select 1 from public.approval_lines
       where document_id = p_document_id and round = v_round and decision <> 'PENDING'
    ) into v_final_reset;

    if not v_final_reset then
      raise exception 'rejected document is terminal' using errcode = '42501';
    end if;
  elsif v_status <> 'REVISION_REQUIRED' then
    raise exception 'only returned documents may be resubmitted' using errcode = '42501';
  end if;

  if v_final_reset then
    -- recall RPC가 이미 전 결재선을 다음 회차 PENDING으로 만들어 두었다.
    v_next := v_round;
  else
    if not exists (
      select 1 from public.approval_lines
       where document_id = p_document_id and round = v_round
         and decision = 'REVISION_REQUESTED'
    ) then
      raise exception 'revision request not found' using errcode = 'P0002';
    end if;

    v_next := app.clone_approval_revision_round(p_document_id);
    select exists (
      select 1 from public.approval_lines
       where document_id = p_document_id and round = v_round and decision = 'APPROVED'
    ) into v_carried;
  end if;

  update public.approval_documents
     set title = coalesce(nullif(btrim(p_title), ''), title),
         field_values = coalesce(p_field_values, field_values),
         status = case when v_carried then 'IN_REVIEW'::public.approval_status
                       else 'PENDING'::public.approval_status end,
         completed_at = null,
         updated_at = now()
   where id = p_document_id;

  select array_agg(l.approver_id) into v_notify
    from public.approval_lines l
   where l.document_id = p_document_id and l.round = v_next
     and l.step_order = (
       select min(first_line.step_order)
         from public.approval_lines first_line
        where first_line.document_id = p_document_id
          and first_line.round = v_next and first_line.kind = l.kind
     );
  perform app.notify_approval(p_document_id, v_notify, 'approval_pending', v_uid);

  if v_final_reset then
    select array_agg(distinct approver_id) into v_notify
      from public.approval_lines
     where document_id = p_document_id and round = v_round - 1 and approver_id is not null;
    perform app.notify_approval(p_document_id, v_notify, 'approval_reset_resubmitted', v_uid);
  else
    select array_agg(approver_id) into v_notify
      from public.approval_lines
     where document_id = p_document_id and round = v_round and decision = 'APPROVED';
    perform app.notify_approval(p_document_id, v_notify, 'approval_revision_resubmitted', v_uid);
  end if;
end;
$$;


ALTER FUNCTION "public"."resubmit_approval_document"("p_document_id" "uuid", "p_title" "text", "p_field_values" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resubmit_approval_document"("p_document_id" "uuid", "p_title" "text", "p_field_values" "jsonb") IS '보완 요청 또는 최종 승인 초기화로 돌아온 문서를 기안자가 재상신한다. 최종 승인 초기화는 미리 복제한 전체 PENDING 회차를 처음부터 시작한다.';



CREATE OR REPLACE FUNCTION "public"."rotate_module_public_link"("p_entity_key" "text", "p_module_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_token text;
begin
  update public.program_module_public_links
     set token = app.new_public_link_token(), updated_at = now()
   where entity_key = p_entity_key and program_module_id = p_module_id
  returning token into v_token;

  if v_token is null then
    raise exception '재발급할 링크를 찾을 수 없거나 권한이 없습니다.' using errcode = '42501';
  end if;
  return jsonb_build_object('token', v_token);
end;
$$;


ALTER FUNCTION "public"."rotate_module_public_link"("p_entity_key" "text", "p_module_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rotate_module_public_link"("p_entity_key" "text", "p_module_id" "uuid") IS '공개 주소 재발급. 옛 주소는 즉시 죽고 되살릴 수 없다 — 유출 대응 전용.';



CREATE OR REPLACE FUNCTION "public"."save_approval_draft"("p_document_id" "uuid", "p_title" "text", "p_form_id" "uuid", "p_form_version_id" "uuid", "p_field_values" "jsonb", "p_department_id" "uuid", "p_lines" "jsonb", "p_recipient_ids" "uuid"[], "p_submit" boolean, "p_budget_document_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid     uuid := app.current_app_user_id();
  v_drafter uuid;
  v_status  public.approval_status;
  v_round   integer;
begin
  if v_uid is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  select drafter_id, status into v_drafter, v_status
    from public.approval_documents
   where id = p_document_id and deleted_at is null
   for update;

  if not found then
    raise exception 'document not found' using errcode = 'P0002';
  end if;
  -- 기안자 본인만. 워크스페이스 쓰기 권한으로는 열지 않는다.
  if v_drafter is distinct from v_uid then
    raise exception 'only the drafter may edit this document' using errcode = '42501';
  end if;
  -- 상신된 문서는 이 경로로 손대지 못한다.
  if v_status <> 'DRAFT' then
    raise exception 'only DRAFT documents may be edited' using errcode = '42501';
  end if;

  update public.approval_documents set
    title              = p_title,
    form_id            = p_form_id,
    form_version_id    = p_form_version_id,
    field_values       = p_field_values,
    department_id      = p_department_id,
    budget_document_id = p_budget_document_id,
    status             = case when p_submit then 'PENDING'::public.approval_status
                              else 'DRAFT'::public.approval_status end,
    updated_at         = now()
  where id = p_document_id;

  -- 현재 회차만 갈아끼운다. 회차는 지우기 전에 읽어야 한다 — 지운 뒤에는 max(round)가
  -- 지난 회차를 가리켜, 새 결재선이 이미 끝난 회차에 섞여 들어간다.
  v_round := app.approval_current_round(p_document_id);
  delete from public.approval_lines
   where document_id = p_document_id and round = v_round;
  insert into public.approval_lines (document_id, approver_id, step_order, kind, round)
  select p_document_id,
         (e ->> 'approver_id')::uuid,
         (e ->> 'step_order')::integer,
         (e ->> 'kind')::public.approval_line_kind,
         v_round
    from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) e;

  delete from public.approval_recipients where document_id = p_document_id;
  insert into public.approval_recipients (document_id, user_id, sort_order)
  select p_document_id, u, i - 1
    from unnest(coalesce(p_recipient_ids, '{}'::uuid[])) with ordinality as t(u, i);
end;
$$;


ALTER FUNCTION "public"."save_approval_draft"("p_document_id" "uuid", "p_title" "text", "p_form_id" "uuid", "p_form_version_id" "uuid", "p_field_values" "jsonb", "p_department_id" "uuid", "p_lines" "jsonb", "p_recipient_ids" "uuid"[], "p_submit" boolean, "p_budget_document_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_approval_draft"("p_document_id" "uuid", "p_title" "text", "p_form_id" "uuid", "p_form_version_id" "uuid", "p_field_values" "jsonb", "p_department_id" "uuid", "p_lines" "jsonb", "p_recipient_ids" "uuid"[], "p_submit" boolean, "p_budget_document_id" "uuid") IS '임시저장 문서의 값·참조자·근거 품의와 **현재 회차** 결재선을 갈아끼운다. 기안자 본인의 DRAFT만 통과하며 상신 검증은 문서 원장 트리거가 건다(경로가 이 함수 하나가 아니다).';



CREATE OR REPLACE FUNCTION "public"."save_kpi_actual"("p_assignment_id" "uuid", "p_template_item_id" "uuid", "p_actual_value" numeric DEFAULT NULL::numeric, "p_qualitative_value" "text" DEFAULT NULL::"text", "p_actual_payload" "jsonb" DEFAULT NULL::"jsonb", "p_evidence_ref" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v_id uuid;
begin
  insert into public.kpi_actual_revisions
    (assignment_id, template_item_id, actual_value, qualitative_value, actual_payload,
     evidence_ref, revision_no, entered_by)
  values
    (p_assignment_id, p_template_item_id, p_actual_value, nullif(btrim(p_qualitative_value), ''),
     p_actual_payload, nullif(btrim(p_evidence_ref), ''), 0, app.current_app_user_id())
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."save_kpi_actual"("p_assignment_id" "uuid", "p_template_item_id" "uuid", "p_actual_value" numeric, "p_qualitative_value" "text", "p_actual_payload" "jsonb", "p_evidence_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_application_form"("p_program_id" "uuid", "p_program_module_id" "uuid", "p_form_id" "uuid", "p_title" "text", "p_public_status" "text", "p_landing" "jsonb", "p_fields" "jsonb", "p_open_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_close_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_id       uuid := p_form_id;
  v_token    text;
  v_title    text := nullif(btrim(p_title), '');
  v_status   text := coalesce(nullif(btrim(p_public_status), ''), 'PRIVATE');
  v_module   uuid := p_program_module_id;
  v_keep_ids uuid[];
  v_field    jsonb;
  v_fid      uuid;
begin
  -- 인가: 관리자 또는 (ac 쓰기 + 해당 프로그램 접근권). 종전 그대로 — 모집을 열고 닫는 것은
  -- 사업 담당자의 일이다(ADMIN이 정하는 것은 그 종류가 나갈 수 있는지의 상한뿐이다).
  if not (
    app.is_admin()
    or (app.can_write_workspace('project') and app.can_access_program(p_program_id))
  ) then
    raise exception '신청서를 변경할 권한이 없습니다.' using errcode = '42501';
  end if;

  if v_status not in ('PRIVATE', 'OPEN', 'CLOSED') then
    raise exception '공개 상태 값이 올바르지 않습니다: %', v_status;
  end if;
  if p_open_at is not null and p_close_at is not null and p_close_at <= p_open_at then
    raise exception '모집 마감 일시는 시작 일시보다 뒤여야 합니다.';
  end if;

  if p_program_module_id is not null and not exists (
    select 1 from public.program_modules pm
    where pm.id = p_program_module_id
      and pm.program_id = p_program_id
      and pm.module_type = 'RECRUITMENT'
  ) then
    raise exception '모집 신청서는 해당 프로그램의 모집 모듈 인스턴스에만 연결할 수 있습니다.';
  end if;

  if v_id is not null and not exists (
    select 1 from public.application_forms where id = v_id and program_id = p_program_id
  ) then
    raise exception '수정할 신청서를 찾을 수 없습니다.';
  end if;

  -- 폼 본문(제목·랜딩)만 저장한다. 공개 메타(토큰·상태·기간)는 더 이상 여기 담기지 않는다.
  if v_id is null then
    insert into public.application_forms
      (program_id, program_module_id, title, status, landing)
    values (p_program_id, p_program_module_id, coalesce(v_title, '모집 신청서'),
            'DRAFT', coalesce(p_landing, '{}'::jsonb))
    returning id into v_id;
  else
    update public.application_forms set
      program_module_id = coalesce(p_program_module_id, program_module_id),
      title             = coalesce(v_title, title),
      landing           = coalesce(p_landing, landing),
      updated_at        = now()
    where id = v_id
    returning program_module_id into v_module;
  end if;

  -- 공개 메타 → 링크 원장. 이 함수는 DEFINER라 RLS가 걸리지 않으므로 템플릿 상한을 여기서
  -- 직접 확인한다. 닫는 방향(PRIVATE)은 상한과 무관하게 허용한다 — 상한이 내려간 뒤에도
  -- 담당자가 자기 손으로 정리할 수 있어야 한다.
  if v_module is not null then
    if v_status <> 'PRIVATE' and not app.module_public_linkable('RECRUITMENT') then
      raise exception '모집 템플릿의 링크 공유가 꺼져 있습니다. ADMIN 모듈 관리에서 켜 주세요.'
        using errcode = '42501';
    end if;
    insert into public.program_module_public_links
      (entity_key, program_module_id, token, status, open_at, close_at, created_by)
    values ('program', v_module, app.new_public_link_token(), v_status,
            p_open_at, p_close_at, app.current_app_user_id())
    on conflict (entity_key, program_module_id) do update set
      -- 토큰은 건드리지 않는다: 이미 배포된 주소가 죽으면 수습할 방법이 없다.
      status     = excluded.status,
      open_at    = excluded.open_at,
      close_at   = excluded.close_at,
      updated_at = now()
    returning token into v_token;
  end if;

  -- 필드 reconcile: p_fields가 배열일 때만 수행(NULL이면 필드 미변경).
  if p_fields is not null and jsonb_typeof(p_fields) = 'array' then
    v_keep_ids := '{}'::uuid[];
    for v_field in select * from jsonb_array_elements(p_fields) loop
      v_fid := nullif(v_field->>'id', '')::uuid;
      if v_fid is null then
        insert into public.application_form_fields
          (form_id, field_type, label, is_required, options, file_constraints, sort_order)
        values (
          v_id,
          coalesce(v_field->>'field_type', 'text'),
          coalesce(v_field->>'label', ''),
          coalesce((v_field->>'is_required')::boolean, false),
          coalesce(v_field->'options', '[]'::jsonb),
          coalesce(v_field->'file_constraints', '{}'::jsonb),
          coalesce((v_field->>'sort_order')::integer, 0)
        )
        returning id into v_fid;
      else
        update public.application_form_fields set
          field_type       = coalesce(v_field->>'field_type', field_type),
          label            = coalesce(v_field->>'label', label),
          is_required      = coalesce((v_field->>'is_required')::boolean, is_required),
          options          = coalesce(v_field->'options', options),
          file_constraints = coalesce(v_field->'file_constraints', file_constraints),
          sort_order       = coalesce((v_field->>'sort_order')::integer, sort_order)
        where id = v_fid and form_id = v_id;
      end if;
      v_keep_ids := array_append(v_keep_ids, v_fid);
    end loop;

    if exists (
      select 1 from public.application_form_fields f
      where f.form_id = v_id
        and not (f.id = any(v_keep_ids))
        and exists (select 1 from public.application_answers a where a.field_id = f.id)
    ) then
      raise exception '이미 접수된 응답이 있는 필드는 삭제할 수 없습니다. (해당 필드를 유지하세요)';
    end if;

    delete from public.application_form_fields f
    where f.form_id = v_id and not (f.id = any(v_keep_ids));
  end if;

  return jsonb_build_object('id', v_id, 'public_token', v_token);
end;
$$;


ALTER FUNCTION "public"."set_application_form"("p_program_id" "uuid", "p_program_module_id" "uuid", "p_form_id" "uuid", "p_title" "text", "p_public_status" "text", "p_landing" "jsonb", "p_fields" "jsonb", "p_open_at" timestamp with time zone, "p_close_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_application_form"("p_program_id" "uuid", "p_program_module_id" "uuid", "p_form_id" "uuid", "p_title" "text", "p_public_status" "text", "p_landing" "jsonb", "p_fields" "jsonb", "p_open_at" timestamp with time zone, "p_close_at" timestamp with time zone) IS '모집 신청서 저장. 폼 본문은 application_forms, 공개 메타(주소·상태·기간)는 program_module_public_links에 담는다(2026-09-02 이관).';



CREATE OR REPLACE FUNCTION "public"."set_attendance_record"("p_user_id" "uuid", "p_work_date" "date", "p_status" "text", "p_check_in" timestamp with time zone, "p_check_out" timestamp with time zone, "p_place" "public"."attendance_place", "p_note" "text", "p_reason" "text") RETURNS "public"."attendance_days"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_policy public.attendance_policies%rowtype;
  v_old    public.attendance_days%rowtype;
  v_row    public.attendance_days%rowtype;
begin
  if btrim(coalesce(p_reason, '')) = '' then
    raise exception '정정 사유를 입력해야 합니다.';
  end if;
  if p_check_out is not null and p_check_in is null then
    raise exception '출근 기록 없이 퇴근만 남길 수 없습니다.';
  end if;

  select * into v_old from public.attendance_days
   where user_id = p_user_id and work_date = p_work_date and deleted_at is null;

  if found then
    update public.attendance_days
       set status_code  = p_status,
           check_in_at  = p_check_in,
           check_out_at = p_check_out,
           work_place   = p_place,
           note         = p_note
     where id = v_old.id
     returning * into v_row;
  else
    -- 결근으로만 그려지던 빈 칸에 상태를 지정하는 경우 — 이때 처음 행이 생긴다.
    v_policy := app.resolve_attendance_policy(p_user_id, p_work_date);
    insert into public.attendance_days (
      user_id, work_date, work_place, check_in_at, check_out_at,
      status_code, auto_status_code, policy_check_in_to, policy_work_minutes, note
    )
    values (
      p_user_id, p_work_date, p_place, p_check_in, p_check_out,
      p_status,
      app.attendance_auto_status(p_check_in, p_check_out,
        coalesce(v_policy.check_in_to, time '09:00'), coalesce(v_policy.work_minutes, 540)),
      coalesce(v_policy.check_in_to, time '09:00'),
      coalesce(v_policy.work_minutes, 540),
      p_note
    )
    returning * into v_row;
  end if;

  -- 이력은 바뀐 필드만, 필드별로 한 줄씩. 사유는 같은 문장을 공유한다.
  if v_old.id is null or v_old.status_code is distinct from v_row.status_code then
    insert into public.attendance_edits (attendance_day_id, field, before_value, after_value, reason)
    values (v_row.id, 'status', v_old.status_code, v_row.status_code, p_reason);
  end if;
  if v_old.id is not null and v_old.check_in_at is distinct from v_row.check_in_at then
    insert into public.attendance_edits (attendance_day_id, field, before_value, after_value, reason)
    values (v_row.id, 'check_in_at', v_old.check_in_at::text, v_row.check_in_at::text, p_reason);
  end if;
  if v_old.id is not null and v_old.check_out_at is distinct from v_row.check_out_at then
    insert into public.attendance_edits (attendance_day_id, field, before_value, after_value, reason)
    values (v_row.id, 'check_out_at', v_old.check_out_at::text, v_row.check_out_at::text, p_reason);
  end if;
  if v_old.id is not null and v_old.work_place is distinct from v_row.work_place then
    insert into public.attendance_edits (attendance_day_id, field, before_value, after_value, reason)
    values (v_row.id, 'work_place', v_old.work_place::text, v_row.work_place::text, p_reason);
  end if;
  if v_old.id is not null and coalesce(v_old.note, '') is distinct from coalesce(v_row.note, '') then
    insert into public.attendance_edits (attendance_day_id, field, before_value, after_value, reason)
    values (v_row.id, 'note', v_old.note, v_row.note, p_reason);
  end if;

  return v_row;
end $$;


ALTER FUNCTION "public"."set_attendance_record"("p_user_id" "uuid", "p_work_date" "date", "p_status" "text", "p_check_in" timestamp with time zone, "p_check_out" timestamp with time zone, "p_place" "public"."attendance_place", "p_note" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_attendance_status_bulk"("p_user_ids" "uuid"[], "p_work_dates" "date"[], "p_status" "text", "p_reason" "text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_target record;
  v_policy public.attendance_policies%rowtype;
  v_old    public.attendance_days%rowtype;
  v_row    public.attendance_days%rowtype;
  v_count  integer := 0;
begin
  -- 사유는 단건 정정과 같은 규칙으로 필수다. 일괄이라고 "왜 바꿨는가"가 면제되지 않는다.
  if btrim(coalesce(p_reason, '')) = '' then
    raise exception '정정 사유를 입력해야 합니다.';
  end if;
  if coalesce(array_length(p_user_ids, 1), 0) = 0 then
    raise exception '대상을 하나 이상 선택해야 합니다.';
  end if;
  if array_length(p_user_ids, 1) is distinct from array_length(p_work_dates, 1) then
    raise exception '대상 목록이 어긋났습니다.';
  end if;

  for v_target in
    select u as user_id, d as work_date from unnest(p_user_ids, p_work_dates) as t(u, d)
  loop
    select * into v_old
      from public.attendance_days
     where user_id = v_target.user_id
       and work_date = v_target.work_date
       and deleted_at is null;

    if found then
      -- 이미 그 상태면 건너뛴다. 바뀐 것이 없는데 이력에 줄을 남기면 '무엇이 무엇으로'가
      -- 같은 값 두 개인 기록이 쌓여, 나중에 진짜 변경을 찾을 수 없게 된다.
      if v_old.status_code = p_status then
        continue;
      end if;
      -- 상태만 바꾼다 — 찍힌 시각·근무지·비고는 원장 값 그대로 둔다.
      update public.attendance_days
         set status_code = p_status
       where id = v_old.id
       returning * into v_row;
    else
      -- 결근·미출근으로만 그려지던 빈 칸 — 이때 처음 행이 생긴다. 자동 판정값은 기록이 없는
      -- 상태의 판정이므로 단건 정정과 같은 함수로 매긴다(기준은 그날의 정책 스냅샷).
      v_policy := app.resolve_attendance_policy(v_target.user_id, v_target.work_date);
      insert into public.attendance_days (
        user_id, work_date, status_code, auto_status_code,
        policy_check_in_to, policy_work_minutes
      )
      values (
        v_target.user_id, v_target.work_date, p_status,
        app.attendance_auto_status(null, null,
          coalesce(v_policy.check_in_to, time '09:00'),
          coalesce(v_policy.work_minutes, 540)),
        coalesce(v_policy.check_in_to, time '09:00'),
        coalesce(v_policy.work_minutes, 540)
      )
      returning * into v_row;
    end if;

    insert into public.attendance_edits (attendance_day_id, field, before_value, after_value, reason)
    values (v_row.id, 'status', v_old.status_code, v_row.status_code, p_reason);

    v_count := v_count + 1;
  end loop;

  return v_count;
end $$;


ALTER FUNCTION "public"."set_attendance_status_bulk"("p_user_ids" "uuid"[], "p_work_dates" "date"[], "p_status" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_branch_members"("p_branch_id" "uuid", "p_user_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if not app.is_admin() then
    raise exception '지사 배정인력은 관리자만 변경할 수 있습니다.'
      using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.branches where id = p_branch_id and deleted_at is null
  ) then
    raise exception '존재하지 않는 지사입니다.' using errcode = '22023';
  end if;

  delete from public.branch_members where branch_id = p_branch_id;

  insert into public.branch_members (branch_id, user_id, sort_order)
  select p_branch_id, u.id, t.ord::integer
    from unnest(coalesce(p_user_ids, '{}'::uuid[])) with ordinality as t(uid, ord)
    join public.users u on u.id = t.uid
   where u.deleted_at is null
     and u.user_type::text not in ('external_startup', 'external_expert', 'temporary_guest')
  on conflict (branch_id, user_id) do nothing;   -- 입력에 같은 사람이 중복돼도 1행
end $$;


ALTER FUNCTION "public"."set_branch_members"("p_branch_id" "uuid", "p_user_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_branch_members"("p_branch_id" "uuid", "p_user_ids" "uuid"[]) IS '지사 배정인력 명단 일괄 교체. 관리자만 실행 가능(함수 내부 검사). 조인 테이블은 write RLS 정책 없음(Default Deny)이라 이 RPC가 유일한 쓰기 경로.';



CREATE OR REPLACE FUNCTION "public"."set_capital_call_payments"("p_capital_call_id" "uuid", "p_rows" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid  uuid := app.current_app_user_id();
  v_fund uuid;
begin
  if v_uid is null then
    raise exception 'unauthorized' using errcode = '42501';
  end if;
  -- 차수 소속 펀드 조회(capital_calls SELECT RLS가 접근 판정 → 권한 없으면 v_fund null).
  select fund_id into v_fund
    from public.capital_calls
   where id = p_capital_call_id and deleted_at is null;
  if v_fund is null then
    raise exception 'capital_call_not_found_or_forbidden' using errcode = '42501';
  end if;

  -- payload에서 빠진 LP 행 제거(그 차수에서 요청 취소).
  delete from public.capital_call_payments p
   where p.capital_call_id = p_capital_call_id
     and p.lp_id not in (
       select (e->>'lp_id')::uuid
         from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) e
        where nullif(e->>'lp_id','') is not null
     );

  -- upsert: 요청액 · LP별 상태만 쓴다(나머지는 파생).
  insert into public.capital_call_payments
        (capital_call_id, lp_id, fund_id, requested_amount, status)
  select p_capital_call_id,
         (e->>'lp_id')::uuid,
         v_fund,
         coalesce(nullif(e->>'requested_amount','')::numeric, 0),
         (coalesce(
            nullif(e->>'status',''),
            case when coalesce((e->>'is_paid')::boolean, false) then 'PAID' else 'SCHEDULED' end
          ))::public.capital_call_status
    from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) e
   where nullif(e->>'lp_id','') is not null
     -- 같은 펀드 소속 LP만 허용(교차 펀드 오염 차단).
     and exists (
       select 1 from public.fund_lps fl
        where fl.id = (e->>'lp_id')::uuid and fl.fund_id = v_fund and fl.deleted_at is null
     )
  on conflict (capital_call_id, lp_id) do update
     set requested_amount = excluded.requested_amount,
         status           = excluded.status,
         fund_id          = excluded.fund_id;
end $$;


ALTER FUNCTION "public"."set_capital_call_payments"("p_capital_call_id" "uuid", "p_rows" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_capital_call_payments"("p_capital_call_id" "uuid", "p_rows" "jsonb") IS '캐피탈 콜 차수×LP 요청액·LP별 상태 그리드 원자 교체. SECURITY INVOKER — 권한은 capital_call_payments/fund_lps RLS가 판정. 근거: 3_5_workspace_fund.md §1.3';



CREATE OR REPLACE FUNCTION "public"."set_department_membership"("p_version_id" "uuid", "p_user_id" "uuid", "p_department_id" "uuid", "p_effective_from" "date" DEFAULT NULL::"date") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_from date;
  v_version public.org_versions%rowtype;
  v_member_id uuid;
begin
  if not (app.is_admin() or app.can_write_workspace('management')) then
    raise exception '인력 배치를 변경할 권한이 없습니다.' using errcode = '42501';
  end if;
  select * into v_version from public.org_versions
   where id = p_version_id and deleted_at is null;
  if v_version.id is null then raise exception '조직 버전을 찾을 수 없습니다.' using errcode = 'P0002'; end if;
  if p_department_id is not null and not exists (
    select 1 from public.departments d
     where d.id = p_department_id and d.version_id = p_version_id and d.deleted_at is null
  ) then
    raise exception '선택한 조직 버전의 부서가 아닙니다.' using errcode = '23514';
  end if;

  v_from := coalesce(
    p_effective_from,
    case when v_version.status = 'DRAFT' or v_version.effective_from > current_date
      then v_version.effective_from else current_date end
  );
  if v_from < v_version.effective_from then
    raise exception '배치 시작일은 조직 버전 시작일보다 빠를 수 없습니다.' using errcode = '22007';
  end if;

  -- 같은 날 시작한 배치는 닫을 구간이 없으므로 soft delete하고, 이전부터 이어진 배치만 닫는다.
  update public.dept_members
     set deleted_at = now()
   where version_id = p_version_id and user_id = p_user_id and deleted_at is null
     and effective_from = v_from
     and (effective_to is null or effective_to > v_from);
  update public.dept_members
     set effective_to = v_from
   where version_id = p_version_id and user_id = p_user_id and deleted_at is null
     and effective_from < v_from
     and (effective_to is null or effective_to > v_from);

  if p_department_id is not null then
    insert into public.dept_members
      (version_id, department_id, user_id, effective_from, effective_to)
    values
      (p_version_id, p_department_id, p_user_id, v_from, v_version.effective_to)
    returning id into v_member_id;
  end if;

  if p_version_id = public.current_org_version_id() then
    update public.users set department_id = p_department_id where id = p_user_id;
  end if;
  return v_member_id;
end $$;


ALTER FUNCTION "public"."set_department_membership"("p_version_id" "uuid", "p_user_id" "uuid", "p_department_id" "uuid", "p_effective_from" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_entity_creator"("p_table" "text", "p_id" "uuid", "p_user_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_before uuid;
  v_rows   integer;
begin
  if not app.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if not app.has_contribution_trigger(p_table) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  -- 변동 이력 트리거가 있어도 created_by 가 없는 원장이 생길 수 있으므로 카탈로그로 확인한다.
  if not exists (
    select 1 from information_schema.columns
     where table_schema = 'public' and table_name = p_table and column_name = 'created_by'
  ) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  if p_user_id is null then
    raise exception 'creator_required' using errcode = '23514';
  end if;
  -- 비활성/삭제 계정으로는 교체할 수 없다(목록 소속이 사라진 사람에게 붙는 것을 막는다).
  if not exists (
    select 1 from public.users u
     where u.id = p_user_id and u.is_active and u.deleted_at is null
  ) then
    raise exception 'invalid_user' using errcode = '23503';
  end if;

  execute format('select created_by from public.%I where id = $1', p_table)
    into v_before using p_id;

  -- 사유는 트리거가 알 수 없는 정보라 트랜잭션 GUC 로 실어 보낸다(기여 로그 note).
  perform set_config(
    'app.contribution_ctx',
    jsonb_build_object(
      'action', 'edited',
      'source', 'manual',
      'note', coalesce(nullif(p_reason, ''), '관리자 등록자 교체')
    )::text,
    true
  );

  execute format('update public.%I set created_by = $1 where id = $2', p_table)
    using p_user_id, p_id;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    -- 대상이 없거나(잘못된 id) 이 원장에 대한 쓰기가 RLS 로 막힌 경우.
    raise exception 'not_found_or_forbidden' using errcode = '42501';
  end if;

  perform app.log_admin_audit(
    'CREATOR_CHANGE',
    jsonb_build_object('entity_table', p_table, 'entity_id', p_id, 'created_by', v_before),
    jsonb_build_object('entity_table', p_table, 'entity_id', p_id, 'created_by', p_user_id),
    p_reason
  );
end;
$_$;


ALTER FUNCTION "public"."set_entity_creator"("p_table" "text", "p_id" "uuid", "p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_entity_creator"("p_table" "text", "p_id" "uuid", "p_user_id" "uuid", "p_reason" "text") IS '관리자 전용 등록자(created_by) 교체. 허용 원장은 app.has_contribution_trigger() 가 카탈로그에서 판정하고, 변경은 audit_logs(CREATOR_CHANGE)와 원장 변동 이력에 함께 남는다. SECURITY INVOKER — 쓰기 가능 여부는 각 원장 RLS 가 판정한다.';



CREATE OR REPLACE FUNCTION "public"."set_fund_lps"("p_fund_id" "uuid", "p_rows" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid   uuid := app.current_app_user_id();
  v_keep  uuid[];
  v_drop  uuid[];
begin
  if v_uid is null then
    raise exception 'unauthorized' using errcode = '42501';
  end if;
  -- 접근 판정은 정책 헬퍼를 그대로 호출(권한 단일 원천). 실제 DML은 RLS가 재차 강제한다.
  if not (app.can_write_workspace('fund') and app.can_access_fund(p_fund_id)) then
    raise exception 'fund_not_found_or_forbidden' using errcode = '42501';
  end if;

  -- payload가 유지하려는 기존 LP id 목록.
  select coalesce(array_agg((e->>'id')::uuid), '{}'::uuid[]) into v_keep
    from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) e
   where nullif(e->>'id','') is not null;

  -- 명부에서 빠진 조합원 = 이번 저장으로 제외된 LP.
  select coalesce(array_agg(fl.id), '{}'::uuid[]) into v_drop
    from public.fund_lps fl
   where fl.fund_id = p_fund_id
     and fl.deleted_at is null
     and not (fl.id = any(v_keep));

  if array_length(v_drop, 1) is not null then
    -- 납입 행 먼저 제거(집계 트리거가 실납입액·실출자금액을 되돌린다).
    delete from public.capital_call_payments p where p.lp_id = any(v_drop);
    -- 원장은 soft delete. 지분율 트리거가 남은 조합원 기준으로 100%를 다시 나눈다.
    update public.fund_lps fl
       set deleted_at = now()
     where fl.id = any(v_drop);
  end if;

  -- 신규 삽입 / 기존 갱신(조합원명이 빈 행은 무시).
  insert into public.fund_lps (id, fund_id, name, lp_type, commitment_amount, contact)
  select coalesce(nullif(e->>'id','')::uuid, gen_random_uuid()),
         p_fund_id,
         trim(e->>'name'),
         coalesce(nullif(e->>'lp_type',''), 'LIMITED')::public.fund_lp_type,
         coalesce(nullif(e->>'commitment_amount','')::numeric, 0),
         coalesce(e->'contact', '{}'::jsonb)
    from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) e
   where coalesce(trim(e->>'name'), '') <> ''
  on conflict (id) do update
     set name              = excluded.name,
         lp_type           = excluded.lp_type,
         commitment_amount = excluded.commitment_amount,
         contact           = excluded.contact,
         -- 지웠다가 되살리는 경로(같은 id를 다시 보냄)도 여기서 열어둔다.
         deleted_at        = null
   -- 다른 펀드의 LP id를 실어 보내 남의 원장을 덮어쓰는 것을 막는다.
   where public.fund_lps.fund_id = p_fund_id;
end $$;


ALTER FUNCTION "public"."set_fund_lps"("p_fund_id" "uuid", "p_rows" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_fund_lps"("p_fund_id" "uuid", "p_rows" "jsonb") IS '펀드 출자자(LP) 명부 원자 교체. 빠진 LP는 soft delete + 납입 행 제거, 지분율은 트리거 파생. SECURITY INVOKER — 권한은 fund_lps RLS가 판정. 근거: 3_5_workspace_fund.md §2.2';



CREATE OR REPLACE FUNCTION "public"."set_fund_purposes"("p_fund_id" "uuid", "p_purposes" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid uuid := app.current_app_user_id();
begin
  if v_uid is null then
    raise exception 'unauthorized' using errcode = '42501';
  end if;
  -- 접근 판정은 정책 헬퍼를 그대로 호출(권한 단일 원천). 실제 DML은 RLS가 재차 강제한다.
  if not (app.can_write_workspace('fund') and app.can_access_fund(p_fund_id)) then
    raise exception 'fund_not_found_or_forbidden' using errcode = '42501';
  end if;

  -- 사용자가 제거한 목적 삭제(부합 매핑은 FK cascade로 함께 제거).
  delete from public.fund_purposes p
   where p.fund_id = p_fund_id
     and p.id not in (
       select (e->>'id')::uuid
         from jsonb_array_elements(coalesce(p_purposes, '[]'::jsonb)) e
        where nullif(e->>'id','') is not null
     );

  -- 신규 삽입/기존 갱신(라벨이 빈 행은 무시).
  insert into public.fund_purposes (id, fund_id, kind, label, target_pct, sort_order, created_by)
  select coalesce(nullif(e->>'id','')::uuid, gen_random_uuid()),
         p_fund_id,
         e->>'kind',
         trim(e->>'label'),
         nullif(e->>'target_pct','')::numeric,
         coalesce((e->>'sort_order')::int, (ord - 1)::int),
         v_uid
    from jsonb_array_elements(coalesce(p_purposes, '[]'::jsonb)) with ordinality as t(e, ord)
   where coalesce(trim(e->>'label'), '') <> ''
     and e->>'kind' in ('MANDATORY','MAIN','SPECIAL')
  on conflict (id) do update
     set kind       = excluded.kind,
         label      = excluded.label,
         target_pct = excluded.target_pct,
         sort_order = excluded.sort_order;
end $$;


ALTER FUNCTION "public"."set_fund_purposes"("p_fund_id" "uuid", "p_purposes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_fund_purposes"("p_fund_id" "uuid", "p_purposes" "jsonb") IS '펀드 목적(의무투자/주목적/특수목적) 집합 원자 교체. SECURITY INVOKER — 권한은 fund_purposes RLS가 판정.';



CREATE OR REPLACE FUNCTION "public"."set_fund_staffing"("p_fund_id" "uuid", "p_manager_id" "uuid", "p_operators" "uuid"[] DEFAULT '{}'::"uuid"[], "p_admins" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid uuid := app.current_app_user_id();
begin
  if v_uid is null then
    raise exception 'unauthorized' using errcode = '42501';
  end if;

  -- 대표펀드매니저 갱신. funds UPDATE RLS가 쓰기 권한을 판정한다(권한 없으면 0행 → forbidden).
  update public.funds set manager_id = p_manager_id where id = p_fund_id;
  if not found then
    raise exception 'fund_not_found_or_forbidden' using errcode = '42501';
  end if;

  -- 운용/관리 인력 전체 교체. fund_managers write RLS가 판정한다. 대표는 manager_id가 소유하므로
  -- 여기 행은 is_lead=false로만 둔다(대표=OPERATION lead 개념은 쓰지 않는다).
  delete from public.fund_managers where fund_id = p_fund_id;

  insert into public.fund_managers (fund_id, user_id, role, is_lead, assigned_by)
  select p_fund_id, u, 'OPERATION', false, v_uid
    from unnest(coalesce(p_operators, '{}'::uuid[])) u
   where u is not null
  on conflict (fund_id, user_id) do update set role = 'OPERATION', assigned_by = v_uid;

  insert into public.fund_managers (fund_id, user_id, role, is_lead, assigned_by)
  select p_fund_id, u, 'ADMIN', false, v_uid
    from unnest(coalesce(p_admins, '{}'::uuid[])) u
   where u is not null
  on conflict (fund_id, user_id) do update set role = 'ADMIN', assigned_by = v_uid;
end $$;


ALTER FUNCTION "public"."set_fund_staffing"("p_fund_id" "uuid", "p_manager_id" "uuid", "p_operators" "uuid"[], "p_admins" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_fund_staffing"("p_fund_id" "uuid", "p_manager_id" "uuid", "p_operators" "uuid"[], "p_admins" "uuid"[]) IS '펀드 인력 배정: 대표펀드매니저(funds.manager_id) + 운용(OPERATION)/관리(ADMIN) 인력(fund_managers) 원자 교체. SECURITY INVOKER — 권한은 각 원장 RLS가 판정.';



CREATE OR REPLACE FUNCTION "public"."set_guest_account_active"("p_user_id" "uuid", "p_active" boolean, "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_type   public.user_type;
  v_active boolean;
  v_name   text;
begin
  if not app.is_admin() then
    raise exception '게스트 계정 상태는 시스템 관리자만 바꿀 수 있습니다.' using errcode = '42501';
  end if;

  select u.user_type, u.is_active, u.name
    into v_type, v_active, v_name
    from public.users u
   where u.id = p_user_id and u.deleted_at is null;
  if not found then
    raise exception '대상 계정을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;

  -- 임직원 계정을 이 경로로 재우지 않는다. 임직원 비활성화는 인사 원장의 일이고,
  -- 여기서 함께 처리하면 '게스트 계정 관리'라는 이름이 사실과 달라진다.
  if not app.is_guest_user_type(v_type) then
    raise exception '게스트 계정이 아닙니다.' using errcode = '22023';
  end if;

  -- 정지는 되돌릴 수 있지만 그 사람의 오늘 업무를 끊는다. 왜 끊었는지가 남지 않으면
  -- 다음 담당자는 풀어도 되는지 판단할 근거가 없다.
  if not p_active and nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception '정지 사유를 입력해야 합니다.' using errcode = '22023';
  end if;

  if v_active = p_active then
    return; -- 같은 상태면 아무 일도 하지 않는다(감사 로그에 빈 줄을 남기지 않는다).
  end if;

  update public.users
     set is_active = p_active,
         -- 정지할 때만 올린다. 이미 발급된 토큰을 죽여, 나중에 풀어도 그 토큰이
         -- 되살아나지 않게 한다. 해제 시에는 죽일 세션이 없다.
         session_version = case when p_active then session_version else session_version + 1 end,
         updated_at = now()
   where id = p_user_id;

  perform app.log_guest_access(
    p_user_id,
    case when p_active then 'GUEST_ACCOUNT_RESTORE' else 'GUEST_ACCOUNT_SUSPEND' end,
    case when p_active then 'guest:active' else 'guest:suspended' end,
    jsonb_build_object('user_id', p_user_id, 'name', v_name, 'user_type', v_type),
    p_reason
  );
end;
$$;


ALTER FUNCTION "public"."set_guest_account_active"("p_user_id" "uuid", "p_active" boolean, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_guest_account_active"("p_user_id" "uuid", "p_active" boolean, "p_reason" "text") IS '게스트 계정 정지·해제(전 사업 동시). 정지 시 session_version을 올려 발급된 토큰까지 무효화한다. ADMIN 전용, 감사 로그 강제. 근거: 20260903180000';



CREATE OR REPLACE FUNCTION "public"."set_guest_accounts_active"("p_user_ids" "uuid"[], "p_active" boolean, "p_reason" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid;
  v_count   integer := 0;
begin
  if not app.is_admin() then
    raise exception 'GUEST 계정 상태는 시스템 관리자만 바꿀 수 있습니다.' using errcode = '42501';
  end if;
  if coalesce(pg_catalog.array_length(p_user_ids, 1), 0) = 0 then
    raise exception '변경할 계정을 하나 이상 선택해야 합니다.' using errcode = '22023';
  end if;
  if not p_active and nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception '정지 사유를 입력해야 합니다.' using errcode = '22023';
  end if;

  for v_user_id in
    select distinct picked.id from pg_catalog.unnest(p_user_ids) as picked(id)
     where picked.id is not null
     order by picked.id
  loop
    perform public.set_guest_account_active(v_user_id, p_active, p_reason);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."set_guest_accounts_active"("p_user_ids" "uuid"[], "p_active" boolean, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_guest_accounts_active"("p_user_ids" "uuid"[], "p_active" boolean, "p_reason" "text") IS 'ADMIN 전용 GUEST 계정 일괄 정지·해제. 선택 전체를 한 트랜잭션에서 처리하며 단건 감사 규칙을 그대로 적용한다.';



CREATE OR REPLACE FUNCTION "public"."set_investment_purposes"("p_investment_id" "uuid", "p_purpose_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid  uuid := app.current_app_user_id();
  v_fund uuid;
begin
  if v_uid is null then
    raise exception 'unauthorized' using errcode = '42501';
  end if;
  -- 투자 소속 펀드 조회(investments SELECT RLS가 접근을 판정 → 권한 없으면 v_fund null).
  select fund_id into v_fund from public.investments where id = p_investment_id and deleted_at is null;
  if v_fund is null then
    raise exception 'investment_not_found_or_forbidden' using errcode = '42501';
  end if;

  delete from public.investment_purposes where investment_id = p_investment_id;

  -- 같은 펀드에 속한 목적만 매핑(교차 펀드 오염 차단). insert는 RLS가 재차 강제.
  insert into public.investment_purposes (investment_id, purpose_id, fund_id, created_by)
  select p_investment_id, pid, v_fund, v_uid
    from unnest(coalesce(p_purpose_ids, '{}'::uuid[])) pid
   where pid is not null
     and exists (
       select 1 from public.fund_purposes fp where fp.id = pid and fp.fund_id = v_fund
     );
end $$;


ALTER FUNCTION "public"."set_investment_purposes"("p_investment_id" "uuid", "p_purpose_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_investment_purposes"("p_investment_id" "uuid", "p_purpose_ids" "uuid"[]) IS '투자↔목적 부합 매핑 원자 교체. SECURITY INVOKER — 권한은 investment_purposes/investments RLS가 판정.';



CREATE OR REPLACE FUNCTION "public"."set_kpi_primary_assignment"("p_kpi_version_id" "uuid", "p_template_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_target_overrides" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid;
begin
  if not (app.is_admin() or app.can_write_workspace('management')) then
    raise exception 'KPI를 할당할 권한이 없습니다.' using errcode = '42501';
  end if;
  if p_subject_type not in ('DEPARTMENT','PERSON') then
    raise exception '올바르지 않은 KPI 대상 종류입니다.' using errcode = '22023';
  end if;

  update public.kpi_assignments
     set deleted_at = now()
   where kpi_version_id = p_kpi_version_id
     and subject_type = p_subject_type
     and assignment_kind = 'PRIMARY'
     and deleted_at is null
     and ((p_subject_type = 'DEPARTMENT' and department_id = p_subject_id)
       or (p_subject_type = 'PERSON' and user_id = p_subject_id));

  if p_template_id is null then return null; end if;
  insert into public.kpi_assignments
    (kpi_version_id, template_id, subject_type, department_id, user_id, assignment_kind, target_overrides)
  values (
    p_kpi_version_id, p_template_id, p_subject_type,
    case when p_subject_type = 'DEPARTMENT' then p_subject_id end,
    case when p_subject_type = 'PERSON' then p_subject_id end,
    'PRIMARY', coalesce(p_target_overrides, '{}'::jsonb)
  ) returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."set_kpi_primary_assignment"("p_kpi_version_id" "uuid", "p_template_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_target_overrides" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_ma_program_party_links"("p_program_id" "uuid", "p_buyer_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_seller_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'app'
    AS $$
declare
  v_category text;
  v_buyer_ids uuid[];
  v_seller_ids uuid[];
  v_module_id uuid;
  v_left text;
begin
  if not app.can_write_workspace('mna')
     or not app.can_access_ws_program('mna', p_program_id) then
    raise exception 'M&A 프로젝트 매물 연결 권한이 없습니다.' using errcode = '42501';
  end if;

  select category
    into v_category
    from public.ma_programs
   where id = p_program_id;

  if not found then
    raise exception 'M&A 프로젝트를 찾을 수 없습니다.' using errcode = 'P0002';
  end if;

  select coalesce(array_agg(distinct x), '{}'::uuid[])
    into v_buyer_ids
    from unnest(coalesce(p_buyer_ids, '{}'::uuid[])) as x
   where x is not null;

  select coalesce(array_agg(distinct x), '{}'::uuid[])
    into v_seller_ids
    from unnest(coalesce(p_seller_ids, '{}'::uuid[])) as x
   where x is not null;

  if v_category = 'SELL' and cardinality(v_buyer_ids) > 0 then
    raise exception 'Sell 프로젝트에는 M&A SELLER 매물만 연결할 수 있습니다.' using errcode = '23514';
  elsif v_category = 'BUY' and cardinality(v_seller_ids) > 0 then
    raise exception 'Buy 프로젝트에는 M&A BUYER 매물만 연결할 수 있습니다.' using errcode = '23514';
  elsif v_category not in ('SELL', 'BUY', 'SELL_BUY')
        and (cardinality(v_buyer_ids) > 0 or cardinality(v_seller_ids) > 0) then
    raise exception 'Sell, Buy 또는 Sell+Buy 프로젝트만 매물을 연결할 수 있습니다.' using errcode = '23514';
  end if;

  if exists (
    select 1
      from unnest(v_seller_ids) id
     where not exists (
       select 1 from public.ma_sellers s where s.id = id and s.deleted_at is null
     )
  ) then
    raise exception '연결할 수 없는 M&A SELLER 매물이 포함되어 있습니다.' using errcode = '23503';
  end if;

  if exists (
    select 1
      from unnest(v_buyer_ids) id
     where not exists (
       select 1 from public.ma_buyers b where b.id = id and b.deleted_at is null
     )
  ) then
    raise exception '연결할 수 없는 M&A BUYER 매물이 포함되어 있습니다.' using errcode = '23503';
  end if;

  delete from public.ma_program_party_links where program_id = p_program_id;

  if v_category in ('SELL', 'SELL_BUY') then
    insert into public.ma_program_party_links (program_id, seller_id)
    select p_program_id, id from unnest(v_seller_ids) id;
  end if;
  if v_category in ('BUY', 'SELL_BUY') then
    insert into public.ma_program_party_links (program_id, buyer_id)
    select p_program_id, id from unnest(v_buyer_ids) id;
  end if;

  -- 연결이 하나라도 있으면 퀵리뷰 모듈이 하나 선다(2026-09-08 사용자 지정 "연동하면 탭이
  -- 생기는 게 아니라 모듈을 하나 생성하자").
  --
  -- **여기서 만드는 이유**는 연결을 바꾸는 길이 이 함수 하나이기 때문이다. 화면에서 만들면
  -- 다른 경로로 연결된 프로젝트에는 모듈이 서지 않고, 그 사실을 알려 주는 것이 없다.
  --
  -- **title을 비운다.** uq_program_modules_title이 프로젝트 안에서 모듈명을 유일하게 잡고
  -- 있어, '퀵리뷰'를 박아 넣으면 담당자가 이미 그 이름의 글쓰기 모듈을 만들어 둔
  -- 프로젝트에서 **매물 연결 자체가 실패한다.** 이름이 비면 화면이 템플릿 라벨로 폴백한다.
  --
  -- 상태는 DRAFT(준비)다. 기간·담당자는 여기서 적지 않는다 — 그 두 칸은 이제 원장이
  -- 답한다(퀵 리뷰의 작성일·작성자). 모듈에 값을 적어 두면 원장을 고쳤을 때 어느 쪽이
  -- 진짜인지 판정할 근거가 없다.
  if cardinality(v_seller_ids) > 0 or cardinality(v_buyer_ids) > 0 then
    insert into public.program_modules (program_id, entity_key, module_type, visibility, status)
    select p_program_id, 'ma_program', 'QUICK_REVIEW'::public.module_type,
           'INTERNAL_ONLY'::public.module_visibility, 'DRAFT'::public.module_status
     where not exists (
       select 1
         from public.program_modules m
        where m.program_id = p_program_id
          and m.entity_key = 'ma_program'
          and m.module_type = 'QUICK_REVIEW'
     );

  -- 연결이 0건이면 모듈도 함께 걷는다(2026-09-09 사용자 지정 "빠지면 퀵리뷰도 같이 빠지는
  -- 구조"). 비출 것이 없는 거울을 워크플로우에 세워 두면 그 줄이 없는 일을 있다고 말한다.
  --
  -- **담긴 것이 있으면 두고 나간다.** 자동 삭제에는 따라쓰기 확인도 PM 판정도 없으므로,
  -- 무엇 하나라도 이 모듈에 매달려 있으면(글·폼·링크·공지·첨부) 사람이 지우게 한다.
  -- 판정은 삭제창이 쓰는 함수를 그대로 부른다 — 같은 물음에 두 벌의 답을 만들지 않는다.
  else
    select m.id into v_module_id
      from public.program_modules m
     where m.program_id = p_program_id
       and m.entity_key = 'ma_program'
       and m.module_type = 'QUICK_REVIEW';

    if v_module_id is not null then
      select string_agg(b.rel_name || ' ' || b.row_count || '건', ', ')
        into v_left
        from public.program_module_delete_blockers('ma_program', v_module_id) b;

      if v_left is null then
        -- 되돌릴 수 없는 삭제다. 자동이라도(오히려 자동이라서) 누가 무엇을 없앴는지 남긴다.
        insert into public.audit_logs (actor_user_id, action, changed_workspace, before_data, reason)
        values (
          app.current_app_user_id(), 'MODULE_DELETE', 'mna',
          jsonb_build_object('entity_key', 'ma_program', 'module_id', v_module_id,
                             'program_id', p_program_id, 'module_type', 'QUICK_REVIEW'),
          '매물 연결 해제로 퀵리뷰 모듈 자동 삭제'
        );
        -- 담당자 배정은 cascade라 본체 삭제가 함께 지운다. 그 밖에 매달린 것은 위에서
        -- 0건임을 확인했다.
        delete from public.program_modules where id = v_module_id;
      end if;
    end if;
  end if;
end;
$$;


ALTER FUNCTION "public"."set_ma_program_party_links"("p_program_id" "uuid", "p_buyer_ids" "uuid"[], "p_seller_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_ma_program_party_links"("p_program_id" "uuid", "p_buyer_ids" "uuid"[], "p_seller_ids" "uuid"[]) IS 'M&A 프로젝트의 매물 연결 전량 교체. 연결이 생기면 퀵리뷰 모듈이 하나 서고, 연결이 0건이 되면 그 모듈을 함께 걷는다(매달린 데이터가 있으면 두고 나가며 그때는 사람이 삭제한다).';



CREATE OR REPLACE FUNCTION "public"."set_ma_program_staffing"("p_program_id" "uuid", "p_departments" "jsonb", "p_managers" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_dep_count  int;
  v_mgr_count  int;
  v_pm         int;
  v_prog_start date;
  v_prog_end   date;
  v_env_start  date;
  v_env_end    date;
  v_bad        int;
begin
  -- 인가
  if not (
    app.is_admin()
    or (app.can_write_workspace('mna') and app.can_access_ws_program('mna', p_program_id))
  ) then
    raise exception '사업 담당자를 변경할 권한이 없습니다.' using errcode = '42501';
  end if;

  select count(*) into v_dep_count
  from jsonb_to_recordset(coalesce(p_departments, '[]'::jsonb))
    as d(org_version_id uuid, department_id uuid, kind text, collaboration_ratio int);
  select count(*), count(*) filter (where role = 'PM') into v_mgr_count, v_pm
  from jsonb_to_recordset(coalesce(p_managers, '[]'::jsonb))
    as m(user_id uuid, org_version_id uuid, department_id uuid, role text, allocation_rate int, start_date date, end_date date);

  if v_dep_count = 0 and v_mgr_count = 0 then
    delete from public.ma_program_managers    where program_id = p_program_id;
    delete from public.ma_program_departments where program_id = p_program_id;
    return;
  end if;
  if v_dep_count = 0 then
    raise exception '부서 구성을 먼저 설정해야 합니다.';
  end if;

  if exists (
    select 1 from jsonb_to_recordset(p_departments) as d(org_version_id uuid, kind text, collaboration_ratio int)
    where d.org_version_id is null or d.kind not in ('MAIN', 'COLLAB')
       or d.collaboration_ratio is null or d.collaboration_ratio < 1 or d.collaboration_ratio > 100
  ) then
    raise exception '부서 종류(MAIN/COLLAB)·협업비율(1~100)·org 버전을 올바르게 입력하세요.';
  end if;
  if exists (
    select 1 from jsonb_to_recordset(p_departments) as d(org_version_id uuid, department_id uuid)
    left join public.departments dd on dd.id = d.department_id
    where dd.id is null or dd.version_id <> d.org_version_id
  ) then
    raise exception '부서가 지정한 조직 버전에 속하지 않습니다.';
  end if;
  if exists (
    select 1 from jsonb_to_recordset(p_departments) as d(org_version_id uuid, department_id uuid, kind text, collaboration_ratio int)
    group by d.org_version_id
    having count(*) filter (where d.kind = 'MAIN') <> 1
        or sum(d.collaboration_ratio) <> 100
        or count(*) <> count(distinct d.department_id)
  ) then
    raise exception '각 조직 버전(단계)에서 메인 1개 + 협업비율 합 100%%를 지켜야 합니다.';
  end if;

  if v_mgr_count = 0 then raise exception '담당자를 1명 이상 배정해야 합니다.'; end if;
  if v_pm < 1 then raise exception 'PM을 최소 1명(구간) 지정해야 합니다.'; end if;
  if exists (
    select 1 from jsonb_to_recordset(p_managers) as m(role text, allocation_rate int, start_date date, end_date date, org_version_id uuid, department_id uuid)
    where m.role is null or m.role not in ('PM', 'MEMBER')
       or m.allocation_rate is null or m.allocation_rate < 1 or m.allocation_rate > 100
       or m.start_date is null or m.end_date is null or m.start_date > m.end_date
       or m.org_version_id is null or m.department_id is null
  ) then
    raise exception '담당자 구간의 부서·역할·투입률(1~100)·수행 기간을 올바르게 입력하세요.';
  end if;
  if exists (
    select 1 from jsonb_to_recordset(p_managers) as m(org_version_id uuid, department_id uuid)
    where not exists (
      select 1 from jsonb_to_recordset(p_departments) as d(org_version_id uuid, department_id uuid)
      where d.org_version_id = m.org_version_id and d.department_id = m.department_id)
  ) then
    raise exception '담당자의 부서는 해당 단계에 지정된 부서 중 하나여야 합니다.';
  end if;
  if exists (
    select 1 from jsonb_to_recordset(p_managers) as m(org_version_id uuid, start_date date, end_date date)
    join public.org_versions ov on ov.id = m.org_version_id
    where m.start_date < ov.effective_from or (ov.effective_to is not null and m.end_date >= ov.effective_to)
  ) then
    raise exception '담당자 구간이 소속 조직 버전의 유효기간을 벗어났습니다.';
  end if;

  select start_date, end_date into v_prog_start, v_prog_end from public.ma_programs where id = p_program_id;
  if v_prog_start is not null and v_prog_end is not null then
    if exists (
      select 1 from jsonb_to_recordset(p_managers) as m(start_date date, end_date date)
      where m.start_date < v_prog_start or m.end_date > v_prog_end
    ) then
      raise exception '담당자 수행 기간은 사업 기간(% ~ %) 내여야 합니다.', v_prog_start, v_prog_end;
    end if;
  end if;

  select coalesce(v_prog_start, min(start_date)), coalesce(v_prog_end, max(end_date))
    into v_env_start, v_env_end
  from jsonb_to_recordset(p_managers) as m(start_date date, end_date date);

  with days as (select g.d::date d from generate_series(v_env_start, v_env_end, interval '1 day') g(d)),
  cfg_ver as (
    select distinct d.org_version_id, ov.effective_from, ov.effective_to
    from jsonb_to_recordset(p_departments) as d(org_version_id uuid, department_id uuid, kind text, collaboration_ratio int)
    join public.org_versions ov on ov.id = d.org_version_id
  ),
  day_ver as (
    select days.d, cv.org_version_id
    from days join cfg_ver cv
      on days.d >= cv.effective_from and (cv.effective_to is null or days.d < cv.effective_to)
  )
  select count(*) into v_bad
  from day_ver dv
  join jsonb_to_recordset(p_departments) as dep(org_version_id uuid, department_id uuid, kind text, collaboration_ratio int)
    on dep.org_version_id = dv.org_version_id
  where dep.collaboration_ratio <> (
    select coalesce(sum(m.allocation_rate), 0)
    from jsonb_to_recordset(p_managers)
      as m(org_version_id uuid, department_id uuid, allocation_rate int, start_date date, end_date date)
    where m.org_version_id = dep.org_version_id and m.department_id = dep.department_id
      and m.start_date <= dv.d and m.end_date >= dv.d
  );
  if v_bad > 0 then
    raise exception '단계별로 각 부서를 전 구간에서 협업비율만큼 채워야 합니다. (미충족 %건)', v_bad;
  end if;

  delete from public.ma_program_managers    where program_id = p_program_id;
  delete from public.ma_program_departments where program_id = p_program_id;
  insert into public.ma_program_departments (program_id, org_version_id, department_id, kind, collaboration_ratio)
  select p_program_id, d.org_version_id, d.department_id, d.kind::public.program_department_kind, d.collaboration_ratio
  from jsonb_to_recordset(p_departments) as d(org_version_id uuid, department_id uuid, kind text, collaboration_ratio int);
  insert into public.ma_program_managers
    (program_id, org_version_id, user_id, department_id, role, allocation_rate, start_date, end_date, assigned_by)
  select
    p_program_id, m.org_version_id, m.user_id, m.department_id, m.role::public.program_manager_role,
    m.allocation_rate, m.start_date, m.end_date, app.current_app_user_id()
  from jsonb_to_recordset(p_managers)
    as m(user_id uuid, org_version_id uuid, department_id uuid, role text, allocation_rate int, start_date date, end_date date);
end;
$$;


ALTER FUNCTION "public"."set_ma_program_staffing"("p_program_id" "uuid", "p_departments" "jsonb", "p_managers" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_ma_program_staffing"("p_program_id" "uuid", "p_departments" "jsonb", "p_managers" "jsonb") IS 'M&A 사업 부서+담당자 배치 org 버전(단계)별 독립 검증·원자 교체. set_program_staffing(AC)의 mna 원장 대응.';



CREATE OR REPLACE FUNCTION "public"."set_minute_links"("p_minute_id" "uuid", "p_links" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  r record;
begin
  if not (app.is_admin() or app.is_minute_author(p_minute_id)) then
    raise exception '회의록 작성자만 연동 대상을 변경할 수 있습니다.'
      using errcode = '42501';
  end if;

  delete from public.meeting_minute_links where minute_id = p_minute_id;

  for r in
    -- 같은 대상이 두 역할로 실려 오면 참석자 쪽을 남긴다(unique 제약이 한 줄만 허용한다).
    select distinct on (target_type, target_id) target_type, target_id, role
      from (
        select (elem->>'target_type') as target_type,
               (elem->>'target_id')::uuid as target_id,
               -- 역할이 비어 오면 '회의가 다룬 대상'이다(옛 화면·옛 저장 경로와 같은 뜻).
               coalesce(nullif(elem->>'role', ''), 'SUBJECT') as role
          from jsonb_array_elements(coalesce(p_links, '[]'::jsonb)) as elem
         where elem->>'target_type' is not null
           and elem->>'target_id' is not null
      ) src
     order by target_type, target_id, (role = 'EXTERNAL_ATTENDEE') desc
  loop
    if not app.can_link_minute_target(r.target_type, r.target_id) then
      raise exception '연동할 수 없는 대상입니다(권한 없음 또는 삭제됨): % %',
        r.target_type, r.target_id using errcode = '42501';
    end if;

    -- 역할 값과 '외부 참석자로 담을 수 있는 종류'는 표의 CHECK 둘이 답한다(위 주석 참조).
    insert into public.meeting_minute_links (minute_id, target_type, target_id, role)
    values (p_minute_id, r.target_type, r.target_id, r.role)
    on conflict (minute_id, target_type, target_id) do nothing;
  end loop;
end $$;


ALTER FUNCTION "public"."set_minute_links"("p_minute_id" "uuid", "p_links" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_minute_links"("p_minute_id" "uuid", "p_links" "jsonb") IS '회의록 연동 대상·외부 참석자 일괄 교체. 작성자/admin만, 대상별 app.can_link_minute_target 통과분만 반영. role(SUBJECT=회의가 다룬 대상, EXTERNAL_ATTENDEE=회의에 온 사외 인원)을 그대로 싣고, 역할별 대상 종류는 표의 CHECK가 강제한다.';



CREATE OR REPLACE FUNCTION "public"."set_minute_people"("p_minute_id" "uuid", "p_people" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if not (app.is_admin() or app.is_minute_author(p_minute_id)) then
    raise exception '회의록 작성자만 참석자·참조를 변경할 수 있습니다.'
      using errcode = '42501';
  end if;

  delete from public.meeting_minute_people where minute_id = p_minute_id;

  insert into public.meeting_minute_people (minute_id, user_id, role)
  select p_minute_id,
         (elem->>'user_id')::uuid,
         coalesce((elem->>'role')::public.minute_person_role, 'ATTENDEE')
    from jsonb_array_elements(coalesce(p_people, '[]'::jsonb)) as elem
   where elem->>'user_id' is not null
  on conflict (minute_id, user_id) do update set role = excluded.role;
end $$;


ALTER FUNCTION "public"."set_minute_people"("p_minute_id" "uuid", "p_people" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_minute_people"("p_minute_id" "uuid", "p_people" "jsonb") IS '회의록 참석자(ATTENDEE)/참조(REFERENCE) 명단 일괄 교체. 작성자·관리자만 실행 가능(함수 내부 검사). 조인 테이블은 write RLS 정책 없음(Default Deny)이라 이 RPC가 유일한 쓰기 경로.';



CREATE OR REPLACE FUNCTION "public"."set_module_public_link"("p_entity_key" "text", "p_module_id" "uuid", "p_status" "text", "p_open_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_close_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_contact" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_type   text;
  v_status text := coalesce(nullif(btrim(p_status), ''), 'PRIVATE');
  v_row    public.program_module_public_links%rowtype;
begin
  if p_entity_key not in ('program', 'ma_program') then
    raise exception '원장 키가 올바르지 않습니다: %', p_entity_key;
  end if;
  if v_status not in ('PRIVATE', 'OPEN', 'CLOSED') then
    raise exception '공개 상태 값이 올바르지 않습니다: %', v_status;
  end if;
  if p_open_at is not null and p_close_at is not null and p_close_at <= p_open_at then
    raise exception '공개 마감은 공개 시작 이후여야 합니다.';
  end if;

  -- 모듈이 보이지 않으면(없거나 접근 불가) 여기서 끝난다 — RLS가 이미 답을 냈다.
  select r.module_type into v_type
    from app.ws_module_row(p_entity_key, p_module_id) r;
  if v_type is null then
    raise exception '모듈을 찾을 수 없거나 접근 권한이 없습니다.' using errcode = '42501';
  end if;
  if not app.module_public_linkable(v_type) then
    raise exception '이 템플릿은 링크 공유를 켤 수 없습니다: %', v_type;
  end if;

  insert into public.program_module_public_links
    (entity_key, program_module_id, token, status, open_at, close_at, contact, created_by)
  values
    (p_entity_key, p_module_id, app.new_public_link_token(), v_status,
     p_open_at, p_close_at, nullif(btrim(p_contact), ''), app.current_app_user_id())
  on conflict (entity_key, program_module_id) do update set
    -- 토큰은 건드리지 않는다. 껐다 켜도 같은 주소가 돌아와야 이미 배포한 공고문이 살아 있다.
    status     = excluded.status,
    open_at    = excluded.open_at,
    close_at   = excluded.close_at,
    contact    = excluded.contact,
    updated_at = now()
  returning * into v_row;

  return jsonb_build_object(
    'id', v_row.id, 'token', v_row.token, 'status', v_row.status,
    'open_at', v_row.open_at, 'close_at', v_row.close_at, 'contact', v_row.contact
  );
end;
$$;


ALTER FUNCTION "public"."set_module_public_link"("p_entity_key" "text", "p_module_id" "uuid", "p_status" "text", "p_open_at" timestamp with time zone, "p_close_at" timestamp with time zone, "p_contact" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_module_public_link"("p_entity_key" "text", "p_module_id" "uuid", "p_status" "text", "p_open_at" timestamp with time zone, "p_close_at" timestamp with time zone, "p_contact" "text") IS '모듈 공개 링크 생성/수정(최초 호출 시 토큰 1회 발급, 이후 고정). SECURITY INVOKER — 인가는 링크 원장 RLS가 판정한다.';



CREATE OR REPLACE FUNCTION "public"."set_module_templates"("p_rows" "jsonb") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_row   jsonb;
  v_key   text;
  v_count integer := 0;
begin
  if not app.is_admin() then
    raise exception '모듈 카탈로그를 변경할 권한이 없습니다.' using errcode = '42501';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception '저장할 목록이 올바르지 않습니다.';
  end if;

  for v_row in select * from jsonb_array_elements(p_rows) loop
    v_key := v_row->>'key';
    if not exists (select 1 from public.module_templates where key = v_key) then
      raise exception '없는 템플릿입니다: %', v_key;
    end if;
    -- 옛 화면(열어 둔 탭)이 상한 2종을 보내면 조용히 무시하지 않고 사유를 말한다 —
    -- 무시하면 담당자는 저장이 됐다고 읽고 왜 안 바뀌는지 묻게 된다.
    if v_row ? 'allow_guest' or v_row ? 'allow_public_link' then
      raise exception '공유 상한 2종은 공유 범위 한 축으로 바뀌었습니다. 화면을 새로 고친 뒤 다시 저장하세요.';
    end if;

    update public.module_templates set
      category   = coalesce(v_row->>'category', category),
      sort_order = coalesce((v_row->>'sort_order')::integer, sort_order),
      is_active  = coalesce((v_row->>'is_active')::boolean, is_active),
      workspaces = coalesce(
                     (select array_agg(value::text)
                        from jsonb_array_elements_text(v_row->'workspaces') as value),
                     case when v_row ? 'workspaces' then '{}'::text[] else workspaces end),
      visibility = coalesce(v_row->>'visibility', visibility),
      updated_at = now()
    where key = v_key;
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."set_module_templates"("p_rows" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_module_templates"("p_rows" "jsonb") IS '모듈 템플릿 배치 저장(ADMIN 전용). 분류·순서·사용 여부·워크스페이스 노출·공유 범위 성격을 한 트랜잭션에 반영한다.';



CREATE OR REPLACE FUNCTION "public"."set_program_guest_access_window"("p_program_id" "uuid", "p_ends" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_ws    text;
  v_table text;
begin
  if p_program_id is null then
    raise exception '대상을 찾을 수 없습니다.' using errcode = '22023';
  end if;

  v_ws := app.program_ws(p_program_id);
  v_table := case v_ws
               when 'project' then 'programs'
               when 'mna'     then 'ma_programs'
               when 'fund'    then 'funds'
             end;
  if v_table is null then
    raise exception '대상을 찾을 수 없습니다.' using errcode = '22023';
  end if;

  if not app.is_program_manager(p_program_id) then
    raise exception '담당자(PM·MEMBER·운용역)만 접근 기간을 정할 수 있습니다.' using errcode = '42501';
  end if;

  -- 지난 날짜를 막지 않는다. 이미 끝난 사업의 문을 지금 닫는 것이 실제 운용이고,
  -- 담당자가 오늘 이후만 고를 수 있으면 그 일을 할 방법이 없다.
  execute format('update public.%I set guest_access_ends_at = $2, updated_at = now() where id = $1', v_table)
    using p_program_id, p_ends;

  perform app.log_guest_access(
    null,
    'GUEST_ACCESS_WINDOW',
    'guest:login',
    jsonb_build_object('program_id', p_program_id, 'workspace', v_ws, 'ends', p_ends),
    null
  );
end;
$_$;


ALTER FUNCTION "public"."set_program_guest_access_window"("p_program_id" "uuid", "p_ends" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_program_guest_access_window"("p_program_id" "uuid", "p_ends" timestamp with time zone) IS '이 사업 게스트의 접근 종료일을 정한다(사업 담당자 전용, SECURITY INVOKER). null이면 제한 없음. 참여 기업·전문가 전원에게 같이 걸린다 — 기업별 예외는 두지 않고, 한 곳만 막을 일은 차단이 답한다. 근거: 3_9_1 §8';



CREATE OR REPLACE FUNCTION "public"."set_program_module"("p_entity_key" "text", "p_program_id" "uuid", "p_module_id" "uuid", "p_module_type" "text", "p_title" "text", "p_status" "text", "p_visibility" "text", "p_participation_mode" "text", "p_settings" "jsonb", "p_assignees" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_ws         text := app.entity_key_workspace(p_entity_key);
  v_managers   text;
  v_prog_table text;
  v_id         uuid := p_module_id;
  v_title      text := nullif(btrim(p_title), '');
  v_mode       text;
  v_ps         date := (p_settings->>'start_date')::date;
  v_pe         date := (p_settings->>'end_date')::date;
  v_prog       jsonb;
  v_prop_start date;
  v_prop_end   date;
  v_op_start   date;
  v_op_end     date;
  v_row        jsonb;
  v_uid        uuid;
  v_ok         boolean;
begin
  if p_entity_key not in ('program', 'ma_program') then
    raise exception '알 수 없는 사업 원장입니다: %', p_entity_key using errcode = '22023';
  end if;

  if p_assignees is not null and jsonb_typeof(p_assignees) <> 'array' then
    raise exception '담당자 목록의 형식이 올바르지 않습니다.' using errcode = '22023';
  end if;

  select managers_table into v_managers from app.ws_module_tables(p_entity_key);
  v_prog_table := case p_entity_key
    when 'program'    then 'programs'
    when 'ma_program' then 'ma_programs'
  end;

  -- 인가: 관리자 또는 (해당 워크스페이스 쓰기 + 그 사업 접근권)
  if not (
    app.is_admin()
    or (app.can_write_workspace(v_ws) and app.can_access_ws_program(v_ws, p_program_id))
  ) then
    raise exception '운영 모듈을 변경할 권한이 없습니다.' using errcode = '42501';
  end if;

  -- 배치 가능한 템플릿인가(ADMIN 카탈로그가 답한다). 화면에서 감추는 것은 보안이 아니다.
  if v_id is null and not app.module_template_available(p_module_type, v_ws) then
    raise exception '이 워크스페이스에서 배치할 수 없는 모듈 종류입니다: %', p_module_type
      using errcode = '42501';
  end if;

  -- 수정 대상 인스턴스가 이 사업 소속인지 확인(원장까지 함께 본다).
  if v_id is not null and not exists (
    select 1 from public.program_modules
     where id = v_id and program_id = p_program_id and entity_key = p_entity_key
  ) then
    raise exception '수정할 모듈 인스턴스를 찾을 수 없습니다.';
  end if;

  -- 배정 방식: 미지정 시 템플릿 기본값으로 강제.
  v_mode := coalesce(p_participation_mode, case p_module_type
    when 'RECRUITMENT'       then 'OPEN_APPLICATION'
    when 'DOC_REVIEW'        then 'REVIEWER_ASSIGNMENT'
    when 'ONSITE_EVAL'       then 'REVIEWER_ASSIGNMENT'
    when 'DEMO_DAY'          then 'REVIEWER_ASSIGNMENT'
    when 'ORIENTATION'       then 'ADMIN_ONLY'
    when 'OUTCOMES'          then 'ADMIN_ONLY'
    when 'CUSTOM_ACTIVITY'   then 'ADMIN_ONLY'
    when 'MENTORING'         then 'MANUAL_ALLOCATION'
    when 'BUSINESS_MATCHING' then 'STARTUP_FCFS'
  end);

  -- 모듈명 중복 금지(사업 내, 정규화 비교; 수정 시 자기 자신 제외).
  if v_title is not null and exists (
    select 1 from public.program_modules pm
     where pm.program_id = p_program_id
       and lower(btrim(pm.title)) = lower(v_title)
       and (v_id is null or pm.id <> v_id)
  ) then
    raise exception '이미 같은 이름의 모듈이 있습니다: %', v_title;
  end if;

  -- OUTCOMES 단일성(신규 생성 시).
  if p_module_type = 'OUTCOMES' and v_id is null and exists (
    select 1 from public.program_modules
     where program_id = p_program_id and module_type = 'OUTCOMES'
  ) then
    raise exception '성과/KPI 모듈은 사업당 1개만 배치할 수 있습니다.';
  end if;

  -- 기간 검증: start<=end 및 제안/운영 기간 중 한 구간에 완전 포함.
  -- 두 사업 원장의 기간 컬럼명이 같으므로 jsonb로 한 번에 읽는다.
  if v_ps is not null and v_pe is not null then
    if v_ps > v_pe then
      raise exception '종료일은 시작일 이후여야 합니다.';
    end if;
    execute format('select to_jsonb(p) from public.%I p where p.id = $1', v_prog_table)
      into v_prog using p_program_id;
    v_prop_start := (v_prog->>'proposal_start_date')::date;
    v_prop_end   := (v_prog->>'proposal_end_date')::date;
    v_op_start   := (v_prog->>'start_date')::date;
    v_op_end     := (v_prog->>'end_date')::date;
    if (v_prop_start is not null and v_prop_end is not null)
       or (v_op_start is not null and v_op_end is not null) then
      if not (
        (v_prop_start is not null and v_prop_end is not null and v_ps >= v_prop_start and v_pe <= v_prop_end)
        or (v_op_start is not null and v_op_end is not null and v_ps >= v_op_start and v_pe <= v_op_end)
      ) then
        raise exception '모듈 기간은 제안 기간 또는 운영 기간 내에서만 설정할 수 있습니다.';
      end if;
    end if;
  end if;

  -- 담당자 검증(전체 사전 확인; 풀 소속은 트리거와 이중 방어).
  -- 업무롤 길이도 여기서 함께 본다 — CHECK가 최종 강제하지만, 그때 나오는 오류 문구는
  -- 담당자에게 무엇이 잘못됐는지 말해 주지 못한다.
  if p_assignees is not null then
    for v_row in select * from jsonb_array_elements(p_assignees) loop
      v_uid := (v_row->>'user_id')::uuid;
      if v_uid is null then
        raise exception '담당자 목록에 사용자 없이 들어온 항목이 있습니다.' using errcode = '22023';
      end if;
      execute format(
        'select exists (select 1 from public.%I where program_id = $1 and user_id = $2)', v_managers)
        into v_ok using p_program_id, v_uid;
      if not v_ok then
        raise exception '담당자는 사업 담당자 풀에 있는 사용자만 지정할 수 있습니다.' using errcode = '42501';
      end if;
      if char_length(coalesce(btrim(v_row->>'duty'), '')) > 200 then
        raise exception '업무롤은 200자를 넘을 수 없습니다.';
      end if;
    end loop;
  end if;

  -- 인스턴스 upsert(생성/수정).
  if v_id is null then
    insert into public.program_modules
      (entity_key, program_id, module_type, title, enabled, status, participation_mode, visibility, settings)
    values (
      p_entity_key, p_program_id, p_module_type::public.module_type, v_title, true,
      p_status::public.module_status, v_mode::public.participation_mode,
      p_visibility::public.module_visibility, coalesce(p_settings, '{}'::jsonb)
    )
    returning id into v_id;
  else
    update public.program_modules set
      title              = v_title,
      status             = p_status::public.module_status,
      participation_mode = v_mode::public.participation_mode,
      visibility         = p_visibility::public.module_visibility,
      settings           = coalesce(p_settings, '{}'::jsonb),
      updated_at         = now()
    where id = v_id;
  end if;

  -- 담당자 전량 교체. 같은 사람이 두 번 들어오면 **앞엣것만** 남긴다 — 화면이 중복 선택을
  -- 막지만 서버가 그 가정 위에 서면 안 되고, 같은 명령 안의 중복은 on conflict가 걸러 주지
  -- 못하는 자리(DO UPDATE는 같은 행을 두 번 건드릴 수 없다)라 먼저 접어서 넣는다.
  delete from public.program_module_assignees where program_module_id = v_id;
  if p_assignees is not null then
    insert into public.program_module_assignees (program_module_id, user_id, duty, assigned_by)
    select distinct on (uid) v_id, uid, duty, app.current_app_user_id()
      from (
        select (a.value->>'user_id')::uuid                        as uid,
               nullif(btrim(coalesce(a.value->>'duty', '')), '')  as duty,
               a.ordinality                                       as pos
          from jsonb_array_elements(p_assignees) with ordinality as a(value, ordinality)
      ) src
     order by uid, pos
    on conflict (program_module_id, user_id) do nothing;
  end if;

  return v_id;
end;
$_$;


ALTER FUNCTION "public"."set_program_module"("p_entity_key" "text", "p_program_id" "uuid", "p_module_id" "uuid", "p_module_type" "text", "p_title" "text", "p_status" "text", "p_visibility" "text", "p_participation_mode" "text", "p_settings" "jsonb", "p_assignees" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_program_module"("p_entity_key" "text", "p_program_id" "uuid", "p_module_id" "uuid", "p_module_type" "text", "p_title" "text", "p_status" "text", "p_visibility" "text", "p_participation_mode" "text", "p_settings" "jsonb", "p_assignees" "jsonb") IS '사업 운영 모듈 인스턴스 생성/수정 + 담당자(업무롤 포함) 전량 교체(원자). AC·M&A·PROJECT 공용이며 소유 원장은 p_entity_key가 정한다. 모듈명 유일·담당자 풀 소속·OUTCOMES 단일·기간 포함·템플릿 카탈로그 허용·업무롤 길이를 서버에서 강제한다.';



CREATE OR REPLACE FUNCTION "public"."set_program_staffing"("p_program_id" "uuid", "p_departments" "jsonb", "p_managers" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_dep_count  int;
  v_mgr_count  int;
  v_pm         int;
  v_prog_start date;
  v_prog_end   date;
  v_env_start  date;
  v_env_end    date;
  v_bad        int;
begin
  -- 인가
  if not (
    app.is_admin()
    or (app.can_write_workspace('project') and app.can_access_program(p_program_id))
  ) then
    raise exception '프로그램 담당자를 변경할 권한이 없습니다.' using errcode = '42501';
  end if;

  select count(*) into v_dep_count
  from jsonb_to_recordset(coalesce(p_departments, '[]'::jsonb))
    as d(org_version_id uuid, department_id uuid, kind text, collaboration_ratio int);
  select count(*), count(*) filter (where role = 'PM') into v_mgr_count, v_pm
  from jsonb_to_recordset(coalesce(p_managers, '[]'::jsonb))
    as m(user_id uuid, org_version_id uuid, department_id uuid, role text, allocation_rate int, start_date date, end_date date);

  -- 둘 다 비면(미배정) 전량 삭제 후 종료.
  if v_dep_count = 0 and v_mgr_count = 0 then
    delete from public.program_managers    where program_id = p_program_id;
    delete from public.program_departments where program_id = p_program_id;
    return;
  end if;
  if v_dep_count = 0 then
    raise exception '부서 구성을 먼저 설정해야 합니다.';
  end if;

  -- 부서 값 유효성(종류/비율/버전 소속)
  if exists (
    select 1 from jsonb_to_recordset(p_departments) as d(org_version_id uuid, kind text, collaboration_ratio int)
    where d.org_version_id is null or d.kind not in ('MAIN', 'COLLAB')
       or d.collaboration_ratio is null or d.collaboration_ratio < 1 or d.collaboration_ratio > 100
  ) then
    raise exception '부서 종류(MAIN/COLLAB)·협업비율(1~100)·org 버전을 올바르게 입력하세요.';
  end if;
  -- 부서는 해당 org 버전 소속이어야 함(departments.version_id = org_version_id).
  if exists (
    select 1 from jsonb_to_recordset(p_departments) as d(org_version_id uuid, department_id uuid)
    left join public.departments dd on dd.id = d.department_id
    where dd.id is null or dd.version_id <> d.org_version_id
  ) then
    raise exception '부서가 지정한 조직 버전에 속하지 않습니다.';
  end if;
  -- 단계(버전) 그룹별: 메인 정확히 1개 + 협업비율 합 100 + 부서 중복 없음.
  if exists (
    select 1 from jsonb_to_recordset(p_departments) as d(org_version_id uuid, department_id uuid, kind text, collaboration_ratio int)
    group by d.org_version_id
    having count(*) filter (where d.kind = 'MAIN') <> 1
        or sum(d.collaboration_ratio) <> 100
        or count(*) <> count(distinct d.department_id)
  ) then
    raise exception '각 조직 버전(단계)에서 메인 1개 + 협업비율 합 100%%를 지켜야 합니다.';
  end if;

  -- 담당자 값 유효성
  if v_mgr_count = 0 then raise exception '담당자를 1명 이상 배정해야 합니다.'; end if;
  if v_pm < 1 then raise exception 'PM을 최소 1명(구간) 지정해야 합니다.'; end if;
  if exists (
    select 1 from jsonb_to_recordset(p_managers) as m(role text, allocation_rate int, start_date date, end_date date, org_version_id uuid, department_id uuid)
    where m.role is null or m.role not in ('PM', 'MEMBER')
       or m.allocation_rate is null or m.allocation_rate < 1 or m.allocation_rate > 100
       or m.start_date is null or m.end_date is null or m.start_date > m.end_date
       or m.org_version_id is null or m.department_id is null
  ) then
    raise exception '담당자 구간의 부서·역할·투입률(1~100)·수행 기간을 올바르게 입력하세요.';
  end if;
  -- 담당자 (버전, 부서)는 그 버전에 지정된 부서 중 하나여야 함.
  if exists (
    select 1 from jsonb_to_recordset(p_managers) as m(org_version_id uuid, department_id uuid)
    where not exists (
      select 1 from jsonb_to_recordset(p_departments) as d(org_version_id uuid, department_id uuid)
      where d.org_version_id = m.org_version_id and d.department_id = m.department_id)
  ) then
    raise exception '담당자의 부서는 해당 단계에 지정된 부서 중 하나여야 합니다.';
  end if;
  -- 담당자 구간은 그 org 버전 유효기간[from, to) 안이어야 함.
  if exists (
    select 1 from jsonb_to_recordset(p_managers) as m(org_version_id uuid, start_date date, end_date date)
    join public.org_versions ov on ov.id = m.org_version_id
    where m.start_date < ov.effective_from or (ov.effective_to is not null and m.end_date >= ov.effective_to)
  ) then
    raise exception '담당자 구간이 소속 조직 버전의 유효기간을 벗어났습니다.';
  end if;

  -- 프로그램 기간 내
  select start_date, end_date into v_prog_start, v_prog_end from public.programs where id = p_program_id;
  if v_prog_start is not null and v_prog_end is not null then
    if exists (
      select 1 from jsonb_to_recordset(p_managers) as m(start_date date, end_date date)
      where m.start_date < v_prog_start or m.end_date > v_prog_end
    ) then
      raise exception '담당자 수행 기간은 프로그램 기간(% ~ %) 내여야 합니다.', v_prog_start, v_prog_end;
    end if;
  end if;

  select coalesce(v_prog_start, min(start_date)), coalesce(v_prog_end, max(end_date))
    into v_env_start, v_env_end
  from jsonb_to_recordset(p_managers) as m(start_date date, end_date date);

  -- 핵심 불변식: 매일 × '그날 유효한 설정된 단계'의 부서마다 활성 담당자 합 = 협업비율.
  with days as (select g.d::date d from generate_series(v_env_start, v_env_end, interval '1 day') g(d)),
  cfg_ver as (
    select distinct d.org_version_id, ov.effective_from, ov.effective_to
    from jsonb_to_recordset(p_departments) as d(org_version_id uuid, department_id uuid, kind text, collaboration_ratio int)
    join public.org_versions ov on ov.id = d.org_version_id
  ),
  day_ver as (
    select days.d, cv.org_version_id
    from days join cfg_ver cv
      on days.d >= cv.effective_from and (cv.effective_to is null or days.d < cv.effective_to)
  )
  select count(*) into v_bad
  from day_ver dv
  join jsonb_to_recordset(p_departments) as dep(org_version_id uuid, department_id uuid, kind text, collaboration_ratio int)
    on dep.org_version_id = dv.org_version_id
  where dep.collaboration_ratio <> (
    select coalesce(sum(m.allocation_rate), 0)
    from jsonb_to_recordset(p_managers)
      as m(org_version_id uuid, department_id uuid, allocation_rate int, start_date date, end_date date)
    where m.org_version_id = dep.org_version_id and m.department_id = dep.department_id
      and m.start_date <= dv.d and m.end_date >= dv.d
  );
  if v_bad > 0 then
    raise exception '단계별로 각 부서를 전 구간에서 협업비율만큼 채워야 합니다. (미충족 %건)', v_bad;
  end if;

  -- 원자 교체
  delete from public.program_managers    where program_id = p_program_id;
  delete from public.program_departments where program_id = p_program_id;
  insert into public.program_departments (program_id, org_version_id, department_id, kind, collaboration_ratio)
  select p_program_id, d.org_version_id, d.department_id, d.kind::public.program_department_kind, d.collaboration_ratio
  from jsonb_to_recordset(p_departments) as d(org_version_id uuid, department_id uuid, kind text, collaboration_ratio int);
  insert into public.program_managers
    (program_id, org_version_id, user_id, department_id, role, allocation_rate, start_date, end_date, assigned_by)
  select
    p_program_id, m.org_version_id, m.user_id, m.department_id, m.role::public.program_manager_role,
    m.allocation_rate, m.start_date, m.end_date, app.current_app_user_id()
  from jsonb_to_recordset(p_managers)
    as m(user_id uuid, org_version_id uuid, department_id uuid, role text, allocation_rate int, start_date date, end_date date);
end;
$$;


ALTER FUNCTION "public"."set_program_staffing"("p_program_id" "uuid", "p_departments" "jsonb", "p_managers" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_program_staffing"("p_program_id" "uuid", "p_departments" "jsonb", "p_managers" "jsonb") IS 'AC 프로그램 부서+담당자 배치 org 버전(단계)별 독립 검증·원자 교체. 단계별 메인1·협업비율합100, 단계별 일별 부서합=협업비율.';



CREATE OR REPLACE FUNCTION "public"."set_user_branches"("p_user_id" "uuid", "p_branch_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if not (app.is_admin() or app.can_write_workspace('management')) then
    raise exception '지사 배정은 관리자 또는 인사 관리 권한자만 변경할 수 있습니다.'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
      from public.users u
     where u.id = p_user_id
       and u.deleted_at is null
       and u.user_type::text not in ('external_startup', 'external_expert', 'temporary_guest')
  ) then
    raise exception '지사에 배정할 수 없는 계정입니다.' using errcode = '22023';
  end if;

  -- 해제: 인사 관리 폼이 보여주는 범위(활성 지사)에서 선택이 빠진 것만 지운다.
  -- 비활성·삭제된 지사의 기존 배정은 화면에 뜨지 않으므로 여기서 건드리지 않는다 —
  -- 보이지 않는 값을 저장 버튼 한 번으로 지우면 되살릴 근거가 남지 않는다.
  delete from public.branch_members m
   using public.branches b
   where m.user_id = p_user_id
     and b.id = m.branch_id
     and b.deleted_at is null
     and b.is_active
     and not (m.branch_id = any (coalesce(p_branch_ids, '{}'::uuid[])));

  -- 추가: 지사별 명단 맨 뒤에 붙인다. 이미 배정된 지사는 행을 그대로 두어
  -- '지사 관리'에서 잡아둔 표기 순서(sort_order)가 흔들리지 않게 한다.
  insert into public.branch_members (branch_id, user_id, sort_order)
  select b.id,
         p_user_id,
         coalesce(
           (select max(m2.sort_order) from public.branch_members m2 where m2.branch_id = b.id),
           0
         ) + 1
    from public.branches b
   where b.id = any (coalesce(p_branch_ids, '{}'::uuid[]))
     and b.deleted_at is null
     and b.is_active
  on conflict (branch_id, user_id) do nothing;
end $$;


ALTER FUNCTION "public"."set_user_branches"("p_user_id" "uuid", "p_branch_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_user_branches"("p_user_id" "uuid", "p_branch_ids" "uuid"[]) IS '임직원 한 명의 지사 배정 교체(인사 관리 경로). admin 또는 management write만 실행 가능(함수 내부 검사). 활성 지사만 대상이며 비활성 지사의 기존 배정은 보존한다. set_branch_members()와 함께 branch_members의 유일한 쓰기 경로.';



CREATE OR REPLACE FUNCTION "public"."start_meeting_recording"("p_minute_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_user uuid := app.current_app_user_id();
  v_id uuid;
begin
  if v_user is null or not app.can_write_workspace('office') then
    raise exception '회의 녹음 권한이 없습니다.' using errcode = '42501';
  end if;
  if p_minute_id is not null and not app.is_minute_author(p_minute_id) then
    raise exception '회의록 작성자만 녹음을 연결할 수 있습니다.' using errcode = '42501';
  end if;

  insert into public.meeting_recordings (minute_id, owner_id)
  values (p_minute_id, v_user)
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."start_meeting_recording"("p_minute_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."startup_facet_counts"("p_keyword" "text" DEFAULT NULL::"text", "p_mine_user" "uuid" DEFAULT NULL::"uuid", "p_locations" "text"[] DEFAULT NULL::"text"[], "p_regions" "uuid"[] DEFAULT NULL::"uuid"[], "p_region_unset" boolean DEFAULT NULL::boolean, "p_industries" "text"[] DEFAULT NULL::"text"[], "p_stages" "text"[] DEFAULT NULL::"text"[], "p_stage_unset" boolean DEFAULT NULL::boolean, "p_categories" "text"[] DEFAULT NULL::"text"[], "p_category_unset" boolean DEFAULT NULL::boolean, "p_statuses" "text"[] DEFAULT NULL::"text"[], "p_age_min" integer DEFAULT NULL::integer, "p_age_max" integer DEFAULT NULL::integer, "p_search_email" boolean DEFAULT false, "p_search_phone" boolean DEFAULT false) RETURNS TABLE("axis" "text", "key" "text", "cnt" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  -- 구분 축 — 구분 조건(p_categories·p_category_unset)을 빼고 센다.
  select 'category'::text,
         coalesce(f.category, 'UNSET'),
         count(*)::bigint
    from app.startup_pool_filtered(
           p_keyword, p_mine_user, p_locations, p_regions, p_region_unset,
           p_industries, p_stages, p_stage_unset, null::text[], null::boolean,
           p_statuses, p_age_min, p_age_max, p_search_email, p_search_phone) f
   group by 2
  union all
  -- 권역 축 — 권역 조건(p_regions·p_region_unset)을 빼고 센다.
  -- 소재지 조건은 남긴다: 소재지는 권역의 아래 단이라, 시·도를 골라 둔 채 권역 칸을 보면
  -- 그 시·도가 속한 권역만 서는 것이 사실이다.
  select 'region'::text,
         coalesce(f.region_tag_id::text, 'UNSET'),
         count(*)::bigint
    from app.startup_pool_filtered(
           p_keyword, p_mine_user, p_locations, null::uuid[], null::boolean,
           p_industries, p_stages, p_stage_unset, p_categories, p_category_unset,
           p_statuses, p_age_min, p_age_max, p_search_email, p_search_phone) f
   group by 2
$$;


ALTER FUNCTION "public"."startup_facet_counts"("p_keyword" "text", "p_mine_user" "uuid", "p_locations" "text"[], "p_regions" "uuid"[], "p_region_unset" boolean, "p_industries" "text"[], "p_stages" "text"[], "p_stage_unset" boolean, "p_categories" "text"[], "p_category_unset" boolean, "p_statuses" "text"[], "p_age_min" integer, "p_age_max" integer, "p_search_email" boolean, "p_search_phone" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."startup_facet_counts"("p_keyword" "text", "p_mine_user" "uuid", "p_locations" "text"[], "p_regions" "uuid"[], "p_region_unset" boolean, "p_industries" "text"[], "p_stages" "text"[], "p_stage_unset" boolean, "p_categories" "text"[], "p_category_unset" boolean, "p_statuses" "text"[], "p_age_min" integer, "p_age_max" integer, "p_search_email" boolean, "p_search_phone" boolean) IS 'STARTUP 목록 요약 카드(구분·권역) 집계. app.startup_pool_filtered를 그대로 불러 축별로 묶으므로 필터 판정이 목록과 어긋나지 않는다. 각 축은 자기 조건을 빼고 세어 타일이 필터로 동작한다. 값이 비어 있는 행의 키는 ''UNSET''. SECURITY INVOKER.';



CREATE OR REPLACE FUNCTION "public"."startup_fund_investments"("p_startup_id" "uuid") RETURNS TABLE("investment_id" "uuid", "fund_id" "uuid", "fund_name" "text", "invested_at" "date", "round" "text", "valuation" numeric, "amount" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
begin
  if not app.can_read_workspace('startup') then
    raise exception 'insufficient privilege' using errcode = '42501';
  end if;

  return query
    select i.id, i.fund_id, f.name, i.invested_at, i.stage, i.valuation, i.amount
      from public.investments i
      join public.funds f on f.id = i.fund_id
     where i.startup_id = p_startup_id
       and i.deleted_at is null
       and f.deleted_at is null
     order by i.invested_at desc nulls last;
end;
$$;


ALTER FUNCTION "public"."startup_fund_investments"("p_startup_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."startup_pool_entities"("p_keyword" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 30, "p_offset" integer DEFAULT 0, "p_mine_user" "uuid" DEFAULT NULL::"uuid", "p_locations" "text"[] DEFAULT NULL::"text"[], "p_regions" "uuid"[] DEFAULT NULL::"uuid"[], "p_region_unset" boolean DEFAULT NULL::boolean, "p_industries" "text"[] DEFAULT NULL::"text"[], "p_stages" "text"[] DEFAULT NULL::"text"[], "p_stage_unset" boolean DEFAULT NULL::boolean, "p_categories" "text"[] DEFAULT NULL::"text"[], "p_category_unset" boolean DEFAULT NULL::boolean, "p_statuses" "text"[] DEFAULT NULL::"text"[], "p_age_min" integer DEFAULT NULL::integer, "p_age_max" integer DEFAULT NULL::integer, "p_search_email" boolean DEFAULT false, "p_search_phone" boolean DEFAULT false) RETURNS TABLE("row_json" "jsonb", "total_count" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'app', 'public'
    AS $$
  with f as (
    select * from app.startup_pool_filtered(
      p_keyword, p_mine_user, p_locations, p_regions, p_region_unset,
      p_industries, p_stages, p_stage_unset, p_categories, p_category_unset,
      p_statuses, p_age_min, p_age_max, p_search_email, p_search_phone)
  ),
  total as (select count(*)::bigint as c from f),
  page as (
    select f.id from f order by f.updated_at desc nulls last, f.id limit p_limit offset p_offset
  )
  select
    to_jsonb(s)
      || jsonb_build_object(
           'creator', case when cu.id is null then null
                           else jsonb_build_object('id', cu.id, 'name', cu.name) end,
           'managers', coalesce(mg.managers, '[]'::jsonb))
      as row_json,
    (select c from total) as total_count
    from page
    join public.startups s on s.id = page.id
    left join public.users cu on cu.id = s.created_by
    left join lateral (
      select jsonb_agg(
               jsonb_build_object(
                 'user_id', sm.user_id,
                 'is_lead', sm.is_lead,
                 'user', case when mu.id is null then null
                              else jsonb_build_object('id', mu.id, 'name', mu.name) end)
               order by sm.is_lead desc) as managers
        from public.startup_managers sm
        left join public.users mu on mu.id = sm.user_id
       where sm.startup_id = s.id
    ) mg on true
   order by s.updated_at desc nulls last, s.id
$$;


ALTER FUNCTION "public"."startup_pool_entities"("p_keyword" "text", "p_limit" integer, "p_offset" integer, "p_mine_user" "uuid", "p_locations" "text"[], "p_regions" "uuid"[], "p_region_unset" boolean, "p_industries" "text"[], "p_stages" "text"[], "p_stage_unset" boolean, "p_categories" "text"[], "p_category_unset" boolean, "p_statuses" "text"[], "p_age_min" integer, "p_age_max" integer, "p_search_email" boolean, "p_search_phone" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."startup_pool_entities"("p_keyword" "text", "p_limit" integer, "p_offset" integer, "p_mine_user" "uuid", "p_locations" "text"[], "p_regions" "uuid"[], "p_region_unset" boolean, "p_industries" "text"[], "p_stages" "text"[], "p_stage_unset" boolean, "p_categories" "text"[], "p_category_unset" boolean, "p_statuses" "text"[], "p_age_min" integer, "p_age_max" integer, "p_search_email" boolean, "p_search_phone" boolean) IS 'STARTUP 기업 목록 한 페이지. 필터 판정은 app.startup_pool_filtered가 소유하고 여기서는 정렬·페이지·표시용 JSON 조립만 한다. row_json은 startups 행 전체 + creator/managers 임베드이며 total_count는 필터 반영 건수다. SECURITY INVOKER.';



CREATE OR REPLACE FUNCTION "public"."today_birthdays"() RETURNS TABLE("user_id" "uuid", "user_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
#variable_conflict use_column
declare
  v_today    date := app.kst_today();
  v_feb_last boolean;
begin
  -- SECURITY DEFINER로 MANAGEMENT 원장을 읽으므로 호출자 자격을 함수 안에서 먼저 확인한다.
  -- 게스트를 조용히 빈 목록으로 돌려보내지 않고 막는 이유는, 이 함수가 열려 있다는 사실
  -- 자체가 외부 계정에게 답할 물음이 아니기 때문이다.
  if app.current_app_user_id() is null or app.is_guest() then
    raise exception '권한이 없습니다.' using errcode = '42501';
  end if;

  -- 평년의 2월 28일인가. 2월 29일생은 그날 함께 선다(민법 제160조의 '말일' 기준) — 그러지
  -- 않으면 4년에 세 번 그 사람의 생일이 어디에도 서지 않는다.
  v_feb_last := extract(month from v_today) = 2
                and extract(day from v_today) = 28
                and v_today = (date_trunc('month', v_today) + interval '1 month - 1 day')::date;

  return query
    select u.id, u.name
    from public.hr_profiles h
    join public.users u on u.id = h.user_id
    where h.birth_date is not null
      -- 재직 중인 내부 임직원만. 게스트는 hr_profiles를 갖지 않지만, 유형 판정을 함께 걸어
      -- 그 전제가 깨지는 날에도 이 창구로는 새지 않게 한다.
      and u.is_active
      and u.deleted_at is null
      and not app.is_guest_user_type(u.user_type)
      and (
        (extract(month from h.birth_date) = extract(month from v_today)
         and extract(day from h.birth_date) = extract(day from v_today))
        or (v_feb_last
            and extract(month from h.birth_date) = 2
            and extract(day from h.birth_date) = 29)
      )
    order by u.name;
end;
$$;


ALTER FUNCTION "public"."today_birthdays"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."today_birthdays"() IS '오늘(KST) 생일인 재직 임직원의 id와 이름. 생년월일은 MANAGEMENT 전용 hr_profiles에 잠긴 채로 두고 이 창구는 연도·월·일 어느 것도 답하지 않는다. 외부 게스트·비로그인은 42501로 막는다.';



CREATE OR REPLACE FUNCTION "public"."update_entity"("p_table" "text", "p_id" "uuid", "p_values" "jsonb", "p_note" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_cols text;
  v_set  text;
  v_rows integer;
begin
  if not app.has_contribution_trigger(p_table) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  if p_values is null or jsonb_typeof(p_values) <> 'object' or p_values = '{}'::jsonb then
    raise exception 'empty_values' using errcode = '22023';
  end if;
  if coalesce(btrim(p_note), '') = '' then
    raise exception 'reason_required' using errcode = '23514';
  end if;
  if p_values ?| array['id', 'created_at', 'created_by', 'deleted_at', 'merged_into_id'] then
    raise exception 'protected_column' using errcode = '22023';
  end if;

  perform set_config('app.contribution_ctx',
                     jsonb_build_object('note', btrim(p_note))::text,
                     true);

  select string_agg(format('%I', k), ', ' order by k),
         string_agg(format('%I = r.%I', k, k), ', ' order by k)
    into v_cols, v_set
    from jsonb_object_keys(p_values) as k;

  execute format(
    'update public.%I t set %s from (select %s from jsonb_populate_record(null::public.%I, $1)) r where t.id = $2',
    p_table, v_set, v_cols, p_table
  ) using p_values, p_id;
  get diagnostics v_rows = row_count;

  -- 0행이면 대상이 없거나 RLS가 막은 것이다. 둘을 구분해 알려주지 않는다.
  if v_rows = 0 then
    raise exception 'not_found_or_forbidden' using errcode = '42501';
  end if;
end $_$;


ALTER FUNCTION "public"."update_entity"("p_table" "text", "p_id" "uuid", "p_values" "jsonb", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_entity"("p_table" "text", "p_id" "uuid", "p_values" "jsonb", "p_note" "text") IS '수정 저장(사유 필수): 사유를 트랜잭션 컨텍스트에 실어 원장을 UPDATE한다. 원장 변경과 사유 기록이 한 트랜잭션. SECURITY INVOKER — 쓰기 권한은 각 원장 RLS가 판정한다.';



CREATE OR REPLACE FUNCTION "public"."update_my_profile"("p_note" "text" DEFAULT NULL::"text", "p_photo" "text" DEFAULT NULL::"text", "p_background" "jsonb" DEFAULT NULL::"jsonb", "p_philosophy" "text" DEFAULT NULL::"text", "p_interests" "jsonb" DEFAULT NULL::"jsonb", "p_one_liner" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid        uuid := app.current_app_user_id();
  v_photo      text := nullif(btrim(coalesce(p_photo, '')), '');
  v_philosophy text := nullif(btrim(coalesce(p_philosophy, '')), '');
  v_one_liner  text := nullif(btrim(coalesce(p_one_liner, '')), '');
  v_bg         jsonb;
  v_interests  jsonb;
  v_key        text;
  v_item       jsonb;
  -- 약력 섹션 키: careerConfig.ts의 CAREER_SECTIONS와 동일 집합.
  v_sections constant text[] := array['education', 'career', 'certifications', 'awards'];
  -- 관심분야 상한: noteConfig.ts의 MAX_INTERESTS와 같은 값.
  v_max_interests constant int := 5;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.' using errcode = '42501';
  end if;

  -- 사진: 이미지 data URL만 허용. 원본 2MB의 base64 팽창(약 1.37배)을 감안한 길이 상한.
  if v_photo is not null then
    if v_photo !~ '^data:image/[a-zA-Z0-9.+-]+;base64,' then
      raise exception '사진은 이미지 파일만 첨부할 수 있습니다.' using errcode = '22023';
    end if;
    if length(v_photo) > 2800000 then
      raise exception '이미지는 2MB 이하만 첨부할 수 있습니다.' using errcode = '22023';
    end if;
  end if;

  -- 약력: {섹션키: [ {필드: 값}, ... ]} 형태만 허용하고 모르는 키는 거부한다.
  v_bg := coalesce(p_background, '{}'::jsonb);
  if jsonb_typeof(v_bg) <> 'object' then
    raise exception '약력 형식이 올바르지 않습니다.' using errcode = '22023';
  end if;
  if length(v_bg::text) > 100000 then
    raise exception '약력이 너무 깁니다.' using errcode = '22023';
  end if;
  for v_key in select jsonb_object_keys(v_bg) loop
    if not (v_key = any (v_sections)) then
      raise exception '약력에 허용되지 않은 항목(%)이 있습니다.', v_key using errcode = '22023';
    end if;
    if jsonb_typeof(v_bg -> v_key) <> 'array' then
      raise exception '약력 형식이 올바르지 않습니다.' using errcode = '22023';
    end if;
  end loop;

  -- 관심분야: 산업 태그명 문자열 배열만 허용. 빈 배열은 미지정(null)과 같게 다룬다.
  if p_interests is null or p_interests = 'null'::jsonb then
    v_interests := null;
  else
    if jsonb_typeof(p_interests) <> 'array' then
      raise exception '관심분야 형식이 올바르지 않습니다.' using errcode = '22023';
    end if;
    if jsonb_array_length(p_interests) > v_max_interests then
      raise exception '관심분야는 최대 %개까지 선택할 수 있습니다.', v_max_interests using errcode = '22023';
    end if;
    for v_item in select jsonb_array_elements(p_interests) loop
      if jsonb_typeof(v_item) <> 'string' or length(v_item #>> '{}') > 60 then
        raise exception '관심분야 형식이 올바르지 않습니다.' using errcode = '22023';
      end if;
    end loop;
    v_interests := nullif(p_interests, '[]'::jsonb);
  end if;

  -- 자유 텍스트 상한(철학은 문단 여러 개, 한마디는 짧은 글 기준).
  if length(coalesce(v_philosophy, '')) > 4000 then
    raise exception '액셀러레이터 철학이 너무 깁니다.' using errcode = '22023';
  end if;
  if length(coalesce(v_one_liner, '')) > 2000 then
    raise exception '한마디가 너무 깁니다.' using errcode = '22023';
  end if;

  update public.users
     set profile = coalesce(profile, '{}'::jsonb)
                   || jsonb_build_object(
                        'photo',      v_photo,
                        'background', v_bg,
                        'philosophy', v_philosophy,
                        'interests',  v_interests,
                        'one_liner',  v_one_liner,
                        'note',       nullif(btrim(coalesce(p_note, '')), '')
                      )
   where id = v_uid;
end;
$$;


ALTER FUNCTION "public"."update_my_profile"("p_note" "text", "p_photo" "text", "p_background" "jsonb", "p_philosophy" "text", "p_interests" "jsonb", "p_one_liner" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upload_enrich_entity"("p_table" "text", "p_id" "uuid", "p_values" "jsonb", "p_batch_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $_$
declare
  v_cols text;
  v_set  text;
  v_rows integer;
begin
  if not app.has_contribution_trigger(p_table) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;

  if p_values is null or jsonb_typeof(p_values) <> 'object' or p_values = '{}'::jsonb then
    -- 바꿀 값이 없는 재유입: 기록만 남긴다.
    insert into public.entity_contributions (entity_table, entity_id, action, source, batch_id, note)
    values (p_table, p_id, 'enriched', 'upload', p_batch_id, nullif(btrim(coalesce(p_note, '')), ''));
    return;
  end if;

  perform set_config('app.contribution_ctx',
                     jsonb_build_object(
                       'source', 'upload',
                       'batch_id', p_batch_id,
                       'action', 'enriched',
                       'note', p_note
                     )::text,
                     true);

  select string_agg(format('%I', k), ', ' order by k),
         string_agg(format('%I = r.%I', k, k), ', ' order by k)
    into v_cols, v_set
    from jsonb_object_keys(p_values) as k;

  execute format(
    'update public.%I t set %s from (select %s from jsonb_populate_record(null::public.%I, $1)) r where t.id = $2',
    p_table, v_set, v_cols, p_table
  ) using p_values, p_id;
  get diagnostics v_rows = row_count;

  if v_rows = 0 then
    raise exception 'not_found_or_forbidden' using errcode = '42501';
  end if;
end $_$;


ALTER FUNCTION "public"."upload_enrich_entity"("p_table" "text", "p_id" "uuid", "p_values" "jsonb", "p_batch_id" "uuid", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upload_enrich_entity"("p_table" "text", "p_id" "uuid", "p_values" "jsonb", "p_batch_id" "uuid", "p_note" "text") IS '대량 업로드 제자리 보강/재활성화. 보강할 값이 없는 재유입은 원장 변경이 아니므로 기록만 남긴다.';



CREATE OR REPLACE FUNCTION "public"."upload_insert_entities"("p_table" "text", "p_rows" "jsonb", "p_batch_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"[]
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_row jsonb;
  v_ids uuid[] := '{}';
begin
  if not app.has_contribution_trigger(p_table) then
    raise exception 'unsupported_entity' using errcode = '22023';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'rows_required' using errcode = '22023';
  end if;

  perform set_config('app.contribution_ctx',
                     jsonb_build_object('source', 'upload', 'batch_id', p_batch_id)::text,
                     true);

  for v_row in select * from jsonb_array_elements(p_rows)
  loop
    v_ids := v_ids || app.insert_entity_row(p_table, v_row);
  end loop;

  return v_ids;
end $$;


ALTER FUNCTION "public"."upload_insert_entities"("p_table" "text", "p_rows" "jsonb", "p_batch_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upload_insert_entities"("p_table" "text", "p_rows" "jsonb", "p_batch_id" "uuid") IS '대량 업로드 신규 등록: 배치 컨텍스트(source=upload, batch_id)를 건 채로 행들을 등록한다. 원장 등록과 이력이 한 트랜잭션이라 부분 성공이 남지 않는다.';



CREATE OR REPLACE FUNCTION "public"."withdraw_approval_document"("p_document_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public'
    AS $$
declare
  v_uid     uuid := app.current_app_user_id();
  v_drafter uuid;
  v_status  public.approval_status;
  v_round   integer;
  v_next    integer;
  v_notify  uuid[];
begin
  if v_uid is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;
  if nullif(btrim(p_reason), '') is null then
    raise exception 'a reason is required to withdraw a document' using errcode = '22023';
  end if;

  select drafter_id, status into v_drafter, v_status
    from public.approval_documents
   where id = p_document_id and deleted_at is null
   for update;

  if not found then
    raise exception 'document not found' using errcode = 'P0002';
  end if;
  if v_drafter is distinct from v_uid then
    raise exception 'only the drafter may withdraw this document' using errcode = '42501';
  end if;
  if v_status not in ('PENDING', 'IN_REVIEW', 'REVISION_REQUIRED') then
    raise exception 'only a document in progress may be withdrawn' using errcode = '42501';
  end if;
  if exists (
    select 1 from public.approval_legacy_documents where document_id = p_document_id
  ) then
    raise exception 'an imported document may not be withdrawn' using errcode = '42501';
  end if;
  -- 이 문서를 근거로 하는 지출이 살아 있으면 되가져오지 못한다. 흐르는 중인 품의에는
  -- 원래 지출이 걸릴 수 없지만(근거는 승인된 품의만), 결재 초기화로 되돌아온 품의에는
  -- 이미 걸린 지출이 남아 있다 — 그때 이 가드가 유일한 문이다.
  perform app.assert_no_active_budget_children(p_document_id);

  v_round := app.approval_current_round(p_document_id);

  select array_agg(distinct t.uid) into v_notify
    from (
      select l.approver_id as uid
        from public.approval_lines l
       where l.document_id = p_document_id
         and l.round = v_round
         and l.approver_id is not null
      union
      select r.user_id
        from public.approval_recipients r
       where r.document_id = p_document_id
    ) t;

  v_next := app.clone_approval_full_round(p_document_id);

  update public.approval_documents
     set status = 'DRAFT'::public.approval_status,
         completed_at = null,
         updated_at = now()
   where id = p_document_id;

  insert into public.approval_document_events (
    document_id, source_system, event_type, actor_user_id,
    comment_snapshot, occurred_at, source_payload
  ) values (
    p_document_id, 'NATIVE', 'DRAFT_WITHDRAWN', v_uid,
    btrim(p_reason), now(),
    jsonb_build_object('previous_round', v_round, 'next_round', v_next)
  );

  perform app.notify_approval(p_document_id, v_notify, 'approval_draft_withdrawn', v_uid);
end;
$$;


ALTER FUNCTION "public"."withdraw_approval_document"("p_document_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."withdraw_approval_document"("p_document_id" "uuid", "p_reason" "text") IS '기안 취소 — 기안자가 최종 승인 전 문서를 기안 단계(DRAFT)로 되돌린다. 이 문서를 근거로 하는 지출이 살아 있으면 거절한다. 사유 필수.';



CREATE TABLE IF NOT EXISTS "public"."_retired_asset_checkouts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "asset_id" "uuid" NOT NULL,
    "asset_name" "text" NOT NULL,
    "asset_item_type" "text",
    "asset_serial_no" "text",
    "branch_id" "uuid",
    "status" "public"."asset_checkout_status" DEFAULT 'RESERVED'::"public"."asset_checkout_status" NOT NULL,
    "checkout_at" timestamp with time zone NOT NULL,
    "due_at" timestamp with time zone NOT NULL,
    "returned_at" timestamp with time zone,
    "purpose" "text" NOT NULL,
    "destination" "text",
    "note" "text",
    "created_by" "uuid" NOT NULL,
    "created_by_name" "text",
    "decided_by" "uuid",
    "decided_at" timestamp with time zone,
    "decision_note" "text",
    "returned_by" "uuid",
    "returned_by_name" "text",
    "return_note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "quantity" integer DEFAULT 1 NOT NULL,
    CONSTRAINT "asset_checkouts_period" CHECK (("due_at" > "checkout_at")),
    CONSTRAINT "asset_checkouts_quantity_positive" CHECK (("quantity" >= 1)),
    CONSTRAINT "asset_checkouts_returned_after" CHECK ((("returned_at" IS NULL) OR ("returned_at" >= "checkout_at"))),
    CONSTRAINT "asset_checkouts_returned_pair" CHECK ((("status" = 'RETURNED'::"public"."asset_checkout_status") = ("returned_at" IS NOT NULL)))
);


ALTER TABLE "public"."_retired_asset_checkouts" OWNER TO "postgres";


COMMENT ON TABLE "public"."_retired_asset_checkouts" IS '[퇴역 2026-09-06] 구 public.asset_checkouts — 2026-07-30~08-25에 운영한 반출 예약·승인·반납 기록 14행. 반출 예약 기능을 도입하지 않기로 확정하여 흐름 트리거·함수를 걷고 표는 기록 보존을 위해 개명만 했다(물리 삭제 금지). 앱 롤의 권한은 회수했고 RLS 정책은 남아 있다 — 권한을 되돌릴 일이 생기면 정책이 먼저 서 있어야 한다.';



COMMENT ON COLUMN "public"."_retired_asset_checkouts"."asset_name" IS '등록 시점 자산명 스냅샷. 대장은 그때의 사실이며, 임직원 전원이 assets를 읽을 수는 없다.';



COMMENT ON COLUMN "public"."_retired_asset_checkouts"."due_at" IS '반납 예정 일시. 기간 점유의 끝이라 필수다(끝이 없으면 겹침을 판정할 수 없다).';



COMMENT ON COLUMN "public"."_retired_asset_checkouts"."returned_at" IS '실제 반납 일시. 상태 RETURNED와 짝을 이룬다(check 제약).';



COMMENT ON COLUMN "public"."_retired_asset_checkouts"."quantity" IS '이번 반출로 들고 나가는 개수. 보유 수량에서 이 값만큼 잔여가 줄어든다.';



COMMENT ON CONSTRAINT "asset_checkouts_returned_after" ON "public"."_retired_asset_checkouts" IS '돌아온 시각은 나간 시각보다 앞설 수 없다. 어긋나는 값이 들어오면 막지 않고 전이 트리거(app.validate_asset_checkout_transition)가 checkout_at을 returned_at까지 당겨 맞춘다 — 반납은 언제든 받는다.';



