    "source_was_deleted" boolean DEFAULT false NOT NULL,
    "source_deleted_at" timestamp with time zone,
    "content_html" "text",
    "content_text" "text",
    "approval_line_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "print_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "source_metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "source_row_no" bigint,
    "source_row_sha256" "text",
    "imported_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "approval_legacy_documents_approval_line_snapshot_check" CHECK (("jsonb_typeof"("approval_line_snapshot") = 'object'::"text")),
    CONSTRAINT "approval_legacy_documents_print_snapshot_check" CHECK (("jsonb_typeof"("print_snapshot") = 'object'::"text")),
    CONSTRAINT "approval_legacy_documents_source_document_no_check" CHECK (("source_document_no" <> ''::"text")),
    CONSTRAINT "approval_legacy_documents_source_metadata_check" CHECK (("jsonb_typeof"("source_metadata") = 'object'::"text")),
    CONSTRAINT "approval_legacy_documents_source_row_no_check" CHECK ((("source_row_no" IS NULL) OR ("source_row_no" >= 0))),
    CONSTRAINT "approval_legacy_documents_source_row_sha256_check" CHECK ((("source_row_sha256" IS NULL) OR ("source_row_sha256" ~ '^[0-9A-Fa-f]{64}$'::"text"))),
    CONSTRAINT "approval_legacy_documents_source_system_check" CHECK (("source_system" <> ''::"text"))
);


ALTER TABLE "public"."approval_legacy_documents" OWNER TO "postgres";


COMMENT ON TABLE "public"."approval_legacy_documents" IS 'approval_documents와 1:1인 하이웍스 원본 HTML·인쇄·결재선·삭제 스냅샷.';



CREATE TABLE IF NOT EXISTS "public"."approval_legacy_import_batches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source_system" "text" DEFAULT 'HIWORKS'::"text" NOT NULL,
    "source_file_name" "text" NOT NULL,
    "source_archive_path" "text",
    "source_archive_sha256" "text",
    "source_metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "expected_document_count" bigint DEFAULT 0 NOT NULL,
    "imported_document_count" bigint DEFAULT 0 NOT NULL,
    "failed_document_count" bigint DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'PENDING'::"text" NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "approval_legacy_import_batches_check" CHECK (((("imported_document_count" + "failed_document_count") <= "expected_document_count") OR ("expected_document_count" = 0))),
    CONSTRAINT "approval_legacy_import_batches_expected_document_count_check" CHECK (("expected_document_count" >= 0)),
    CONSTRAINT "approval_legacy_import_batches_failed_document_count_check" CHECK (("failed_document_count" >= 0)),
    CONSTRAINT "approval_legacy_import_batches_imported_document_count_check" CHECK (("imported_document_count" >= 0)),
    CONSTRAINT "approval_legacy_import_batches_source_archive_sha256_check" CHECK ((("source_archive_sha256" IS NULL) OR ("source_archive_sha256" ~ '^[0-9A-Fa-f]{64}$'::"text"))),
    CONSTRAINT "approval_legacy_import_batches_source_metadata_check" CHECK (("jsonb_typeof"("source_metadata") = 'object'::"text")),
    CONSTRAINT "approval_legacy_import_batches_source_system_check" CHECK (("source_system" <> ''::"text")),
    CONSTRAINT "approval_legacy_import_batches_status_check" CHECK (("status" = ANY (ARRAY['PENDING'::"text", 'RUNNING'::"text", 'COMPLETED'::"text", 'FAILED'::"text", 'CANCELLED'::"text"])))
);


ALTER TABLE "public"."approval_legacy_import_batches" OWNER TO "postgres";


COMMENT ON TABLE "public"."approval_legacy_import_batches" IS '하이웍스 전자결재 백업 적재 배치. 원본 private archive 경로·체크섬·진행률을 보관한다.';



CREATE TABLE IF NOT EXISTS "public"."approval_legacy_participants" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "document_id" "uuid" NOT NULL,
    "actor_id" "uuid",
    "source_participant_key" "text",
    "source_role" "text",
    "normalized_role" "text",
    "source_line_section" "text",
    "step_order" integer,
    "source_decision" "text",
    "normalized_decision" "text",
    "decided_at" timestamp with time zone,
    "original_name" "text" NOT NULL,
    "original_department" "text",
    "original_position" "text",
    "parsing_confidence" numeric(5,4),
    "source_metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "approval_legacy_participants_normalized_decision_check" CHECK ((("normalized_decision" IS NULL) OR ("normalized_decision" = ANY (ARRAY['PENDING'::"text", 'APPROVED'::"text", 'REJECTED'::"text", 'CONFIRMED'::"text"])))),
    CONSTRAINT "approval_legacy_participants_normalized_role_check" CHECK ((("normalized_role" IS NULL) OR ("normalized_role" = ANY (ARRAY['DRAFTER'::"text", 'APPROVER'::"text", 'AGREEMENT'::"text", 'FINANCE_AGREEMENT'::"text", 'CC'::"text", 'CONFIRMER'::"text", 'OTHER'::"text"])))),
    CONSTRAINT "approval_legacy_participants_original_name_check" CHECK (("original_name" <> ''::"text")),
    CONSTRAINT "approval_legacy_participants_parsing_confidence_check" CHECK ((("parsing_confidence" IS NULL) OR (("parsing_confidence" >= (0)::numeric) AND ("parsing_confidence" <= (1)::numeric)))),
    CONSTRAINT "approval_legacy_participants_source_metadata_check" CHECK (("jsonb_typeof"("source_metadata") = 'object'::"text")),
    CONSTRAINT "approval_legacy_participants_step_order_check" CHECK ((("step_order" IS NULL) OR ("step_order" >= 0)))
);


ALTER TABLE "public"."approval_legacy_participants" OWNER TO "postgres";


COMMENT ON TABLE "public"."approval_legacy_participants" IS '하이웍스 결재선 HTML에서 파싱한 문서 당시 참여자 스냅샷.';



CREATE TABLE IF NOT EXISTS "public"."approval_lines" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "document_id" "uuid" NOT NULL,
    "approver_id" "uuid",
    "step_order" integer DEFAULT 1 NOT NULL,
    "decision" "public"."approval_decision" DEFAULT 'PENDING'::"public"."approval_decision" NOT NULL,
    "comment" "text",
    "decided_at" timestamp with time zone,
    "kind" "public"."approval_line_kind" DEFAULT 'APPROVAL'::"public"."approval_line_kind" NOT NULL,
    "round" integer DEFAULT 1 NOT NULL,
    "return_to_step" integer,
    "return_via_drafter" boolean,
    "return_reset_agreement" boolean
);


ALTER TABLE "public"."approval_lines" OWNER TO "postgres";


COMMENT ON COLUMN "public"."approval_lines"."kind" IS '결재선 구분. APPROVAL=결재 / AGREEMENT=합의 / FINANCE_AGREEMENT=재무합의. 세 구분 모두 자기 구분 안에서 step_order 순차로 흐르며(앞 순번이 처리해야 다음 차례), 구분끼리는 서로를 기다리지 않는다(결재 1번과 합의 1번은 동시에 각자의 차례일 수 있다). 문서 최종 승인은 구분과 무관하게 모든 행이 승인됐을 때이며, 하나라도 반려되면 문서가 반려된다. 참조(열람 전용, 순번 없음)는 이 원장이 아니라 approval_recipients가 담는다.';



COMMENT ON COLUMN "public"."approval_lines"."round" IS '결재 회차. 되돌림·재상신은 기존 행을 지우거나 되돌리지 않고 다시 도는 구간만 다음 회차로 복제한다. 현재 회차는 max(round) 파생이며 문서에 따로 적지 않는다.';



COMMENT ON COLUMN "public"."approval_lines"."return_to_step" IS '2026-09-10 이전 되돌림 이력. 새 처리에서는 사용하지 않으며 과거 결재 사실 보존을 위해 유지한다.';



COMMENT ON COLUMN "public"."approval_lines"."return_via_drafter" IS '2026-09-10 이전 기안자 경유 이력. 반려·보완 분리 후 새 처리에서는 사용하지 않는다.';



COMMENT ON COLUMN "public"."approval_lines"."return_reset_agreement" IS '2026-09-10 이전 합의 재요청 이력. 보완 재상신은 모든 미처리 자리만 이어가므로 사용하지 않는다.';



CREATE TABLE IF NOT EXISTS "public"."approval_program_links" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "document_id" "uuid" NOT NULL,
    "target_type" "text" NOT NULL,
    "target_id" "uuid" NOT NULL,
    "note" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "approval_program_links_target_type_check" CHECK (("target_type" = ANY (ARRAY['program'::"text", 'ma_program'::"text", 'fund'::"text"])))
);


ALTER TABLE "public"."approval_program_links" OWNER TO "postgres";


COMMENT ON TABLE "public"."approval_program_links" IS '전자결재 문서 ↔ 사업(AC/M&A/PROJECT) 다형 연동. 방향 있는 참조라 document_id가 늘 왼쪽이다. 읽기 app.can_read_approval(문서), 쓰기 app.is_approval_participant(문서) + app.can_link_entity_target(대상).';



CREATE TABLE IF NOT EXISTS "public"."approval_reads" (
    "document_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "read_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."approval_reads" OWNER TO "postgres";


COMMENT ON TABLE "public"."approval_reads" IS '문서 열람 확인. 확인함 뱃지(완료됐는데 미열람)와 참조자 체크마크의 단일 원천. 본인 행만 쓸 수 있고, 표시는 문서 열람 가능자 전원이 본다';



CREATE TABLE IF NOT EXISTS "public"."approval_recipients" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "document_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "kind" "public"."approval_recipient_kind" DEFAULT 'CC'::"public"."approval_recipient_kind" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."approval_recipients" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."assets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "item_type" "text",
    "status" "public"."asset_status" DEFAULT 'AVAILABLE'::"public"."asset_status" NOT NULL,
    "assigned_to" "uuid",
    "return_due" "date",
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "acquisition_type" "public"."asset_acquisition" DEFAULT 'PURCHASE'::"public"."asset_acquisition" NOT NULL,
    "branch_id" "uuid",
    "acquired_on" "date",
    "disposed_on" "date",
    "amount" numeric(14,2),
    "is_portable" boolean DEFAULT false NOT NULL,
    "billing_cycle" "public"."asset_billing_cycle" DEFAULT 'ONE_TIME'::"public"."asset_billing_cycle" NOT NULL,
    "serial_no" "text",
    "photo_paths" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "quantity" integer DEFAULT 1 NOT NULL,
    "manager_id" "uuid",
    "is_pinned" boolean DEFAULT false NOT NULL,
    "location" "text",
    CONSTRAINT "assets_amount_nonneg_chk" CHECK ((("amount" IS NULL) OR ("amount" >= (0)::numeric))),
    CONSTRAINT "assets_assigned_requires_target_chk" CHECK ((("status" <> 'ASSIGNED'::"public"."asset_status") OR ("assigned_to" IS NOT NULL))),
    CONSTRAINT "assets_disposed_after_acquired_chk" CHECK ((("disposed_on" IS NULL) OR ("acquired_on" IS NULL) OR ("disposed_on" >= "acquired_on"))),
    CONSTRAINT "assets_disposed_requires_retired_chk" CHECK ((("disposed_on" IS NULL) OR ("status" = 'RETIRED'::"public"."asset_status"))),
    CONSTRAINT "assets_photo_paths_clean" CHECK ((("array_position"("photo_paths", NULL::"text") IS NULL) AND ("array_position"("photo_paths", ''::"text") IS NULL))),
    CONSTRAINT "assets_photo_paths_max" CHECK ((COALESCE("array_length"("photo_paths", 1), 0) <= 5)),
    CONSTRAINT "assets_quantity_positive" CHECK (("quantity" >= 1))
);


ALTER TABLE "public"."assets" OWNER TO "postgres";


COMMENT ON COLUMN "public"."assets"."item_type" IS '품목(노트북·차량·라이선스·비품 등). 자유입력이며 태그 원장 승격은 후속 과제.';



COMMENT ON COLUMN "public"."assets"."acquisition_type" IS '취득 형태(화면 라벨은 ''분류''). PURCHASE=구매, LEASE=리스, RENTAL=렌탈, OTHER=기타.';



COMMENT ON COLUMN "public"."assets"."branch_id" IS '자산의 소재 지사(branches). 지사 탭이 곧 화면 구조라 필수 귀속이다.';



COMMENT ON COLUMN "public"."assets"."disposed_on" IS '폐기일자. 값이 있으면 status는 RETIRED여야 한다(역방향은 강제하지 않는다).';



COMMENT ON COLUMN "public"."assets"."amount" IS '취득가(원). 감가상각·재무 연동은 범위 밖이며 취득 원가 단일 값이다.';



COMMENT ON COLUMN "public"."assets"."is_portable" IS 'OFFICE 자산 현황(public.portable_assets)에 이 물건을 공개할지. 이름은 반출대장 시절의 것이며(2026-08-25 화면 폐지, 2026-09-06 기능 도입 취소) 이 값이 정하는 것은 임직원 전원에게 보일지 하나다. MANAGEMENT 자산 관리 폼의 ''OFFICE 자산 현황에 공개'' 스위치가 유일한 쓰기 경로다. 컬럼 개칭은 무중단 절차(새 컬럼 추가 → 양쪽 쓰기 → 프론트 전환 → 옛 컬럼 제거)가 필요해 후속으로 둔다 — 한 번에 바꾸면 DB 적용과 프론트 배포 사이에 자산 목록이 죽는 틈이 생긴다.';



COMMENT ON COLUMN "public"."assets"."billing_cycle" IS '금액의 결제 주기. ONE_TIME=완납, MONTHLY=월 구독, YEARLY=연 구독. 연 환산·계약 총액 계산의 기준이며 계약 기간은 acquired_on ~ return_due로 본다.';



COMMENT ON COLUMN "public"."assets"."serial_no" IS '시리얼 번호·관리 번호. 유니크 제약 없음 — 라이선스 키처럼 같은 값이 여러 행에 정당하게 반복될 수 있다.';



COMMENT ON COLUMN "public"."assets"."photo_paths" IS 'asset-photos 버킷의 오브젝트 키 배열(최대 5장, 배열 순서 = 표시 순서). 삭제는 배열에서 빼는 것으로 끝내고 오브젝트는 보존한다.';



COMMENT ON COLUMN "public"."assets"."quantity" IS '보유 수량. 같은 물건을 여러 개 두는 자산(케이블·의자 등)에서 1보다 커진다. 반출 가능 여부와 무관하게 자산의 사실이다.';



COMMENT ON COLUMN "public"."assets"."manager_id" IS '자산 관리자. 이 물건을 맡아 반출 요청·승인을 받는 사람이며, 물건을 지급받아 쓰는 사람(assigned_to)과는 다른 축이다. MANAGEMENT 자산 관리 폼에서 지정하고 OFFICE 반출대장이 표에 적는다.';



COMMENT ON COLUMN "public"."assets"."is_pinned" IS '중요 표시. 켜면 목록 정렬(자산명 순)을 무시하고 최상단에 서며 번호 칸에 핀 표식이 붙는다. 자산의 속성이라 MANAGEMENT 자산 관리와 OFFICE 반출대장이 같은 값을 쓴다.';



COMMENT ON COLUMN "public"."assets"."location" IS '보관 위치 — 지사 안에서 물건이 놓인 자리(예: 3층 회의실, 지하 창고 A). 자유입력이며 지사(branch_id)의 하위 값이다. OFFICE 자산 현황이 카드와 상세에 그대로 적는다.';



CREATE TABLE IF NOT EXISTS "public"."attachment_extracts" (
    "attachment_id" "uuid" NOT NULL,
    "parser_version" "text" NOT NULL,
    "content_hash" "text",
    "byte_size" bigint,
    "mime" "text",
    "status" "text" NOT NULL,
    "summary" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "body" "jsonb",
    "failed_reason" "text",
    "analyzed_by" "uuid",
    "analyzed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "extracted_by" "text" DEFAULT 'server'::"text" NOT NULL,
    CONSTRAINT "attachment_extracts_extracted_by_ck" CHECK (("extracted_by" = ANY (ARRAY['server'::"text", 'client'::"text"]))),
    CONSTRAINT "attachment_extracts_shape" CHECK (((("status" = 'ready'::"text") AND ("body" IS NOT NULL)) OR (("status" = 'failed'::"text") AND ("failed_reason" IS NOT NULL)) OR (("status" = 'original'::"text") AND ("body" IS NULL)))),
    CONSTRAINT "attachment_extracts_status_check" CHECK (("status" = ANY (ARRAY['ready'::"text", 'failed'::"text", 'original'::"text"])))
);


ALTER TABLE "public"."attachment_extracts" OWNER TO "postgres";


COMMENT ON TABLE "public"."attachment_extracts" IS 'AI 작성하기의 자료 분석 캐시(첨부 1건 = 1행). 원본에서 다시 만들 수 있는 파생물이라 원본이 지워지면 함께 지운다. 권한은 원본 첨부와 같다.';



COMMENT ON COLUMN "public"."attachment_extracts"."parser_version" IS '캐시 무효화 축. 이 값이 서버가 아는 현재 값과 다르면 화면이 재분석 필요로 세운다.';



COMMENT ON COLUMN "public"."attachment_extracts"."content_hash" IS '분석한 쪽이 계산한 SHA-256(기록용). 첨부는 교체되지 않아 불변이므로 무효화 판정에는 쓰지 않는다.';



COMMENT ON COLUMN "public"."attachment_extracts"."summary" IS '화면 표시용 건수(sheets/paragraphs/slides/tables/pages/chars). 본문 없이 상태 줄을 그리기 위해 따로 둔다.';



COMMENT ON COLUMN "public"."attachment_extracts"."body" IS '추출 결과 { chunks: [{ kind, location, text, tables }] }. 원본 내용 그 자체이므로 등급도 원본과 같다.';



COMMENT ON COLUMN "public"."attachment_extracts"."extracted_by" IS '이 글자를 뽑은 쪽. server=Edge Function(오피스·텍스트·링크·모델 OCR), client=브라우저 Worker(PDF 텍스트 레이어). 권한 축이 아니라 품질 판독용이며, 다른 파일의 글자가 심기는 것은 서버의 SHA-256 대조가 막는다.';



COMMENT ON CONSTRAINT "attachment_extracts_shape" ON "public"."attachment_extracts" IS '완료 행에는 본문이, 실패 행에는 사유가 있다. 반쪽 행은 "완료인데 읽을 것이 없는" 자료가 된다.';



CREATE TABLE IF NOT EXISTS "public"."attendance_edits" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "attendance_day_id" "uuid" NOT NULL,
    "edited_by" "uuid",
    "edited_by_name" "text",
    "edited_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "field" "text" NOT NULL,
    "before_value" "text",
    "after_value" "text",
    "reason" "text" NOT NULL,
    CONSTRAINT "attendance_edits_field_chk" CHECK (("field" = ANY (ARRAY['status'::"text", 'check_in_at'::"text", 'check_out_at'::"text", 'work_place'::"text", 'note'::"text"]))),
    CONSTRAINT "attendance_edits_reason_chk" CHECK (("btrim"("reason") <> ''::"text"))
);


ALTER TABLE "public"."attendance_edits" OWNER TO "postgres";


COMMENT ON TABLE "public"."attendance_edits" IS '근태 정정 이력(append-only). 사유 필수이며 UPDATE·DELETE 정책을 두지 않는다.';



CREATE TABLE IF NOT EXISTS "public"."attendance_statuses" (
    "code" "text" NOT NULL,
    "label" "text" NOT NULL,
    "tone" "text" DEFAULT 'neutral'::"text" NOT NULL,
    "kind" "text" DEFAULT 'WORK'::"text" NOT NULL,
    "is_system" boolean DEFAULT false NOT NULL,
    "is_paid" boolean DEFAULT true NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
