    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone
);


ALTER TABLE "public"."meeting_places" OWNER TO "postgres";


COMMENT ON TABLE "public"."meeting_places" IS '[폐기 2026-08-20] 회의실 지점 원장. 회의실 소속은 지사 원장(public.branches)으로 되돌렸다 — 20260820150000_meeting_rooms_rejoin_branches.sql. 조회·쓰기 코드 없음(이력 보존용).';



CREATE TABLE IF NOT EXISTS "public"."meeting_recording_segments" (
    "id" "uuid" NOT NULL,
    "recording_id" "uuid" NOT NULL,
    "segment_no" integer NOT NULL,
    "storage_path" "text" NOT NULL,
    "file_name" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "byte_size" bigint NOT NULL,
    "duration_ms" integer NOT NULL,
    "status" "text" DEFAULT 'PENDING'::"text" NOT NULL,
    "transcript" "text",
    "error_code" "text",
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "uploaded_at" timestamp with time zone,
    "transcribed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "meeting_recording_segments_attempt_count_check" CHECK (("attempt_count" >= 0)),
    CONSTRAINT "meeting_recording_segments_byte_size_check" CHECK ((("byte_size" > 0) AND ("byte_size" <= 14680064))),
    CONSTRAINT "meeting_recording_segments_duration_ms_check" CHECK ((("duration_ms" > 0) AND ("duration_ms" <= 420000))),
    CONSTRAINT "meeting_recording_segments_mime_type_check" CHECK (("mime_type" = ANY (ARRAY['audio/webm'::"text", 'audio/mp4'::"text", 'audio/ogg'::"text", 'audio/wav'::"text", 'audio/mpeg'::"text", 'audio/mp3'::"text", 'audio/x-m4a'::"text", 'audio/aac'::"text"]))),
    CONSTRAINT "meeting_recording_segments_segment_no_check" CHECK ((("segment_no" >= 1) AND ("segment_no" <= 36))),
    CONSTRAINT "meeting_recording_segments_status_check" CHECK (("status" = ANY (ARRAY['PENDING'::"text", 'UPLOADED'::"text", 'TRANSCRIBING'::"text", 'READY'::"text", 'FAILED'::"text"])))
);


ALTER TABLE "public"."meeting_recording_segments" OWNER TO "postgres";


COMMENT ON TABLE "public"."meeting_recording_segments" IS '장시간 녹음을 안전하게 자동 보존하기 위한 내부 물리 구간. UI에서는 세션 한 건으로 표시한다.';



CREATE TABLE IF NOT EXISTS "public"."meeting_recordings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
