    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "meeting_recordings_duration_ms_check" CHECK (("duration_ms" >= 0)),
    CONSTRAINT "meeting_recordings_status_check" CHECK (("status" = ANY (ARRAY['RECORDING'::"text", 'PROCESSING'::"text", 'READY'::"text", 'FAILED'::"text"])))
);


ALTER TABLE "public"."meeting_recordings" OWNER TO "postgres";


COMMENT ON TABLE "public"."meeting_recordings" IS '사용자에게 한 건으로 보이는 회의 녹음 세션. 원본/전사/AI 초안은 Restricted 등급이다.';



