ALTER TABLE "public"."module_kpi_snapshots" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."module_templates" (
    "key" "text" NOT NULL,
    "category" "text" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "workspaces" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "visibility" "text" DEFAULT 'INTERNAL_ONLY'::"text" NOT NULL,
    "allow_guest" boolean GENERATED ALWAYS AS (("visibility" = 'GUEST_ONLY'::"text")) STORED,
    "allow_public_link" boolean GENERATED ALWAYS AS (("visibility" = 'PUBLIC_LINK'::"text")) STORED,
    CONSTRAINT "module_templates_category_check" CHECK (("category" = ANY (ARRAY['BASE'::"text", 'INTAKE'::"text", 'OPERATION'::"text", 'OUTCOME'::"text"]))),
    CONSTRAINT "module_templates_visibility_check" CHECK (("visibility" = ANY (ARRAY['PUBLIC_LINK'::"text", 'GUEST_ONLY'::"text", 'INTERNAL_ONLY'::"text"]))),
    CONSTRAINT "module_templates_workspaces_check" CHECK (("workspaces" <@ ARRAY['project'::"text", 'mna'::"text"]))
);


ALTER TABLE "public"."module_templates" OWNER TO "postgres";


COMMENT ON TABLE "public"."module_templates" IS '사업 운영 모듈의 템플릿 카탈로그. 행은 마이그레이션이 심고 ADMIN은 배치 값만 고친다.';



COMMENT ON COLUMN "public"."module_templates"."is_active" IS '카탈로그: 새로 배치 가능한가. 끄면 기존 인스턴스는 그대로 동작하고 신규 생성만 막힌다.';



COMMENT ON COLUMN "public"."module_templates"."visibility" IS '이 종류가 쓰는 공유 범위(성격). PUBLIC_LINK면 인스턴스는 그 값 하나로 고정되고,
   GUEST_ONLY면 담당자가 GUEST_ONLY/INTERNAL_ONLY 중에서 고르며, INTERNAL_ONLY면 내부 전용이다.';



COMMENT ON COLUMN "public"."module_templates"."allow_guest" IS '읽기 호환 껍데기(visibility에서 파생, 쓰기 불가). 새 코드는 visibility를 읽는다.';



COMMENT ON COLUMN "public"."module_templates"."allow_public_link" IS '읽기 호환 껍데기(visibility에서 파생, 쓰기 불가). 새 코드는 visibility를 읽는다.';



CREATE TABLE IF NOT EXISTS "public"."networks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "affiliation" "text",
    "email" "text",
    "phone" "text",
    "linkedin_url" "text",
    "category" "text",
    "country_tag_id" "uuid",
    "region_scope" "text" DEFAULT 'DOMESTIC'::"text" NOT NULL,
    "expertise" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "profile" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "is_provisional" boolean DEFAULT false NOT NULL,
    "merged_into_id" "uuid",
    "created_by" "uuid" DEFAULT "app"."current_app_user_id"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "networks_active_country_required_chk" CHECK ((("deleted_at" IS NOT NULL) OR ("country_tag_id" IS NOT NULL))),
    CONSTRAINT "networks_category_chk" CHECK ((("category" IS NULL) OR ("category" = ANY (ARRAY['experts'::"text", 'van'::"text", 'exp'::"text", 'investors'::"text", 'startup'::"text", 'corporates'::"text", 'institutions'::"text", 'universities'::"text", 'etc'::"text", 'vendors'::"text"])))),
    CONSTRAINT "networks_region_scope_chk" CHECK (("region_scope" = ANY (ARRAY['DOMESTIC'::"text", 'OVERSEAS'::"text"])))
);


ALTER TABLE "public"."networks" OWNER TO "postgres";


COMMENT ON TABLE "public"."networks" IS 'NETWORKS 통합 원장. 구분(category)과 국가(country_tag_id)가 직교한 두 축이며, 종전 원장 11종(국내 10 + 글로벌 1)을 대체한다. 구분이 null이면 미분류(분류 전 임시 상태).';



COMMENT ON COLUMN "public"."networks"."category" IS '구분 코드(experts|van|exp|investors|startup|corporates|institutions|universities|etc|vendors). null = 미분류. startup은 스타트업 대표·임직원 등 사람의 분류이며 startups 원장 연결을 뜻하지 않는다. 라벨은 화면 상수가 소유한다.';



COMMENT ON COLUMN "public"."networks"."country_tag_id" IS '국가(country_tags). 지역 축의 유일한 입력값 — 한국도 여기에 명시한다. 권역은 국가에서 조인해 읽는다. null은 국가 미확인(옛 데이터)이며 신규 등록에서는 허용하지 않는다.';



COMMENT ON COLUMN "public"."networks"."region_scope" IS '국내/해외(DOMESTIC|OVERSEAS). 국가에서 파생되어 저장되는 열이며 손으로 고치지 않는다 — app.sync_network_region_scope() 트리거가 채운다.';



COMMENT ON COLUMN "public"."networks"."profile" IS '사진·부서·직책·매칭여부·소속이력 등(jsonb). 구분 라벨은 담지 않는다 — 그 사실은 category 컬럼 하나가 답한다.';



COMMENT ON CONSTRAINT "networks_active_country_required_chk" ON "public"."networks" IS '활성 네트워크 인물은 국가 태그가 필수이며, 국가 미확인 삭제 이력만 보존한다.';



