    "sort_order" integer DEFAULT 0 NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "display_mode" "text" DEFAULT 'DEFAULT'::"text" NOT NULL,
    CONSTRAINT "position_tags_display_mode_chk" CHECK (("display_mode" = ANY (ARRAY['DEFAULT'::"text", 'PRIORITY'::"text", 'PARALLEL_JOINED'::"text", 'PARALLEL_SEPARATE'::"text"])))
);


ALTER TABLE "public"."position_tags" OWNER TO "postgres";


COMMENT ON COLUMN "public"."position_tags"."display_mode" IS '이름 옆 호칭 표기 방식. PRIORITY=직책만, PARALLEL_JOINED=직급을 앞에 붙여 한 단어로(책임매니저), PARALLEL_SEPARATE=직급/직책, DEFAULT=직책만.';



CREATE TABLE IF NOT EXISTS "public"."program_announcements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "program_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "body" "text",
    "created_by" "uuid" DEFAULT "app"."current_app_user_id"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "entity_key" "text" DEFAULT 'program'::"text" NOT NULL,
    CONSTRAINT "program_announcements_entity_key_check" CHECK (("entity_key" = ANY (ARRAY['program'::"text", 'ma_program'::"text", 'fund'::"text"])))
);


ALTER TABLE "public"."program_announcements" OWNER TO "postgres";


COMMENT ON TABLE "public"."program_announcements" IS '사업 공지사항(AC — 사업 단위 게시판). WORKS 사업 상세의 공지사항 탭에서 담당자가 쓰고,
   GUEST 고정 메뉴 공지사항에서 게스트가 읽는다. 모듈별 NOTICE(program_notices)와 축이 다르다';



COMMENT ON COLUMN "public"."program_announcements"."body" IS '공지 본문(공용 리치텍스트 에디터 HTML). GUEST는 허용 목록 정화기를 거쳐 그린다';



CREATE TABLE IF NOT EXISTS "public"."program_departments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "program_id" "uuid" NOT NULL,
    "department_id" "uuid" NOT NULL,
