    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "org_version_id" "uuid" NOT NULL,
    CONSTRAINT "program_departments_collaboration_ratio_check" CHECK ((("collaboration_ratio" >= 1) AND ("collaboration_ratio" <= 100)))
);


ALTER TABLE "public"."program_departments" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."program_links" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "program_id" "uuid" NOT NULL,
    "program_module_id" "uuid" NOT NULL,
    "label" "text" NOT NULL,
    "url" "text" NOT NULL,
    "description" "text",
    "sort_order" integer DEFAULT 0 NOT NULL,
    "created_by" "uuid" DEFAULT "app"."current_app_user_id"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "entity_key" "text" DEFAULT 'program'::"text" NOT NULL,
    CONSTRAINT "program_links_entity_key_check" CHECK (("entity_key" = ANY (ARRAY['program'::"text", 'ma_program'::"text"]))),
    CONSTRAINT "program_links_url_scheme" CHECK (("url" ~* '^https?://'::"text"))
);


ALTER TABLE "public"."program_links" OWNER TO "postgres";


COMMENT ON TABLE "public"."program_links" IS 'URL첨부 모듈의 링크 목록(AC). 모듈 카드를 누르면 이 행들이 링크 버튼 모달로 열린다';



CREATE TABLE IF NOT EXISTS "public"."program_managers" (
    "program_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "assigned_by" "uuid",
    "assigned_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "role" "public"."program_manager_role" DEFAULT 'MEMBER'::"public"."program_manager_role" NOT NULL,
    "allocation_rate" smallint NOT NULL,
    "start_date" "date" NOT NULL,
    "end_date" "date" NOT NULL,
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "department_id" "uuid",
    "org_version_id" "uuid",
    CONSTRAINT "program_managers_alloc_chk" CHECK ((("allocation_rate" >= 1) AND ("allocation_rate" <= 100))),
    CONSTRAINT "program_managers_period_chk" CHECK (("end_date" >= "start_date"))
);


ALTER TABLE "public"."program_managers" OWNER TO "postgres";


COMMENT ON TABLE "public"."program_managers" IS '프로그램 담당자(다대다). 등록자(programs.created_by)와 별개 축이며 재지정 가능.';



CREATE TABLE IF NOT EXISTS "public"."program_module_assignees" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "program_module_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "assigned_by" "uuid",
    "assigned_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "duty" "text",
    CONSTRAINT "program_module_assignees_duty_len" CHECK ((("duty" IS NULL) OR ("char_length"("duty") <= 200)))
);


ALTER TABLE "public"."program_module_assignees" OWNER TO "postgres";


COMMENT ON TABLE "public"."program_module_assignees" IS '운영 모듈 인스턴스 담당자(다중). 프로그램 담당자 풀(program_managers) 소속 사용자만 배정 가능.';



COMMENT ON COLUMN "public"."program_module_assignees"."duty" IS '이 모듈에서 이 담당자가 하는 일(업무롤) 한 줄. 역할(PM·멤버)은 사업 담당자 원장이 답하므로 여기 적지 않는다. 빈 문자열은 저장하지 않고 null로 접는다.';



CREATE TABLE IF NOT EXISTS "public"."program_module_public_links" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "entity_key" "text" NOT NULL,
    "program_module_id" "uuid" NOT NULL,
    "token" "text" NOT NULL,
    "status" "text" DEFAULT 'PRIVATE'::"text" NOT NULL,
    "open_at" timestamp with time zone,
    "close_at" timestamp with time zone,
    "contact" "text",
    "view_count" integer DEFAULT 0 NOT NULL,
    "last_viewed_at" timestamp with time zone,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    CONSTRAINT "pmpl_entity_key_check" CHECK (("entity_key" = ANY (ARRAY['program'::"text", 'ma_program'::"text"]))),
    CONSTRAINT "pmpl_status_check" CHECK (("status" = ANY (ARRAY['PRIVATE'::"text", 'OPEN'::"text", 'CLOSED'::"text"]))),
    CONSTRAINT "pmpl_window_check" CHECK ((("open_at" IS NULL) OR ("close_at" IS NULL) OR ("close_at" > "open_at")))
);


ALTER TABLE "public"."program_module_public_links" OWNER TO "postgres";


COMMENT ON TABLE "public"."program_module_public_links" IS '모듈 공개 링크(모듈 1:1). 켜고 끄는 것은 사업 담당자(운영), 그 종류가 나갈 수 있는지는
   ADMIN의 module_templates.allow_public_link(정책)가 정한다.';



COMMENT ON COLUMN "public"."program_module_public_links"."entity_key" IS '소유 원장: program(AC) | ma_program(M&A) | project_program(PROJECT). RLS 워크스페이스 판정 근거.';



COMMENT ON COLUMN "public"."program_module_public_links"."token" IS '공개 주소(/p/:token) 토큰. 최초 1회 발급 후 고정 — 껐다 켜도 같은 주소가 돌아온다. 교체는 재발급 RPC만.';



COMMENT ON COLUMN "public"."program_module_public_links"."view_count" IS '열린 횟수. 누가 봤는지는 로그인이 없어 알 수 없다.';



CREATE TABLE IF NOT EXISTS "public"."program_modules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "program_id" "uuid" NOT NULL,
    "module_type" "public"."module_type" NOT NULL,
    "enabled" boolean DEFAULT true NOT NULL,
    "status" "public"."module_status" DEFAULT 'DRAFT'::"public"."module_status" NOT NULL,
    "participation_mode" "public"."participation_mode",
    "manager_id" "uuid",
    "settings" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "visibility" "public"."module_visibility" DEFAULT 'INTERNAL_ONLY'::"public"."module_visibility" NOT NULL,
    "title" "text",
    "entity_key" "text" DEFAULT 'program'::"text" NOT NULL,
    CONSTRAINT "program_modules_entity_key_check" CHECK (("entity_key" = ANY (ARRAY['program'::"text", 'ma_program'::"text"]))),
    CONSTRAINT "program_modules_visibility_check" CHECK (("visibility" = ANY (ARRAY['INTERNAL_ONLY'::"public"."module_visibility", 'GUEST_ONLY'::"public"."module_visibility", 'PUBLIC_LINK'::"public"."module_visibility"])))
);


ALTER TABLE "public"."program_modules" OWNER TO "postgres";


COMMENT ON COLUMN "public"."program_modules"."visibility" IS '공유 범위(배타 3값). PUBLIC_LINK=주소를 아는 누구나 / GUEST_ONLY=내부+초대된 참여기업·전문가 /
   INTERNAL_ONLY=내부 운영자만. 어느 값을 쓸지는 담당자가 고르지 않고 module_templates.visibility가
   정한다 — 노출 범위는 그때그때의 선택이 아니라 모듈 종류의 성격이다.';



COMMENT ON COLUMN "public"."program_modules"."entity_key" IS '소유 원장: program(AC) | ma_program(M&A) | project_program(PROJECT). program_id가 어느 사업 원장을 가리키는지와 RLS 워크스페이스 판정의 근거.';



CREATE TABLE IF NOT EXISTS "public"."program_notices" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "program_id" "uuid" NOT NULL,
    "program_module_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "body" "text",
    "created_by" "uuid" DEFAULT "app"."current_app_user_id"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone
);


ALTER TABLE "public"."program_notices" OWNER TO "postgres";


COMMENT ON TABLE "public"."program_notices" IS '메뉴(모듈)별 NOTICE 알림 글(AC). WORKS 모듈 화면 우측에서 담당자가 쓰고,
   GUEST 메뉴 우측 같은 자리에서 게스트가 읽는다. 글쓰기(POST) 모듈은 대상이 아니다';



COMMENT ON COLUMN "public"."program_notices"."body" IS '알림 본문(리치텍스트 HTML). 게시판·글쓰기 모듈과 동일한 TipTap 에디터로 작성하고,
   GUEST는 글쓰기 본문과 같은 허용 목록 정화기를 거쳐 그린다';



CREATE TABLE IF NOT EXISTS "public"."program_overviews" (
    "program_id" "uuid" NOT NULL,
    "body" "text",
    "created_by" "uuid" DEFAULT "app"."current_app_user_id"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "entity_key" "text" DEFAULT 'program'::"text" NOT NULL,
    CONSTRAINT "program_overviews_entity_key_check" CHECK (("entity_key" = ANY (ARRAY['program'::"text", 'ma_program'::"text", 'fund'::"text"])))
);


ALTER TABLE "public"."program_overviews" OWNER TO "postgres";


COMMENT ON TABLE "public"."program_overviews" IS '사업개요(사업소개문, AC — 사업 1건당 1건, program_id가 PK). WORKS 사업 상세의 사업개요
   탭에서 담당자가 쓰고, GUEST 로그인 직후 첫 화면에서 게스트가 읽는다';



COMMENT ON COLUMN "public"."program_overviews"."body" IS '소개 본문(공용 리치텍스트 에디터 HTML). GUEST는 허용 목록 정화기(sanitizeRichText)를 거쳐 그린다';



COMMENT ON COLUMN "public"."program_overviews"."entity_key" IS '소유 원장: program(AC) | ma_program(M&A) | project_program(PROJECT).';



CREATE TABLE IF NOT EXISTS "public"."program_participant_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "entity_key" "text" NOT NULL,
    "program_id" "uuid" NOT NULL,
    "master_table" "text" NOT NULL,
    "master_id" "uuid" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "program_participant_entries_entity_key_check" CHECK (("entity_key" = ANY (ARRAY['program'::"text", 'ma_program'::"text"]))),
    CONSTRAINT "program_participant_entries_master_table_check" CHECK (("master_table" = ANY (ARRAY['startups'::"text", 'networks'::"text", 'ma_sellers'::"text", 'ma_buyers'::"text"])))
);


ALTER TABLE "public"."program_participant_entries" OWNER TO "postgres";


COMMENT ON TABLE "public"."program_participant_entries" IS '사업 참가자 목록(명단). 참가 사실 한 축만 지며 게스트 계정·로그인과 갈려 있다. 값은 원장(startups/networks/ma_sellers/ma_buyers)이 소유하고 여기서는 참조만 든다.';



COMMENT ON COLUMN "public"."program_participant_entries"."entity_key" IS '소유 원장: program(AC) | ma_program(M&A).';



COMMENT ON COLUMN "public"."program_participant_entries"."master_table" IS '이 줄의 자격이자 원장 출처. 값 목록은 program_participants·guest_identities의 CHECK와 한 벌로 움직인다 — 자격을 하나 열 때 세 곳을 같은 커밋에서 연다.';



COMMENT ON COLUMN "public"."program_participant_entries"."deleted_at" IS '명단에서 뺀 시각(소프트 삭제). 유일 제약은 살아 있는 행에만 걸리므로 뺀 대상을 다시 담을 수 있다.';



CREATE TABLE IF NOT EXISTS "public"."program_participants" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "program_id" "uuid" NOT NULL,
    "user_id" "uuid",
    "master_id" "uuid",
    "status" "text" DEFAULT 'ACTIVE'::"text" NOT NULL,
    "invited_at" timestamp with time zone,
    "joined_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "master_table" "text",
    "login_status" "public"."participant_login_status" DEFAULT 'NOT_ALLOWED'::"public"."participant_login_status" NOT NULL,
    "login_opened_by" "uuid",
    "login_opened_at" timestamp with time zone,
    "entity_key" "text" DEFAULT 'program'::"text" NOT NULL,
    "access_starts_at" timestamp with time zone,
    "access_ends_at" timestamp with time zone,
    "created_by" "uuid",
    CONSTRAINT "program_participants_access_window_check" CHECK ((("access_starts_at" IS NULL) OR ("access_ends_at" IS NULL) OR ("access_starts_at" < "access_ends_at"))),
    CONSTRAINT "program_participants_entity_key_check" CHECK (("entity_key" = ANY (ARRAY['program'::"text", 'ma_program'::"text", 'fund'::"text"]))),
    CONSTRAINT "program_participants_master_table_chk" CHECK ((("master_table" IS NULL) OR ("master_table" = ANY (ARRAY['startups'::"text", 'networks'::"text", 'ma_sellers'::"text", 'ma_buyers'::"text"]))))
);


ALTER TABLE "public"."program_participants" OWNER TO "postgres";


COMMENT ON COLUMN "public"."program_participants"."master_table" IS '이 참여 줄의 자격이자 원장 출처: startups(참가기업) | networks(참가전문가). 게스트가 이 줄로 들어오면 그 자격의 화면이 열린다 — 자격은 계정이 아니라 줄이 갖는다(한 사람이 한 사업에 두 자격으로 참여하면 줄이 둘이고 화면도 둘이다). 근거: 3_9_1 §4';



COMMENT ON COLUMN "public"."program_participants"."login_status" IS '게스트 로그인 개방 상태. 명부 등록과 별개 축이며 사업 담당자만 바꾼다.';



COMMENT ON COLUMN "public"."program_participants"."entity_key" IS '소유 원장: program(PROJECT) | ma_program(M&A) | fund(FUND — 조합, program_id는 funds.id). 모듈 계열은 아직 fund를 받지 않는다(온기보고를 여는 날 함께 연다).';



COMMENT ON COLUMN "public"."program_participants"."access_starts_at" IS '[폐지 예정 2026-09-05] 판정에 쓰이지 않는다. 접근 기간은 사업 원장의 guest_access_ends_at이 답한다. Edge Function 재배포 후 컬럼을 걷는다.';



COMMENT ON COLUMN "public"."program_participants"."access_ends_at" IS '[폐지 예정 2026-09-05] 판정에 쓰이지 않는다. 접근 기간은 사업 원장의 guest_access_ends_at이 답한다. Edge Function 재배포 후 컬럼을 걷는다.';



COMMENT ON COLUMN "public"."program_participants"."created_by" IS '이 참여 줄을 명부에 담은 사람. 어떤 권한도 주지 않는 서술 값이며 트리거가 찍는다. 옛 행은 알 수 없어 null이다.';



CREATE TABLE IF NOT EXISTS "public"."program_posts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "program_id" "uuid" NOT NULL,
    "program_module_id" "uuid",
    "session_source_id" "uuid",
    "activity_type" "text",
    "title" "text" NOT NULL,
    "activity_date" "date",
    "visibility" "public"."activity_visibility" DEFAULT 'INTERNAL_ONLY'::"public"."activity_visibility" NOT NULL,
