CREATE TABLE IF NOT EXISTS "public"."programs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text" NOT NULL,
    "internal_title" "text",
    "slug" "text",
    "status" "public"."program_status" DEFAULT 'DRAFT'::"public"."program_status" NOT NULL,
    "start_date" "date",
    "end_date" "date",
    "host_organization" "text",
    "partner_organization" "text",
    "description" "text",
    "created_by" "uuid" DEFAULT "app"."current_app_user_id"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "proposal_start_date" "date",
    "proposal_end_date" "date",
    "code" "text",
    "category" "text",
    "industries" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "guest_access_ends_at" timestamp with time zone,
    CONSTRAINT "programs_category_check" CHECK ((("category" IS NULL) OR ("category" = ANY (ARRAY['PUBLIC'::"text", 'PRIVATE'::"text", 'REVENUE'::"text", 'NEW'::"text", 'ETC'::"text"]))))
);


ALTER TABLE "public"."programs" OWNER TO "postgres";


COMMENT ON COLUMN "public"."programs"."start_date" IS '운영 기간 시작일(실제 행사 관리 기간)';



COMMENT ON COLUMN "public"."programs"."end_date" IS '운영 기간 종료일(실제 행사 관리 기간)';



COMMENT ON COLUMN "public"."programs"."proposal_start_date" IS '제안 단계 시작일(제안서 작성~발표 기간의 시작)';



COMMENT ON COLUMN "public"."programs"."proposal_end_date" IS '제안 단계 종료일(제안서 작성~발표 기간의 끝)';



COMMENT ON COLUMN "public"."programs"."code" IS '사업코드(6자리 영숫자 난수, 유니크). 신규 등록 시 트리거 자동 부여.';



COMMENT ON COLUMN "public"."programs"."category" IS '사업구분: PUBLIC(공공)/PRIVATE(민간)/REVENUE(매출)/NEW(신규)/ETC(기타). null=미지정.';



COMMENT ON COLUMN "public"."programs"."industries" IS '산업 태그(industry_tags) 다중 선택 배열(최대 3개). 이 사업이 발굴·대상으로 하는 산업군.';



COMMENT ON COLUMN "public"."programs"."guest_access_ends_at" IS '이 사업 게스트의 접근 종료. null이면 제한 없음. 참여 기업·전문가 전원에게 같이 걸린다(기업별 예외는 두지 않는다 — 한 곳만 막을 일은 차단이 답한다). 기본값은 사업 종료일 + 14일이며 첫 개방 때 open_program_guest_access가 채운다. 근거: 3_9_1 §8';



