CREATE TABLE IF NOT EXISTS "public"."trade_partners" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "code_seq" integer NOT NULL,
    "name" "text" NOT NULL,
    "partner_type" "text" NOT NULL,
    "registration_no" "text",
    "bank_code" "text",
    "account_no" "text",
    "account_holder" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "code" "text" GENERATED ALWAYS AS (('YN-'::"text" || "lpad"(("code_seq")::"text", 5, '0'::"text"))) STORED,
    "verified_at" timestamp with time zone,
    "verified_by" "uuid",
    CONSTRAINT "trade_partners_account_no_chk" CHECK ((("account_no" IS NULL) OR ("account_no" ~ '^[0-9][0-9-]{4,29}$'::"text"))),
    CONSTRAINT "trade_partners_account_set_chk" CHECK (((("bank_code" IS NULL) AND ("account_no" IS NULL) AND ("account_holder" IS NULL)) OR (("bank_code" IS NOT NULL) AND ("account_no" IS NOT NULL) AND ("btrim"(COALESCE("account_holder", ''::"text")) <> ''::"text")))),
    CONSTRAINT "trade_partners_bank_code_chk" CHECK ((("bank_code" IS NULL) OR ("bank_code" ~ '^[0-9]{3}$'::"text"))),
    CONSTRAINT "trade_partners_code_seq_chk" CHECK ((("code_seq" >= 1) AND ("code_seq" <= 99999))),
    CONSTRAINT "trade_partners_name_chk" CHECK (("btrim"("name") <> ''::"text")),
    CONSTRAINT "trade_partners_registration_no_chk" CHECK ((("registration_no" IS NULL) OR (("partner_type" = 'CORPORATE'::"text") AND ("registration_no" ~ '^[0-9]{10}$'::"text")) OR (("partner_type" = 'INDIVIDUAL'::"text") AND ("registration_no" ~ '^[0-9]{8}$'::"text")))),
    CONSTRAINT "trade_partners_type_chk" CHECK (("partner_type" = ANY (ARRAY['CORPORATE'::"text", 'INDIVIDUAL'::"text"])))
);


ALTER TABLE "public"."trade_partners" OWNER TO "postgres";


COMMENT ON TABLE "public"."trade_partners" IS 'MANAGEMENT 거래처 원장(코드·상호·구분·등록번호·계좌). 지급 상대의 단일 원천이며 NETWORKS vendors(외주 네트워크 마스터)와는 다른 축이다.';



COMMENT ON COLUMN "public"."trade_partners"."registration_no" IS '법인=사업자등록번호 10자리, 개인=생년월일 8자리. 숫자만 저장하고 표기는 화면이 만든다.';



COMMENT ON COLUMN "public"."trade_partners"."bank_code" IS '금융기관 코드 3자리(표준값). 은행 이름표는 apps/works/src/features/management/partners/config.ts가 갖는다.';



COMMENT ON COLUMN "public"."trade_partners"."is_active" IS '거래 사용 여부. 오등록 정리(deleted_at)와 다른 축이며, 중단해도 과거 지급 내역을 설명할 수 있게 목록에 남는다.';



COMMENT ON COLUMN "public"."trade_partners"."code" IS '표시용 거래처 코드(YN- + 등록순 5자리). 생성 열이라 직접 쓰지 않으며 발급 후 바뀌지 않는다.';



COMMENT ON COLUMN "public"."trade_partners"."verified_at" IS '경영지원이 증빙(사업자등록증·통장사본)을 보고 계좌를 확인한 시점. 비어 있으면 화면에 "확인 전" 딱지가 붙는다 — 송금 요청에서 즉석 등록한 거래처가 확인된 거래처와 같은 얼굴로 서지 않게 한다. 송금 요청·상신을 막지는 않는다(걸러 내는 일은 결재자의 반려가 한다).';



CREATE OR REPLACE VIEW "public"."trade_partners_directory" WITH ("security_invoker"='false') AS
 SELECT "id",
    "code",
    "name",
    "partner_type",
        CASE
            WHEN ("partner_type" = 'CORPORATE'::"text") THEN "registration_no"
            ELSE "left"("registration_no", 4)
        END AS "registration_no",
    "bank_code",
    "right"("regexp_replace"("account_no", '\D'::"text", ''::"text", 'g'::"text"), 4) AS "account_no_last4",
    "account_holder",
    "is_active",
    "verified_at",
    "updated_at"
   FROM "public"."trade_partners" "p"
  WHERE (("deleted_at" IS NULL) AND "app"."is_internal_user"());


ALTER VIEW "public"."trade_partners_directory" OWNER TO "postgres";


COMMENT ON VIEW "public"."trade_partners_directory" IS 'OFFICE 거래처 조회면·송금 요청 선택 목록. 원장(trade_partners)은 management 전용이고 이 뷰가 내부 임직원에게 가려진 한 벌을 낸다(계좌번호 뒤 4자리, 개인 생년월일은 연도만, 증빙 서류 없음, 확인 여부 포함). security_invoker=false이므로 접근 판정은 본문의 app.is_internal_user()가 한다. 근거: 20260903230000 · 20260911140000';



CREATE TABLE IF NOT EXISTS "public"."upload_batches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "uploaded_by" "uuid",
    "filename" "text",
    "content_hash" "text",
    "total_rows" integer DEFAULT 0 NOT NULL,
    "inserted_count" integer DEFAULT 0 NOT NULL,
    "merged_count" integer DEFAULT 0 NOT NULL,
    "skipped_count" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."upload_batches" OWNER TO "postgres";


COMMENT ON TABLE "public"."upload_batches" IS '대용량 업로드 배치 이력(파일 해시로 동일 파일 재업로드 경고)';



CREATE TABLE IF NOT EXISTS "public"."users" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "auth_user_id" "uuid",
    "user_type" "public"."user_type" NOT NULL,
    "email" "text",
    "name" "text" NOT NULL,
    "department_id" "uuid",
    "company_id" "uuid",
    "session_version" integer DEFAULT 1 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "phone" "text",
    "profile" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL
);


ALTER TABLE "public"."users" OWNER TO "postgres";


COMMENT ON COLUMN "public"."users"."phone" IS '임직원 연락처(개인정보). 목록/상세 마스킹은 앱 계층에서 강제(원본 노출은 민감정보 토글).';



COMMENT ON COLUMN "public"."users"."profile" IS '임직원 자유 프로필(jsonb): company/position/bio/note 등. 전문가 profile 패턴과 동일.';



CREATE TABLE IF NOT EXISTS "public"."workspace_permissions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "workspace_key" "public"."workspace_key" NOT NULL,
    "permission_level" "public"."permission_level" DEFAULT 'none'::"public"."permission_level" NOT NULL,
    "scope_type" "public"."scope_type" DEFAULT 'none'::"public"."scope_type" NOT NULL,
    "scope_id" "uuid",
    "expires_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."workspace_permissions" OWNER TO "postgres";


