ALTER TABLE "public"."attachments" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "attachments_announcement_guest_select" ON "public"."attachments" FOR SELECT USING (("app"."is_guest"() AND ("deleted_at" IS NULL) AND ("target_type" = 'program_announcement'::"text") AND (EXISTS ( SELECT 1
   FROM "public"."program_announcements" "a"
  WHERE (("a"."id" = "attachments"."target_id") AND ("a"."deleted_at" IS NULL) AND ("a"."program_id" IN ( SELECT "app"."guest_program_ids"() AS "guest_program_ids")))))));



CREATE POLICY "attachments_guest_select" ON "public"."attachments" FOR SELECT USING (("app"."is_guest"() AND ("deleted_at" IS NULL) AND ("program_module_id" IS NOT NULL) AND ("program_module_id" IN ( SELECT "app"."guest_open_module_ids"() AS "guest_open_module_ids"))));



CREATE POLICY "attachments_insert" ON "public"."attachments" FOR INSERT TO "authenticated" WITH CHECK ((("uploaded_by" = "app"."current_app_user_id"()) AND ("app"."current_app_user_id"() IS NOT NULL) AND
CASE
    WHEN ("target_type" = 'ma_buyer'::"text") THEN "app"."can_manage_ma_party"('ma_buyer'::"text", "target_id")
    WHEN ("target_type" = 'ma_seller'::"text") THEN "app"."can_manage_ma_party"('ma_seller'::"text", "target_id")
    ELSE true
END AND (("target_type" <> ALL (ARRAY['office_minute'::"text", 'office_minute_voice'::"text"])) OR "app"."is_minute_author"("target_id")) AND (("target_type" <> 'approval'::"text") OR "app"."is_approval_drafter"("target_id"))));



CREATE POLICY "attachments_overview_guest_select" ON "public"."attachments" FOR SELECT USING (("app"."is_guest"() AND ("deleted_at" IS NULL) AND ("target_type" = 'program_overview'::"text") AND ("target_id" IN ( SELECT "app"."guest_program_ids"() AS "guest_program_ids"))));



CREATE POLICY "attachments_question_guest_select" ON "public"."attachments" FOR SELECT USING (("app"."is_guest"() AND ("deleted_at" IS NULL) AND ("target_type" = 'program_question'::"text") AND (EXISTS ( SELECT 1
   FROM "public"."program_questions" "q"
  WHERE (("q"."id" = "attachments"."target_id") AND ("q"."deleted_at" IS NULL) AND ("q"."created_by" = "app"."current_app_user_id"()) AND ("q"."program_id" IN ( SELECT "app"."guest_program_ids"() AS "guest_program_ids")))))));



CREATE POLICY "attachments_select" ON "public"."attachments" FOR SELECT TO "authenticated" USING (("app"."is_admin"() OR (("app"."current_app_user_id"() IS NOT NULL) AND ("app"."current_app_role"() <> ALL (ARRAY['external_startup'::"text", 'external_expert'::"text", 'temporary_guest'::"text"])) AND
CASE
    WHEN ("target_type" = 'ma_buyer'::"text") THEN "app"."can_read_ma_party"('ma_buyer'::"text", "target_id")
    WHEN ("target_type" = 'ma_seller'::"text") THEN "app"."can_read_ma_party"('ma_seller'::"text", "target_id")
    ELSE true
END AND (("target_type" <> ALL (ARRAY['office_minute'::"text", 'office_minute_voice'::"text"])) OR "app"."can_read_minute"("target_id")) AND (("target_type" <> 'approval'::"text") OR "app"."can_read_approval"("target_id")))));



CREATE POLICY "attachments_update" ON "public"."attachments" FOR UPDATE TO "authenticated" USING (
CASE
    WHEN ("target_type" = 'ma_buyer'::"text") THEN "app"."can_manage_ma_party"('ma_buyer'::"text", "target_id")
    WHEN ("target_type" = 'ma_seller'::"text") THEN "app"."can_manage_ma_party"('ma_seller'::"text", "target_id")
    ELSE ("app"."is_admin"() OR ("uploaded_by" = "app"."current_app_user_id"()))
END) WITH CHECK (
CASE
    WHEN ("target_type" = 'ma_buyer'::"text") THEN "app"."can_manage_ma_party"('ma_buyer'::"text", "target_id")
    WHEN ("target_type" = 'ma_seller'::"text") THEN "app"."can_manage_ma_party"('ma_seller'::"text", "target_id")
    ELSE ("app"."is_admin"() OR ("uploaded_by" = "app"."current_app_user_id"()))
END);



