ALTER TABLE "public"."entity_contributions" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "entity_contributions_insert" ON "public"."entity_contributions" FOR INSERT TO "authenticated" WITH CHECK ((
CASE
    WHEN ("entity_table" = 'ma_buyers'::"text") THEN "app"."can_manage_ma_party"('ma_buyer'::"text", "entity_id")
    WHEN ("entity_table" = 'ma_sellers'::"text") THEN "app"."can_manage_ma_party"('ma_seller'::"text", "entity_id")
    WHEN "app"."entity_key_workspace_scoped"("entity_table") THEN "app"."can_write_workspace"("app"."entity_key_workspace"("entity_table"))
    WHEN ("app"."entity_key_workspace"("entity_table") = 'fund'::"text") THEN ("app"."can_write_workspace"('fund'::"text") AND "app"."can_access_fund"("entity_id"))
    ELSE ("app"."can_write_workspace"("app"."entity_key_workspace"("entity_table")) AND "app"."can_access_ws_program"("app"."entity_key_workspace"("entity_table"), "entity_id"))
END AND (("user_id" IS NULL) OR ("user_id" = "app"."current_app_user_id"()))));



CREATE POLICY "entity_contributions_select" ON "public"."entity_contributions" FOR SELECT TO "authenticated" USING (
CASE
    WHEN ("entity_table" = 'ma_buyers'::"text") THEN "app"."can_read_ma_party"('ma_buyer'::"text", "entity_id")
    WHEN ("entity_table" = 'ma_sellers'::"text") THEN "app"."can_read_ma_party"('ma_seller'::"text", "entity_id")
    WHEN "app"."entity_key_workspace_scoped"("entity_table") THEN "app"."can_read_workspace"("app"."entity_key_workspace"("entity_table"))
    WHEN ("app"."entity_key_workspace"("entity_table") = 'fund'::"text") THEN ("app"."can_read_workspace"('fund'::"text") AND "app"."can_access_fund"("entity_id"))
    ELSE ("app"."can_read_workspace"("app"."entity_key_workspace"("entity_table")) AND "app"."can_access_ws_program"("app"."entity_key_workspace"("entity_table"), "entity_id"))
END);



